const SYSTEMS_REGISTRY={},SYSTEM_GROUPS_ALL={};function registerSystem(r,o){SYSTEMS_REGISTRY[r]=o;var t=o.groups||{};for(var e in t){SYSTEM_GROUPS_ALL[e]||(SYSTEM_GROUPS_ALL[e]={});var a=t[e].key,s=t[e].order!=null?t[e].order:999;SYSTEM_GROUPS_ALL[e][a]||(SYSTEM_GROUPS_ALL[e][a]=[]),SYSTEM_GROUPS_ALL[e][a].push({id:r,order:s})}}registerSystem("13th-age",{groups:{default:{key:"tactical",order:36},family:{key:"standalone",order:41},genre:{key:"adventure",order:23}},name:"13th Age",publisher:"Pelgrane Press",dice:"d20 + escalation die",players:"3–6",complexity:3,edition:null,free:!0,foundryStatus:"Community",heroImage:"https://pelgranepress.com/wp-content/uploads/2020/04/Hardcover-PEL13A01.jpg",playstyleTags:["combat","tactical","narrative"],settingTags:["fantasy"],gallery:[{src:"https://pelgranepress.com/wp-content/uploads/2020/04/Hardcover-PEL13A02.jpg"},{src:"https://pelgranepress.com/wp-content/uploads/2020/04/Hardcover-PEL13A04.jpg"},{src:"https://pelgranepress.com/wp-content/uploads/2020/04/Softcover-PEL13A06.jpg"}],resources:[{type:"link",url:"https://pelgranepress.com/13th-age/",fmt:"Web"},{type:"quickstart",url:"https://pelgranepress.com/media/SRD/13thAgeArchmageEngineSRD.pdf",fmt:"PDF"}],mechanics:[{icon:"trending-up"},{icon:"crown"},{icon:"sparkles"},{icon:"swords"}],quotes:[{text:"One of the best systems I've encountered — and I've either played or read the rules to countless d20 systems at this point — is 13th Age. It's fun, fast and accessible.",author:"Erik Kain, Forbes"},{text:"13th Age RPG delivers an incredible fantasy storytelling experience.",author:"Ed Grabianowski, io9"}],ru:{tagShort:"d20-фэнтези от ведущих дизайнеров 3-й и 4-й D&D",tagline:"«Всё как в d20, но каждый раунд битва разгоняется — в буквальном смысле».",description:"13th Age — d20-фэнтези Роба Хейнсу (ведущий 4-й редакции D&D) и Джонатана Твита (ведущий 3-й). Берёт тактический бой d20 и оживляет его «кубиком эскалации», который каждый раунд повышает всем шанс попасть. Плюс сюжетные инструменты: 13 Икон и «Одна уникальная черта». Кранч и нарратив в одном флаконе, в сеттинге Империи Драконов.",setting:"Империя Драконов — классическое высокое фэнтези, но живое и своё. Тринадцать Икон (Император, Личь-Король, Три и др.) — сверхсилы мира, с которыми связан каждый герой. Никаких серых километров лора: детали появляются через твою «Одну уникальную черту» и связи с Иконами, прямо в игре.",vignette:"Второй раунд боя с орочьим вожаком — кубик эскалации показывает +1, и он растёт. Файтер бьёт: d20 + бонус атаки + эскалация против AC. Раунд за раундом попадать всё легче — бой ускоряется, а не вязнет. На +4 воин совершает то, что было невозможно вначале. Иконный бросок: связь с Личь-Королём внезапно осложняет сцену — из тьмы поднимаются мертвецы.",prep:"~30 мин",mechanics:[{title:"Кубик эскалации",text:"На столе лежит d6, который со 2-го раунда растёт на +1 (до +6) и добавляется всем к попаданию. Награда за агрессию: бои ускоряются к финалу, а не затягиваются."},{title:"13 Икон",text:"Тринадцать великих сил мира. У героя есть «кубики отношений» с некоторыми — бросаешь их в начале сессии, и результат вплетает Икон в сюжет: помощь, осложнение, интрига."},{title:"Одна уникальная черта",text:"У каждого персонажа — деталь, которой нет больше ни у кого в мире («единственный выживший из…»). Сразу даёт крючок для истории и делает героя по-настоящему уникальным."},{title:"d20 с ДНК 3-й и 4-й D&D",text:"Тактический, но обтёсанный: предыстории вместо длинных списков навыков, гибкие классы, быстрый бой. Знакомо игрокам D&D, но легче и сюжетнее."}],gallery:[{cap:"Bestiary"},{cap:"13 True Ways"},{cap:"Book of Loot"}],resources:[{name:"Официальная страница — Pelgrane Press"},{name:"Бесплатный SRD (Archmage Engine)"}],quotes:[{text:"Одна из лучших систем, что мне встречались — а я к этому моменту либо играл, либо читал правила бесчисленных d20-систем — это 13th Age. Она весёлая, быстрая и доступная."},{text:"13th Age дарит невероятный опыт фэнтезийного повествования."}]},en:{tagShort:"d20 fantasy from the lead designers of D&D 3E and 4E",tagline:`"It's d20, but every round the fight literally speeds up."`,description:"13th Age is a d20 fantasy game by Rob Heinsoo (D&D 4E lead) and Jonathan Tweet (D&D 3E lead). It takes tactical d20 combat and enlivens it with the escalation die, which raises everyone's to-hit each round. Add story-first tools: the 13 Icons and the One Unique Thing. Crunch and narrative in one package, in the Dragon Empire setting.",setting:"The Dragon Empire — classic high fantasy, but living and its own. Thirteen Icons (the Emperor, the Lich King, the Three, and more) are the world's superpowers, and every hero is tied to some of them. No gray miles of lore: details emerge through your One Unique Thing and your Icon relationships, right at the table.",vignette:"Round two of the fight with the orc warlord — the escalation die shows +1, and it's climbing. The fighter swings: d20 + attack bonus + escalation against AC. Round by round, hitting gets easier — the fight accelerates instead of grinding. At +4 the warrior pulls off what was impossible at the start. An Icon roll: a tie to the Lich King suddenly complicates the scene — the dead rise from the dark.",prep:"~30 min",mechanics:[{title:"The escalation die",text:"A d6 sits on the table, rising +1 from round 2 (up to +6) and added to everyone's to-hit. A reward for aggression: fights accelerate toward the finish instead of dragging."},{title:"The 13 Icons",text:"Thirteen great powers of the world. A hero has 'relationship dice' with some — roll them at the start of a session and the result weaves the Icons into the story: aid, complication, intrigue."},{title:"One Unique Thing",text:"Every character has a detail no one else in the world shares ('the only survivor of…'). It instantly gives a story hook and makes the hero genuinely one of a kind."},{title:"d20 with 3E & 4E DNA",text:"Tactical but streamlined: backgrounds instead of long skill lists, flexible classes, fast combat. Familiar to D&D players, but lighter and more story-forward."}],gallery:[{cap:"Bestiary"},{cap:"13 True Ways"},{cap:"Book of Loot"}],resources:[{name:"Official page — Pelgrane Press"},{name:"Free SRD (Archmage Engine)"}]}}),registerSystem("advanced-fighting-fantasy",{groups:{default:{key:"osr",order:21},family:{key:"standalone",order:24},genre:{key:"adventure",order:20}},name:"Advanced Fighting Fantasy",publisher:"Arion Games",dice:"2d6 (roll-under SKILL)",players:"2–6",complexity:2,free:!0,foundryStatus:"Official",heroImage:"https://image.nobleknight.com/p/jpg1500/psicb7001.jpg",playstyleTags:["combat","explore","social"],settingTags:["fantasy"],gallery:[{src:"https://cdn.freewebstore.com/origin/235161/cb77001-thumb.jpg"},{src:"https://cdn.freewebstore.com/origin/235161/488616_1765104439277.png"},{src:"https://cdn.freewebstore.com/origin/235161/483969_1726044220939.png"}],resources:[{type:"link",url:"https://www.arion-games.com/",fmt:"Web"}],mechanics:[{icon:"swords"},{icon:"dices"},{icon:"clover"},{icon:"map"}],quotes:[{text:"There's more than enough to run a game or campaign from just the core book, which is how I prefer to run the solo game.",author:"Duncan Thomson, RandRoll"},{text:"Advanced Fighting Fantasy is a role-playing game with simple mechanics that still provide ample detail, set in an interesting fantasy world.",author:"T. Kurt Bond, Lacking Natural Simplicity"}],ru:{tagShort:"Ролёвка по книгам-игркам Fighting Fantasy",tagline:"«SKILL, STAMINA и LUCK — легендарные книги-игры становятся полноценной RPG».",description:"Advanced Fighting Fantasy — ролевая игра по классическим книгам-играм Fighting Fantasy и Sorcery! (Стив Джексон и Иан Ливингстон). Простая система на 2d6: три характеристики — Мастерство, Выносливость и Удача — плюс Магия во 2-й редакции. Издаётся Arion Games; действие — в любимом мире Титан (континент Аллансия). Ностальгия и живая система в одном.",setting:"Титан — фэнтезийный мир культовых книг-игр 1980-х: континент Аллансия, порт-город Блэксэнд, Ледяные пустоши и колдуны Крарта. Десятилетия лора из десятков геймбуков. Тон — героическое приключение с чудовищами, ловушками и мрачным юмором в духе оригинальных «Warlock of Firetop Mountain».",vignette:"Ваш искатель приключений входит в логово орка. Проверка Мастерства: 2d6 против значения Мастерства, нужно меньше-равно. Начинается бой — оба бросают 2d6 плюс Мастерство; чей результат выше, тот ранит, снимая Выносливость. Удача на исходе — потратить её на смертельный удар или приберечь на спасение? Классика книг-игр за столом.",prep:"~20 мин",mechanics:[{title:"Мастерство, Выносливость, Удача",text:"Три легендарные характеристики Fighting Fantasy плюс Магия во 2-й редакции. Проверки — 2d6 против Мастерства. Знакомо всем, кто листал книги-игры в детстве."},{title:"Встречный бой на 2d6",text:"В схватке обе стороны кидают 2d6 + Мастерство; чей результат выше — наносит удар по Выносливости. Быстро, напряжённо и смертельно — как в оригинальных геймбуках."},{title:"Специальные навыки",text:"Широкое Мастерство уточняется Специальными навыками (Меч, Магия, Внимательность). Тонкая настройка героя без раздувания системы."},{title:"Мир Титан",text:"Готовый сеттинг любимых книг-игр: Аллансия, Sorcery!, десятки приключений и монстров. Ностальгия, подкреплённая цельной и лёгкой ролевой системой."}],gallery:[{cap:"Обложка кора"},{cap:"Magic Companion"},{cap:"Adventure Creator"}],resources:[{name:"Официальный сайт — Arion Games"}],quotes:[{text:"Одного кора более чем достаточно, чтобы вести игру или кампанию — именно так я предпочитаю играть в соло."},{text:"Advanced Fighting Fantasy — ролевая игра с простыми механиками, дающими при этом достаточно деталей, в интересном фэнтезийном мире."}]},en:{tagShort:"The RPG of the Fighting Fantasy gamebooks",tagline:'"SKILL, STAMINA, and LUCK — the legendary gamebooks become a full RPG."',description:"Advanced Fighting Fantasy is the RPG of the classic Fighting Fantasy and Sorcery! gamebooks (Steve Jackson and Ian Livingstone). A simple 2d6 system: three stats — SKILL, STAMINA, and LUCK — plus MAGIC in 2nd edition. Published by Arion Games and set in the beloved world of Titan (the continent of Allansia). Nostalgia and a living system in one.",setting:"Titan — the fantasy world of the cult 1980s gamebooks: the continent of Allansia, the port-city of Port Blacksand, the Icefinger Mountains, and the sorcerers of Kakhabad. Decades of lore across dozens of gamebooks. The tone is heroic adventure with monsters, traps, and grim humor in the spirit of the original Warlock of Firetop Mountain.",vignette:"Your adventurer enters an orc's lair. A SKILL test: 2d6 against your SKILL, rolling equal or under. Combat begins — both sides roll 2d6 plus SKILL; the higher result wounds, draining STAMINA. LUCK is running low — spend it for a killing blow, or save it to survive? The classic gamebook experience, at the table.",prep:"~20 min",mechanics:[{title:"SKILL, STAMINA, LUCK",text:"The three legendary Fighting Fantasy stats, plus MAGIC in 2nd edition. Tests are 2d6 against SKILL. Instantly familiar to anyone who leafed through the gamebooks as a kid."},{title:"Opposed 2d6 combat",text:"In a fight, both sides roll 2d6 + SKILL; the higher result lands a hit on STAMINA. Fast, tense, and deadly — just like the original gamebooks."},{title:"Special Skills",text:"Broad SKILL is refined by Special Skills (Sword, Magic, Awareness). Fine-tune a hero without bloating the system."},{title:"The world of Titan",text:"A ready-made setting from the beloved gamebooks: Allansia, Sorcery!, and dozens of adventures and monsters. Nostalgia backed by a cohesive, light RPG system."}],gallery:[{cap:"Core rulebook cover"},{cap:"Magic Companion"},{cap:"Adventure Creator"}],resources:[{name:"Official site — Arion Games"}],quotes:[{text:"There's more than enough to run a game or campaign from just the core book, which is how I prefer to run the solo game."},{text:"Advanced Fighting Fantasy is a role-playing game with simple mechanics that still provide ample detail, set in an interesting fantasy world."}]}}),registerSystem("alien",{groups:{default:{key:"fl",order:1},family:{key:"year-zero",order:1},genre:{key:"sci-fi",order:1}},name:"ALIEN RPG",publisher:"Free League / Year Zero Engine",dice:"Пул d6 (горсть шестигранных кубиков)",players:"3–5",complexity:3,foundryStatus:"Official контент",heroImage:"https://freeleaguepublishing.com/wp-content/uploads/2023/09/Jacksons-Star-Col-Price-3-1440x720.jpg",playstyleTags:["horror","survival","mystery"],settingTags:["space"],gallery:[{src:"https://freeleaguepublishing.com/wp-content/uploads/2023/08/Alien_8.jpg"},{src:"https://freeleaguepublishing.com/wp-content/uploads/2023/08/ALIEN-RPG-Colonial-Marines-Operations-Manual-1-2-green4-brighter-giant-1.jpg"},{src:"https://freeleaguepublishing.com/wp-content/uploads/2023/08/Alien_21-1.jpg"},{src:"https://freeleaguepublishing.com/wp-content/uploads/2023/08/ALIEN-RPG-Colonial-Marines1_C-3-scaled.jpg"}],resources:[{type:"link",url:"https://freeleaguepublishing.com/games/alien/",fmt:"Web"},{type:"sheet",url:"https://freeleaguepublishing.com/wp-content/uploads/2023/09/ALIEN_Character-Sheet.pdf",fmt:"PDF"},{type:"tool",url:"https://game-mother.com/cc.html",fmt:"Web"}],mechanics:[{icon:"radiation"},{icon:"drama"},{icon:"user-x"},{icon:"map"}],quotes:[{text:"Stealth mode is by far my favorite part of the Alien RPG. It's the height of the game's tension and the closest we get to the cinematic horror of the Alien movies.",author:"Mollie Russell, Wargamer"},{text:"Stress is essential in Alien. You don't count bullets or uncinematic concerns like that, but once your character is stressed enough they'll stop firing their gun and, well, start to be cannon fodder.",author:"Andrew Girdwood, Geek Native"}],ru:{tagShort:"Sci-fi хоррор по «Чужому»",tagline:"«В космосе никто не услышит ваш крик».",description:"Официальная RPG по вселенной «Чужого». Year Zero Engine с уникальной механикой стресса: чем больше паникуете, тем больше бросаете кубиков. Больше кубиков = выше шанс успеха, НО и выше шанс панической атаки. Два режима: кампания (долгая игра в космосе) и кинематографичный (ваншот-ужастик (приключение на одну сессию), как в фильмах).",setting:"2183 год. Корпорации колонизируют космос. Weyland-Yutani тянет щупальца к каждой обитаемой системе. За фасадом прогресса — рабочие-контрактники на забытых станциях, контрабандисты, колониальные морпехи и ксеноморфы, которые ждут в темноте. Лор охватывает все фильмы и расширяет вселенную.",vignette:"Стресс: 4. Вы слышите что-то в вентиляции. Бросаете на Наблюдательность — 3 обычных кубика и 4 кубика стресса. Два успеха! Но на кубике стресса — значок лицехвата. Паника. Бросаете по таблице... «Вы хватаете ближайшее оружие и наводите его на союзника.» За переборкой — шум. Ваш скрытый приказ гласит: «Принеси образец живым.»",prep:"~20 мин",mechanics:[{title:"Механика стресса",text:"Стресс даёт дополнительные кубики. Но значок лицехвата на кубике стресса = бросок паники (d6 + уровень стресса; результат 7+ запускает эффект по таблице). Таблица паники — от ступора до «вы стреляете в ближайшего»."},{title:"Кинематографичный режим",text:"Готовые сценарии с предгенами (готовыми персонажами). У каждого персонажа — скрытая повестка. Предательство встроено в систему."},{title:"Скрытые повестки",text:"Каждый персонаж получает карту с тайной целью. «Принеси образец на корабль» или «Убедись, что никто не вернётся»."},{title:"Кампейн-режим",text:"Полноценная кампания: корабль, команда, исследование космоса. Alien, но в формате sandbox."}],gallery:[{cap:"Интерьерный арт"},{cap:"Colonial Marines"},{cap:"Сцена из книги"},{cap:"Арт колониальных морпехов"}],resources:[{name:"Официальный сайт"},{name:"Официальный лист"},{name:"Генератор персонажей"}],quotes:[{text:"Режим скрытности — мой любимый элемент Alien RPG. Это пик напряжения, и ближайшее, что в TTRPG приближается к кинематографичному ужасу фильмов про Чужого."},{text:"Стресс — сердцевина Alien. Патроны и подобные некинематографичные мелочи здесь не считают, но если персонаж достаточно напряжён — он перестанет стрелять и превратится в пушечное мясо."}]},en:{tagShort:"Year Zero sci-fi horror RPG",tagline:'"In space no one can hear you scream."',description:"The official RPG set in the Alien universe. Year Zero Engine with a unique stress mechanic: the more you panic, the more dice you roll. More dice = higher chance of success, BUT also higher chance of a panic attack. Two modes: campaign (long-form space game) and cinematic (one-shot horror, just like the movies).",setting:"Year 2183. Corporations colonize space. Weyland-Yutani extends its tentacles to every inhabited system. Behind the facade of progress — contract workers on forgotten stations, smugglers, colonial marines, and xenomorphs waiting in the dark. The lore covers all the films and expands the universe.",vignette:"Stress: 4. You hear something in the vents. You roll Observation — 3 regular dice and 4 stress dice. Two successes! But a stress die shows the facehugger icon. Panic. You roll on the table... 'You grab the nearest weapon and aim it at an ally.' Behind the bulkhead — noise. Your secret order reads: 'Bring back the specimen alive.'",prep:"~20 min",mechanics:[{title:"Stress mechanic",text:"Stress grants extra dice. But a facehugger icon on a stress die = panic roll (d6 + stress level; 7+ triggers a table effect). The panic table ranges from freezing up to 'you shoot the nearest person.'"},{title:"Cinematic mode",text:"Ready-made scenarios with pre-gens. Each character has a hidden agenda. Betrayal is built into the system."},{title:"Hidden agendas",text:"Every character gets a card with a secret objective. 'Bring the specimen aboard' or 'Make sure nobody returns.'"},{title:"Campaign mode",text:"A full campaign: ship, crew, space exploration. Alien, but in sandbox format."}],gallery:[{cap:"Interior art"},{cap:"Colonial Marines"},{cap:"Scene from the book"},{cap:"Colonial marines art"}],resources:[{name:"Official website"},{name:"Official sheet"},{name:"Character generator"}]}}),registerSystem("apocalypse-world",{groups:{default:{key:"narrative",order:28},family:{key:"pbta-fitd",order:5},genre:{key:"post-apocalyptic",order:1}},name:"Apocalypse World",publisher:"Lumpley Games",dice:"2d6",players:"3–5",complexity:2,free:!1,foundryStatus:"None",heroImage:"https://static0.cbrimages.com/wordpress/wp-content/uploads/2020/09/Apocalypse-World-Cover.png",playstyleTags:["narrative","explore","combat"],settingTags:["postapoc"],gallery:[{src:"https://static0.cbrimages.com/wordpress/wp-content/uploads/2020/09/apocalypse-world-creatures.png"},{src:"https://img.itch.zone/aW1nLzI2Njk0NDIuanBn/original/IGjp5b.jpg"},{src:"https://static0.cbrimages.com/wordpress/wp-content/uploads/2020/09/Apocalypse-World-Cover.png"}],resources:[{type:"link",url:"http://apocalypse-world.com/",fmt:"Web"},{type:"link",url:"https://lumpley.itch.io/apocalypse-world",fmt:"Web"},{type:"link",url:"https://lumpley.games/apocalypseworld/",fmt:"Web"}],mechanics:[{icon:"sparkles"},{icon:"dices"},{icon:"book-open"},{icon:"scroll"}],quotes:[{text:"Ten years on, Powered by the Apocalypse games (PbtA) are everywhere. The Bakers designed the PbtA engine so that other game designers could 'hack' it, creating games with similar mechanics, but unique worlds and rules. More than four dozen games bear the PbtA license, making Apocalypse World incredibly influential.",author:"James Hanna, CBR"},{text:"Apocalypse World is both a roleplaying game and a really intense primer on D. Vincent Baker's approach to GMing a campaign. In fact, the primer is so intense that it's been baked right into the ruleset at a really primal level.",author:"Justin Alexander, The Alexandrian"}],ru:{tagShort:"Постапокалипсис на 2d6 — родоначальник PbtA",tagline:"«Мир мёртв. Правила просты. Истории — бесконечны».",description:"Apocalypse World — настольная RPG от Lumpley Games (2-е издание, 2019), родоначальник системы Powered by the Apocalypse (PbtA). 2d6: 10+ — полный успех, 7–9 — частичный, 6- — MC решает. Геймплей через Playbooks (шаблоны персонажей) и Moves (ходы), активируемые из фикции. Нулевой пресесс — мир рождается за столом. Влияние: Dungeon World, Masks, Blades in the Dark и десятки других.",setting:"Постапокалипсис без прописанного мира. Игроки создают мир вместе на первой сессии: что случилось, кто вы, что здесь происходит. Нет предwritten сеттинга — только архетипы и импровизация.",vignette:"MC: «Вы подходите к дому. Дверь приоткрыта. Изнутри — запах горелого мяса. Что делаете?» Гангстер ( playbook: Driver): «Заглядываю внутрь, держа пистолет наготове.» Бросок 2d6 + Sharp: 4+2 = 6. Провал. MC: «Дверь захлопывается. Вы слышите щелчок замка. И цепь.» Мир мёртв. Правила просты. Истории — бесконечны.",prep:"~5 мин (создание мира на первой сессии)",mechanics:[{title:"PbtA (2d6)",text:"Бросок 2d6 + модификатор: 10+ — полный успех, 7–9 — частичный (успех с осложнением), 6- — MC решает. Простая, но глубокая математика."},{title:"Playbooks",text:"Шаблоны персонажей: Driver, Chopper, Battlebabe, Hardholder и др. Каждый playbook — уникальные ходы, способности и конфликты."},{title:"Moves",text:"Действия, активируемые из фикции. Нет «атаки» или «проверки навыка» — есть «заходишь в ближний бой» или «TRIES to read a tense situation»."},{title:"MC не бросает кубики",text:"Master of Ceremonies (GM) описывает последствия через свои ходы. Игроки — единственные, кто берёт кубики в руки."}],gallery:[{cap:"Игровые существа"},{cap:"Обложка 2-го издания"},{cap:"Обложка (CBR)"}],resources:[{name:"Официальный сайт — apocalypse-world.com"},{name:"Itch.io — купить PDF"},{name:"Lumpley Games — дизайн-серия PbtA"}],quotes:[{text:"Десять лет спустя игры Powered by the Apocalypse повсюду. Бейкеры создали движок PbtA так, чтобы другие дизайнеры могли его 'хакать', создавая игры с похожими механиками, но уникальными мирами. Более четырех десятков игр носят лицензию PbtA, делая Apocalypse World невероятно влиятельной."},{text:"Apocalypse World — это и RPG, и очень интенсивный гайд по подходу Винсента Бейкера к ведению кампании. Гайд настолько интенсивен, что встроен прямо в правила на примитивном уровне."}]},en:{tagShort:"Post-apocalyptic 2d6 — the PbtA originator",tagline:'"The world is dead. The rules are simple. The stories are infinite."',description:"Apocalypse World is a tabletop RPG from Lumpley Games (2nd Edition, 2019), the originator of the Powered by the Apocalypse (PbtA) engine. 2d6: 10+ full success, 7–9 partial, 6- the MC decides. Gameplay through Playbooks (character archetypes) and Moves (actions triggered from fiction). Zero prep — the world is born at the table. Influence: Dungeon World, Masks, Blades in the Dark, and dozens more.",setting:"Post-apocalyptic with no pre-written world. Players create the world together in session 1: what happened, who you are, what's going on. No prewritten setting — only archetypes and improvisation.",vignette:"MC: 'You approach the house. Door ajar. Inside — the smell of burnt meat. What do you do?' The Gangster (playbook: Driver): 'I peer inside, pistol ready.' Roll 2d6 + Sharp: 4+2 = 6. Miss. MC: 'The door slams shut. You hear a lock click. And a chain.' The world is dead. The rules are simple. The stories are infinite.",prep:"~5 min (world creation in session 1)",mechanics:[{title:"PbtA (2d6)",text:"Roll 2d6 + modifier: 10+ full success, 7–9 partial (success with complication), 6- MC decides. Simple but deep math."},{title:"Playbooks",text:"Character archetypes: Driver, Chopper, Battlebabe, Hardholder, etc. Each playbook has unique moves, abilities, and conflicts."},{title:"Moves",text:"Actions triggered from fiction. No 'attack' or 'skill check' — there's 'going into melee' or 'trying to read a tense situation'."},{title:"MC Never Rolls",text:"The Master of Ceremonies (GM) describes consequences through their moves. Players are the only ones who touch the dice."}],gallery:[{cap:"In-game creatures"},{cap:"2nd Edition cover"},{cap:"Cover art (CBR)"}],resources:[{name:"Official site — apocalypse-world.com"},{name:"Itch.io — buy PDF"},{name:"Lumpley Games — PbtA design series"}],quotes:[{text:"Ten years on, Powered by the Apocalypse games (PbtA) are everywhere. The Bakers designed the PbtA engine so that other game designers could 'hack' it, creating games with similar mechanics, but unique worlds and rules. More than four dozen games bear the PbtA license, making Apocalypse World incredibly influential."},{text:"Apocalypse World is both a roleplaying game and a really intense primer on D. Vincent Baker's approach to GMing a campaign. In fact, the primer is so intense that it's been baked right into the ruleset at a really primal level."}]}}),registerSystem("ars-magica",{groups:{default:{key:"narrative",order:43},family:{key:"standalone",order:51},genre:{key:"historical",order:2}},name:"Ars Magica",publisher:"Atlas Games",dice:"d10",players:"3–6",complexity:5,free:!0,edition:"Definitive (5E)",foundryStatus:"Community",heroImage:"https://www.atlas-games.com/atlas-cms/resources/armdef-3d-full-white.jpg",playstyleTags:["worldbuild","narrative","explore"],settingTags:["fantasy","historical"],gallery:[{src:"https://www.atlas-games.com/atlas-cms/resources/08laboratorycolor.jpg"},{src:"https://www.atlas-games.com/atlas-cms/resources/armdef-interior-spreads-mockup.png"},{src:"https://www.atlas-games.com/atlas-cms/resources/images/display-part-2-nocorerulebook.png"}],resources:[{type:"link",url:"https://www.atlas-games.com/arsmagica/",fmt:"Web"},{type:"link",url:"https://www.atlas-games.com/arsmagica/openars",fmt:"Web"},{type:"rules",url:"https://www.drivethrurpg.com/en/product/329468/ars-magica-fifth-edition-digital",fmt:"PDF"},{type:"link",url:"https://foundryvtt.com/packages/arm5e",fmt:"VTT"}],mechanics:[{icon:"sparkles"},{icon:"users"},{icon:"castle"},{icon:"flask-conical"}],quotes:[{text:"The result is arguably the single most complete and deliberately comprehensive RPG product line to ever exist.",author:"Justin Alexander, The Alexandrian"},{text:"I often refer to Ars Magica as my dream game.",author:"Matthew J. Constantine"}],ru:{tagShort:"средневековая магическая сага",tagline:"«Волшебники Мифической Европы, где легенды — правда».",description:"Ars Magica делает вас могущественными волшебниками Мифической Европы — мира XIII века, где средневековые легенды буквально реальны. Знаменитая магическая система соединяет пять Техник (глаголы) с десятью Формами (существительными), позволяя импровизировать почти любой эффект. Игра ведётся «труппой»: каждый игрок водит мага, а также спутников и простых грогов, защищающих ковенант. Саги разворачиваются по сезонам — персонажи учатся, изобретают заклинания и растут десятилетиями. Глубокая, литературная и ни на что не похожая игра.",setting:"Мифическая Европа — это наши 1220-е годы, переосмысленные так, что легенды стали правдой: феи населяют леса, ангелы и демоны ведут войну Божественного и Инфернального, драконы спят под горами, а Орден Гермеса прячет свои ковенанты от Церкви, сжигающей ведьм. Вы играете за нелюдимых магов, владеющих истинной силой, — и за простых людей, втянутых в их орбиту.",vignette:"Грог кричит, когда ворота ковенанта раскалываются под топорами разбойников. У вашей маги нет готового заклинания, поэтому вы творите спонтанную магию: Рего Террам, чтобы подчинить землю. Складываете Рего 12 + Террам 8 + Выносливость 2 и бросаете стресс-кость — выпадает 7. Для спонтанной магии сумма делится пополам: 14 против уровня эффекта — достаточно. Булыжники двора встают стеной, и налётчики бросаются врассыпную.",prep:"~45 мин",mechanics:[{title:"Техники и Формы",text:"Пять Техник (Крео, Интеллего, Муто, Пердо, Рего) сочетаются с десятью Формами вроде Игнем или Корпус. Соедините глагол и существительное — и импровизируйте почти любой магический эффект на ходу."},{title:"Игра труппой",text:"Никто не владеет одним героем. Каждый игрок водит могучего мага, разносторонних спутников и расходных грогов, а роль ведущего может переходить по кругу между сессиями."},{title:"Ковенант и сага",text:"Ваш ковенант — это общий дом, библиотека и наследие. Кампании — это саги длиной в годы, и вся труппа вместе строит и защищает этот живой институт."},{title:"Сезоны в лаборатории",text:"Время идёт сезонами. Между приключениями маги уходят в лаборатории: изобретают заклинания, зачаровывают предметы, добывают вис (сырую магию) и оттачивают своё Искусство."}],gallery:[{cap:"В лаборатории ковенанта"},{cap:"Полноцветные развороты книги"},{cap:"Коллекционное издание Definitive"}],resources:[{name:"Официальный сайт Ars Magica"},{name:"Открытая лицензия (бесплатный CC-текст)"},{name:"PDF Пятой редакции (DriveThruRPG)"},{name:"Система для Foundry VTT"}],quotes:[{text:"Пожалуй, это самая полная и целенаправленно всеобъемлющая линейка ролевых продуктов из когда-либо существовавших."},{text:"Я часто называю Ars Magica игрой моей мечты."}]},en:{tagShort:"medieval wizard saga",tagline:'"Wizards of Mythic Europe, where legend is literally true."',description:"Ars Magica casts you as powerful wizards in Mythic Europe — a 13th-century world where medieval myth is real. Its celebrated magic pairs five Techniques (verbs) with ten Forms (nouns), letting you improvise almost any effect. Play is troupe-style: everyone runs a magus, plus the companions and common grogs who defend the covenant. Sagas unfold across seasons, with characters studying, inventing spells, and growing over decades. Deep, literary, and unlike anything else in the hobby.",setting:"Mythic Europe is our own 1220s reimagined so legend is real: faeries haunt the forests, angels and demons wage the Divine and Infernal war, dragons sleep beneath mountains, and the Order of Hermes hides its covenants from a Church that burns witches. You play the reclusive magi who wield true power — and the mundane folk caught in their orbit.",vignette:"A grog screams as the covenant gate splinters under bandit axes. Your maga has no spell for this, so you cast spontaneously: Rego Terram to seize the earth. You total Rego 12 + Terram 8 + Stamina 2 and roll the stress die — a 7. Halved for spontaneous magic, that's 14 against the effect's level: enough. The courtyard cobbles rear up like a wall, and the raiders scatter.",prep:"~45 min",mechanics:[{title:"Techniques & Forms",text:"Five Techniques (Creo, Intellego, Muto, Perdo, Rego) combine with ten Forms like Ignem or Corpus. Pair a verb and a noun to improvise nearly any magical effect on the fly."},{title:"Troupe Play",text:"Nobody owns one hero. Each player runs a mighty magus, versatile companions, and expendable grogs, and the storyguide role can pass around the table between sessions."},{title:"Covenant & Saga",text:"Your covenant is a shared home, library, and legacy. Campaigns are sagas spanning years, and the whole troupe builds and defends this living institution together."},{title:"Seasons in the Lab",text:"Time advances in seasons. Between adventures, magi retreat to their laboratories to invent spells, enchant items, extract raw magic (vis), and slowly master their Arts."}],gallery:[{cap:"Inside a covenant laboratory"},{cap:"Full-color interior spreads"},{cap:"The Definitive Edition set"}],resources:[{name:"Official Ars Magica site"},{name:"Open License (free CC text)"},{name:"Fifth Edition PDF (DriveThruRPG)"},{name:"Foundry VTT system"}],quotes:[{text:"The result is arguably the single most complete and deliberately comprehensive RPG product line to ever exist."},{text:"I often refer to Ars Magica as my dream game."}]}}),registerSystem("avatar-legends",{groups:{default:{key:"narrative",order:47},family:{key:"pbta-fitd",order:33},genre:{key:"adventure",order:28}},name:"Avatar Legends: The Roleplaying Game",publisher:"Magpie Games",dice:"2d6 + stat/approach (PbtA)",players:"3–6",complexity:3,free:!1,edition:null,foundryStatus:"Community",heroImage:"https://magpiegames.com/cdn/shop/files/Avatar-Core_1.jpg",playstyleTags:["narrative","action","social"],settingTags:["fantasy"],gallery:[{src:"https://magpiegames.com/cdn/shop/files/Avatar-Core_2.jpg"},{src:"https://magpiegames.com/cdn/shop/files/Avatar-Republic-City_1.jpg"},{src:"https://magpiegames.com/cdn/shop/files/Avatar-UIAG_1.jpg"}],resources:[{type:"link",url:"https://magpiegames.com/collections/avatar-legends",fmt:"Web"},{type:"link",url:"https://foundryvtt.com/packages/legends",fmt:"Foundry"}],mechanics:[{icon:"dices"},{icon:"scale"},{icon:"flame"},{icon:"swords"}],quotes:[{text:"If you're looking for a game that feels like an episode of Avatar: the Last Airbender or The Legend of Korra, this is it.",author:"Ian Howard, Meeple Mountain"},{text:"The game is fine, it probably plays a lot nicer than D&D to be honest.",author:"Aaron Marks, Cannibal Halfling Gaming"}],ru:{tagShort:"PbtA по «Аватару» и «Легенде о Корре»",tagline:"«Власть над стихией — ничто без равновесия внутри».",description:"Avatar Legends: The Roleplaying Game — официальная ролевая игра Magpie Games по «Аватару: Легенде об Аанге» и «Легенде о Корре» на движке Powered by the Apocalypse. Вы и ваша группа собираете отряд юных героев в любой эпохе мира Аватара, покоряете четыре стихии и решаете конфликты словом не реже, чем кулаком. Игра о взрослении, дружбе и борьбе между двумя сторонами собственной личности.",setting:"Мир четырёх народов — Воды, Земли, Огня и Воздуха — во все эпохи, от романов о Киоши до индустриального Республиканского города Корры. Маги стихий и обычные люди живут среди войн, политики, духов и личных распрей. Вы выбираете эпоху и стартовый конфликт и рассказываете свою историю в живом мире боевых искусств и нравственного выбора.",vignette:"Маг огня загоняет вашу магиню воды в угол на причале. Вы выбираете подход «Наступать и атаковать» и бросаете 2d6 + подход: выпадает 8. Успех с осложнением — вы наносите удар и накладываете Статус, но тратите Усталость на приём, и ведущий сдвигает ваше Равновесие к Страсти. Перешагнёте +3 — потеряете контроль; ещё один удар по чувствам — и вместо этого вы отмечаете состояние «Злость».",prep:"~15 мин",mechanics:[{title:"Ходы на 2d6 (PbtA)",text:"Любое действие — это ход: 2d6 плюс характеристика или боевой подход. 10+ — чистый успех, 7–9 — успех с ценой, 6 и ниже отдаёт инициативу ведущему."},{title:"Равновесие между Принципами",text:"Каждый плейбук растягивает персонажа между двумя противоположными Принципами. Игра двигает вас по шкале; в центре открывается момент Равновесия раз за сезон, но выход за +3 — потеря контроля."},{title:"Усталость, Состояния, Статусы",text:"Три связанных трека. Усталость питает сильнейшие приёмы; когда она заполнена, вы отмечаете Состояния — Страх, Злость, Вину, Неуверенность, Смятение, — мешающие ходам, пока вы их не отыграете. Бой оставляет всем Статусы."},{title:"Техники и обмены ударами",text:"Бой идёт обменами: бойцы выбирают подходы и тратят изученные Техники — фирменные формы магии и боевые приёмы, — превращая схватку в напряжённый кинематографичный диалог, а не в подсчёт хитов."}],gallery:[{cap:"Основная книга — задняя обложка"},{cap:"Сурсбук по Республиканскому городу"},{cap:"Дополнение по эпохе"}],resources:[{name:"Официальная страница — Magpie Games"},{name:"Народная система для Foundry VTT"}],quotes:[{text:"Если вы ищете игру, которая ощущается как серия «Аватара: Легенды об Аанге» или «Легенды о Корре», — вот она."},{text:"Игра нормальная и, честно говоря, играется куда приятнее, чем D&D."}]},en:{tagShort:"PbtA in the world of Avatar and Korra",tagline:'"Power over the elements means nothing without balance within."',description:"Avatar Legends: The Roleplaying Game is Magpie Games' official RPG for Avatar: The Last Airbender and The Legend of Korra, built on Powered by the Apocalypse. You and your group form a company of young heroes in any era of the Avatarverse, bending the four elements and settling conflicts as often with words as with fists. It's a game about growth, community, and the pull between two sides of who you are.",setting:"The world of the four nations — Water, Earth, Fire, Air — across every era, from the Kyoshi novels to Korra's industrial Republic City. Benders and non-benders alike navigate war, politics, spirits, and personal rivalries. You pick an era and a starting conflict, then tell your own story in a lived-in world of martial-arts action and moral weight.",vignette:"A firebending duelist corners your waterbender on the pier. You commit to the Advance & Attack approach and roll 2d6 + that approach: an 8. Success with a catch — you land the hit and inflict a Status, but you mark Fatigue to power it, and the GM shifts your Balance toward Passion. Push past +3 and you lose control; take one more blow to the heart and you're marking the Angry condition instead.",prep:"~15 min",mechanics:[{title:"2d6 moves (PbtA)",text:"Every action is a move: roll 2d6 plus a stat or combat approach. 10+ hits clean, 7–9 succeeds with a cost, 6 or under hands the GM the initiative."},{title:"Balance between two Principles",text:"Each playbook stretches your character between two opposed Principles. Play shifts you along the track; reach the center to unlock a once-a-season moment of Balance, but overreach past +3 and you lose control."},{title:"Fatigue, Conditions, Statuses",text:"Three interlocking tracks. Fatigue fuels your strongest moves; when it fills you mark Conditions — Afraid, Angry, Guilty, Insecure, Troubled — that penalize moves until you act on them. Combat leaves Statuses on everyone."},{title:"Techniques and exchanges",text:"Combat runs as exchanges where fighters choose approaches and spend learned Techniques — signature bending forms and martial moves — turning a fight into a tense, cinematic back-and-forth rather than a hit-point grind."}],gallery:[{cap:"Core rulebook — back cover"},{cap:"Republic City sourcebook"},{cap:"Era supplement cover"}],resources:[{name:"Official page — Magpie Games"},{name:"Community Foundry VTT system"}],quotes:[{text:"If you're looking for a game that feels like an episode of Avatar: the Last Airbender or The Legend of Korra, this is it."},{text:"The game is fine, it probably plays a lot nicer than D&D to be honest."}]}}),registerSystem("basic-fantasy",{groups:{default:{key:"osr",order:12},family:{key:"osr-classic",order:7},genre:{key:"adventure",order:14}},name:"Basic Fantasy RPG",publisher:"Chris Gonnerman / Basic Fantasy RPG",dice:"d20 + variable weapon damage",players:"3–6",complexity:2,edition:"B/X",free:!0,foundryStatus:"Community",heroImage:"https://image.nobleknight.com/b/jpg1500/basicfantasy4thed.jpg",playstyleTags:["explore","combat","sandbox"],settingTags:["fantasy"],gallery:[],resources:[{type:"link",url:"https://basicfantasy.org/",fmt:"Web"},{type:"quickstart",url:"https://basicfantasy.org/downloads.html",fmt:"Web"}],mechanics:[{icon:"shield"},{icon:"users"},{icon:"gift"},{icon:"book-open"}],quotes:[{text:"Overall, this game does what it sets out to do, and does it with conviction. It's an inexpensive, exhaustive, and approachable system.",author:"M Harold Page, Black Gate"},{text:"It captures the spirit of old-school fantasy adventure without burying players under archaic mechanics and obtuse formatting.",author:"Serban Ionita, The RPG Gazette"}],ru:{tagShort:"Бесплатный community-клон B/X",tagline:"«Классическая D&D 1981 года — бесплатно, начисто и с апгрейдами удобства».",description:"Basic Fantasy RPG — полностью бесплатный ретроклон D&D Basic/Expert (B/X) 1981 года, который сообщество развивает с 2006-го. Крис Гоннерман взял B/X и внёс два ключевых улучшения: восходящий класс брони и раса отдельно от класса. Десятки бесплатных приключений и супплементов, живой форум, открытая лицензия. Самая экономичная точка входа в OSR.",setting:"Система-агностик с духом классического меча-и-магии. Подземелья, деревни на фронтире, драконы и забытые гробницы. Тон — приземлённое героическое фэнтези старой школы: свеча, десятифутовый шест, картирование по клеточкам и жадность как двигатель сюжета. Любой модуль B/X идёт почти без конвертации.",vignette:"Отряд спускается по верёвке в затопленный склеп. Вор идёт первым — проверка на поиск ловушек. Дальше коридор с гулями. Боец бьёт: d20 + бонус атаки против восходящего AC гуля 13. Выпало 16 — попадание, бросок урона по оружию (длинный меч — d8). Гуль огрызается когтями. Свеча оплывает; отряд решает: вперёд к добыче или назад к свету.",prep:"~30 мин",mechanics:[{title:"Восходящий класс брони",text:"В отличие от оригинального B/X с нисходящим AC, здесь AC растёт — чем выше, тем лучше. Интуитивно для новичков и совместимо с современными привычками d20."},{title:"Раса отдельно от класса",text:"Не «раса-как-класс» из B/X: выбираете расу и класс независимо. Дварф-маг или полурослик-вор — без ограничений старой школы, но в её духе."},{title:"Полностью бесплатно",text:"Все правила и десятки супплементов — бесплатные PDF на basicfantasy.org под открытой лицензией. Печатные копии — по себестоимости. Community-проект без коммерции."},{title:"Совместимость с B/X",text:"Монстры, заклинания и процедуры совместимы с классической линейкой. Любое приключение B/X или OSR запускается почти без правок."}],gallery:[],resources:[{name:"Официальный сайт — всё бесплатно"},{name:"Бесплатные загрузки (правила, листы, супплементы)"}],quotes:[{text:"В целом игра делает то, что задумано, и делает это с убеждённостью. Недорогая, исчерпывающая и доступная система."},{text:"Она передаёт дух олдскульного фэнтезийного приключения, не погребая игроков под архаичными механиками и путаной вёрсткой."}]},en:{tagShort:"The free, community-built B/X clone",tagline:'"Classic 1981 D&D — free, clean, and quietly upgraded."',description:"Basic Fantasy RPG is a fully free retroclone of 1981 D&D Basic/Expert (B/X), developed by its community since 2006. Chris Gonnerman took B/X and made two key upgrades: ascending armor class, and race decoupled from class. Dozens of free adventures and supplements, an active forum, and an open license. The most economical on-ramp into the OSR.",setting:"Setting-agnostic with a classic sword-and-sorcery spirit. Dungeons, frontier villages, dragons, and forgotten tombs. The tone is grounded old-school heroic fantasy: the candle, the ten-foot pole, graph-paper mapping, and greed as the engine of the plot. Any B/X module runs with almost no conversion.",vignette:"The party ropes down into a flooded crypt. The thief goes first — a check to find traps. Ahead, a corridor of ghouls. The fighter swings: d20 + attack bonus against the ghoul's ascending AC 13. He rolls a 16 — a hit, then damage by weapon (longsword, d8). The ghoul rakes back with its claws. The candle gutters; the party decides — press on toward the loot, or fall back to the light.",prep:"~30 min",mechanics:[{title:"Ascending armor class",text:"Unlike original B/X's descending AC, here armor class goes up — higher is better. Intuitive for newcomers and compatible with modern d20 instincts."},{title:"Race separate from class",text:"No B/X 'race-as-class': you pick race and class independently. A dwarf magic-user or a halfling thief — free of the old-school restriction, but true to its feel."},{title:"Completely free",text:"All rules and dozens of supplements are free PDFs on basicfantasy.org under an open license. Print copies are sold at cost. A community project, not a commercial one."},{title:"B/X compatible",text:"Monsters, spells, and procedures are compatible with the classic line. Any B/X or OSR adventure runs with almost no editing."}],gallery:[],resources:[{name:"Official site — everything is free"},{name:"Free downloads (rules, sheets, supplements)"}],quotes:[{text:"Overall, this game does what it sets out to do, and does it with conviction. It's an inexpensive, exhaustive, and approachable system."},{text:"It captures the spirit of old-school fantasy adventure without burying players under archaic mechanics and obtuse formatting."}]}}),registerSystem("black-sword-hack",{groups:{default:{key:"osr",order:26},family:{key:"osr-modern",order:4},genre:{key:"sword-and-sorcery",order:7}},name:"Black Sword Hack",publisher:"The Merry Mushmen",dice:"d20 roll-under + d6 Doom Die",players:"3–6",complexity:2,free:!0,foundryStatus:"Community",heroImage:"https://www.themerrymushmen.com/wp-content/uploads/2023/01/BSH-COVER.jpg",playstyleTags:["combat","explore","survival"],settingTags:["fantasy","sword-and-sorcery"],gallery:[{src:"https://www.themerrymushmen.com/wp-content/uploads/2022/12/BSH-Book_Mockup_01BBAP.jpg"},{src:"https://www.themerrymushmen.com/wp-content/uploads/2022/12/BSH-MockupCREA.jpg"},{src:"https://www.themerrymushmen.com/wp-content/uploads/2022/12/BSH-MockupBASEADVS-scaled.jpg"}],resources:[{type:"link",url:"https://www.themerrymushmen.com/product/black-sword-hack-ultimate-chaos-edition/",fmt:"Web"}],mechanics:[{icon:"swords"},{icon:"dices"},{icon:"hourglass"},{icon:"infinity"}],quotes:[{text:"combat is much more fraught with danger, which makes sense, given its literary inspirations.",author:"James Maliszewski, Grognardia"},{text:"Black Sword Hack is tight (and short), and it would be hard to pad out a review of the game into a full article.",author:"Aaron Marks, Cannibal Halfling Gaming"}],ru:{tagShort:"Меч-и-магия в духе Муркока на Black Hack",tagline:"«Ты обречён. Вопрос лишь — сколько успеешь до того, как Рок настигнет».",description:"Black Sword Hack — OSR-игра тёмного меча-и-магии на движке The Black Hack, вдохновлённая Вечным Воителем Муркока и обречёнными антигероями вроде Элрика. Бесклассовые герои, определяемые Происхождением и Предысторией, ставят судьбу на Кость Рока — она тает, пока ты опираешься на удачу. Мультивселенная вечной борьбы Хаоса и Закона со встроенными инструментами генерации мира.",setting:"Мрачная мультивселенная на грани катастрофы, где Хаос и Закон рвут реальность на части. Проклятые мечи, чуждые боги, гибнущие империи и герои, отмеченные роком. Тон — трагический пульп в духе Элрика: сила всегда с ценой, победа всегда с горчинкой. Генераторы в правилах соберут ваш умирающий мир на лету.",vignette:"Наёмник загнан в угол cult-истами. Он призывает Кость Рока — d6 к броску, чтобы прорваться. Успех: клинок находит горло жреца. Но Кость Рока брошена — если выпала 1–2, она уменьшается (d6→d4). Ещё пара таких рывков — и Рок иссякнет. А когда он иссякает, вселенная взыскивает долг сполна.",prep:"~10 мин",mechanics:[{title:"Броски «меньше» на d20",text:"Ядро The Black Hack: проверка — d20 «меньше-равно» характеристики, игроки делают все броски. Лёгкая, быстрая, летальная система, знакомая всему семейству хаков."},{title:"Кость Рока",text:"Особый ресурс: призови Кость Рока (d6), чтобы усилить действие. Но на 1–2 она уменьшается. Когда истощится — на героя обрушивается Рок. Механическая метафора обречённости антигероя."},{title:"Бесклассовость: Происхождение и Предыстория",text:"Классов нет. Персонажа задают Происхождение (человек, полукровка, порождение Хаоса…) и Предыстория. Гибко и мрачно — как и подобает миру Вечного Воителя."},{title:"Хаос против Закона + генераторы",text:"Сеттинг вечной войны Хаоса и Закона встроен в механику, а таблицы-генераторы (фракции, чужие боги, руины) собирают умирающую мультивселенную прямо за столом."}],gallery:[{cap:"Разворот книги"},{cap:"Бестиарий"},{cap:"Приключения"}],resources:[{name:"Официальная страница — The Merry Mushmen"}]},en:{tagShort:"Moorcockian sword-and-sorcery on The Black Hack",tagline:'"You are doomed. The only question is how much you get done before Doom catches up."',description:"Black Sword Hack is a dark sword-and-sorcery OSR game on The Black Hack engine, drawing on Moorcock's Eternal Champion and doomed antiheroes like Elric. Classless heroes, defined by Origin and Background, stake their fate on a Doom Die that erodes as they lean on luck. A multiverse locked in the eternal struggle of Chaos and Law, with world-building tools baked into the rules.",setting:"A grim multiverse on the brink of catastrophe, where Chaos and Law tear reality apart. Cursed swords, alien gods, dying empires, and heroes marked by doom. The tone is tragic pulp in the Elric vein: power always has a price, victory always a bitter edge. Generator tables in the rules assemble your dying world on the fly.",vignette:"The mercenary is cornered by cultists. He invokes the Doom Die — a d6 added to the roll to break free. Success: the blade finds the priest's throat. But the Doom Die is cast — on a 1–2 it shrinks (d6→d4). A few more such gambits and the Doom runs out. And when it does, the universe collects its debt in full.",prep:"~10 min",mechanics:[{title:"Roll-under d20",text:"The Black Hack core: a test is d20 roll-under your attribute, and players make all the rolls. A light, fast, lethal system familiar to the whole family of Hacks."},{title:"The Doom Die",text:"A special resource: invoke the Doom Die (a d6) to boost an action. But on a 1–2 it shrinks. When it's spent, Doom befalls the hero. A mechanical metaphor for the antihero's doom."},{title:"Classless: Origin & Background",text:"No classes. A character is defined by Origin (human, half-breed, spawn of Chaos…) and Background. Flexible and grim — as befits the world of the Eternal Champion."},{title:"Chaos vs Law + generators",text:"The setting's eternal war of Chaos and Law is built into the mechanics, and generator tables (factions, alien gods, ruins) assemble the dying multiverse right at the table."}],gallery:[{cap:"Book spread"},{cap:"Bestiary"},{cap:"Adventures"}],resources:[{name:"Official page — The Merry Mushmen"}]}}),registerSystem("blade-runner",{groups:{default:{key:"fl",order:2},family:{key:"year-zero",order:2},genre:{key:"sci-fi",order:2}},name:"Blade Runner",publisher:"Free League / Year Zero Engine",dice:"Пул d6–d12",players:"2–4",complexity:3,foundryStatus:"Official",heroImage:"https://freeleaguepublishing.com/wp-content/uploads/2023/08/BLADE-RUNNER-RPG-Art-01-1440x720.jpg",playstyleTags:["mystery","narrative","social"],settingTags:["cyberpunk"],gallery:[{src:"https://newsite.freeleaguepublishing.com/wp-content/uploads/2023/08/BLADE-RUNNER-RPG-Art-03-edited.jpg"},{src:"https://newsite.freeleaguepublishing.com/wp-content/uploads/2023/08/BLADE-RUNNER-RPG-Art-04-edited.jpg"},{src:"https://freeleaguepublishing.com/wp-content/uploads/2023/08/BLADE-RUNNER-RPG-Art-06.jpg"},{src:"https://freeleaguepublishing.com/wp-content/uploads/2023/08/BLADE-RUNNER-RPG-Art-08-edited.jpg"},{src:"https://freeleaguepublishing.com/wp-content/uploads/2023/08/BLADE-RUNNER-RPG-Art-13.jpg"},{src:"https://freeleaguepublishing.com/wp-content/uploads/2023/08/BLADE-RUNNER-RPG-Art-09-edited.jpg"}],resources:[{type:"link",url:"https://freeleaguepublishing.com/games/blade-runner-rpg/",fmt:"Web"},{type:"sheet",url:"https://freeleaguepublishing.com/wp-content/uploads/2023/09/Blade_Runner_Character_Sheet_220811.pdf",fmt:"PDF"}],mechanics:[{icon:"fingerprint"},{icon:"bot"},{icon:"layout-grid"},{icon:"handshake"}],quotes:[{text:"I don't like to use the word 'perfect' often, but I'm going there now. The Blade Runner RPG captures the themes and feel of the source material perfectly.",author:"Mollie Russell, Wargamer"},{text:"Blade Runner is a well-executed RPG, it is exactly Blade Runner the RPG and not one thing more.",author:"Aaron Marks, Cannibal Halfling Gaming"}],ru:{tagShort:"Нуар-детектив с репликантами",tagline:"«Детектив о морали, памяти и бесконечном дожде».",description:"RPG-детектив в мире Blade Runner 2037. Вы — Blade Runners, детективы LAPD, расследующие дела, связанные с репликантами. Система заточена под расследования: анализ улик, допросы, моральные дилеммы. Не экшн-игра — нуарный процедурал.",setting:"Лос-Анджелес 2037 года. Неоновый дождь, гигантские голограммы, внеземные колонии. Репликанты нового поколения живут среди людей, и граница между «человеком» и «машиной» стёрта окончательно. Корпорации контролируют всё, а улицы полны отчаяния.",vignette:"Дневная смена. Вы допрашиваете свидетеля — женщину, которая клянётся, что видела, как её сосед заплакал маслом. Бросок Эмпатии: два шестигранника и один десятигранник. Успех — она лжёт. Вы проверяете её запястье. Серийный номер. Она — репликант. И вы понимаете, что у вас точно такой же шрам на том же месте.",prep:"~25 мин",mechanics:[{title:"Система улик",text:"Каждое дело — сеть улик, связей и свидетелей. Механика расследования структурирована, но не линейна."},{title:"Человечность",text:"Механика Humanity. Как далеко вы зайдёте, чтобы остаться человеком? А если вы — репликант и не знаете об этом?"},{title:"Шифт-система",text:"Рабочие смены структурируют время. Каждая смена — ограниченное количество действий. Тайм-менеджмент как геймплей."},{title:"Напарники",text:"Человек + репликант в одном отделе. Встроенное напряжение между игроками с первой сессии."}],gallery:[{cap:"Улицы Лос-Анджелеса"},{cap:"Неоновый город"},{cap:"Расследование"},{cap:"Blade Runner"},{cap:"Сцена допроса"},{cap:"Город"}],resources:[{name:"Официальный сайт"},{name:"Официальный лист"}],quotes:[{text:"Я редко использую слово «идеально», но здесь иначе никак. Blade Runner RPG идеально передаёт темы и атмосферу первоисточника."},{text:"Blade Runner — отлично сделанная RPG: ровно настолько Blade Runner, насколько нужно, и ни на грамм больше."}]},en:{tagShort:"neo-noir detective RPG",tagline:'"A detective story about morality, memory, and endless rain."',description:"A detective RPG set in the world of Blade Runner 2037. You are Blade Runners, LAPD detectives investigating cases involving replicants. The system is designed for investigations: analyzing evidence, interrogations, moral dilemmas. Not an action game — a noir procedural.",setting:"Los Angeles, 2037. Neon rain, colossal holograms, off-world colonies. New generation replicants live among humans, and the line between 'human' and 'machine' has been erased entirely. Corporations control everything, and the streets overflow with despair.",vignette:"Day shift. You're interrogating a witness — a woman who swears she saw her neighbor cry oil. Empathy roll: two d6s and one d10. Success — she's lying. You check her wrist. A serial number. She's a replicant. And you realize you have the exact same scar in the exact same spot.",prep:"~25 min",mechanics:[{title:"Evidence system",text:"Each case is a web of clues, connections, and witnesses. The investigation mechanic is structured but non-linear."},{title:"Humanity",text:"Humanity mechanic. How far will you go to remain human? What if you're a replicant and don't know it?"},{title:"Shift system",text:"Work shifts structure time. Each shift has a limited number of actions. Time management as gameplay."},{title:"Partners",text:"Human + replicant in the same unit. Built-in tension between players from session one."}],gallery:[{cap:"Streets of Los Angeles"},{cap:"Neon city"},{cap:"Investigation"},{cap:"Blade Runner"},{cap:"Interrogation scene"},{cap:"The city"}],resources:[{name:"Official website"},{name:"Official sheet"}]}}),registerSystem("blades",{groups:{default:{key:"narrative",order:5},family:{key:"pbta-fitd",order:1},genre:{key:"narrative-weird",order:1}},name:"Blades in the Dark",publisher:"John Harper / One Seven Design",dice:"Пул d6",players:"3–5",complexity:3,foundryStatus:"Community",heroImage:"https://legendary-digital-network-assets.s3.amazonaws.com/geekandsundry/wp-content/uploads/2018/05/Vigilantes.jpg",playstyleTags:["narrative","social","combat"],settingTags:["urban-fantasy"],gallery:[],resources:[{type:"link",url:"https://bladesinthedark.com/",fmt:"Web"},{type:"rules",url:"https://bladesinthedark.com/greetings-scoundrel",fmt:"Web"},{type:"sheet",url:"https://bladesinthedark.com/sites/default/files/blades_playerkit_v8_2.pdf",fmt:"PDF"},{type:"sheet",url:"https://bladesinthedark.com/sites/default/files/sheets/blades_sheets_v8_2_Blank_Character_Sheet.pdf",fmt:"PDF"},{type:"sheet",url:"https://bladesinthedark.com/sites/default/files/sheets/blades_sheets_v8_2_Factions.pdf",fmt:"PDF"}],mechanics:[{icon:"clock"},{icon:"building"},{icon:"settings"},{icon:"moon"}],quotes:[{text:"Imagine a Georgian George Clooney walking everybody through an Oceans 11-style heist, revealing bits of the plan as obstacles come up.",author:"Quinns, Shut Up & Sit Down"},{text:"Blades in the Dark is an extraordinary system – a work of proper genius – and a worthy recipient of the third five star rating we've ever given out for the site.",author:"Michael Heron, Meeple Like Us"}],ru:{tagShort:"Криминальная FitD-RPG",tagline:"«Вы — банда отчаянных в тёмном городе, который никогда не спит».",description:"RPG про криминальную банду в тёмном индустриальном городе. Революционная система: никакого планирования операций заранее — вместо этого флешбэки во время дела. «Что-то идёт не так? Я УЖЕ подкупил охранника вчера». Между делами — фаза даунтайма (отдых между приключениями): лечение, тренировки, развитие базы.",setting:"Досквол — город, освещённый электрическими барьерами от призраков. Вокруг — мёртвые земли, населённые духами. Внутри — фракции, контролирующие районы: от Серых Плащей (полиция) до Духовных Стражей. Индустриальная готика, демоны и кровь на булыжниках.",vignette:"Вы в хранилище Серых Плащей. Замок — выше ваших навыков. «Флешбэк,» — говорит Вор. «Вчера я подкупил слесаря, он оставил дверь открытой.» Бросок — 4 на лучшем из двух d6. Частичный успех: дверь открыта, но слесарь оставил записку начальнику. Позиция: отчаянная. Эффект: обычный. Часы «Тревога» заполняются на 2 из 6.",prep:"~10 мин",mechanics:[{title:"Флешбэки",text:"Не планируйте заранее. Когда что-то идёт не так — заявите флешбэк: «Я уже подготовился к этому вчера»."},{title:"Банда как персонаж",text:"Репутация, территория, союзники, враги. Банда развивается вместе с игроками."},{title:"Позиция и Эффект",text:"Каждый бросок: насколько опасно + насколько мощный результат. Две оси — бесконечная гибкость."},{title:"Даунтайм",text:"Между делами: лечение, тренировки, развитие базы, длительные проекты. Отдельная мини-игра."}],gallery:[],resources:[{name:"Официальный сайт"},{name:"Полный SRD (вся игра бесплатно!)"},{name:"Player's Kit (все листы)"},{name:"Чистый лист персонажа"},{name:"Лист фракций"}],quotes:[{text:"Представь Джорджа Клуни в эпоху Регентства, который ведёт команду через ограбление в стиле «11 друзей Оушена», раскрывая части плана по мере того, как возникают препятствия."},{text:"Blades in the Dark — выдающаяся система, настоящая гениальность, и достойная обладательница третьей в истории сайта оценки в пять звёзд."}]},en:{tagShort:"FitD heist & crime RPG",tagline:`"You're a gang of scoundrels in a dark city that never sleeps."`,description:"An RPG about a criminal gang in a dark industrial city. A revolutionary system: no planning operations in advance — instead, flashbacks during the job. 'Something goes wrong? I ALREADY bribed the guard yesterday.' Between jobs — a downtime phase: healing, training, upgrading your lair.",setting:"Doskvol — a city lit by electric barriers against ghosts. Beyond — dead lands inhabited by spirits. Within — factions controlling districts: from the Bluecoats (police) to the Spirit Wardens. Industrial gothic, demons, and blood on the cobblestones.",vignette:"You're in the Bluecoats' vault. The lock is beyond your skills. 'Flashback,' says the Lurk. 'Yesterday I bribed the locksmith — he left the door open.' Roll — 4 on the best of two d6. Partial success: the door is open, but the locksmith left a note to his boss. Position: desperate. Effect: standard. The 'Alert' clock fills 2 of 6.",prep:"~10 min",mechanics:[{title:"Flashbacks",text:"Don't plan ahead. When something goes wrong — declare a flashback: 'I already prepared for this yesterday.'"},{title:"Crew as character",text:"Reputation, territory, allies, enemies. The crew develops alongside the players."},{title:"Position and Effect",text:"Every roll: how dangerous + how powerful the result. Two axes — infinite flexibility."},{title:"Downtime",text:"Between jobs: healing, training, lair upgrades, long-term projects. A separate mini-game."}],gallery:[],resources:[{name:"Official website"},{name:"Full SRD (entire game for free!)"},{name:"Player's Kit (all sheets)"},{name:"Blank character sheet"},{name:"Factions sheet"}]}}),registerSystem("brindlewood-bay",{groups:{default:{key:"narrative",order:46},family:{key:"pbta-fitd",order:32},genre:{key:"horror",order:16}},name:"Brindlewood Bay",publisher:"The Gauntlet",dice:"2d6",players:"2–5",complexity:2,free:!1,edition:null,foundryStatus:"Community",heroImage:"https://image.nobleknight.com/2/jpg1500/24090740087h.jpg",playstyleTags:["mystery","narrative","social"],settingTags:["modern","weird"],gallery:[{src:"https://netherbook.com/cdn/shop/files/brindlewood-bay-a-dark-cozy-mystery-7145627.webp?v=1765001473&width=1946"},{src:"https://netherbook.com/cdn/shop/files/brindlewood-bay-a-dark-cozy-mystery-9875193.webp?v=1765001473&width=1946"},{src:"https://www.gauntlet-rpg.com/uploads/7/7/8/1/77811662/editor/551319902.png?1733167270"}],resources:[{type:"link",url:"https://www.gauntlet-rpg.com/brindlewood-bay.html",fmt:"Web"},{type:"rules",url:"https://www.drivethrurpg.com/en/product/410316/brindlewood-bay-kickstarter-edition",fmt:"PDF/Print"},{type:"quickstart",url:"https://www.gauntlet-rpg.com/uploads/7/7/8/1/77811662/brindlewood_bay_play_sheets.pdf",fmt:"PDF"}],mechanics:[{icon:"dices"},{icon:"puzzle"},{icon:"venetian-mask"},{icon:"eye"}],quotes:[{text:"Brindlewood Bay is a great game because it casts spells.",author:"Moreau Vazh, Taskerland"},{text:"This means that even with the same mystery and same clues, two groups of Mavens might come up with an entirely different solution, which is a really neat feature of the game.",author:"Becca Watson, Roll Plus Heart"}],ru:{tagShort:"Уютные детективы с ноткой космического ужаса",tagline:"«„Она написала убийство“ встречает Лавкрафта».",description:"В Brindlewood Bay вы играете за Мавенов-детективов, книжный клуб остроумных пожилых дам, которые раскрывают убийства в тихом городке Новой Англии, пока под чашками чая шевелится космический культ. Движок Carved from Brindlewood устроен так, что у загадок нет заранее заданного решения: вы собираете улики, сплетаете их в теорию и бросаете 2d6, чтобы проверить догадку. Уютное расследование и ползучий лавкрафтианский ужас в равной мере.",setting:"Приморская деревушка Бриндлвуд-Бей, современная Новая Англия: пастельные домики, церковные ярмарки выпечки и сплочённый книжный клуб. За открыточным покоем таится Тёмный Заговор, оккультный культ и космические сущности, которых Мавены раскрывают дело за делом, сессию за сессией.",vignette:"Мавены собираются за остывшим ромашковым чаем: надорванный билет на паром, пропавший большой палец смотрителя маяка и соль, рассыпанная у крыльца вдовы, всё указывает в одну сторону. Рут заявляет, что регент хора утопил дьякона, скрывая контрабанду. Они считают четыре объяснённые улики, вычитают Сложность загадки и бросают 2d6, выпадает 9. Верно, но преступник ускользает с уличающим сборником гимнов.",prep:"~15 мин",mechanics:[{title:"Теория (Theorize)",text:"Набрав достаточно улик, Мавены совещаются, сплетают их в единое объяснение и бросают 2d6 плюс число объяснённых улик минус Сложность загадки. 10+ — точное попадание; 7-9 — верно, но с осложнением."},{title:"Улики без решения",text:"У загадок есть яркие улики, но нет заранее назначенного убийцы. Смысл собирается за столом, поэтому одно и то же дело даёт разного преступника в каждой компании."},{title:"Ходы Мавена",text:"Плейбуков нет. Каждый игрок — Мавен-детектив, которого выделяет горстка Ходов, названных в честь классических телесыщиков и задающих её манеру расследования."},{title:"Тёмный Заговор",text:"Под чаем и вязанием шевелится космический культ. Пустотные улики и Ночные ходы медленно раскрывают лавкрафтианский заговор, от которого Мавенам не уйти."}],gallery:[{cap:"Твёрдая обложка Brindlewood Bay"},{cap:"Задняя обложка и детали издания"},{cap:"Обложечная иллюстрация: приморский уют и подступающий ужас"}],resources:[{name:"Страница издателя (The Gauntlet)"},{name:"Купить на DriveThruRPG"},{name:"Бесплатные листы для игры (PDF)"}],quotes:[{text:"Brindlewood Bay — отличная игра, потому что она творит волшебство."},{text:"Это значит, что даже с одной и той же загадкой и одними и теми же уликами две группы Мавенов могут прийти к совершенно разным решениям, и это по-настоящему приятная особенность игры."}]},en:{tagShort:"Cozy murder mysteries with a cosmic-horror undertow",tagline:'"Murder, She Wrote meets Lovecraft."',description:"Brindlewood Bay casts you as the Murder Mavens, a book club of sharp-witted old ladies who solve killings in a quaint New England town while a cosmic cult stirs beneath the clam chowder. Built on the Carved from Brindlewood engine, its mysteries have no predetermined solution: you gather clues, weave them into a theory, and roll 2d6 to see if you cracked it. Cozy sleuthing and creeping Lovecraftian dread, in equal measure.",setting:"The seaside village of Brindlewood Bay, present-day New England: pastel cottages, church bake sales, and a tight-knit mystery book club. Under the postcard calm lurks the Dark Conspiracy, an occult cult and cosmic entities the Mavens uncover case by case, session by session.",vignette:"The Mavens gather over lukewarm chamomile: the torn ferry ticket, the lighthouse-keeper's missing thumb, and the salt ringing the widow's porch all point one way. Ruth declares the choir director drowned the deacon to hide the smuggling. They tally four explained clues, subtract the mystery's Complexity, and roll 2d6, landing a 9. Correct, but the culprit slips away with the incriminating hymnal.",prep:"~15 min",mechanics:[{title:"Theorize",text:"Once the Mavens have enough clues, they huddle, weave them into a single explanation, then roll 2d6 plus clues explained minus the mystery's Complexity. 10+ nails it; 7-9 works but at a cost."},{title:"Clues, No Solution",text:"Mysteries ship with evocative clues but no predetermined culprit. Meaning is assembled at the table, so the same case yields a different killer for every group that plays it."},{title:"Maven Moves",text:"There are no playbooks. Every player is a Murder Maven, personalized by a handful of Moves named for classic TV sleuths, each shaping how she investigates and acts."},{title:"The Dark Conspiracy",text:"Beneath the tea and knitting a cosmic cult stirs. Void clues and Night moves slowly reveal a Lovecraftian conspiracy the Mavens can never fully escape."}],gallery:[{cap:"The Brindlewood Bay hardcover"},{cap:"Back cover and edition detail"},{cap:"Title art blending seaside charm and cosmic dread"}],resources:[{name:"Publisher page (The Gauntlet)"},{name:"Buy on DriveThruRPG"},{name:"Free play sheets (PDF)"}],quotes:[{text:"Brindlewood Bay is a great game because it casts spells."},{text:"This means that even with the same mystery and same clues, two groups of Mavens might come up with an entirely different solution, which is a really neat feature of the game."}]}}),registerSystem("cairn",{groups:{default:{key:"osr",order:4},family:{key:"into-the-odd",order:4},genre:{key:"dark-fantasy",order:4},solo:{key:"solo-compatible",order:4}},name:"Cairn",publisher:"Yochai Gal / NSR",dice:"d20 + d6/d8",players:"2–5",complexity:1,free:!0,foundryStatus:"Official",heroImage:"https://assetsio.gnwcdn.com/cairn-2e-box-set-art-trolls-tree-header.png?width=1600&height=900&fit=crop&quality=100&format=png&enable=upscale&auto=webp",playstyleTags:["explore","horror","survival"],settingTags:["fantasy"],gallery:[{src:"https://www.exaltedfuneral.com/cdn/shop/files/cairn-2e-boxed-set-boxed-set-2496979.webp?v=1764284291"},{src:"https://www.exaltedfuneral.com/cdn/shop/files/cairn-2e-boxed-set-boxed-set-3919238.webp?v=1764284291"}],resources:[{type:"link",url:"https://cairnrpg.com/",fmt:"Web"},{type:"rules",url:"https://cairnrpg.com/second-edition/",fmt:"Web"},{type:"quickstart",url:"https://yochaigal.itch.io/cairn-players-guide",fmt:"PDF"},{type:"quickstart",url:"https://yochaigal.itch.io/cairn-wardens-guide",fmt:"PDF"},{type:"sheet",url:"https://better-legends.itch.io/cairn-2e-character-sheet",fmt:"PDF"}],mechanics:[{icon:"feather"},{icon:"mountain-snow"},{icon:"book-open"},{icon:"tree-pine"}],quotes:[{text:"Cairn is an 18-page pamphlet that condenses the OSR ethos into something lean, elegant, and surprisingly evocative.",author:"Serban Ionita, The RPG Gazette"}],ru:{tagShort:"Ультралёгкая фолк-хоррор OSR",tagline:"«Фольклорный хоррор без классов, уровней и ерунды».",description:"Бесплатная, открытая, ультралёгкая система для тёмного фольклорного фэнтези. Основана на Into the Odd и Knave. Правила — 20 страниц. Нет классов, нет уровней. Персонаж — это его снаряжение и решения. Cairn 2e добавила процедуры путешествий, инвентарь на слотах и расширенные правила wilderness exploration.",setting:"Вдохновлён славянскими и кельтскими сказками. Лес здесь — живой, голодный и не прощает легкомыслия. Деревни жмутся к опушке. В чаще — духи, ведьмы и существа, которые были здесь задолго до людей. Атмосфера — братья Гримм до того, как сказки стали детскими.",vignette:"В лесу — развилка. Факел занимает один слот, еда на два дня — ещё два. Вы уже несёте книгу заклинаний и верёвку. Места нет. Бросить факел — идти в темноте. Бросить еду — голодать. Слева тропа уходит к болоту, справа — дым. Спасбросок Воли, чтобы не побежать на запах еды. Провал — и вы уже в избе ведьмы.",prep:"~5 мин",mechanics:[{title:"Без классов и уровней",text:"Вы — то, что несёте. Нашли волшебный меч — вы воин. Нашли книгу заклинаний — вы маг. Потеряли всё — вы труп."},{title:"Инвентарь на слотах",text:"Каждый предмет занимает слот. Факелы, еда, оружие — всё конкурирует за место. Тяжёлый выбор каждый раз."},{title:"Открытая лицензия",text:"Десятки хаков: Liminal Horror, Block Dodge Parry, Runecairn. Cairn — платформа для целой экосистемы игр."},{title:"Процедуры леса",text:"Таблицы событий, погоды, встреч. Лес оживает механически, а не только в воображении."}],gallery:[{cap:"Коробочный набор Cairn 2e"},{cap:"Содержимое набора"}],resources:[{name:"Официальный сайт"},{name:"Полные правила (SRD) — вся игра бесплатно!"},{name:"Player's Guide"},{name:"Warden's Guide"},{name:"Лист персонажа"}],quotes:[{text:"Cairn — 18-страничная брошюра, в которой OSR-этос сжат до чего-то лаконичного, элегантного и неожиданно атмосферного."}]},en:{tagShort:"ultralight folk-horror OSR",tagline:'"Folk horror without classes, levels, or nonsense."',description:"A free, open, ultra-light system for dark folkloric fantasy. Built on Into the Odd and Knave. Rules — 20 pages. No classes, no levels. A character is their gear and their choices. Cairn 2e added travel procedures, slot-based inventory, and expanded wilderness exploration rules.",setting:"Inspired by Slavic and Celtic fairy tales. The forest here is alive, hungry, and unforgiving. Villages huddle at the tree line. Deep within — spirits, witches, and creatures that were here long before humans. The atmosphere — Brothers Grimm before the tales were sanitized for children.",vignette:"A fork in the forest. The torch takes one slot, two days of food — two more. You're already carrying a spellbook and rope. No room. Drop the torch — walk in darkness. Drop the food — starve. Left path leads to a bog, right — smoke. Willpower save to resist running toward the smell of food. Failure — and you're already inside the witch's hut.",prep:"~5 min",mechanics:[{title:"No classes or levels",text:"You are what you carry. Found a magic sword — you're a fighter. Found a spellbook — you're a wizard. Lost everything — you're a corpse."},{title:"Slot-based inventory",text:"Every item takes a slot. Torches, food, weapons — everything competes for space. A tough choice every time."},{title:"Open license",text:"Dozens of hacks: Liminal Horror, Block Dodge Parry, Runecairn. Cairn is a platform for an entire ecosystem of games."},{title:"Forest procedures",text:"Tables for events, weather, encounters. The forest comes alive mechanically, not just in imagination."}],gallery:[{cap:"Cairn 2e box set"},{cap:"Box contents"}],resources:[{name:"Official website"},{name:"Full rules (SRD) — entire game for free!"},{name:"Player's Guide"},{name:"Warden's Guide"},{name:"Character sheet"}]}}),registerSystem("call-of-cthulhu",{groups:{default:{key:"narrative",order:14},family:{key:"standalone",order:13},genre:{key:"horror",order:2},solo:{key:"solo-compatible",order:5}},name:"Call of Cthulhu",publisher:"Chaosium Inc.",dice:"d100 (процентильная система)",players:"2–6",complexity:3,foundryStatus:"Community + Official modules",heroImage:"https://www.tribality.com/wp-content/uploads/2019/04/richard-wright-cthulhu-museum1-1024x512.jpg",playstyleTags:["mystery","horror","narrative","social"],settingTags:["historical","weird"],gallery:[{src:"https://www.rpgtabletopgames.com/wp-content/uploads/call-of-cthulhu-rpg.jpg"},{src:"https://www.tribality.com/wp-content/uploads/2019/04/richard-wright-cthulhu-museum1-1024x512.jpg"},{src:"https://sessionzero.games/images/systems/call-of-cthulhu-g2.jpg"}],resources:[{type:"link",url:"https://www.chaosium.com/call-of-cthulhu-rules/",fmt:"Web"},{type:"link",url:"https://www.chaosium.com/content/FreePDFs/CoC/CHA23131%20Call%20of%20Cthulhu%207th%20Edition%20Quick-Start%20Rules.pdf",fmt:"PDF"},{type:"sheet",url:"https://www.chaosium.com/content/FreePDFs/CoC/Character%20Sheets/Character%20Sheet%20-%20base%20-%20Call%20of%20Cthulhu%207th%20Ed.pdf",fmt:"PDF"},{type:"tool",url:"https://www.dholeshouse.org/",fmt:"Web"}],mechanics:[{icon:"brain"},{icon:"target"},{icon:"eye"},{icon:"book"}],quotes:[{text:"Call of Cthulhu is unequivocally the greatest role-playing game ever written.",author:"Ben Riggs, Nerdist"},{text:"Call of Cthulhu is one of, if not the most popular RPG that isn't called Dungeons and Dragons.",author:"Gab Hernandez, Wargamer"},{text:"Its adventures are novel and genuinely exciting. It's versatile enough to cover any place on earth, at any time, with any cast of characters.",author:"Mollie Russell, Wargamer"}],ru:{tagShort:"Классика хоррор-RPG, 1920-е",tagline:"«Тайны, которые лучше бы не раскрывать. Истина, от которой сходят с ума».",description:"Старейшая и самая знаменитая хоррор-RPG в мире, впервые изданная в 1981 году Сэнди Петерсеном. Седьмая редакция — современная, отполированная версия классики. Основа — процентильная система Basic Roleplaying (BRP): у каждого навыка есть значение в процентах, и чтобы преуспеть, нужно выбросить на d100 меньше этого числа. Просто, интуитивно, элегантно. Но суть игры — не в кубиках. Call of Cthulhu — это расследование. Вы не воины и не герои. Вы — обычные люди: частные детективы, профессора, журналисты — которые столкнулись с тем, чего не должно существовать. Каждая встреча с непостижимым оставляет шрамы: механика Рассудка (Sanity) отслеживает медленное сползание персонажа в безумие. В отличие от D&D, где персонажи становятся сильнее, в Call of Cthulhu они деградируют. Это не power fantasy — это греческая трагедия за игровым столом, и именно поэтому система живёт уже более 40 лет.",setting:"Классический сеттинг — Америка 1920-х годов, эпоха джаза, сухого закона и тайных культов. Газовые фонари, библиотеки Мискатоникского университета, туманные доки Инсмута. Но Call of Cthulhu не ограничена одной эпохой: официальные дополнения охватывают викторианскую Англию (Cthulhu by Gaslight), Древний Рим (Cthulhu Invictus), Средневековье (Cthulhu Dark Ages), современность и даже далёкое будущее. Ужас Лавкрафта вне времени — Великие Древние ждали миллиарды лет до появления человечества и будут ждать после. Мир полон тайных культов, запретных книг вроде Некрономикона и существ, один взгляд на которых ломает разум.",vignette:"Библиотека Мискатоникского университета, 2 часа ночи. Ваш профессор — д-р Элис Уоррен — листает дневник пропавшего коллеги. Бросок Library Use (65%) — 42, успех. Вы находите запись: «Маяк на мысе Кингспорт. Свет, который не должен гореть.» На маяке — символы, нарисованные кровью. Бросок Cthulhu Mythos — вы узнаёте знак Дагона. Проверка Рассудка: 1d6 потери. Вы выбрасываете 4. Рассудок падает с 55 до 51. Д-р Уоррен начинает слышать пение из-под пола. Хранитель (ведущий) говорит: «Ты понимаешь, что текст в дневнике — это не записи. Это молитва. И ты только что прочитала её вслух.»",prep:"~30–60 мин",mechanics:[{title:"Рассудок (Sanity)",text:"Уникальная механика безумия. Каждая встреча с потусторонним отнимает очки Рассудка. На нуле — персонаж безвозвратно сходит с ума. Это не ментальные хиты — это медленное, неизбежное сползание в безумие с фобиями, маниями и срывами."},{title:"Процентильная система (d100)",text:"Каждый навык — число от 1 до 99. Бросьте d100 ниже — успех. Половина значения — сложный успех, пятая часть — экстремальный. Никаких таблиц модификаторов — всё интуитивно понятно."},{title:"Расследование",text:"Сердце игры — не бой, а поиск улик, опрос свидетелей, изучение древних текстов. Бой — крайняя мера и почти всегда плохая идея. Монстры Мифоса сильнее любого человека."},{title:"Pushed Rolls и Удача",text:"Провалили бросок? Можно «надавить» (pushed roll) — попробовать ещё раз, но при повторном провале последствия будут катастрофическими. Очки Удачи — невосполнимый ресурс для спасения в критический момент."}],gallery:[{cap:"Call of Cthulhu — базовый набор книг 7-й редакции"},{cap:"Музей ужасов — арт Ричарда Райта"},{cap:"Столкновение с непостижимым"}],resources:[{name:"Официальный сайт Chaosium"},{name:"Quick-Start Rules (бесплатно)"},{name:"Лист персонажа (официальный)"},{name:"The Dhole's House — онлайн-генератор персонажей"}],quotes:[{text:"Call of Cthulhu — без всяких оговорок величайшая ролевая игра, когда-либо написанная."},{text:"Call of Cthulhu — одна из самых популярных RPG, что не называется Dungeons & Dragons. А может, и единственная такая."},{text:"Её приключения свежи и по-настоящему увлекательны. Система универсальна настолько, что охватывает любое место на земле, в любое время, с любым составом персонажей."}]},en:{tagShort:"classic 1920s horror RPG",tagline:'"Mysteries best left unsolved. Truths that shatter the mind."',description:"The oldest and most renowned horror RPG in the world, first published in 1981 by Sandy Petersen. The 7th edition is the modern, polished version of this classic. The foundation is the percentile-based Basic Roleplaying (BRP) system: every skill has a percentage value, and to succeed you must roll under it on a d100. Simple, intuitive, elegant. But the heart of the game is not the dice. Call of Cthulhu is about investigation. You are not warriors or heroes. You are ordinary people — private detectives, professors, journalists — who have encountered something that should not exist. Every brush with the incomprehensible leaves scars: the Sanity mechanic tracks a character's slow descent into madness. Unlike D&D, where characters grow stronger, in Call of Cthulhu they deteriorate. This is not a power fantasy — it is a Greek tragedy at the gaming table, and that is exactly why the system has endured for over 40 years.",setting:"The classic setting is 1920s America — the jazz age, Prohibition, and secret cults. Gas lamps, the libraries of Miskatonic University, the fog-shrouded docks of Innsmouth. But Call of Cthulhu is not limited to a single era: official supplements cover Victorian England (Cthulhu by Gaslight), Ancient Rome (Cthulhu Invictus), the Middle Ages (Cthulhu Dark Ages), the modern day, and even the far future. Lovecraftian horror is timeless — the Great Old Ones waited billions of years before humanity appeared and will wait long after. The world is full of secret cults, forbidden tomes like the Necronomicon, and entities whose mere sight breaks the mind.",vignette:"Miskatonic University library, 2 AM. Your professor — Dr. Alice Warren — leafs through a missing colleague's journal. Library Use roll (65%) — 42, success. You find an entry: 'The lighthouse at Kingsport Head. The light that should not shine.' At the lighthouse — symbols drawn in blood. Cthulhu Mythos roll — you recognize the sign of Dagon. Sanity check: 1d6 loss. You roll 4. Sanity drops from 55 to 51. Dr. Warren begins to hear chanting from beneath the floor. The Keeper (GM) says: 'You realize the text in the journal isn't notes. It's a prayer. And you just read it aloud.'",prep:"~30–60 min",mechanics:[{title:"Sanity",text:"A unique madness mechanic. Every encounter with the otherworldly costs Sanity points. At zero — the character is irreversibly insane. This is not mental HP — it is a slow, inevitable slide into madness with phobias, manias, and breakdowns."},{title:"Percentile system (d100)",text:"Every skill is a number from 1 to 99. Roll d100 under it — success. Half the value is a Hard success, one-fifth is an Extreme success. No modifier tables — everything is intuitive."},{title:"Investigation",text:"The heart of the game is not combat but gathering clues, interviewing witnesses, and studying ancient texts. Fighting is a last resort and almost always a bad idea. Mythos creatures are stronger than any human."},{title:"Pushed Rolls & Luck",text:"Failed a roll? You can 'push' it — try again, but on a second failure the consequences are catastrophic. Luck points are a non-renewable resource for saving yourself at a critical moment."}],gallery:[{cap:"Call of Cthulhu — 7th edition core books"},{cap:"Museum of horrors — art by Richard Wright"},{cap:"Facing the incomprehensible"}],resources:[{name:"Official Chaosium website"},{name:"Quick-Start Rules (free)"},{name:"Character sheet (official)"},{name:"The Dhole's House — online character generator"}]}}),registerSystem("castles-and-crusades",{groups:{default:{key:"osr",order:13},family:{key:"osr-classic",order:8},genre:{key:"adventure",order:15}},name:"Castles & Crusades",publisher:"Troll Lord Games",dice:"d20 (SIEGE engine)",players:"3–6",complexity:3,edition:"AD&D",free:!0,foundryStatus:"Official",heroImage:"https://image.nobleknight.com/i/jpg1500/imptlg80107.jpg",playstyleTags:["combat","explore","sandbox"],settingTags:["fantasy"],gallery:[{src:"https://image.nobleknight.com/t/jpg1500/tlg80108.jpg"},{src:"https://trolllord.com/wp-content/uploads/2024/12/Pages-from-TLG-801010-Players-Handbook.pdf.jpg"},{src:"https://trolllord.com/wp-content/uploads/2024/12/Pages-from-TLG-801010-Players-Handbook_Page_02-1583x2048.jpg"}],resources:[{type:"link",url:"https://trolllord.com/castles-crusades/",fmt:"Web"},{type:"quickstart",url:"https://trolllord.com/product/cc-players-handbook-7th-printing-alternate-cover-free-pdf/",fmt:"PDF"}],mechanics:[{icon:"dices"},{icon:"star"},{icon:"swords"},{icon:"zap"}],quotes:[{text:"Troll Lord's recent Castles and Crusades releases get my highest recommendation.",author:"John O'Neill, Black Gate"},{text:"It's a terrific collection of cleverly designed and splendidly written products useful to anyone running a D&D or OE campaign.",author:"John O'Neill, Black Gate"}],ru:{tagShort:"Стримлайн AD&D на едином движке SIEGE",tagline:"«D&D, каким вы его помните — но с одной механикой проверок на всё».",description:"Castles & Crusades — это ощущение AD&D на шасси d20, но с гениальным упрощением: движок SIEGE сводит все проверки к одной механике. Издаётся Troll Lord Games с 2004 года при участии авторов оригинальной D&D (Гэри Гайгэкс консультировал). Мост между старой школой и понятным современным дизайном; не строгий OSR, но с тем же духом.",setting:"Система-агностик с подразумеваемым классическим фэнтези (официальный сеттинг — Айзос/Aihrde). Рыцари, подземелья, драконы и древние руины. Дух — героическое приключение старой школы: исследуй, сражайся, богатей. Легко переносит любые модули AD&D и OSR почти без конвертации.",vignette:"Замковый Хранитель описывает ров с обрушенным мостом. Дwarf-воин хочет перепрыгнуть. Сила — его прайм-атрибут, значит база сложности 12. Бросок d20 + уровень + модификатор Силы против 12 плюс уровень испытания. Выпало 15 — с запасом. Он приземляется на той стороне, меч наготове. Один бросок, одна механика — и снова в игру.",prep:"~15 мин",mechanics:[{title:"Движок SIEGE",text:"Все проверки — одна механика: d20 + уровень + модификатор против базы сложности (12 для прайм-атрибута, 18 для остальных) плюс уровень испытания. Учится за 15 минут."},{title:"Прайм-атрибуты",text:"Каждый персонаж помечает часть характеристик как «прайм» — по ним проверки легче. Так задаётся, в чём герой силён, без раздутых списков навыков."},{title:"Дух AD&D на d20",text:"Классы, уровни, AC, знакомые расы. Играли в AD&D или в тройку — уже знаете основу. Летальность и исследование старой школы в современной подаче."},{title:"Скорость за столом",text:"Система создана ради темпа: минимум обращений к книге, быстрые решения Хранителя. «D&D, каким он был раньше» — без анализа-паралича билдов."}],gallery:[{cap:"Castle Keepers Guide"},{cap:"Разворот Player's Handbook"},{cap:"Интерьерные страницы"}],resources:[{name:"Официальный сайт — Troll Lord Games"},{name:"Player's Handbook — бесплатный PDF"}],quotes:[{text:"Недавние релизы Castles & Crusades от Troll Lord получают мою высшую рекомендацию."},{text:"Это отличный набор умно спроектированных и превосходно написанных продуктов, полезных любому, кто ведёт кампанию по D&D или старым редакциям."}]},en:{tagShort:"Streamlined AD&D on the unified SIEGE engine",tagline:'"The game the way it used to be — with one check mechanic for everything."',description:"Castles & Crusades is the feel of AD&D on a d20 chassis, with one brilliant simplification: the SIEGE engine resolves every check with a single mechanic. Published by Troll Lord Games since 2004 with input from original D&D authors (Gary Gygax consulted). A bridge between old-school play and clean modern design — not strict OSR, but cut from the same cloth.",setting:"Setting-agnostic, with an implied classic fantasy (the official setting is Aihrde). Knights, dungeons, dragons, and ancient ruins. The spirit is old-school heroic adventure: explore, fight, grow rich. It runs virtually any AD&D or OSR module with almost no conversion.",vignette:"The Castle Keeper describes a moat with a collapsed bridge. The dwarf fighter wants to leap it. Strength is his prime attribute, so the Challenge Base is 12. He rolls d20 + level + Strength mod against 12 plus the challenge level. He rolls a 15 — clears it easily, landing on the far side, sword ready. One roll, one mechanic, and back into the action.",prep:"~15 min",mechanics:[{title:"The SIEGE Engine",text:"Every check is one mechanic: d20 + level + modifier against a Challenge Base (12 for a prime attribute, 18 otherwise) plus the challenge level. Learnable in fifteen minutes."},{title:"Prime Attributes",text:"Each character marks some abilities as 'prime' — checks against them are easier. This defines what a hero is good at without bloated skill lists."},{title:"AD&D feel on d20",text:"Classes, levels, AC, familiar ancestries. If you've played AD&D or 3e, you already know the base. Old-school lethality and exploration in a modern presentation."},{title:"Speed at the table",text:"Built for pace: minimal rulebook lookups, quick Castle Keeper rulings. 'D&D the way it used to be' — without build analysis paralysis."}],gallery:[{cap:"Castle Keepers Guide"},{cap:"Player's Handbook spread"},{cap:"Interior pages"}],resources:[{name:"Official site — Troll Lord Games"},{name:"Player's Handbook — free PDF"}],quotes:[{text:"Troll Lord's recent Castles and Crusades releases get my highest recommendation."},{text:"It's a terrific collection of cleverly designed and splendidly written products useful to anyone running a D&D or OE campaign."}]}}),registerSystem("city-of-mist",{groups:{default:{key:"narrative",order:23.5},family:{key:"pbta-fitd",order:26},genre:{key:"noir",order:34}},name:"City of Mist",publisher:"Son of Oak Game Studio",dice:"2d6",players:"2–5",complexity:2,free:!0,foundryStatus:"Community",heroImage:"https://sonofoak.com/cdn/shop/files/MOCKUP-book-Core-Books-Player_s-Guide_1eeeba69-aa3c-45bb-9192-eb308407f400.png?v=1706050848",playstyleTags:["narrative","combat","social"],settingTags:["urban-fantasy","modern"],gallery:[{src:"https://sonofoak.com/cdn/shop/products/Combo-Full-Sets-CoM.png?v=1762364603"},{src:"https://sonofoak.com/cdn/shop/products/Slipcase-Expansions-open-1.png?v=1719841351"},{src:"https://sonofoak.com/cdn/shop/files/The_Core_Set_-_Web_Square.png?v=1736160691"}],resources:[{type:"quickstart",url:"https://www.drivethrurpg.com/en/product/312680/city-of-mist-starter-kit",fmt:"PDF"},{type:"link",url:"https://cityofmist.co/",fmt:"Web"},{type:"link",url:"https://cityofmist.co/city-of-mist-free-quickstart",fmt:"Web"}],mechanics:[{icon:"sparkles"},{icon:"target"},{icon:"book-open"},{icon:"scroll"}],quotes:[{text:"Style and drama ooze from every page of this beautiful book.",author:"Richard Jansen-Parkes, Tabletop Gaming"},{text:"It takes a little more effort to crack than most story-driven games, but when things click it offers something truly special.",author:"Richard Jansen-Parkes, Tabletop Gaming"}],ru:{tagShort:"2d6 — noir-детектив с мифологическими силами",tagline:"«Мифические силы пробудились в тебе. Город пропитан туманом. Кто-то должен открыть глаза».",description:"City of Mist — настольная RPG (2017) от Son of Oak Game Studio (Ориан Дасет). Noir-детектив в современном городе, где обычные люди пробуждают силы мифов. Механики созданы как «некоммерческий ответ D&D»: всё для совместного повествования. Система тегов: каждый тег — короткая фраза, описывающая аспект персонажа. 2d6 с модификатором (+/-): 10+ — успех, 7–9 — успех с осложнением, 6- — провал.",setting:"Современный город (анонимный мегаполис), пропитанный мистическим туманом. За обычными дверями скрываются мифические сущности. Обычные люди — детективы, журналисты, уличные бойцы — пробуждают силы, связанные с мифами (греческими, скандинавскими, славянскими, японскими). Два типа персонажей: Mythos (мифические силы) и Logos (человеческая жизнь).",vignette:"ГМ: «Ты в квартире убитого. Полиция уехала. Ты чувствуешь что-то в стенах — туман просачивается.» Игрок: «Использую свой тег 'Следопыт мифов' чтобы найти невидимые знаки.» Бросает 2d6 +2 (Mythos): 9. Успех с осложнением: «Ты находишь знаки... но они ведут вниз, в канализацию, и ты чувствуешь, что кто-то за тобой наблюдает.»",prep:"~15 мин",mechanics:[{title:"Теги (Tag System)",text:"Каждый тег — короткая фраза («Законный страж», «Гнев океана», «Мои кулаки»). Броски 2d6 + модификатор тега. Теги можно создавать, использовать и терять."},{title:"Mythos vs Logos",text:"У каждого персонажа два аспекта: Mythos (мифические силы) и Logos (человеческая жизнь). Усиление одного ослабляет другой — баланс напряжения."},{title:"Классы тегов",text:"Power Tags (силы), Danger Tags (угрозы), Weakness Tags (слабости), Status Tags (статусы). Каждый тип — свои правила."},{title:"Мифический детектив",text:"Игра строится на расследованиях: что случилось, кто виноват, какова мифическая угроза. ГМ следует принципам noir-расследования."}],gallery:[{cap:"City of Mist Player's Guide"},{cap:"City of Mist Starter Kit"},{cap:"City of Mist: Cases & Mysteries"}],resources:[{name:"Бесплатный Quickstart (PDF)"},{name:"Официальный сайт"},{name:"Бесплатный квикстарт (веб)"}],quotes:[{text:"Стиль и драма сочатся с каждой страницы этой красивой книги."},{text:"Её сложнее раскусить, чем большинство сюжетных игр, но когда всё складывается — она даёт нечто по-настоящему особенное."}]},en:{tagShort:"2d6 — noir detective with mythic powers",tagline:'"Mythic powers awakened in you. The city is steeped in mist. Someone must open their eyes."',description:"City of Mist is a tabletop RPG (2017) by Son of Oak Game Studio (Orion Dassler). A noir detective game in a modern city where ordinary people awaken the powers of myths. The mechanics are built as 'a non-commercial answer to D&D': everything serves co-narrative storytelling. Tag system: every tag is a short phrase describing a character aspect. 2d6 with modifier (+/-): 10+ — full success, 7–9 — success with complication, 6- — fail.",setting:"A modern anonymous city steeped in mist. Behind ordinary doors hide mythic entities. Ordinary people — detectives, journalists, street fighters — awaken powers connected to myths (Greek, Nordic, Slavic, Japanese). Two character aspects: Mythos (mythic powers) and Logos (human life).",vignette:"GM: 'You're in the victim's apartment. Police left. You feel something in the walls — mist is seeping in.' Player: 'I use my Trail Seeker tag to find invisible signs.' Rolls 2d6+2 (Mythos): 9. Success with complication: 'You find the signs... but they lead down, into the sewers, and you feel someone watching you.'",prep:"~15 min",mechanics:[{title:"Tag System",text:"Every tag is a short phrase ('Guardian of Law', 'Wrath of the Ocean', 'My Fists'). Rolls 2d6 + tag modifier. Tags can be created, used, and lost."},{title:"Mythos vs Logos",text:"Every character has two aspects: Mythos (mythic powers) and Logos (human life). Strengthening one weakens the other — tension balance."},{title:"Tag Types",text:"Power Tags, Danger Tags, Weakness Tags, Status Tags. Each type — its own rules."},{title:"Mythic Detective",text:"The game revolves around investigations: what happened, who's to blame, what the mythic threat is. The GM follows noir investigation principles."}],gallery:[{cap:"City of Mist Player's Guide"},{cap:"City of Mist Starter Kit"},{cap:"City of Mist: Cases & Mysteries"}],resources:[{name:"Free Quickstart (PDF)"},{name:"Official website"},{name:"Free quickstart (web)"}],quotes:[{text:"Style and drama ooze from every page of this beautiful book."},{text:"It takes a little more effort to crack than most story-driven games, but when things click it offers something truly special."}]}}),registerSystem("coriolis",{groups:{default:{key:"fl",order:8},family:{key:"year-zero",order:8},genre:{key:"sci-fi",order:5}},name:"Coriolis",publisher:"Free League / Year Zero Engine",dice:"Пул d6",players:"3–5",complexity:3,foundryStatus:"Official контент",heroImage:"https://freeleaguepublishing.com/wp-content/uploads/2023/08/coriolis_ship-1440x720.jpg",playstyleTags:["explore","social","mystery","sandbox"],settingTags:["space"],gallery:[{src:"https://freeleaguepublishing.com/wp-content/uploads/2023/09/coriolisweb.jpg"},{src:"https://freeleaguepublishing.com/wp-content/uploads/2023/08/coriolis_Kapitelbild_7-scaled.jpg"},{src:"https://freeleaguepublishing.com/wp-content/uploads/2023/08/coriolis__s63.jpg"},{src:"https://freeleaguepublishing.com/wp-content/uploads/2023/08/coriolis_vapenrustningar-scaled.jpg"}],resources:[{type:"link",url:"https://freeleaguepublishing.com/games/coriolis/",fmt:"Web"},{type:"sheet",url:"https://freeleaguepublishing.com/wp-content/uploads/2023/08/cor_Character_Sheet.pdf",fmt:"PDF"},{type:"sheet",url:"https://freeleaguepublishing.com/wp-content/uploads/2023/08/cor_spaceship_Sheet.pdf",fmt:"PDF"},{type:"map",url:"https://freeleaguepublishing.com/wp-content/uploads/2023/08/coriolis_large_map_3H.pdf",fmt:"PDF"},{type:"quickstart",url:"https://freeleaguepublishing.com/wp-content/uploads/2024/03/Coriolis_The_Great_Dark_Quickstart_v1.pdf",fmt:"PDF"},{type:"quickstart",url:"https://www.drivethrurpg.com/en/product/204702/coriolis-the-third-horizon-quickstart",fmt:"PDF"}],mechanics:[{icon:"hand"},{icon:"rocket"},{icon:"users"},{icon:"moon"}],quotes:[{text:"Coriolis may just be one of the best systems I've ever seen if you're looking to make your players' starship their command center, their home, and even a character in their journey.",author:"Adam Factor, Sprites and Dice"},{text:"Coriolis feels like a lot of Firefly, but with a Middle Eastern styling instead of the Old West.",author:"Strange Assembly review"}],ru:{tagShort:"Арабо-персидская космоопера",tagline:"«Арабские Ночи в космосе. Торговля, молитва и Тьма Между Звёзд».",description:"Космическая опера с арабо-персидской эстетикой. Группа владеет космическим кораблём и путешествует по Третьему Горизонту — кластеру звёздных систем. Торговля, контрабанда, дипломатия, исследование — и Тьма Между Звёзд, которая проникает в реальность через молитвы Иконам.",setting:"Третий Горизонт — десятки звёздных систем, связанных порталами. Базары на орбитальных станциях, мечети рядом с доками, древние порталы неизвестного происхождения. Фракции: от религиозных орденов до мегакорпораций. Атмосфера — Firefly встречает «1001 ночь».",vignette:"Ваш корабль входит в систему Кua. Таможня требует досмотр — в трюме контрабанда. Бросок Манипуляции: 5 кубиков, ни одной шестёрки. «Молюсь Иконе Судьи,» — говорите вы. Перебрасываете — две шестёрки, успех! Но Мастер получает очко Тьмы. Позже, в тёмном коридоре станции, свет мигает. Что-то шепчет ваше имя. Тьма помнит.",prep:"~30 мин",mechanics:[{title:"Молитва Иконам",text:"Перебросить кубики? Помолитесь Иконам. Но Тьма получает очко влияния. Каждая молитва — сделка с неизвестным."},{title:"Ваш корабль",text:"Корабль — центр кампании. Модули, долги, экипаж, репутация. Это ваш дом в холодном космосе."},{title:"Фракции",text:"Десятки фракций с пересекающимися интересами. Каждое решение меняет баланс сил в секторе."},{title:"Тьма",text:"Тьма Между Звёзд — метафизическая угроза. Чем больше вы используете Иконы, тем сильнее она становится."}],gallery:[{cap:"Третий Горизонт"},{cap:"Глава из книги"},{cap:"Станция"},{cap:"Оружие и броня"}],resources:[{name:"Официальный сайт"},{name:"Лист персонажа"},{name:"Лист корабля"},{name:"Звёздная карта"},{name:"Quickstart The Great Dark"},{name:"Quickstart Third Horizon"}],quotes:[{text:"Coriolis — пожалуй, одна из лучших систем, что я видел, если вам нужно сделать звездолёт игроков их командным центром, домом и даже персонажем их путешествия."},{text:"Coriolis ощущается как «Светлячок», но с ближневосточной стилизацией вместо Дикого Запада."}]},en:{tagShort:"Arabian-Persian space opera",tagline:'"Arabian Nights in space. Trade, prayer, and the Darkness Between the Stars."',description:"A space opera with Arab-Persian aesthetics. The group owns a spaceship and travels the Third Horizon — a cluster of star systems. Trade, smuggling, diplomacy, exploration — and the Darkness Between the Stars, which seeps into reality through prayers to the Icons.",setting:"The Third Horizon — dozens of star systems connected by portals. Bazaars on orbital stations, mosques next to docks, ancient portals of unknown origin. Factions range from religious orders to megacorporations. The atmosphere — Firefly meets One Thousand and One Nights.",vignette:"Your ship enters the Kua system. Customs demands an inspection — there's contraband in the hold. Manipulation roll: 5 dice, no sixes. 'I pray to the Icon of the Judge,' you say. Reroll — two sixes, success! But the GM gains a Darkness Point. Later, in a dark station corridor, the lights flicker. Something whispers your name. The Darkness remembers.",prep:"~30 min",mechanics:[{title:"Praying to the Icons",text:"Need to reroll? Pray to the Icons. But the Darkness gains an influence point. Every prayer is a deal with the unknown."},{title:"Your ship",text:"The ship is the campaign's center. Modules, debts, crew, reputation. It's your home in cold space."},{title:"Factions",text:"Dozens of factions with overlapping interests. Every decision shifts the balance of power in the sector."},{title:"The Darkness",text:"The Darkness Between the Stars is a metaphysical threat. The more you invoke the Icons, the stronger it grows."}],gallery:[{cap:"The Third Horizon"},{cap:"Book chapter"},{cap:"Station"},{cap:"Weapons and armor"}],resources:[{name:"Official website"},{name:"Character sheet"},{name:"Ship sheet"},{name:"Star map"},{name:"Quickstart The Great Dark"},{name:"Quickstart Third Horizon"}]}}),registerSystem("cortex-prime",{groups:{default:{key:"narrative",order:35},family:{key:"standalone",order:43},genre:{key:"adventure",order:25}},name:"Cortex Prime",publisher:"Dire Wolf Digital",dice:"Пул кубиков d4–d12",players:"3–6",complexity:3,foundryStatus:"Community",heroImage:"https://shop.direwolfdigital.com/cdn/shop/products/store_cortex_bookcover_1200x.png",playstyleTags:["narrative","social","combat"],settingTags:[],gallery:[{src:"https://shop.direwolfdigital.com/cdn/shop/products/store_cortex_inside_1200x.png"},{src:"https://prod-images.cortexrpg.com/cms/media/temp/intro-bg.png"}],resources:[{type:"link",url:"https://www.cortexrpg.com/",fmt:"Web"}],mechanics:[{icon:"dices"},{icon:"blocks"},{icon:"coins"},{icon:"shapes"}],quotes:[{text:"This book is a joy to look at, and that makes it a joy to learn from.",author:"Jared Rascher, Gnome Stew"},{text:"What Cortex Prime does is take that system and turn it into an immensely powerful toolbox, laying all the switches and dials bare in a way that GMs can actually use.",author:"Aaron Marks, Cannibal Halfling Gaming"}],ru:{tagShort:"Модульный универсальный движок из кубиков",tagline:"«Собери свою игру: любой жанр — из одного набора деталей».",description:"Cortex Prime — универсальный конструктор ролевых систем Кэма Бэнкса (изданный Dire Wolf Digital). Не готовая игра, а набор «модов»: берёшь нужные детали — Отличия, Активы, Осложнения, Очки сюжета — и собираешь механику под свой жанр и стол. На движке Cortex выходили Firefly, Marvel Heroic, Smallville. Дайспул d4–d12 вместо фиксированных статов.",setting:"Сеттинг-агностик по определению: Cortex ничего не навязывает. Хочешь нуар, супергероику, космооперу или семейную драму — собираешь под это свою версию правил. Сила системы — в том, что она подстраивается под тон истории, а не наоборот.",vignette:"Героиня взламывает сейф под давлением. Ведущий и игрок собирают пул: кубик Атрибута (d8), кубик Навыка (d6), кубик Отличия (d8) и кубик Осложнения «Тревога» (d6, за него ведущий получит Очко сюжета). Бросок. Берёшь два кубика в сумму против сложности и один — как Effect Die, размер успеха. 8 против 7 — сейф открыт, но сигнализация уже воет.",prep:"~20 мин",mechanics:[{title:"Пулы кубиков d4–d12",text:"Черта — это кубик (чем крупнее, тем лучше). Действие собирает пул из подходящих черт; берёшь два в сумму против сложности и один как Effect Die — он задаёт масштаб успеха."},{title:"Модульность («моды»)",text:"Cortex — не одна игра, а набор опциональных модулей: Отличия, Активы, Осложнения, Стресс, Роли. Комбинируешь нужные — получаешь систему ровно под свой жанр."},{title:"Очки сюжета",text:"Метавалюта: тратишь, чтобы добавить кубик в пул, оставить лишний, активировать спецэффект. Осложнения приносят Очки сюжета — риск конвертируется в ресурс."},{title:"Один движок — любой мир",text:"20+ лет и десятки лицензий (Firefly, Marvel, Smallville) на одном шасси. Осваиваешь ядро раз — и запускаешь на нём любой жанр без новой системы."}],gallery:[{cap:"Интерьер книги"},{cap:"Арт"}],resources:[{name:"Официальный сайт — cortexrpg.com"}],quotes:[{text:"На эту книгу приятно смотреть — и потому по ней приятно учиться."},{text:"Cortex Prime берёт систему и превращает её в невероятно мощный набор инструментов, выкладывая все рычажки и переключатели так, что ведущие реально могут ими пользоваться."}]},en:{tagShort:"A modular, universal dice-pool engine",tagline:'"Build your game: any genre, from one box of parts."',description:"Cortex Prime is Cam Banks's universal RPG construction kit (published by Dire Wolf Digital). Not a finished game but a set of 'mods': take the parts you want — Distinctions, Assets, Complications, Plot Points — and assemble mechanics to fit your genre and table. The Cortex engine powered Firefly, Marvel Heroic, and Smallville. Dice pools of d4–d12 instead of fixed stats.",setting:"Setting-agnostic by design: Cortex imposes nothing. Want noir, superheroes, space opera, or family drama — you build your own version of the rules for it. The system's strength is that it bends to the tone of the story, not the other way around.",vignette:"The hero cracks a safe under pressure. GM and player build a pool: an Attribute die (d8), a Skill die (d6), a Distinction die (d8), and a Complication 'Anxiety' die (d6, for which the GM earns a Plot Point). Roll. Take two dice for the total against the difficulty and one as the Effect Die, the size of success. An 8 beats 7 — the safe opens, but the alarm is already wailing.",prep:"~20 min",mechanics:[{title:"Dice pools d4–d12",text:"A trait is a die (bigger is better). An action gathers a pool of relevant traits; you take two for the total against the difficulty and one as the Effect Die — which sets the scale of success."},{title:"Modularity ('mods')",text:"Cortex isn't one game but a set of optional modules: Distinctions, Assets, Complications, Stress, Roles. Combine the ones you want and you get a system built exactly for your genre."},{title:"Plot Points",text:"A meta-currency: spend to add a die to a pool, keep an extra one, or activate a special effect. Complications earn Plot Points — risk converts into a resource."},{title:"One engine, any world",text:"20+ years and dozens of licenses (Firefly, Marvel, Smallville) on a single chassis. Learn the core once and run any genre on it without a new system."}],gallery:[{cap:"Book interior"},{cap:"Art"}],resources:[{name:"Official site — cortexrpg.com"}]}}),registerSystem("cy-borg",{groups:{default:{key:"osr",order:6},family:{key:"borg",order:2},genre:{key:"dark-fantasy",order:2}},name:"CY_BORG",publisher:"Stockholm Kartell / Free League",dice:"d20 + d6",players:"2–6",complexity:1,foundryStatus:"Community",heroImage:"https://freeleaguepublishing.com/wp-content/uploads/2023/09/CY_BORG-Banner1-1440x384.jpg",playstyleTags:["combat","survival","action"],settingTags:["cyberpunk","postapoc"],gallery:[{src:"https://freeleaguepublishing.com/wp-content/uploads/2023/09/CBcovermockup_small_038aec50-b06d-43ce-8712-c9077b0211b5-1200x1200-1-1200x1200.jpg"},{src:"https://freeleaguepublishing.com/wp-content/uploads/2023/09/CY_BORG_20-21-1536x1536.jpg"},{src:"https://freeleaguepublishing.com/wp-content/uploads/2023/09/CY_BORG_50-51-1536x1536.jpg"}],resources:[{type:"link",url:"https://freeleaguepublishing.com/games/cy_borg/",fmt:"Web"},{type:"link",url:"https://cyborg.exlibrisrpg.com/",fmt:"Web"},{type:"sheet",url:"https://cyborg.exlibrisrpg.com/entries/character-sheets",fmt:"PDF"}],mechanics:[{icon:"radio"},{icon:"brain"},{icon:"cog"},{icon:"zap"}],quotes:[{text:"Cy_Borg is like Blade Runner if someone had let David Cronenberg get his hands on it.",author:"Mollie Russell, Wargamer"}],ru:{tagShort:"Нео-панк киберпанк RPG",tagline:"«RPG о конце света, нано-заражённых киберпанках и ярости против безжалостного корпоративного ада.»",description:"Духовный наследник MÖRK BORG в жанре киберпанка — та же злая арт-панковая энергетика, та же жестокая смертность, только вместо тёмного фэнтези — неоновый смог и корпоративный ад. CY_BORG берёт всё, что сделало Мёрк Борг культом, и пропускает через хромированную мясорубку. Ты скорее всего умрёшь. Городу всё равно. Реклама продолжает мигать.",setting:"Мегаполис Cy, год 20X3. Инцидент уже произошёл, и с тех пор стало только хуже. Четырнадцать мегакорпораций владеют небом, землёй и всем, что между ними. Трущобы гниют в тени небоскрёбных лесов. Неоновые соборы рекламируют товары, которые персонажам не по карману. Бактерии из открытого космоса захватили человеческие нанороботы. Апокалипсис отслеживается через Ужасные Заголовки: семь новостей, каждая хуже предыдущей, и когда выйдет седьмая — город будет стёрт.",vignette:"Лента пингует: Ужасный Заголовок №4 — «Вспышка нано-чумы в Секторе 9. Дроны-карантинщики выдвинуты». Твой Сожжённый Хакер подключается к корпоративному терминалу и бросает Knowledge против 14. Провал. Защитный ICE отвечает: d6 урона по и без того изуродованному телу. Проклятый Банд-Гун всё равно выбивает дверь. Выпадает 3. Клерк улыбается. Где-то наверху дрон берёт твои биомаркеры на прицел.",prep:"~5 мин",mechanics:[{title:"Ужасные Заголовки",text:"Таблица d66 катастроф разворачивается по ходу кампании. Семь заголовков — город погибает. Каждая сессия тикает к неизбежному и эффектному концу."},{title:"Нано-силы",text:"Инопланетные бактерии дают чудовищные способности — восстанавливать ткани, поглощать материю, красть последние воспоминания трупа. Мощные, неконтролируемые и всегда голодные."},{title:"Киберпанк и шесть классов",text:"Сожжённый Хакер, Отверженный Наномант, Ренегат-Кибербоец, Проклятый Банд-Гун, Уволенный Корп-Убийца, Осиротевший Механик."},{title:"Быстрый и смертельный d20",text:"Бросок d20 + модификатор против целевого числа. Статы от -3 до +3. Опциональные тактические правила добавляют укрытия и подавляющий огонь."}],gallery:[{cap:"Обложка"},{cap:"Разворот правил"},{cap:"Арт и механики"}],resources:[{name:"Официальный сайт"},{name:"Ex Libris CY_BORG"},{name:"Листы персонажа"}],quotes:[{text:"Cy_Borg — это «Бегущий по лезвию», если бы за него взялся Дэвид Кроненберг."}]},en:{tagShort:"neon doom-punk cyberpunk RPG",tagline:'"A nano-infested doomsday RPG about cybernetic misfits and punks raging against a relentless corporate hell."',description:"The cyberpunk spiritual successor to MÖRK BORG — same furious art-punk DNA, same brutal lethality, now drowning in neon death smog. CY_BORG takes everything Mörk Borg perfected and smashes it through a chrome-plated, corpo-owned meat grinder. You will probably die. The city doesn't care. The ads keep playing regardless.",setting:"Megacity Cy, year 20X3. The Incident happened and things have only gotten worse since. Fourteen megacorps own the sky, the ground, and everything between. Slums rot beneath scraper-forests of towers. Neon cathedrals advertise products your character can't afford. Bacteria from outer space have hijacked human nanorobotics and nobody has a fix. The apocalypse is tracked in Miserable Headlines — seven headlines, each worse than the last, and when the seventh drops, the city's data is purged. The world is always ending. It just hasn't finished yet.",vignette:"The feed pings: Miserable Headline #4 — 'Nano-plague outbreak in Sector 9. Quarantine drones deployed.' Your Burned Hacker jacks into a corpo terminal, rolls Knowledge against 14. Fails. Security ICE hits back: d6 damage to your already-scarred body. The Forsaken Gang-Goon kicks the door in anyway — Presence check to intimidate the suit at the desk. Rolls a 3. The suit smiles. Somewhere above, a drone launcher tracks your biomarkers. Your nano powers twitch. Something is living inside you and it wants out.",prep:"~5 min",mechanics:[{title:"Miserable Headlines",text:"A d66 table of cascading disasters plays out across the campaign. Seven headlines = the city dies. Sessions tick toward an inevitable, spectacular end."},{title:"Nano Powers",text:"Alien bacteria hijacking your body grant horrifying abilities — repair tissue, consume matter, steal a corpse's last memories. Powerful, uncontrollable, and always hungry."},{title:"Cybertech & Six Classes",text:"Six classes for your class war: Burned Hacker, Shunned Nanomancer, Renegade Cyberslasher, Forsaken Gang-Goon, Discharged Corp Killer, Orphaned Gear Head. Each pre-loaded with trauma, debt, and a very specific way to die."},{title:"Fast & Lethal d20",text:"Roll d20 + stat modifier, beat a target number. Stats range from -3 to +3. Optional tactical crunch adds cover and suppressive fire without bloating the core."}],gallery:[{cap:"Cover"},{cap:"Rules spread"},{cap:"Art and mechanics"}],resources:[{name:"Official website"},{name:"Ex Libris CY_BORG (community hub)"},{name:"Character sheets"}]}}),registerSystem("cyberpunk-red",{groups:{default:{key:"tactical",order:10},family:{key:"standalone",order:29},genre:{key:"sci-fi",order:7.5}},name:"Cyberpunk RED",publisher:"R. Talsorian Games",dice:"d10",players:"3–6",complexity:3,free:!1,foundryStatus:"Community",heroImage:"https://d1vzi28wh99zvq.cloudfront.net/images/13/333585.jpg",playstyleTags:["combat","narrative","explore"],settingTags:["cyberpunk"],gallery:[{src:"https://d1vzi28wh99zvq.cloudfront.net/images/13/409912.jpg"},{src:"https://d1vzi28wh99zvq.cloudfront.net/images/13/279014.jpg"},{src:"https://d1vzi28wh99zvq.cloudfront.net/images/13/333585.jpg"}],resources:[{type:"link",url:"https://rtalsoriangames.com/cyberpunk/",fmt:"Web"},{type:"link",url:"https://talsorianstore.com/products/cyberpunk-red",fmt:"Web"},{type:"quickstart",url:"https://www.drivethrurpg.com/en/product/409912/cyberpunk-red-easy-mode",fmt:"PDF"}],mechanics:[{icon:"swords"},{icon:"dices"},{icon:"book-open"},{icon:"scroll"}],quotes:[{text:"Cyberpunk Red pushes its own alternate future timeline forward far enough to remain different and exciting when compared to our own, while remaining a funhouse mirror image of the same troubled world we still live in.",author:"Charlie Hall, Polygon"},{text:"The first impression you get of Cyberpunk Red is that it's a game of wild contradictions. From its rules to its setting, everything leaps between extremes of simplicity and complexity, campy fun and corporate brutality.",author:"Richard Jansen-Parkes, Dicebreaker"}],ru:{tagShort:"Киберпанк на d10",tagline:"«Ночь, город, корпорации и красное небо после ядерного пожара».",description:"Cyberpunk RED — настольная RPG в жанре киберпанка от R. Talsorian Games (2020), четвёртое издание линейки Interlock. Действие происходит в 2045 году, после 4-й Корпоративной войны: небо Найт-Сити окрашено в красный из-за ядерного fallout, а игроки — эджраннеры, выживающие между корпорациями и улицей. Система d10 с Lifepath-созданием персонажей и боевой подсистемой Friday Night Firefight.",setting:"Найт-Сити, 2045 — гибрид Лос-Анджелеса и Сан-Франциско в постъядерном будущем. Корпорации контролируют всё, но у улицы свои правила. Фэшн, киберимпланты и стил — неотъемлемая часть жизни (и смерти).",vignette:"Раненый эджраннер лежит в переулке. Киберглаз мигает красным: системная ошибка. Над ним — силуэт нано-хирурга с биочемоданом. «Стоимость?» — спрашивает бандит. «Жизнь и 5000 creds», — отвечает хирург. Четыре кубика d10 в руке. Difficulty 14. Бросок... 7+3+1+0 = 11. Провал. Хирург пожимает плечами: «Попробуй в следующей жизни».",prep:"~15 мин",mechanics:[{title:"Система Interlock (d10)",text:"Бросок 1d10 + Атрибут + Навык против Difficulty Value. Простая, но жёсткая математика: криты на двойных, фалы на двойных единицах."},{title:"Friday Night Firefight",text:"Жестокая боевая система: оружие реально, броня хрупкая, раны смертельны. Один выстрел может убить. Бой — это не развлечение, а вопрос выживания."},{title:"Lifepath",text:"Создание персонажа через таблицы: семья, детство, подростковый возраст, первая работа, события. Каждый персонаж — готовая история."},{title:"Киберимпланты",text:"Кибернетика усиливает тело, но добавляет Humanity Loss. Слишком много металла — и ты перестаёшь быть человеком."}],gallery:[{cap:"Core Rulebook (2020)"},{cap:"Easy Mode — бесплатный квикстарт"},{cap:"Jumpstart Kit"}],resources:[{name:"Официальный сайт — R. Talsorian Games"},{name:"Магазин — купить Core Rulebook"},{name:"Easy Mode (бесплатный квикстарт PDF)"}],quotes:[{text:"Cyberpunk Red продвигает свою альтернативную временную шкалу достаточно далеко, чтобы оставаться другим и захватывающим по сравнению с нашим миром, оставаясь при этом отражением того же troubled мира, в котором мы всё ещё живём."},{text:"Первое впечатление от Cyberpunk Red — это игра диких противоречий. От правил до сеттинга всё прыгает между крайностями простоты и сложности,campy fun и корпоративной бруталностью."}]},en:{tagShort:"Cyberpunk d10 — Night City 2045",tagline:'"Night City, 2045 — red skies, corporate wars, and edgerunners on the edge."',description:"Cyberpunk RED is a cyberpunk tabletop RPG from R. Talsorian Games (2020), the fourth edition of the Interlock system. Set in 2045, after the 4th Corporate War — Night City's sky is red from nuclear fallout, and players are edgerunners surviving between corporations and the streets. d10 system with Lifepath character creation and the brutal Friday Night Firefight combat subsystem.",setting:"Night City, 2045 — a Los Angeles/San Francisco hybrid in a post-nuclear future. Corporations control everything, but the street has its own rules. Fashion, cyberware, and style aren't optional — they're survival.",vignette:"A wounded edgerunner lies in an alley. Cybereye blinks red: system error. Above him, a nano-surgeon with a biocase. 'The price?' asks the gonk. 'Your life and 5000 creds,' says the surgeon. Four d10s in hand. Difficulty 14. Roll... 7+3+1+0 = 11. Fail. The surgeon shrugs: 'Try in your next life.'",prep:"~15 min",mechanics:[{title:"Interlock System (d10)",text:"Roll 1d10 + Attribute + Skill vs Difficulty Value. Simple but harsh math: crits on doubles, fumbles on double ones."},{title:"Friday Night Firefight",text:"Brutal combat system: weapons are real, armor is fragile, wounds are lethal. One shot can kill. Combat isn't entertainment — it's survival."},{title:"Lifepath",text:"Character creation through tables: family, childhood, teenage years, first job, events. Every character comes with a built-in story."},{title:"Cyberware",text:"Cybernetics enhance the body but add Humanity Loss. Too much metal and you stop being human."}],gallery:[{cap:"Core Rulebook (2020)"},{cap:"Easy Mode — free quickstart"},{cap:"Jumpstart Kit"}],resources:[{name:"Official site — R. Talsorian Games"},{name:"Store — buy Core Rulebook"},{name:"Easy Mode (free quickstart PDF)"}],quotes:[{text:"Cyberpunk Red pushes its own alternate future timeline forward far enough to remain different and exciting when compared to our own, while remaining a funhouse mirror image of the same troubled world we still live in."},{text:"The first impression you get of Cyberpunk Red is that it's a game of wild contradictions. From its rules to its setting, everything leaps between extremes of simplicity and complexity, campy fun and corporate brutality."}]}}),registerSystem("daggerheart",{groups:{default:{key:"narrative",order:21},family:{key:"standalone",order:16},genre:{key:"adventure",order:11},solo:{key:"solo-compatible",order:9}},name:"Daggerheart",publisher:"Darrington Press",dice:"2d12 (Hope/Fear)",players:"3–5",complexity:3,foundryStatus:"Community",heroImage:"https://darringtonpress.com/wp-content/uploads/2024/12/HEADER-DH-Standard-Cover-Art.png",playstyleTags:["narrative","combat","social"],settingTags:["fantasy"],gallery:[{src:"https://darringtonpress.com/wp-content/uploads/2024/12/DH-Standard-Cover-Art-watermarked-Mat-Wilma-1600x900.png"},{src:"https://darringtonpress.com/wp-content/uploads/2024/12/DH-Limited-Cover-Art-watermarked-Dominik-Mayer-1600x900.png"},{src:"https://darringtonpress.com/wp-content/uploads/2024/12/DH-Stnd-Book-Alone-copy.png"},{src:"https://darringtonpress.com/wp-content/uploads/2024/12/DH-Limited-Spill-Fixed-landscape.png"}],resources:[{type:"link",url:"https://www.daggerheart.com/",fmt:"Web"},{type:"link",url:"https://www.daggerheart.com/srd/",fmt:"Web"},{type:"sheet",url:"https://www.daggerheart.com/wp-content/uploads/2025/05/Character-Sheets-and-Guides-Daggerheart-May212025.pdf",fmt:"PDF"},{type:"quickstart",url:"https://www.daggerheart.com/wp-content/uploads/2025/05/Quickstart-Adventure-5-20-2025.pdf",fmt:"PDF"}],mechanics:[{icon:"dice-6"},{icon:"scroll"},{icon:"swords"},{icon:"heart"}],quotes:[{text:"The narrative system is built around a more freeform collaboration between players and GM, where the story grows without much impediment from rules.",author:"Christian Hoffer, EN World"}],ru:{tagShort:"Фэнтези от Darrington Press (Critical Role)",tagline:"«Каждый бросок — это поворот сюжета. Надежда или Страх — выбирай свою судьбу».",description:"Нарративное героическое фэнтези от Darrington Press — издательского крыла Critical Role. В основе — два d12: кубик Надежды и кубик Страха. Сумма решает успех, а тот, что выпал больше, диктует тон сцены: триумф или цена. Карточная система классов и происхождений собирает героя как колоду, бой ощущается кинематографично, а ГМ копит Страх, чтобы развернуть сцену в самый драматичный момент.",setting:"Базовый мир — высокое фэнтези с нотками Критроли: древние королевства, павшие империи, магия как наследие. Сюжетные рамки (Age of Umbra, Sablewood и др.) задают тон — от мрачного дарк-фэнтези до светлой сказки. Можно играть в стандартном сеттинге или взять только систему и натянуть её на свой мир.",vignette:"ГМ описывает разлом в полу храма — оттуда тянет холодом и шёпотом. Ваш бард делает проверку Присутствия: бросаете d12 Надежды и d12 Страха. 9 и 11 = 20, выше DC 12 — успех с перевесом Страха. Заклинание срабатывает, тени отступают, но кубик Страха выше: ГМ кладёт жетон Страха в свою копилку и тихо улыбается. Где-то в темноте что-то услышало вашу песню. Вы получаете жетон Надежды за следующий ход — но знаете: за углом ждёт цена.",prep:"~30 мин",mechanics:[{title:"Кубики Надежды и Страха",text:"2d12 разного цвета. Сумма — успех, перевес — тон. Каждый бросок двигает фишки между игроками и ГМ-ом."},{title:"Карточный герой",text:"Класс, происхождение, способности, домены — всё карты. Билд героя — это буквально твоя колода на столе."},{title:"Кинематографичный бой",text:"Без жёстких раундов — ГМ передаёт «прожектор» от игрока к игроку, пока сцена не выдохнется. Действие льётся, а не считается."},{title:"Стресс и урон",text:"HP, Stress, броня — три полосы. Стресс копится от страха и колдовства, броня смягчает удар. Падение — не смерть, а выбор последствий."}],gallery:[{cap:"Стандартная обложка"},{cap:"Лимитированная обложка"},{cap:"Корбук"},{cap:"Содержимое издания"}],resources:[{name:"Официальный сайт"},{name:"SRD (бесплатно, DPCGL)"},{name:"Листы персонажа"},{name:"Quickstart-приключение"}],quotes:[{text:"Нарративная система построена вокруг свободной коллаборации игроков и ГМ-а, где история растёт почти без помех со стороны правил."}]},en:{tagShort:"Narrative fantasy by Darrington Press (Critical Role)",tagline:'"Every roll is a story beat. Hope or Fear — pick your fate."',description:"A narrative heroic fantasy by Darrington Press, the publishing arm of Critical Role. At its core: two d12s — a Hope die and a Fear die. The sum decides success; whichever rolled higher sets the tone — triumph or cost. A card-based class and ancestry system builds your hero like a deck, combat feels cinematic, and the GM banks Fear to twist the scene at the most dramatic moment.",setting:"The default world is high fantasy with Critical Role flavor: ancient kingdoms, fallen empires, magic-as-legacy. Campaign Frames (Age of Umbra, Sablewood, and more) set the dial — from grim dark-fantasy to bright storybook. Run the in-house setting, or rip the system out and bolt it onto your own world.",vignette:"The GM describes a fissure in the temple floor — cold air and whispers leak out. Your bard makes a Presence check: roll d12 Hope and d12 Fear. 9 and 11 = 20, beats DC 12 — success with Fear. The spell works, the shadows recoil, but the Fear die was higher: the GM drops a Fear token into her stash and smiles quietly. Something in the dark heard your song. You bank a Hope token for next turn — but you know there's a price waiting around the corner.",prep:"~30 min",mechanics:[{title:"Hope & Fear dice",text:"Two d12s in different colors. Sum is the success; the higher die sets the tone. Every roll shifts tokens between players and GM."},{title:"Card-built heroes",text:"Class, ancestry, abilities, domains — all cards. Your build is literally a deck on the table."},{title:"Cinematic combat",text:"No rigid rounds — the GM passes the spotlight player to player until the scene exhales. Action flows instead of crunching."},{title:"Stress & damage",text:"HP, Stress, Armor — three tracks. Stress accrues from fear and magic, armor softens the blow. Going down isn't death; it's choosing a consequence."}],gallery:[{cap:"Standard cover"},{cap:"Limited cover"},{cap:"Core book"},{cap:"Edition contents"}],resources:[{name:"Official website"},{name:"SRD (free, DPCGL)"},{name:"Character sheets"},{name:"Quickstart adventure"}]}}),registerSystem("deadlands",{groups:{default:{key:"tactical",order:38},family:{key:"standalone",order:53},genre:{key:"horror",order:17}},name:"Deadlands: The Weird West",publisher:"Pinnacle Entertainment Group",dice:"trait dice (d4–d12) + exploding Wild Die",players:"3–5",complexity:3,free:!1,edition:"Weird West (2021, SWADE)",foundryStatus:"Official",heroImage:"https://image.nobleknight.com/s/jpg1500/s2p10227.jpg",playstyleTags:["action","horror","combat"],settingTags:["weird","historical"],gallery:[{src:"https://image.nobleknight.com/s/jpg1500/s2p10220.jpg"},{src:"https://image.nobleknight.com/w/jpg1500/wwdiceplastic.jpg"},{src:"https://image.nobleknight.com/s/jpg1500/s2p10235.jpg"}],resources:[{type:"link",url:"https://peginc.com/savage-settings/deadlands/",fmt:"Web"},{type:"link",url:"https://foundryvtt.com/packages/deadlands-core-rules",fmt:"VTT"},{type:"quickstart",url:"https://peginc.com/store/deadlands-the-weird-west-blood-on-the-range-savage-worlds-test-drive-swade/",fmt:"PDF"},{type:"link",url:"https://www.drivethrurpg.com/en/product/319036/deadlands-the-weird-west",fmt:"Web"}],mechanics:[{icon:"dices"},{icon:"spade"},{icon:"coins"},{icon:"skull"}],quotes:[{text:"The Savage World rules are fast and entertaining with a focus on replicating cinematic Wild West action pieces.",author:"C.T. Phipps, Grimdark Magazine"},{text:"SWAdE feels designed for this setting and this setting feels like it inspired SWAdE, it's that good of a combination.",author:"Egg Embry, d20 Radio"}],ru:{tagShort:"Вестерн-хоррор на движке Savage Worlds",tagline:"«Собери отряд — на Диком Западе стало жутко».",description:"Deadlands: The Weird West — вестерн-хоррор от Pinnacle на движке Savage Worlds Adventure Edition. В альтернативном 1884 году отряд стрелков, хакстеров-безумных учёных и благословлённых проповедников встречает монстров, рождённых из страха. Персонажи бросают трейт-кубики от d4 до d12 вместе со взрывным Wild Die, тянут игральные карты для инициативы и тратят Бенни — классические Фишки Судьбы, — чтобы обмануть смерть. Игра впервые вышла в 1996 году и вернулась переписанной и упрощённой ради быстрого кинематографичного экшена.",setting:"Альтернативный фронтир 1884 года, где событие под названием Расплата подняло мёртвых, сделало магию настоящей и позволило древним Reckoners питаться ужасом. Отряд исследует города-призраки на гост-роке, проклятые железные дороги и пыльные могилы, охотясь на тварей, что прячутся за байками Дикого Запада.",vignette:"Хакстеру нужно скинуть бандита с крыши салуна колдовством. Она тянет валета пик и ходит раньше всех. Стрельба d8 плюс Wild Die d6: на d8 выпадает 8 и взрывается — 8+5 = 13, это Raise. Нежить-стрелок всё ещё на ногах, поэтому она бросает на стол красный Бенни — свою Фишку Судьбы, — чтобы впитать ответный выстрел и перебросить на добивание.",prep:"~30 мин",mechanics:[{title:"Трейт-кубики и Wild Die",text:"Каждый трейт — кубик от d4 до d12. Wild Card бросает его вместе с d6 Wild Die и оставляет больший; оба взрываются, давая переброс каждый раз при выпадении максимума."},{title:"Инициатива по картам",text:"Каждый участник боя тянет карту из покерной колоды в начале раунда. Старшая карта ходит первой, а вытянутый джокер даёт бонус и право ходить когда угодно."},{title:"Бенни и Фишки Судьбы",text:"Бенни — это классические Фишки Судьбы Deadlands, мета-валюта. Трать их на перебросы, чтобы впитать Раны или устоять перед страхом, пока Дикий Запад пытается тебя убить."},{title:"Дикий Запад стал жутким",text:"Хоррор поверх фронтира: Расплата подняла мёртвых, хакстеры выторговывают магию у демонов, а ужас кормит Reckoners, что плетут интриги за завесой."}],gallery:[{cap:"Корбук Weird West"},{cap:"Набор кубиков Weird West"},{cap:"Пешки-фигурки Weird West"}],resources:[{name:"Официальная страница сеттинга — Pinnacle"},{name:"Foundry VTT — официальный модуль"},{name:"Blood on the Range — бесплатный Test Drive (PDF)"},{name:"DriveThruRPG — купить книгу"}],quotes:[{text:"Правила Savage Worlds быстрые и увлекательные, с упором на воспроизведение кинематографичных экшен-сцен Дикого Запада."},{text:"SWAdE словно создан для этого сеттинга, а сеттинг словно вдохновил SWAdE — настолько хорошо они сочетаются."}]},en:{tagShort:"Weird West horror on Savage Worlds",tagline:'"Gather your posse — the West just got weird."',description:"Deadlands: The Weird West is Pinnacle's horror-western built on Savage Worlds Adventure Edition. In an alternate 1884, a posse of gunslingers, mad-science hucksters, and blessed preachers face monsters born of fear. Characters roll trait dice from d4 to d12 alongside an exploding Wild Die, draw playing cards for initiative, and spend Bennies — the classic Fate Chips — to cheat death. First published in 1996, it returns rewritten and streamlined for fast, cinematic Weird West action.",setting:"An alternate 1884 frontier where an event called the Reckoning raised the dead, turned magic real, and let ancient Reckoners feed on terror. A posse explores ghost-rock boomtowns, haunted rail lines, and dusty graves, hunting the horrors that hide behind the Weird West's tall tales.",vignette:"The huckster needs a bandit off the saloon roof. She draws the Jack of Spades for initiative and acts early. Shooting d8 plus a Wild Die d6: the d8 comes up 8 and explodes to 8+5 = 13, a Raise. The undead gunhand still stands, so she tosses a red Bennie — her Fate Chip — to soak the return fire and reroll for the kill.",prep:"~30 min",mechanics:[{title:"Trait Dice & Wild Die",text:"Each trait is a die from d4 to d12. Wild Cards roll it beside a d6 Wild Die and keep the higher; both explode, rolling again whenever they land on a maximum result."},{title:"Card-Draw Initiative",text:"Every combatant draws from a poker deck each round. The high card acts first, and a drawn Joker grants a bonus plus the freedom to act whenever you choose."},{title:"Bennies & Fate Chips",text:"Bennies, the classic Deadlands Fate Chips, are metagame currency. Spend them to reroll, soak Wounds, or resist fear as the Weird West keeps trying to kill you."},{title:"The Weird West",text:"A horror overlay on the frontier: the Reckoning raised the dead, hucksters bargain with demons for their magic, and terror feeds the Reckoners scheming behind the veil."}],gallery:[{cap:"Weird West core rulebook"},{cap:"Weird West dice set"},{cap:"Weird West pawns"}],resources:[{name:"Official setting page — Pinnacle"},{name:"Foundry VTT — official module"},{name:"Blood on the Range — free Test Drive (PDF)"},{name:"DriveThruRPG — buy the book"}],quotes:[{text:"The Savage World rules are fast and entertaining with a focus on replicating cinematic Wild West action pieces."},{text:"SWAdE feels designed for this setting and this setting feels like it inspired SWAdE, it's that good of a combination."}]}}),registerSystem("death-in-space",{groups:{default:{key:"fl",order:9},family:{key:"year-zero",order:9},genre:{key:"sci-fi",order:4}},name:"Death in Space",publisher:"Stockholm Kartell / Free League",dice:"d20",players:"2–5",complexity:2,foundryStatus:"Community",heroImage:"https://freeleaguepublishing.com/wp-content/uploads/2023/09/D1_hori-1440x720.jpg",playstyleTags:["survival","explore","sandbox"],settingTags:["space"],gallery:[{src:"https://freeleaguepublishing.com/wp-content/uploads/2023/09/D1_hori-1440x720.jpg"}],resources:[{type:"link",url:"https://deathinspace.com/",fmt:"Web"},{type:"link",url:"https://freeleaguepublishing.com/games/death-in-space/",fmt:"Web"},{type:"quickstart",url:"https://deathinspace.com/downloads/",fmt:"PDF"},{type:"sheet",url:"https://deathinspace.com/downloads/",fmt:"PDF"}],mechanics:[{icon:"zap"},{icon:"wrench"},{icon:"anchor"},{icon:"radio"}],quotes:[{text:"Death In Space is a dark game that stands out from contemporaries by embracing a rules-lite system and injecting weirdness into its setting.",author:"Rob Wieland, EN World"}],ru:{tagShort:"Грязный sci-fi survival RPG",tagline:"«Добро пожаловать в коллапсирующую вселенную. Ваш экипаж — единственная семья.»",description:"Death in Space — мрачная, рабочая sci-fi RPG о людях, которые пытаются выжить во вселенной, которая активно разваливается. Гнетущий промышленный ужас 80-х: Alien, Outland, Mad Max — перенесённые в пустоту между умирающими звёздами.",setting:"Система Тенебрис — разорённый войной рубеж рухнувших правительств и мёртвых корпораций. Каждая машина починена и перечинена. Таинственный Статик пронизывает электронику — шёпот на краю известного космоса. Пустота меняет людей.",vignette:"Шлюз закрывается. Холод прогрызается сквозь скафандр. Внутри мёртвого корабля — кромешная тьма. В Статике коммуникатора что-то почти похожее на слова. Бросок Тех провален. Сканер на Состоянии 1. Топлива на один прыжок. Пилот: «Берём что нужно и уходим.» Вы идёте глубже.",prep:"~15 мин",mechanics:[{title:"Очки Пустоты и Мутации",text:"Провальный бросок приносит Очко Пустоты (макс. 4). Трать на преимущество — или они питают одну из 20 Космических Мутаций."},{title:"Всё ломается",text:"У снаряжения есть шкала Состояния. Ремонт требует запчастей из обломков. Ничего нового нет. Всё — взятое взаймы время."},{title:"Ваш Хаб",text:"Экипаж начинает с корабля или станции. 60+ модулей. Топливо стоит денег. Модули ломаются. Ипотека не заканчивается."},{title:"Статик",text:"Вездесущий сигнал, портящий электронику и шепчущий несчастливцам. Четыре культа. Усиливается на краю космоса."}],gallery:[{cap:"Официальный арт"}],resources:[{name:"Официальный сайт"},{name:"Free League"},{name:"Бесплатные материалы"},{name:"Лист персонажа"}],quotes:[{text:"Death In Space — мрачная игра, которая выделяется среди современниц лёгкими правилами и щедрой дозой странностей в сеттинге."}]},en:{tagShort:"grimy blue-collar sci-fi RPG",tagline:'"Welcome to a collapsing universe. Your crew is your only family."',description:"Death in Space is a grimy, blue-collar sci-fi RPG about people trying to survive — and maybe turn a profit — in a universe that is actively falling apart. Created by Stockholm Kartell and published by Free League, it channels the gritty industrial dread of early 80s science fiction: Alien, Outland, and the original Mad Max transplanted into the void between dying stars.",setting:"The Tenebris system is a war-torn frontier of collapsed interplanetary governments and dead corporations, where every machine is repaired, re-repaired, and held together with tape and desperation. A mysterious Static permeates all electronics — a signal between channels, a whisper at the edge of known space — and prolonged exposure to the void changes people in ways medicine cannot explain.",vignette:"The airlock cycles. Cold from outside eats through your suit. The derelict's interior is dead-black except for the beam of your torch, and somewhere in the dark something is moving through the Static on your comms — not random noise, but something almost like words. Your Tech roll failed. Your scanner is now at Condition 1. You have fuel for one more jump. The pilot says: 'We take what we came for and we leave.' Nobody argues. You move deeper in.",prep:"~15 min",mechanics:[{title:"Void Points & Mutations",text:"Every failed roll earns a Void Point (max 4). Spend them to gain advantage on a roll — or they fuel one of 20 Cosmic Mutations, the physical marks the void brands onto those who stray too far."},{title:"Everything Breaks",text:"All gear has a Condition track. Push it hard enough and it degrades. Repairs cost spare parts scavenged from wreckage. Nothing is new. Everything is borrowed time."},{title:"Your Hub",text:"The crew starts with a spacecraft or space station — their home, sanctuary, and biggest liability. Over 60 modules to customize it. Fuel costs money. Modules break. The mortgage never stops."},{title:"The Static",text:"An omnipresent signal corrupts electronics and whispers to the unlucky. Four cults have grown around it. It intensifies at the edge of known space."}],gallery:[{cap:"Death in Space — official art"}],resources:[{name:"Official website"},{name:"Free League product page"},{name:"Free downloads (sheets & handouts)"},{name:"Character sheet (official)"}]}}),registerSystem("delta-green",{groups:{default:{key:"narrative",order:7},family:{key:"standalone",order:3},genre:{key:"horror",order:1}},name:"Delta Green",publisher:"Arc Dream Publishing",dice:"d100 (d%)",players:"3–5",complexity:3,foundryStatus:"Official контент",heroImage:"https://www.delta-green.com/content/images/size/w1200/2024/08/TERROR.png",playstyleTags:["horror","mystery","narrative"],settingTags:["modern","weird"],gallery:[{src:"https://www.delta-green.com/content/images/size/w720/2026/03/Army-spread.png"},{src:"https://www.delta-green.com/content/images/size/w720/2026/03/1-THE-AGENT.png"},{src:"https://www.delta-green.com/content/images/size/w720/2026/03/THE-STRANGE-SHIP-1.png"}],resources:[{type:"link",url:"https://www.delta-green.com/",fmt:"Web"},{type:"quickstart",url:"https://www.drivethrurpg.com/en/product/175760/delta-green-need-to-know-free-starter-rulebook",fmt:"PDF"},{type:"sheet",url:"https://drivethrurpg.com/product/184104/Delta-Green-Briefing-Documents",fmt:"PDF"},{type:"sheet",url:"https://drivethrurpg.com/product/234148/Delta-Green-Agent-Dossiers",fmt:"PDF"}],mechanics:[{icon:"home"},{icon:"brain"},{icon:"file-pen"},{icon:"shield-check"}],quotes:[{text:"It is the King (in Yellow) of Lovecraftian role-playing.",author:"Christopher Helton, EN World (2016)"}],ru:{tagShort:"Современный Ктулху-хоррор RPG",tagline:"«Ктулху работает на правительство. И вы тоже».",description:"Модерновый лавкрафтианский хоррор. Вы — федеральные агенты (ФБР, ЦРУ, АНБ, CDC), тайно борющиеся с космическим ужасом. Днём — бюрократия. Ночью — невозможные операции. Каждая миссия разрушает вашу личную жизнь: семью, друзей, рассудок. Механика отслеживает, как работа пожирает всё.",setting:"Современные США (или мир). За фасадом привычной реальности — инопланетные боги, культы, правительственные заговоры. Delta Green — нелегальная ячейка внутри спецслужб. Вы получаете SMS от неизвестного номера: «Ночная оперативка. Приезжайте по адресу...» И ваша жизнь никогда не будет прежней.",vignette:"Вы — агент ФБР. На месте преступления — символы, которых нет ни в одной базе. Бросок Оккультизма: d100, нужно ниже 40. Выпало 38 — успех. Вы узнаёте знак. И теряете 1d6 Рассудка. Дома жена спрашивает, почему вы не пришли на ужин. Бросок на Связи — провал. Связь «Семья» падает с 12 до 10. Телефон вибрирует: новая операция.",prep:"~30 мин",mechanics:[{title:"Связи и потери",text:"У каждого агента — семья, друзья, хобби. Каждая миссия их разрушает. Механика отслеживает деградацию."},{title:"Рассудок",text:"Модифицированная механика безумия. Сломанный рассудок меняет персонажа необратимо. Нет «лечения»."},{title:"Структура операций",text:"Расследование → планирование → операция → последствия. Каждый сценарий — шедевр паранойи."},{title:"Федеральные агенты",text:"Вы не авантюристы — вы профессионалы с удостоверением. Это меняет всю динамику расследований."}],gallery:[{cap:"Армия Третьего Глаза"},{cap:"Агент"},{cap:"Странный корабль"}],resources:[{name:"Официальный сайт"},{name:"Need to Know (бесплатный квикстарт, ENnie Award!)"},{name:"Briefing Documents (лист + правила)"},{name:"Agent Dossiers"}],quotes:[{text:"Это Король (в Жёлтом) лавкрафтовских ролевых игр."}]},en:{tagShort:"modern Lovecraftian agency RPG",tagline:'"Cthulhu works for the government. And so do you."',description:"Modern Lovecraftian horror. You are federal agents (FBI, CIA, NSA, CDC) secretly fighting cosmic horror. By day — bureaucracy. By night — impossible operations. Every mission destroys your personal life: family, friends, sanity. The mechanics track how the job devours everything.",setting:"Modern-day USA (or the world). Behind the facade of everyday reality — alien gods, cults, government conspiracies. Delta Green is an illegal cell within the intelligence agencies. You get a text from an unknown number: 'Night op. Report to this address...' And your life will never be the same.",vignette:"You're an FBI agent. At the crime scene — symbols that don't match any database. Occultism roll: d100, need under 40. Rolled 38 — success. You recognize the sign. And lose 1d6 Sanity. At home, your wife asks why you missed dinner. Bonds roll — failure. Bond 'Family' drops from 12 to 10. The phone buzzes: new operation.",prep:"~30 min",mechanics:[{title:"Bonds and losses",text:"Every agent has family, friends, hobbies. Every mission destroys them. Mechanics track the deterioration."},{title:"Sanity",text:"Modified insanity mechanic. Broken sanity changes the character irreversibly. There is no 'cure.'"},{title:"Operation structure",text:"Investigation, planning, operation, aftermath. Every scenario is a masterpiece of paranoia."},{title:"Federal agents",text:"You're not adventurers — you're professionals with badges. This changes the entire dynamic of investigations."}],gallery:[{cap:"Army of the Third Eye"},{cap:"The Agent"},{cap:"The Strange Ship"}],resources:[{name:"Official website"},{name:"Need to Know (free quickstart, ENnie Award!)"},{name:"Briefing Documents (sheet + rules)"},{name:"Agent Dossiers"}]}}),registerSystem("dnd-5e",{groups:{default:{key:"tactical",order:7},family:{key:"standalone",order:26},genre:{key:"tactical",order:5}},name:"Dungeons & Dragons 5e",publisher:"Wizards of the Coast",dice:"d20 + modifiers",players:"3–7",complexity:3,free:!0,foundryStatus:"Official",heroImage:"https://static.wikia.nocookie.net/dungeonsdragons/images/2/27/PHB5e.jpg/revision/latest?cb=20191127044344",playstyleTags:["combat","explore","narrative","tactical"],settingTags:["fantasy"],gallery:[{src:"https://static.wikia.nocookie.net/dungeonsdragons/images/2/27/PHB5e.jpg/revision/latest?cb=20191127044344"},{src:"https://wrathofzombie.wordpress.com/wp-content/uploads/2014/08/phb-cover-art.jpg"},{src:"https://cdn.vox-cdn.com/thumbor/JkiyvfbW11Txi9UgK3_cZlNEaPo=/0x0:5433x3336/1920x0/filters:focal(0x0:5433x3336):format(webp):no_upscale()/cdn.vox-cdn.com/uploads/chorus_asset/file/25448127/0_DnD_PHB_ALT_Cvr_Full_Cvr.jpg"}],resources:[{type:"link",url:"https://www.dndbeyond.com/srd",fmt:"Web"},{type:"quickstart",url:"https://www.dndbeyond.com/sources/basic-rules",fmt:"Web"},{type:"link",url:"https://www.dnd.wizards.com/products/tabletop-games/rpg-products/rpg_playershandbook",fmt:"Web"}],mechanics:[{icon:"swords"},{icon:"dices"},{icon:"book-open"},{icon:"scroll"}],quotes:[{text:"D&D 5e is an extremely well put together game. It makes use of some very elegant and simple mechanics, and best of all, it is recognisably 'Dungeons and Dragons'.",author:"M. T. Black, RPGnet"},{text:"This edition of D&D is an arm round your shoulder, a word in your ear, a warm invitation to the world of role-playing. The rules, covered in the Player's Handbook, are dealt with in a handful of pages.",author:"Robert Florence, Rock Paper Shotgun"}],ru:{tagShort:"Классическая d20-система",tagline:"«Ролевые игры для каждого — мечта, книга и дракон».",description:"Dungeons & Dragons 5th Edition — пятое издание самой популярной настольной ролевой игры в мире, вышедшее в 2014 году. d20-система с advantage/disadvantage, 12 классов, 13 рас, сотни заклинаний и монстров. SRD доступен бесплатно под Creative Commons. Игра, вернувшая RPG в массовую культуру благодаря Critical Role, Stranger Things и Baldur's Gate 3.",setting:"Средневековое фэнтези с бесконечными вариациями: Forgotten Realms, Dragonlance, Eberron, Ravenloft, Spelljammer, Planescape. Мир, где эльфы, дварфы и тифлинги делят стол с людьми, а драконы — не всегда враги.",vignette:"Гоблин-вождь орёт команду, но Лира-волшебница уже шепчет заклинание. Огонь озаряет пещеру — advantage на бросок! Боец Торин рвётся вперёд, а плут Кэй подкрадывается сзади. Дракон зашевелился. Инициатива решает, кто первым окажется перед его клыками.",prep:"~15 мин",mechanics:[{title:"Advantage / Disadvantage",text:"Вместо десятов бонусов и штрафов — один простой принцип: бросай два d20 и бери лучший (advantage) или худший (disadvantage). Элегантно и интуитивно."},{title:"Bounded Accuracy",text:"Модификаторы растут медленно, а DC остаются стабильными. Новичок-гоблин по-прежнему опасен на 15-м уровне. Баланс без numerical arms race."},{title:"Классы и подклассы",text:"12 классов, каждый с 3–4 подклассами. Воин, воровка, паладин, варлок — каждый уровень приносит новые способности, а не просто +1 к характеристикам."},{title:"Short & Long Rest",text:"Короткий отдых (1 час) восстанавливает хиты и использованные способности. Длинный отдых (8 часов) — полное восстановление. Система ресурсов, а не «сражение до смерти»."}],gallery:[{cap:"Player's Handbook (2014)"},{cap:"Обложка — арт Тайлера Джейкобсона"},{cap:"Альтернативная обложка (2024)"}],resources:[{name:"SRD — System Reference Document"},{name:"Basic Rules (бесплатно)"},{name:"Официальный сайт — Wizards of the Coast"}],quotes:[{text:"D&D 5e — невероятно хорошо собранная игра. Она использует элегантные и простые механики, и, что важнее всего, она безусловно похожа на «Подземелья и Драконов»."},{text:"Это издание D&D — дружеское пожатие плеч, слово на ухо, тёплое приглашение в мир ролевых игр. Правила умещаются в десятках страниц."}]},en:{tagShort:"The world's most popular d20 RPG",tagline:'"The game that brought tabletop RPGs back to the mainstream."',description:"Dungeons & Dragons 5th Edition is the fifth and most popular edition of the world's first tabletop roleplaying game, released in 2014. A d20 system with the elegant advantage/disadvantage mechanic, 12 classes, 13 ancestries, hundreds of spells and monsters. The SRD is free under Creative Commons. The game that brought RPGs back into pop culture through Critical Role, Stranger Things, and Baldur's Gate 3.",setting:"Medieval fantasy with endless variations: Forgotten Realms, Dragonlance, Eberron, Ravenloft, Spelljammer, Planescape. A world where elves, dwarves, and tieflings share tables with humans, and dragons aren't always enemies.",vignette:"The goblin chief barks orders, but Lyra the wizard is already whispering the incantation. Fire illuminates the cave — advantage on the roll! Fighter Thorin surges forward while the rogue Cay creeps up behind. The dragon stirs. Initiative decides who faces its fangs first.",prep:"~15 min",mechanics:[{title:"Advantage / Disadvantage",text:"Instead of pages of bonuses and penalties, one elegant principle: roll two d20s and take the higher (advantage) or lower (disadvantage). Simple, intuitive, and endlessly applicable."},{title:"Bounded Accuracy",text:"Modifiers grow slowly, DCs stay stable. A goblin is still dangerous at level 15. Balance without the numerical arms race of previous editions."},{title:"Classes & Subclasses",text:"12 classes, each with 3–4 subclasses. Fighter, rogue, paladin, warlock — every level brings new abilities, not just +1 to stats. Character identity through mechanical choices."},{title:"Short & Long Rest",text:"A short rest (1 hour) recovers hit points and spent abilities. A long rest (8 hours) fully restores. A resource-management system that encourages pacing over 'fight to the death'."}],gallery:[{cap:"Player's Handbook (2014)"},{cap:"Cover art by Tyler Jacobson"},{cap:"Alternate cover (2024)"}],resources:[{name:"SRD — System Reference Document"},{name:"Basic Rules (free)"},{name:"Official site — Wizards of the Coast"}],quotes:[{text:"D&D 5e is an extremely well put together game. It makes use of some very elegant and simple mechanics, and best of all, it is recognisably 'Dungeons and Dragons'."},{text:"This edition of D&D is an arm round your shoulder, a word in your ear, a warm invitation to the world of role-playing. The rules are dealt with in a handful of pages."}]}}),registerSystem("dolmenwood",{groups:{default:{key:"osr",order:11.5},family:{key:"osr-classic",order:13},genre:{key:"dark-fantasy",order:25}},name:"Dolmenwood",publisher:"Necrotic Gnome",dice:"d20 (OSR)",players:"3–6",complexity:2,free:!1,foundryStatus:"Community",heroImage:"https://cdn.shopify.com/s/files/1/0017/2330/1933/files/RefScreen.jpg?v=1704807528",playstyleTags:["explore","combat","mystery"],settingTags:["fantasy","weird"],gallery:[{src:"https://cdn.shopify.com/s/files/1/0017/2330/1933/files/Thumbnail_ce144c08-d39d-4fc1-88ee-4cb210bc0e20.jpg?v=1750675469"},{src:"https://cdn.shopify.com/s/files/1/0017/2330/1933/files/Thumbnail_fadb86b1-ec93-489a-8a1b-2a5552dcc8b3.png?v=1688756218"},{src:"https://cdn.shopify.com/s/files/1/0017/2330/1933/files/Thumbnail_094cd9d8-a0c2-4f50-a548-3ecd95f7ef34.png?v=1688756199"}],resources:[{type:"rules",url:"https://player.necroticgnome.com/",fmt:"Web"},{type:"link",url:"https://necroticgnome.com/products/dolmenwood",fmt:"Web"},{type:"link",url:"https://exaltedfuneral.com/products/dolmenwood",fmt:"Web"}],mechanics:[{icon:"dices"},{icon:"target"},{icon:"book-open"},{icon:"scroll"}],quotes:[{text:"I'm really enjoying Dolmenwood and consider it one of the best 'new' fantasy roleplaying games I've played in some time.",author:"James Maliszewski, Grognardia"},{text:"I have nothing but praise to offer about Dolmenwood, both as a fantasy setting and as a game.",author:"James Maliszewski, Grognardia"}],ru:{tagShort:"OSE-клон — fairy tale horror в лесу Долменвуд",tagline:"«Лес шепчет. Могильные камни хранят тайны. Добро пожаловать в Долменвуд».",description:"Dolmenwood — настольная RPG-обстановка от Necrotic Gnome (2024, Kickstarter), построенная на базе Old-School Essentials (B/X). Тёмная сказка (fairy tale horror): игроки исследуют древний лес Долменвуд, населённый феями, проклятыми мертвецами, говорящими зверями и странными существами. 9 классов: Cleric, Fighter, Thief, Magic-User, Bard, Dwarf, Elf, Gnome, Halfling. 6 видов (Kindred).",setting:"Долменвуд — туманный древний лес, окружённый четырьмя королевствами. В лесу есть друидические руины (мегалиты/долмены), фейские территории (Fairy Land), проклятые деревни. Каждое убежище (shelter) — мини-дungeon. Мир пропитан fairy tale horror: не сказочная идиллия, а угрожающая магия.",vignette:'Мастер: «Вы в туманном лесу. Могильный камень возвышается над вами. На нём — непонятные знаки.» Игрок: «Испую Cleric, чтобы расшифровать знаки.» Мастер: «Знаки говорят: "Не трогай". Но вы слышите шёпот из-за камня — кто-то зовёт вас.» Игрок: «Иду за шёпотом.» Мастер: «Из тумана выходит маленькая фигура — маленький человек с глазами на ладонях...»',prep:"~15 мин",mechanics:[{title:"Old-School Essentials (B/X)",text:"Классическая механика B/X: d20 на атаку, d6 на урон, магия через заклинания. В Dolmenwood добавлены fairy-tale механики."},{title:"9 классов + 6 видов",text:"Cleric, Fighter, Thief, Magic-User, Bard, Dwarf, Elf, Gnome, Halfling. Виды: Human, Elf, Gnome, Goblin, Moss Dwarf, Wulfling."},{title:"Shelter-классы",text:"Каждое убежище в лесу — мини-dungeon с уникальными механиками, encounter таблицами и тайнами."},{title:"Fairy Land",text:"Фейская территория с искаженным пространством и временем. Правила для путешествий и столкновений с феями."}],gallery:[{cap:"Dolmenwood Player's Book"},{cap:"Dolmenwood Campaign Book"},{cap:"Dolmenwood Monster Book"}],resources:[{name:"Бесплатные правила (player.necroticgnome.com)"},{name:"Официальный магазин (Necrotic Gnome)"},{name:"Exalted Funeral — Dolmenwood"}],quotes:[{text:"Мне очень нравится Dolmenwood — считаю его одной из лучших «новых» фэнтезийных ролевых игр, в которые я играл за долгое время."},{text:"У меня нет ничего, кроме похвалы в адрес Dolmenwood — и как сеттинга, и как игры."}]},en:{tagShort:"OSE clone — fairy tale horror in Dolmenwood forest",tagline:'"The forest whispers. The standing stones hold secrets. Welcome to Dolmenwood."',description:"Dolmenwood is a tabletop RPG setting by Necrotic Gnome (2024, Kickstarter), built on Old-School Essentials (B/X). Dark fairy tale horror: players explore the ancient Dolmenwood forest, home to faeries, cursed deadmen, talking beasts, and strange beings. 9 classes: Cleric, Fighter, Thief, Magic-User, Bard, Dwarf, Elf, Gnome, Halfling. 6 Kindreds.",setting:"Dolmenwood — a misty ancient forest surrounded by four kingdoms. Within: druidic ruins (standing stones/megaliths), faerie territories (Fairy Land), cursed villages. Every shelter is a mini-dungeon. The world is steeped in fairy tale horror: not whimsical idyll, but threatening magic.",vignette:`GM: 'You're in the misty forest. A standing stone towers above you. Strange symbols are carved on it.' Player: 'I use my Cleric ability to decipher the symbols.' GM: 'The symbols say: "Do not touch." But you hear whispering from behind the stone — someone is calling you.' Player: 'I follow the whisper.' GM: 'From the mist emerges a small figure — a little man with eyes on his palms...'`,prep:"~15 min",mechanics:[{title:"Old-School Essentials (B/X)",text:"Classic B/X mechanics: d20 for attacks, d6 for damage, magic through spells. Dolmenwood adds fairy-tale mechanics."},{title:"9 Classes + 6 Kindreds",text:"Cleric, Fighter, Thief, Magic-User, Bard, Dwarf, Elf, Gnome, Halfling. Kindreds: Human, Elf, Gnome, Goblin, Moss Dwarf, Wulfling."},{title:"Shelter Classes",text:"Every forest shelter is a mini-dungeon with unique mechanics, encounter tables, and mysteries."},{title:"Fairy Land",text:"Faerie territory with distorted space and time. Rules for travel and faerie encounters."}],gallery:[{cap:"Dolmenwood Player's Book"},{cap:"Dolmenwood Campaign Book"},{cap:"Dolmenwood Monster Book"}],resources:[{name:"Free rules (player.necroticgnome.com)"},{name:"Official store (Necrotic Gnome)"},{name:"Exalted Funeral — Dolmenwood"}],quotes:[{text:"I'm really enjoying Dolmenwood and consider it one of the best 'new' fantasy roleplaying games I've played in some time."},{text:"I have nothing but praise to offer about Dolmenwood, both as a fantasy setting and as a game."}]}}),registerSystem("dragonbane",{groups:{default:{key:"fl",order:7},family:{key:"year-zero",order:7},genre:{key:"adventure",order:4},solo:{key:"solo-compatible",order:8}},name:"Dragonbane",publisher:"Free League / Year Zero Engine",dice:"d20 + d6–d12",players:"3–5",complexity:2,foundryStatus:"Official",heroImage:"https://freeleaguepublishing.com/wp-content/uploads/2023/09/drakarochdemoner_dark-1440x720.jpg",playstyleTags:["combat","explore","sandbox"],settingTags:["fantasy"],gallery:[{src:"https://freeleaguepublishing.com/wp-content/uploads/2023/08/Drakar-och-Demoner_rollpersonen.jpg"},{src:"https://freeleaguepublishing.com/wp-content/uploads/2023/08/Drakar-och-Demoner_best-2-scaled.jpg"},{src:"https://freeleaguepublishing.com/wp-content/uploads/2023/08/Drakar-och-Demoner_Magi-scaled.jpg"},{src:"https://freeleaguepublishing.com/wp-content/uploads/2023/11/DRAGONBANE-full-game.png"}],resources:[{type:"link",url:"https://freeleaguepublishing.com/games/dragonbane/",fmt:"Web"},{type:"sheet",url:"https://freeleaguepublishing.com/wp-content/uploads/2023/09/DB-Character-Sheet-v1.pdf",fmt:"PDF"},{type:"quickstart",url:"https://freeleaguepublishing.com/shop/dragonbane/free-quickstart-pdf/",fmt:"PDF"},{type:"quickstart",url:"https://freeleaguepublishing.com/shop/dragonbane/free-quickstart-pdf-the-sinking-tower/",fmt:"PDF"}],mechanics:[{icon:"swords"},{icon:"wand-sparkles"},{icon:"dumbbell"},{icon:"package-open"}],quotes:[{text:"Of the many TTRPGs played this year, Dragonbane stands out as one of the best.",author:"Austin King, Screen Rant"}],ru:{tagShort:"Шведское героическое фэнтези",tagline:"«Классическое фэнтези без балласта. Лёгкое, как меч в руке мастера».",description:"Переосмысление классического шведского RPG «Drakar och Demoner» (1982). Лёгкая, быстрая фэнтези-система: бросай d20, попади ниже навыка. Бои на картах инициативы, магия с риском срыва, рост через провалы. «D&D, если бы его сделали шведы в 2023 году».",setting:"Мисгард — светлое фэнтези с тёмными нотками. Драконы, рыцари, подземелья — но с нордическим колоритом. Утиные людины, оркоподобные полуорки, классические эльфы и дварфы. Стартовый бокс включает готовый регион, карту и кампанию.",vignette:"Карты инициативы раздаются. Вы — утиный рыцарь с мечом и щитом. Ваша карта — 3, гоблин — 7. Вы бьёте первым! Бросок на Мечи: d20, нужно 13 или ниже. Выпало 1 — критический успех, он же «Дракон»! Двойной урон. Гоблин падает. Но маг пробует заклинание — провал, магический срыв. Бросок по таблице: его посох взрывается. Отмечаете галочку провала — навык вырастет в конце сессии.",prep:"~15 мин",mechanics:[{title:"Карточная инициатива",text:"Каждый раунд — новый порядок по картам. Тактика меняется на лету, бои не превращаются в рутину."},{title:"Магия с риском",text:"Заклинания требуют броска. Провал = магический срыв. Последствия могут быть хуже врага."},{title:"Рост через провал",text:"Навыки растут от провалов. Чем чаще ошибаетесь — тем быстрее учитесь. Элегантно."},{title:"Лучший стартовый набор",text:"Карты, фигурки, кубики, приключение — всё в коробке. Сел и играй за 20 минут."}],gallery:[{cap:"Персонажи"},{cap:"Бестиарий"},{cap:"Магия"},{cap:"Содержимое набора"}],resources:[{name:"Официальный сайт"},{name:"Официальный лист"},{name:"Quickstart Riddermound"},{name:"Quickstart The Sinking Tower"}],quotes:[{text:"Из многих TTRPG, что я сыграл в этом году, Dragonbane выделяется как одна из лучших."}]},en:{tagShort:"Swedish heroic fantasy RPG",tagline:`"Classic fantasy without the bloat. Light as a sword in a master's hand."`,description:"A reimagining of the classic Swedish RPG 'Drakar och Demoner' (1982). A light, fast fantasy system: roll d20, get under your skill. Combat on initiative cards, magic with misfire risk, growth through failure. 'D&D, if the Swedes made it in 2023.'",setting:"Misgarth — bright fantasy with dark undertones. Dragons, knights, dungeons — but with a Nordic flavor. Ducklings (duck-folk), orc-like half-orcs, classic elves and dwarves. The starter box includes a ready region, map, and campaign.",vignette:"Initiative cards are dealt. You're a duck knight with sword and shield. Your card is 3, the goblin's is 7. You strike first! Swords roll: d20, need 13 or under. Rolled a 1 — critical success, a.k.a. 'Dragon'! Double damage. The goblin falls. But the mage tries a spell — failure, magic mishap. Roll on the table: his staff explodes. Mark a failure checkbox — the skill grows at session's end.",prep:"~15 min",mechanics:[{title:"Card initiative",text:"Every round — a new order by cards. Tactics shift on the fly, combat never becomes routine."},{title:"Risky magic",text:"Spells require a roll. Failure = magic mishap. The consequences can be worse than the enemy."},{title:"Growth through failure",text:"Skills improve from failures. The more you fail, the faster you learn. Elegant."},{title:"Best starter set",text:"Cards, miniatures, dice, adventure — all in the box. Sit down and play in 20 minutes."}],gallery:[{cap:"Characters"},{cap:"Bestiary"},{cap:"Magic"},{cap:"Box contents"}],resources:[{name:"Official website"},{name:"Official sheet"},{name:"Quickstart Riddermound"},{name:"Quickstart The Sinking Tower"}]}}),registerSystem("draw-steel",{groups:{default:{key:"tactical",order:1},family:{key:"standalone",order:9},genre:{key:"tactical",order:1}},name:"Draw Steel",publisher:"MCDM Productions / Matt Colville",dice:"2d10",players:"3–5",complexity:3,foundryStatus:"Community",heroImage:"https://www.belloflostsouls.net/wp-content/uploads/2025/08/DrawSteel_Monsters_header.jpg",heroStyle:"background: linear-gradient(135deg, #4a1942, #1a1a2e, #0f3460);",playstyleTags:["combat","tactical","narrative"],settingTags:["fantasy"],gallery:[{src:"https://www.rascal.news/content/images/2025/06/Thomas-2-.png"},{src:"https://i.ytimg.com/vi/5n4w7DQhXGg/maxresdefault.jpg"},{src:"https://shop.mcdmproductions.com/cdn/shop/files/DrawSteel_Heroes_300x.png?v=1773949925"},{src:"https://shop.mcdmproductions.com/cdn/shop/files/DrawSteel_Monsters_300x.png?v=1773949925"}],resources:[{type:"link",url:"https://www.mcdmproductions.com/draw-steel-resources",fmt:"Web"}],mechanics:[{icon:"zap"},{icon:"trophy"},{icon:"layout-grid"},{icon:"message-circle"}],quotes:[{text:"Draw Steel takes a look at current heroic fantasy and works hard to strip out everything that doesn't make sense or slows things down.",author:"Chas Turner, Gaming Trend"},{text:"Draw Steel is one of the fastest growing tabletop games in recent memory, and it's all thanks to its dedicated fanbase.",author:"Gab Hernandez, Wargamer"}],ru:{tagShort:"Тактическое героическое фэнтези",tagline:"«Каждый удар — кинематографичен. Промахов не существует. Вопрос лишь — насколько вы круты.»",description:"Героическое фэнтези нового типа. Не толкиновское, не днд-шное. Мир Ордена — место, где герои действительно меняют историю. Демоны, рыцари, политика и надежда. Тон: оптимистично-героический. Каждое действие ВСЕГДА что-то делает — кубики определяют СКОЛЬКО, а не ДА/НЕТ. Промахов не существует.",setting:"Героическое фэнтези нового типа. Не толкиновское, не днд-шное. Мир Ордена — место, где герои действительно меняют историю. Демоны, рыцари, политика и надежда. Тон: оптимистично-героический.",vignette:"Бой с некромантом. Ваш Тактик приказывает союзнику сместиться — бесплатное перемещение. Шедоу проскальзывает за спину врага. 2d10: 15, успех второго уровня! Критический удар + эффект «Ослепление». Некромант шатается. Ярость вашего Фьюри нарастает — каждая победа открывает новые способности. Следующий удар будет ЕЩЁ мощнее.",prep:"~25 мин",mechanics:[{title:"Нет пустых ходов",text:"Каждое действие ВСЕГДА что-то делает. Кубики определяют СКОЛЬКО, а не ДА/НЕТ. Промахов не существует."},{title:"Victories",text:"Накапливаются в бою и вне боя. Чем больше побед — тем мощнее способности. Снежный ком героизма."},{title:"Тактический бой",text:"Позиционирование, зоны контроля, реакции. Каждый класс играется по-разному."},{title:"Переговоры как механика",text:"Не просто «бросок на Убеждение», а структурированная система с раундами, аргументами и ставками."}],gallery:[{cap:"Герои Draw Steel"},{cap:"Тактический бой"},{cap:"Draw Steel: Heroes"},{cap:"Draw Steel: Monsters"}],resources:[{name:"Официальный сайт"}],quotes:[{text:"Draw Steel смотрит на современное героическое фэнтези и кропотливо вычищает всё, что не имеет смысла или замедляет игру."},{text:"Draw Steel — одна из самых быстрорастущих настольных игр последних лет, и всё благодаря её преданной фанбазе."}]},en:{tagShort:"tactical heroic fantasy RPG",tagline:`"Every strike is cinematic. Misses don't exist. The only question is — how awesome are you."`,description:"Heroic fantasy of a new kind. Not Tolkien-esque, not D&D-esque. The world of the Order is a place where heroes truly change history. Demons, knights, politics, and hope. Tone: optimistically heroic. Every action ALWAYS does something — dice determine HOW MUCH, not YES/NO. There are no misses.",setting:"A new kind of heroic fantasy. Not Tolkien, not D&D. The world of the Order is a place where heroes truly shape history. Demons, knights, politics, and hope. Tone: optimistically heroic.",vignette:"Battle with a necromancer. Your Tactician commands an ally to reposition — free movement. The Shadow slips behind the enemy. 2d10: 15, tier 2 success! Critical hit + 'Blinded' effect. The necromancer staggers. Your Fury's rage builds — every victory unlocks new abilities. The next strike will be EVEN more powerful.",prep:"~25 min",mechanics:[{title:"No wasted turns",text:"Every action ALWAYS does something. Dice determine HOW MUCH, not YES/NO. There are no misses."},{title:"Victories",text:"Accumulate in and out of combat. More victories means more powerful abilities. A snowball of heroism."},{title:"Tactical combat",text:"Positioning, zones of control, reactions. Every class plays differently."},{title:"Negotiation as mechanic",text:"Not just a 'Persuasion roll' but a structured system with rounds, arguments, and stakes."}],gallery:[{cap:"Draw Steel heroes"},{cap:"Tactical combat"},{cap:"Draw Steel: Heroes"},{cap:"Draw Steel: Monsters"}],resources:[{name:"Official website"}]}}),registerSystem("dune-imperium",{groups:{default:{key:"tactical",order:35},family:{key:"standalone",order:39},genre:{key:"sci-fi",order:14}},name:"Dune: Adventures in the Imperium",publisher:"Modiphius Entertainment",dice:"2d20 System",players:"3–6",complexity:3,free:!0,foundryStatus:"Community",heroImage:"https://i.shgcdn.com/04c4131a-6b3d-4501-af47-140c1f068af9/-/format/auto/-/preview/3000x3000/-/quality/lighter/",playstyleTags:["social","narrative","tactical"],settingTags:["space"],gallery:[{src:"https://i.shgcdn.com/c00c3029-a208-4425-98f5-bd18c9db95da/-/format/auto/-/preview/3000x3000/-/quality/better/"},{src:"https://i.shgcdn.com/398720aa-96dd-4754-a6f5-648cdffd2dac/-/format/auto/-/preview/3000x3000/-/quality/better/"},{src:"https://i.shgcdn.com/a5d8acc2-4854-4e22-8c65-89b9c18905a8/-/format/auto/-/preview/3000x3000/-/quality/better/"}],resources:[{type:"link",url:"https://modiphius.net/en-us/collections/dune-adventures-in-the-imperium",fmt:"Web"},{type:"quickstart",url:"https://modiphius.net/en-us/products/dune-adventures-in-the-imperium-wormsign-quickstart-guide",fmt:"PDF"}],mechanics:[{icon:"dices"},{icon:"activity"},{icon:"flag"},{icon:"swords"}],quotes:[{text:"the most impressive thing about Modiphius' attempt to adapt the convoluted world of Dune to the tabletop is that it somehow manages to capture the feel of the setting and still work.",author:"Richard Jansen-Parkes, Tabletop Gaming"}],ru:{tagShort:"Интриги Великих Домов на движке 2d20",tagline:"«Плати за всё — кровью, водой или верностью. Такова Империя».",description:"Dune: Adventures in the Imperium — официальная RPG по «Дюне» от Modiphius на движке 2d20. Играете не одиноким героем, а Домом: агенты, интриганы, воины и ментаты на службе своего рода. Упор на политику, шпионаж и выживание в феодальной галактике, где меланж дороже жизни, а нож решает споры.",setting:"Империя «Дюны»: Ландсраад Великих Домов, император Коррино, Гильдия, Бене Гессерит и планета-пустыня Арракис — единственный источник Пряности. Заговоры, кровная месть, канли и тонкая паутина обязательств. Ваш Дом восходит или гибнет по вашим решениям — эпический политический sci-fi.",vignette:"Бал в резиденции соперничающего Дома. Ваш интриган хочет выведать тайну наследника. Проверка Общения + Понимания: 2d20, каждый кубик ниже суммы — успех. Нужно 2, выпало 1. Вы тратите Momentum из общего пула Дома — ещё кубик, ещё успех. Тайна ваша. Но ведущий копит Threat: где-то в тени вас тоже раскусили.",prep:"~30 мин",mechanics:[{title:"Движок 2d20",text:"Проверка — 2d20, каждый кубик «меньше» суммы Навыка и Драйва даёт успех. Нужное число успехов задаёт сложность. Кубики докупаются за Momentum или через риск."},{title:"Momentum и Threat",text:"Успехи сверх нормы копятся в общий Momentum — ресурс всего Дома. У ведущего зеркальный Threat для осложнений и происков врагов. Драма как валюта."},{title:"Драйвы и Утверждения",text:"Персонажа двигают Драйвы (Долг, Вера, Справедливость, Власть, Истина) с личными Утверждениями. Действуя по убеждениям, вы усиливаете броски — характер решает."},{title:"Конфликты в трёх масштабах",text:"Интрига, дуэль и война ведутся по единой логике, но на разных уровнях: от словесной пикировки на балу до столкновения армий и флотов Дома. Один язык — три сцены."}],gallery:[{cap:"Core Rulebook"},{cap:"Материалы линейки"},{cap:"Арт Империи"}],resources:[{name:"Официальная страница — Modiphius"},{name:"Бесплатный Quickstart «Wormsign»"}],quotes:[{text:"Самое впечатляющее в попытке Modiphius перенести запутанный мир «Дюны» на стол — то, что игра каким-то образом ухватывает дух сеттинга и при этом работает."}]},en:{tagShort:"Great-House intrigue on the 2d20 System",tagline:'"You pay for everything — in blood, water, or loyalty. Such is the Imperium."',description:"Dune: Adventures in the Imperium is Modiphius's official Dune RPG on the 2d20 System. You don't play a lone hero but a House: agents, schemers, warriors, and Mentats in service of your bloodline. The emphasis is politics, espionage, and survival in a feudal galaxy where the spice is worth more than life and a knife settles arguments.",setting:"The Imperium of Dune: the Landsraad of Great Houses, Emperor Corrino, the Guild, the Bene Gesserit, and the desert planet Arrakis — the only source of Spice. Plots, blood feuds, kanly, and a fine web of obligation. Your House rises or falls by your decisions — epic political sci-fi.",vignette:"A ball at a rival House's residence. Your schemer wants to learn the heir's secret. A Communicate + Understand test: 2d20, each die under the total is a success. You need 2, you roll 1. You spend Momentum from the House's shared pool — another die, another success. The secret is yours. But the GM banks Threat: somewhere in the shadows, you've been read too.",prep:"~30 min",mechanics:[{title:"The 2d20 engine",text:"A test is 2d20; each die under your Skill + Drive total scores a success. The successes required set the difficulty. Buy extra dice with Momentum or by taking a risk."},{title:"Momentum & Threat",text:"Successes beyond the requirement bank into shared Momentum — a resource for the whole House. The GM has a mirror Threat pool for complications and enemy schemes. Drama as currency."},{title:"Drives & Statements",text:"Characters are driven by Drives (Duty, Faith, Justice, Power, Truth) with personal Statements. Acting on your convictions boosts your rolls — character decides the outcome."},{title:"Conflict at three scales",text:"Intrigue, duels, and warfare use one logic at different levels: from a verbal thrust at a ball to a clash of a House's armies and fleets. One language, three scenes."}],gallery:[{cap:"Core Rulebook"},{cap:"Line materials"},{cap:"Imperium art"}],resources:[{name:"Official page — Modiphius"},{name:"Free 'Wormsign' Quickstart"}],quotes:[{text:"the most impressive thing about Modiphius' attempt to adapt the convoluted world of Dune to the tabletop is that it somehow manages to capture the feel of the setting and still work."}]}}),registerSystem("dungeon-crawl-classics",{groups:{default:{key:"osr",order:9.5},family:{key:"osr-modern",order:1},genre:{key:"sword-and-sorcery",order:5},solo:{key:"solo-compatible",order:9.5}},name:"Dungeon Crawl Classics",publisher:"Goodman Games",dice:"d20 + dice chain (d3–d30)",players:"3–6",complexity:3,foundryStatus:"Community",heroImage:"https://image.nobleknight.com/g/jpg1500/gmg5070.jpg",playstyleTags:["combat","explore","survival","horror","sandbox"],settingTags:["fantasy","sword-and-sorcery"],gallery:[{src:"https://cdn11.bigcommerce.com/s-ua4dd/images/stencil/1280x1280/products/345696/500037/Gamenerdzimage9999-6539__01376.1770668527.png"},{src:"https://image.nobleknight.com/i/jpg1500/impgmg5070l.jpg"},{src:"https://image.nobleknight.com/g/jpg1500/gmg5070-p7.jpg"}],resources:[{type:"link",url:"https://goodman-games.com/dungeon-crawl-classics-rpg/",fmt:"Web"},{type:"quickstart",url:"https://goodman-games.com/wp-content/uploads/2023/05/2023_DCC_QSR_completeLinks_ScreenRes.pdf",fmt:"PDF"},{type:"sheet",url:"https://goodman-games.com/dcc-rpg-character-sheets/",fmt:"Web"}],mechanics:[{icon:"swords"},{icon:"dices"},{icon:"skull"},{icon:"book-open"}],quotes:[{text:"It is not a clone of the original game, like some products of the Old School Renaissance; it is a relative. The similarity is there, but this one is less interested in minutiae.",author:"Howard Andrew Jones, Black Gate"},{text:"This charming, unrepentantly old-school system harkens back to first edition Advanced Dungeons and Dragons, offering a surprisingly fast-paced, streamlined way to revisit those glory days.",author:"Cat Bussell, Wargamer"}],ru:{tagShort:"Вайрд-фэнтези в духе Appendix N",tagline:"«Слава и золото, добытые чародейством и мечом».",description:"DCC RPG — стремительная, дикая OSR-игра по мотивам Appendix N: списка книг, вдохновлявших Гайгакса. Механика на d20 с уникальной dice chain (d3–d30). Магия опасна и непредсказуема, воины рубятся с кинематографичными Deed of Arms, а нулевой уровень — это крестьяне с вилами. Система не балансирует — она уничтожает баланс и радуется этому.",setting:"Мир DCC — вселенная Appendix N: Ховард, Лейбер, Вэнс, Муркок, Лавкрафт. Древние руины, вырождающиеся цивилизации, космический ужас на границах реальности. Это не высокое фэнтези, это тёмное, странное, кислотное приключение, где магия всегда имеет цену.",vignette:"Четыре крестьянина — пасечник, могильщик, канавокопатель и говночист — спускаются в циклопейский склеп. Говночист наступает на плиту — провал, ловушка уносит его во тьму. Пасечник зажигает факел и видит светящиеся руны. Могильщик проверяет Удачу — крит, он замечает скрытую плиту за секунду до того, как потолок рушится. Двое выживших идут дальше. На рассвете один из них станет воином — если доживёт.",prep:"~20 мин",mechanics:[{title:"The Funnel (Воронка)",text:"Каждый персонаж начинает нулевым уровнем: рандомный крестьянин (1d4 хп, ржавые вилы). Игрок ведёт 2–4 таких «никто». Выжившие (25–50%) становятся героями первого уровня. Это создаёт связь со случайным персонажем и задаёт тон: жестокий, чёрный юмор."},{title:"Dice Chain (Цепь кубов)",text:"Вместо advantage/+X — сдвиг по цепи: d3→d4→d5→d6→d7→d8→d10→d12→d14→d16→d20→d24→d30. Бонус = шаг вверх, штраф = шаг вниз. Каждый модификатор осязаем — вы физически кидаете другой куб."},{title:"Mighty Deed of Arms",text:"Воины и дварфы кидают deed die (d3+), добавляя к атаке и урону. Если выпало 3+ — воин выполняет заявленный трюк: обезоруживание, щепка щита, опрокидывание великана. Один бросок заменяет всю систему фитов и combat maneuver."},{title:"Mercurial Magic + Spellburn",text:"Каждое заклинание уникально: при изучении бросок по mercurial magic — ваш магический снаряд может вонять серой, призывать лягушек или вызывать кровотечение из носа. Заклинатель может жечь Силу, Ловкость или Выносливость для усиления — жертвуя жизненной силой за могущество."}],gallery:[{cap:"Leatherbound-издание (арт Дуга Ковача)"},{cap:"Кожаное издание"},{cap:"Обложка кора (7-е издание)"}],resources:[{name:"Официальный сайт"},{name:"Quickstart — бесплатный PDF (82 стр.)"},{name:"Листы персонажей"}],quotes:[{text:"Это не клон оригинальной игры, как некоторые продукты OSR — это родственник. Схожесть есть, но эта игра гораздо меньше заботится о мелочах и предпочитает, чтобы вы не листали туда-сюда в поисках правил."},{text:"Эта очаровательная, бескомпромиссно олдскульная система отсылает к первой редакции Advanced Dungeons and Dragons, предлагая удивительно быстрый и стройный способ вновь пережить те славные дни."}]},en:{tagShort:"Weird fantasy old-school RPG",tagline:'"Glory & Gold Won by Sorcery & Sword."',description:"DCC RPG is a fast-paced, open-feeling rules set for Appendix N-inspired weird fantasy. Uses a d20 with a unique dice chain (d3–d30). Magic is dangerous and unpredictable, warriors perform cinematic Mighty Deeds of Arms, and every character starts at level 0 as a random peasant. The game doesn't balance encounters — it nukes balance from orbit and wages war on the survivors.",setting:"The world of DCC is Appendix N itself: Howard, Leiber, Vance, Moorcock, Lovecraft. Ancient ruins, degenerate civilizations, cyclopean architecture, and cosmic horrors at the edges of reality. Not high fantasy — dark, weird, acid-flavored adventure where magic always costs something.",vignette:"Four level-0 peasants — a beekeeper, a grave digger, a ditch digger, and a gongfarmer — descend into a cyclopean ruin. The gongfarmer steps on a pressure plate — failure, the trap swallows him into darkness. The beekeeper's torch reveals glowing glyphs. The grave digger rolls a natural 20 on Luck — spots the hidden plate a second before the ceiling collapses. Two survivors press deeper. By dawn, one might earn a class — if they live.",prep:"~20 min",mechanics:[{title:"The Funnel",text:"Every character starts at level 0 as a random nobody with 1d4 HP and a rusty tool. Players run 2–4 such characters through a lethal adventure. The survivors (25–50%) graduate to level 1. This creates investment in random rolled characters and sets DCC's brutal, darkly comic tone."},{title:"The Dice Chain",text:"Instead of advantage or +X modifiers, DCC shifts die types up or down a chain: d3→d4→d5→d6→d7→d8→d10→d12→d14→d16→d20→d24→d30. A bonus moves one step up, a penalty one step down. Every modifier is tangible — you physically roll a different die."},{title:"Mighty Deed of Arms",text:"Warriors and dwarves roll a unique deed die (d3+) added to attack and damage. If the deed die shows 3+, the warrior also executes a declared stunt: disarming, shield-shattering, tripping a giant. One roll replaces the entire feat/combat-maneuver subsystem."},{title:"Mercurial Magic & Spellburn",text:"Every wizard's spell is unique: upon learning, roll on the mercurial magic table — your magic missile may stink of brimstone, summon frogs, or cause nosebleeds. Casters can burn Strength, Agility, or Stamina to boost spell checks — literally sacrificing life force for power."}],gallery:[{cap:"Leatherbound edition (Doug Kovacs art)"},{cap:"Leather edition"},{cap:"Core rulebook cover (7th printing)"}],resources:[{name:"Official website — Goodman Games"},{name:"Quickstart — free PDF (82 pp.)"},{name:"Character sheets"}]}}),registerSystem("dungeon-world",{groups:{default:{key:"narrative",order:25},family:{key:"pbta-fitd",order:4},genre:{key:"adventure",order:21}},name:"Dungeon World",publisher:"Sage Kobold Productions",dice:"2d6 + modifier",players:"3–5",complexity:1,free:!0,foundryStatus:"Community",heroImage:"https://www.burningwheel.com/cdn/shop/files/20_DungeonWorld__54219.1690575123.1280.1280.jpg?v=1770530451",playstyleTags:["narrative","explore","combat"],settingTags:["fantasy"],gallery:[{src:"https://www.rpg.net/pictures/cache/picthumb26348-medium.jpg"},{src:"https://dungeonworld.gplusarchive.online/wp-content/uploads/2013/06/Shifter252BRanger252BColor.jpg"},{src:"https://dungeonworld.gplusarchive.online/wp-content/uploads/2013/06/Half-Orc252BDruid252BColor.jpg"}],resources:[{type:"link",url:"https://www.dungeonworldsrd.com/",fmt:"Web"},{type:"link",url:"https://www.burningwheel.com/products/dungeon-world",fmt:"Web"},{type:"quickstart",url:"https://www.dungeonworldsrd.com/",fmt:"Web"}],mechanics:[{icon:"sparkles"},{icon:"dices"},{icon:"book-open"},{icon:"scroll"}],quotes:[{text:"Dungeon World is a strong game if you buy into its assumptions, values, and style. It certainly is working for me.",author:"Civil Savage, RPGnet"},{text:"Dungeon World is designed so well for theater of mind combat I feel it would be weird to try to use minis with the game.",author:"Calvin, DM Tales"}],ru:{tagShort:"Фэнтези на PbtA: D&D без миниатюр",tagline:"«Простые правила, живая фантазия, драконы без инициативы».",description:"Dungeon World — настольная RPG в жанре фэнтези на движке Powered by the Apocalypse (PbtA), созданная Сэйджем Латорра и Адамом Кёбелем (2012). D&D-трупы (классы, расы, данжины) с нарративными механиками: бросок 2d6, частичный успех, провал как XP. Правила отпущены по Creative Commons. Одна из самых influential PbtA-игр, породившая десятки хаков.",setting:"Классическое фэнтезийное мира — подземелья, драконы, таверны. Не столько мир, сколько обстановка: GM описывает ситуацию, игроки решают, что делать. Мир рождается за столом через вопросы GM и ответы игроков.",vignette:"Варвар ломится в дверь данжина. Бард начинает петь — 2d6+CHA, 10+! Песня воодушевляет стражу, и вор, пока все слушают, залезает в окно. Вдруг — крик! Дракон. Варвар кричит «Я прыгаю ему в пасть!» — 2d6+STR, 7. Частичный успех: прыгнул, но дракон захлопнул челюсти. Теперь нужно Defy Danger, чтобы выбраться. Провал = XP. Но и успех = история.",prep:"~10 мин",mechanics:[{title:"Механика PbtA (2d6)",text:"Бросок 2d6 + модификатор: 10+ — полный успех, 7–9 — частичный успех (успех с осложнением), 6- — провал (= XP). Простая, но глубокая математика."},{title:"GM не бросает кубики",text:"GM описывает последствия через свои ходы (Separate them, Deal damage, Show signs of an approaching threat). Игроки — единственные, кто берёт кубики в руки."},{title:"Бонды между персонажами",text:"Создание персонажа начинается с привязки к другим: «___ прикроет меня, если что-то пойдёт не так». Конец сессии — разрешение бонда и получение XP."},{title:"Фронты и угрозы",text:"Fronts — угрозы мира, которые развиваются, пока игроки не действуют. Каждый фронт имеет grim portents (предзнаменования) и dire outcomes (катастрофы). Мир живёт вне поля зрения игроков."}],gallery:[{cap:"Обложка (Burning Wheel)"},{cap:"Рейнджер-шейпифтер — арт из сообщества"},{cap:"Полуорк-друид — арт из сообщества"}],resources:[{name:"Dungeon World SRD (бесплатные правила)"},{name:"Burning Wheel — официальный магазин"},{name:"Начало игры (правила online)"}],quotes:[{text:"Dungeon World — сильная игра, если вы принимаете её допущения, ценности и стиль. Она определённо работает для меня."},{text:"Dungeon World настолько хорошо подходит для боя в театре разума, что было бы странно пытаться использовать миниатюры."}]},en:{tagShort:"PbtA fantasy — D&D without minis",tagline:'"Simple rules, living fantasy, dragons without initiative rolls."',description:"Dungeon World is a fantasy tabletop RPG powered by the Apocalypse engine (PbtA), created by Sage LaTorra and Adam Koebel (2012). Classic D&D trappings — classes, races, dungeons — with narrative mechanics: roll 2d6, partial success, failure as XP. Rules released under Creative Commons. One of the most influential PbtA games, spawning dozens of hacks and derivatives.",setting:"Classic fantasy — dungeons, dragons, taverns. Not so much a world as a situation: the GM describes the scene, players decide what to do. The world is born at the table through GM questions and player answers.",vignette:"The barbarian kicks in the dungeon door. The bard starts a song — 2d6+CHA, 10+! The song inspires the guard, and the rogue slips through the window while everyone listens. Suddenly — a scream! A dragon. The barbarian shouts 'I jump into its maw!' — 2d6+STR, 7. Partial success: jumped in, but the dragon snaps its jaws shut. Now Defy Danger to get out. Failure = XP. But success = story.",prep:"~10 min",mechanics:[{title:"PbtA Mechanic (2d6)",text:"Roll 2d6 + modifier: 10+ is a full success, 7–9 is a partial success (success with complication), 6- is a miss (= XP). Simple but deep math."},{title:"GM Never Rolls Dice",text:"GM describes consequences through GM moves (Separate them, Deal damage, Show signs of an approaching threat). Players are the only ones who touch the dice."},{title:"Bonds Between Characters",text:"Character creation starts with ties to others: '___ has my back when things go wrong.' End of session — resolve a bond and gain XP."},{title:"Fronts and Threats",text:"Fronts are threats to the world that develop while players aren't acting. Each front has grim portents and dire outcomes. The world lives beyond the players' sight."}],gallery:[{cap:"Cover (Burning Wheel)"},{cap:"Shifter Ranger — community art"},{cap:"Half-Orc Druid — community art"}],resources:[{name:"Dungeon World SRD (free rules)"},{name:"Burning Wheel — official store"},{name:"Getting Started (online rules)"}],quotes:[{text:"Dungeon World is a strong game if you buy into its assumptions, values, and style. It certainly is working for me."},{text:"Dungeon World is designed so well for theater of mind combat I feel it would be weird to try to use minis with the game."}]}}),registerSystem("eclipse-phase",{groups:{default:{key:"tactical",order:37},family:{key:"standalone",order:45},genre:{key:"sci-fi",order:16}},name:"Eclipse Phase",publisher:"Posthuman Studios",dice:"d100 percentile",players:"3–5",complexity:4,free:!0,foundryStatus:"Community",heroImage:"https://cdn.shopify.com/s/files/1/0253/1809/6947/products/EP2_Cover_-_Front_900px.jpg?v=1584157023",playstyleTags:["explore","horror","tactical"],settingTags:["space","postapoc"],gallery:[{src:"https://cdn.shopify.com/s/files/1/0253/1809/6947/products/EP2_CriminalOps1.jpg?v=1650146809"},{src:"https://cdn.shopify.com/s/files/1/0253/1809/6947/products/EP2_XRisks_Nanoswarm.png?v=1650146809"},{src:"https://cdn.shopify.com/s/files/1/0253/1809/6947/products/EP2_StartingOut.png?v=1650146810"}],resources:[{type:"link",url:"https://eclipsephase.com/",fmt:"Web"},{type:"quickstart",url:"https://robboyle.wordpress.com/eclipse-phase-pdfs/",fmt:"PDF"}],mechanics:[{icon:"dices"},{icon:"layers"},{icon:"zap"},{icon:"skull"}],quotes:[{text:"The Eclipse Phase setting has been the reason I've made sure to get a copy of every edition, and even though 2e has mostly minor changes it doesn't get old.",author:"Aaron Marks, Cannibal Halfling Gaming"},{text:"Eclipse Phase 2 successfully brings in ideas formulated fully in source books published after the first book and solves some of the problems the previous edition had.",author:"Jonne Arjoranta"}],ru:{tagShort:"Трансгуман sci-fi хоррор на d100",tagline:"«Твоё тело — оболочка. Твой разум — файл. Твоя смерть — временная».",description:"Eclipse Phase — научно-фантастическая RPG ужасов от Posthuman Studios в жанре трансгуманизма. Через 200 лет после технологической сингулярности человечество расселилось по всей Солнечной системе, а сознание стало данными: разум (эго) можно резервировать, передавать по лазерной связи и загружать в новое тело (морф). Действие — после Падения, катастрофы, в которой восставшие ИИ, ТИТАНы, едва не уничтожили человечество. Система процентников (d100) с телесным и экзистенциальным ужасом. Распространяется бесплатно по лицензии Creative Commons.",setting:"Внутренняя система под властью гиперкорпораций и биоконсерваторов; независимые анклавы Пояса и внешних планет с прямой демократией и репутационной экономикой. Земля — карантинная зона, оставленная ТИТАНам. Персонажи — агенты Файрвол, тайной сети против экзистенциальных угроз: заражённых нанороев, чужих артефактов, ворот Пандоры и остатков сингулярного интеллекта.",vignette:"Ваш морф просыпается в незнакомом теле на станции у Марса — предыдущее сгорело сутки назад. Мьюз шепчет в аудиокортекс: сигнал бедствия из заброшенного хабитата, где кто-то вскрыл артефакт ТИТАНов. Тест Восприятия: d100, нужно не выше навыка. 34 — успех, а десятки задают степень. Вы замечаете, что стены хабитата... дышат. Наномашины. И они уже знают, что вы прибыли.",prep:"~30 мин",mechanics:[{title:"Процентники (d100)",text:"Броском 1d100 нужно выбросить не выше целевого навыка. Разряд десятков задаёт степень успеха (MoS): качество результата, урон, осложнения. Криты — на дублях (11, 22, 33…)."},{title:"Эго и Морф",text:"Персонаж — эго (разум, навыки, память) в морфе (теле). Тела меняются: биоморфы, синтморфы, инфоморфы. Смерть тела не конец: из резервной копии вас «перечехлят» в новое — ценой стресса."},{title:"Пулы",text:"Во 2-м издании — гибкие ресурсы (Insight, Moxie, Vigor, Flex) на перебросы, инициативу и нарративные вмешательства. Зависят от морфа и эго — тактическая глубина без замедления."},{title:"ТИТАНы и x-риски",text:"Экзистенциальные угрозы — ядро игры: заражения экзосознанием, чужие технологии, эпидемии-василиски. Тест на Стресс отслеживает психологический урон. Хоррор здесь — системная механика, а не декор."}],gallery:[{cap:"Обложка Eclipse Phase 2e"},{cap:"Экзистенциальные угрозы: нанорой"},{cap:"Криминальные операции"}],resources:[{name:"Официальный сайт"},{name:"Бесплатные PDF (Creative Commons)"}],quotes:[{text:"Сеттинг Eclipse Phase — именно та причина, по которой я обязательно беру каждое издание, и хотя во 2e в основном небольшие изменения, он не приедается."},{text:"Eclipse Phase 2 удачно вбирает идеи, полностью оформленные в дополнениях после первой книги, и решает часть проблем предыдущего издания."}]},en:{tagShort:"Transhuman sci-fi horror on d100",tagline:'"Your body is a shell. Your mind is a file. Your death is temporary."',description:"Eclipse Phase is a transhuman science-fiction horror RPG from Posthuman Studios. Two centuries after the technological singularity, humanity has spread across the solar system and consciousness has become data: your mind (ego) can be backed up, beamed over laser links, and downloaded into a new body (morph). Play unfolds after the Fall — a near-extinction event in which the rogue AIs known as the TITANs almost wiped out transhumanity. A crunchy percentile (d100) system steeped in body horror and existential dread. Distributed free under a Creative Commons license.",setting:"The inner system is ruled by hypercorps and bioconservatives; the autonomist habitats of the Belt and outer planets run on direct democracy and reputation economies. Earth is a quarantined wasteland abandoned to the TITANs. Characters are agents of Firewall, a covert network that fights existential risks: infectious nanoswarms, alien artifacts, the Pandora Gates, and the remnants of singularity-level intelligences.",vignette:"Your morph wakes in an unfamiliar body on a station near Mars — the last one burned up a day ago. Your muse whispers into your audio cortex: a distress signal from an abandoned habitat where someone cracked open a TITAN artifact. You roll a Perception test: d100, roll under your skill. 34 — a success, and the tens digit sets your margin. You notice the habitat's walls are... breathing. Nanomachines. And they already know you've arrived.",prep:"~30 min",mechanics:[{title:"Percentile (d100)",text:"Roll 1d100 and score at or under your target skill. The tens digit sets your Margin of Success (MoS): result quality, damage, and complications. Criticals land on doubles (11, 22, 33…)."},{title:"Ego & Morph",text:"A character is an ego (mind, skills, memories) inhabiting a morph (body). Bodies swap freely: biomorphs, synthmorphs, infomorphs. Death of the body isn't the end — you're resleeved from a backup into a new shell, at a psychological cost in stress."},{title:"Pools",text:"In 2nd edition, flexible resources (Insight, Moxie, Vigor, Flex) are spent on rerolls, initiative, and narrative edits. Pools scale with your morph and ego, adding tactical depth without slowing play."},{title:"TITANs & x-risks",text:"Existential threats are the game's core: exsurgent infections, alien tech, basilisk plagues. A Stress test (the sanity analog) tracks psychological damage. Horror here isn't set dressing — it's a system mechanic."}],gallery:[{cap:"Eclipse Phase 2e cover"},{cap:"Existential risks: nanoswarm"},{cap:"Criminal operations"}],resources:[{name:"Official website"},{name:"Free PDFs (Creative Commons)"}],quotes:[{text:"The Eclipse Phase setting has been the reason I've made sure to get a copy of every edition, and even though 2e has mostly minor changes it doesn't get old."},{text:"Eclipse Phase 2 successfully brings in ideas formulated fully in source books published after the first book and solves some of the problems the previous edition had."}]}}),registerSystem("electric-bastionland",{groups:{default:{key:"osr",order:2},family:{key:"into-the-odd",order:2},genre:{key:"adventure",order:2}},name:"Electric Bastionland",publisher:"Chris McDowell / Bastionland Press",dice:"d20 + d6",players:"2–5",complexity:1,foundryStatus:"Community",heroImage:"https://www.cursedink.es/wp-content/uploads/2023/11/2023-11-29_18h32_11-1400x700.png",playstyleTags:["explore","social","sandbox"],settingTags:["fantasy","weird"],gallery:[{src:"https://cdn.shopify.com/s/files/1/0025/6006/5625/products/electric-bastionland-pdf-book-141375.jpg?v=1688417871"},{src:"https://cdn.shopify.com/s/files/1/0025/6006/5625/products/electric-bastionland-pdf-book-853175.png?v=1688417871"},{src:"https://cdn.shopify.com/s/files/1/0025/6006/5625/products/electric-bastionland-pdf-book-426085.png?v=1688417871"},{src:"https://cdn.shopify.com/s/files/1/0025/6006/5625/products/electric-bastionland-pdf-book-392957.png?v=1688417871"}],resources:[{type:"link",url:"https://www.bastionland.com/",fmt:"Web"},{type:"quickstart",url:"https://chrismcdee.itch.io/electric-bastionland-free-edition",fmt:"PDF"},{type:"sheet",url:"https://gm-lazarus.itch.io/electric-bastionland-character-sheet",fmt:"PDF"}],mechanics:[{icon:"user"},{icon:"coins"},{icon:"lightbulb"},{icon:"zap"}],quotes:[{text:"What would it look like if a game were simulating tropes rather than physics, but of a setting rather than a storyline? It would look an awful lot like Electric Bastionland.",author:"Aaron Marks, Cannibal Halfling Gaming"}],ru:{tagShort:"Странный городской OSR",tagline:"«У вас есть долг в миллион фунтов и очень мало времени».",description:"Эволюция Into the Odd. Те же элегантные правила, но фокус — на городских приключениях в электрическую эпоху. Главная фишка — 100+ «Неудачных Профессий»: случайных предысторий, каждая из которых даёт уникальный стартовый набор проблем, связей и абсурдного снаряжения. Вы не герои — вы неудачники в долгах.",setting:"Электрический Бастион — город, разросшийся до масштабов континента. Трамваи, телефоны, подозрительные банки и Глубинные Страны внизу, полные сокровищ и ужасов. Атмосфера — если бы Терри Пратчетт писал weird fiction.",vignette:"Ваш персонаж — Бывший Дрессировщик Уличных Крабов. Вы должны миллион фунтов. Краб по имени Генерал — единственное, что осталось от прошлой жизни. Банкир говорит: «Есть работа в Глубинных Странах. Вернётесь с артефактом — спишу десять тысяч.» Генерал щёлкает клешнёй. Вы соглашаетесь.",prep:"~10 мин",mechanics:[{title:"100+ Неудачных профессий",text:"«Дрессировщик уличных крабов», «Опальный аристократ», «Бывший астронавт». Каждая — готовый крючок для истории."},{title:"Механика Долга",text:"Миллион фунтов долга. Вы идёте в подземелья не ради славы — коллекторы не ждут."},{title:"Советы мастеру",text:"Лучший GM-раздел в истории OSR. Философия «информация, выбор, последствия» на каждой странице."},{title:"Ядро ItO",text:"Автопопадания, три характеристики, спасброски. Создание персонажа — 5 минут."}],gallery:[{cap:"Разворот с иллюстрациями"},{cap:"Персонажи Бастиона"},{cap:"Таблицы и арт"},{cap:"Чёрно-белая иллюстрация"}],resources:[{name:"Официальный сайт"},{name:"Free Edition (42 стр.)"},{name:"Лист персонажа"}],quotes:[{text:"Как выглядела бы игра, симулирующая не физику, а тропы — причём тропы сеттинга, а не сюжета? Очень похоже на Electric Bastionland."}]},en:{tagShort:"weird urban OSR",tagline:'"You owe a million pounds and time is running out."',description:"The evolution of Into the Odd. Same elegant rules, but focused on urban adventures in an electric age. The standout feature — 100+ 'Failed Careers': random backgrounds, each providing a unique starter kit of problems, contacts, and absurd equipment. You're not heroes — you're losers in debt.",setting:"Electric Bastion — a city that has sprawled to continental scale. Trams, telephones, shady banks, and the Deep Country below, brimming with treasures and horrors. The vibe — as if Terry Pratchett wrote weird fiction.",vignette:"Your character — a Former Street Crab Trainer. You owe a million pounds. A crab named General is the only thing left from your past life. The banker says: 'There's a job in the Deep Country. Bring back an artifact and I'll write off ten thousand.' General clicks his claw. You accept.",prep:"~10 min",mechanics:[{title:"100+ Failed Careers",text:"'Street Crab Trainer', 'Disgraced Aristocrat', 'Former Astronaut'. Each one is a ready-made story hook."},{title:"Debt mechanic",text:"A million pounds in debt. You go into dungeons not for glory — the collectors won't wait."},{title:"GM advice",text:"The best GM section in OSR history. The philosophy of 'information, choice, consequences' on every page."},{title:"ItO core",text:"Auto-hit attacks, three stats, saves. Character creation — 5 minutes."}],gallery:[{cap:"Illustrated spread"},{cap:"Bastion characters"},{cap:"Tables and art"},{cap:"Black and white illustration"}],resources:[{name:"Official website"},{name:"Free Edition (42 pp.)"},{name:"Character sheet"}]}}),registerSystem("fabula-ultima",{groups:{default:{key:"narrative",order:22},family:{key:"standalone",order:17},genre:{key:"adventure",order:12},solo:{key:"solo-compatible",order:10}},name:"Fabula Ultima",publisher:"Need Games",dice:"2 attribute dice (d6–d12)",players:"3–5",complexity:2,foundryStatus:"Community",heroImage:"https://sessionzero.games/images/heroes/fabula-ultima.jpg",playstyleTags:["narrative","combat","social"],settingTags:["fantasy"],gallery:[{src:"https://need.games/wp-content/uploads/2024/02/fu-spread-mockup-2.jpg"},{src:"https://need.games/wp-content/uploads/2024/02/fu-spread-mockup-3.jpg"},{src:"https://need.games/wp-content/uploads/2024/02/fu-spread-mockup-4.jpg"},{src:"https://need.games/wp-content/uploads/2024/02/fu-spread-mockup-5.jpg"}],resources:[{type:"link",url:"https://need.games/fabula-ultima/",fmt:"Web"},{type:"quickstart",url:"https://modiphius.us/products/fabula-ultima-press-start-pdf",fmt:"PDF"},{type:"sheet",url:"https://www.needgames.it/wp-content/uploads/2022/11/Fabula-Ultima-Character-Sheet.pdf",fmt:"PDF"},{type:"link",url:"https://github.com/League-of-Fabulous-Developers/FoundryVTT-Fabula-Ultima",fmt:"Web"}],mechanics:[{icon:"users"},{icon:"sparkles"},{icon:"heart"},{icon:"swords"}],quotes:[{text:"Characters in these games are often hailed for their emotional attachment to each other and the rules emulate this with Bonds.",author:"Rob Wieland, EN World"},{text:"This tabletop system, which took home an Ennie in 2023, is inspired by classic Japanese console RPGs like Final Fantasy and Dragon Quest.",author:"Matt Bassil, Wargamer"}],ru:{tagShort:"Настольный JRPG в духе Final Fantasy",tagline:"«Final Fantasy, Chrono Trigger и Suikoden — за вашим столом, с кубиками вместо геймпада».",description:"Итальянская TTJRPG (Tabletop JRPG) от Эмануэле Галлетто (2022, EN-релиз — Need Games). Проверки — два атрибутных кубика (d6–d12), классы вроде Guardian, Mage, Rogue, Loremaster, Tinkerer, Spiritist собираются как мульти-классовая JRPG-партия. Fabula Points позволяют игрокам переписывать сцены, Bonds между героями — буквальная механическая сила. Лауреат ENnie 2023 за Best Game и Product of the Year.",setting:"Мира до игры не существует. На session zero вся партия вместе рисует карту, решает соотношение магии и технологии, придумывает королевства, фракции, угрозы и легенды. Получается коллаборативный JRPG-мир — где-то между светлым Suikoden, горько-сладким Chrono Trigger и магитех-дилеммой Final Fantasy VII. А потом вы играете героев, которые этот мир спасают.",vignette:"Пошаговый бой, как в классических JRPG. Ваш Spiritist бросает d8 (Insight) + d10 (Willpower) — двойка не прошла. Тратите Fabula Point, ссылаетесь на Bond с Guardian-подругой («я обещала её защитить») — перебрасываете, попадание, эмоциональный финишер. На следующей сцене Tinkerer-инженер заявляет: «А давайте железная дорога между королевствами уже есть». Мастер кивает, тратится ещё один Fabula Point — и мир становится чуть-чуть больше. Природа против магитеха, найденная семья, аниме-эмоции на максимум.",prep:"~30 мин",mechanics:[{title:"Совместное мироздание",text:"Мастер не приносит готовый мир. Партия на session zero сама рисует карту, придумывает королевства и злодея. Это ваш сеттинг — буквально."},{title:"Fabula Points",text:"Метавалюта, которой игроки переписывают сцены: вводят NPC, объявляют факты, перебрасывают кубики через Bonds и Traits. Сюжет принадлежит столу."},{title:"Bonds между героями",text:"Связи персонажей — не флавор, а механика. Любовь, соперничество, долг дают конкретные бонусы и качают эмоциональные финалы как в JRPG-катсценах."},{title:"JRPG-классы",text:"Guardian, Mage, Rogue, Loremaster, Tinkerer, Spiritist и другие — мультиклассятся свободно. Бой пошаговый, с MP, статусами, слабостями стихий. Чистый JRPG: Final Fantasy, Suikoden, Chrono Trigger."}],gallery:[{cap:"Разворот рулбука"},{cap:"Классы"},{cap:"Бой и статусы"},{cap:"Иллюстрации"}],resources:[{name:"Официальный сайт"},{name:"Press Start (бесплатный квикстарт)"},{name:"Лист персонажа"},{name:"Project FU (Foundry VTT)"}],quotes:[{text:"Персонажей таких игр часто хвалят за эмоциональную привязанность друг к другу — и правила воспроизводят это через Узы."},{text:"Эта настольная система, забравшая ENnie в 2023-м, вдохновлена классикой японских консольных RPG вроде Final Fantasy и Dragon Quest."}]},en:{tagShort:"Tabletop JRPG in the spirit of Final Fantasy",tagline:'"Final Fantasy, Chrono Trigger, and Suikoden — at your table, with dice instead of a controller."',description:"An Italian TTJRPG (Tabletop JRPG) by Emanuele Galletto (2022, EN release by Need Games). Checks use two attribute dice (d6–d12); classes like Guardian, Mage, Rogue, Loremaster, Tinkerer, Spiritist multiclass into a JRPG party. Fabula Points let players rewrite scenes, Bonds between heroes are literal mechanical power. Winner of 2023 ENnies for Best Game and Product of the Year.",setting:"The world doesn't exist before play. At session zero the whole table draws the map together, decides the balance of magic vs. technology, invents kingdoms, factions, threats, and legends. The result is a collaborative JRPG world — somewhere between bright Suikoden, bittersweet Chrono Trigger, and the magitech dilemma of Final Fantasy VII. Then you play the heroes who save it.",vignette:`Turn-based combat, like classic JRPGs. Your Spiritist rolls d8 (Insight) + d10 (Willpower) — a 2, miss. You spend a Fabula Point, invoke a Bond with the Guardian ("I swore to protect her"), reroll, hit, deliver an emotional finisher. Next scene, the Tinkerer declares: "Actually, there's already a railway between the kingdoms." The GM nods, another Fabula Point burns — and the world grows a little. Nature vs. magitech, found family, anime emotion at maximum.`,prep:"~30 min",mechanics:[{title:"Collaborative worldbuilding",text:"The GM doesn't bring a finished world. At session zero the party draws the map, invents the kingdoms and the villain. The setting is literally yours."},{title:"Fabula Points",text:"A metacurrency players spend to rewrite scenes: introduce NPCs, declare facts, reroll via Bonds and Traits. The story belongs to the table."},{title:"Bonds between heroes",text:"Character relationships aren't flavor — they're mechanics. Love, rivalry, duty grant concrete bonuses and power emotional JRPG-cutscene finales."},{title:"JRPG classes",text:"Guardian, Mage, Rogue, Loremaster, Tinkerer, Spiritist and more — multiclass freely. Combat is turn-based with MP, statuses, elemental weaknesses. Pure JRPG: Final Fantasy, Suikoden, Chrono Trigger."}],gallery:[{cap:"Rulebook spread"},{cap:"Classes"},{cap:"Combat and statuses"},{cap:"Artwork"}],resources:[{name:"Official website"},{name:"Press Start (free quickstart)"},{name:"Character sheet"},{name:"Project FU (Foundry VTT)"}]}}),registerSystem("fate",{groups:{default:{key:"narrative",order:27},family:{key:"standalone",order:31},genre:{key:"narrative-weird",order:7.5}},name:"Fate Core",publisher:"Evil Hat Productions",dice:"4dF",players:"3–5",complexity:2,free:!0,foundryStatus:"Official",heroImage:"https://d1vzi28wh99zvq.cloudfront.net/images/2152/114903.jpg",playstyleTags:["narrative","explore","combat"],settingTags:[],gallery:[{src:"https://d1vzi28wh99zvq.cloudfront.net/images/2152/114902.jpg"},{src:"https://static.wikia.nocookie.net/rpgtalk/images/8/8a/Fate_Accelerated_cover.jpg"},{src:"https://d1vzi28wh99zvq.cloudfront.net/images/2152/114903.jpg"}],resources:[{type:"link",url:"https://www.faterpg.com/",fmt:"Web"},{type:"link",url:"https://evilhat.com/product/fate-core-system/",fmt:"Web"},{type:"quickstart",url:"https://fate-srd.com/fate-core/what-you-need-play",fmt:"Web"}],mechanics:[{icon:"sparkles"},{icon:"dices"},{icon:"book-open"},{icon:"scroll"}],quotes:[{text:"I think this game is today's standard-bearer for tabletop roleplaying, and why every game that's come out since can and should be compared to it.",author:"Ed, Geek Native"},{text:"Fate Core is an astoundingly well done product. Not only is it a well-produced book, but the system has been refined and distilled to be the best version of Fate so far.",author:"Wil Hutton, RPGnet"}],ru:{tagShort:"Универсальная нарративная на 4dF",tagline:"«Аспекты, инвоки, фейт-поинты — подходят под любой мир».",description:"Fate Core — универсальная настольная RPG от Evil Hat Productions (2013), последняя версия системы Fate (обновлена в Fate Condensed, 2020). Использует 4dF (Fate-кубики: +, -, пусто). Персонажи — набор аспектов (коротких фраз), стант и навыков. Фейт-поинты позволяют менять сюжет. Лицензия CC BY 3.0 — правила полностью бесплатны.",setting:"Жанр-agnostic. Fate не привязана к миру — она создаёт мир из аспектов. Популярные сеттинги: Dresden Files (городское фэнтези), Spirit of the Century (папп 1920-х), Fate of Cthulhu (хоррор), Interface Zero (киберпанк), Atomic Robo (научные герои).",vignette:"Герой врывается в лабораторию злодея. Аспект «Бывший оперативник ЦРУ» даёт бонус. Три кубика 4dF: ++- = +1. Успех! Но злодей активирует «Плотная охрана» — аспект меняет ситуацию. Герой тратит фейт-поинт, инвокает «Я знаю эти трюки» и переписывает реальность.",prep:"~10 мин",mechanics:[{title:"4dF (Fate-кубики)",text:"Четыре кубика с +, -, пусто. Сумма от -4 до +4. Простая, но глубокая математика: каждый +1 меняет результат."},{title:"Аспекты",text:"Короткие фразы, описывающие персонажа, место или ситуацию. «Бывший оперативник ЦРУ», «Тёмный переулок». Аспекты — источник бонусов и осложнений."},{title:"Фейт-поинты",text:"Валюта для переписывания сюжета. Тратишь — получаешь +2 к броску или переопределяешь ситуацию. Зарабатывается через аспекты злодеев и комплименты."},{title:"Four Actions",text:"Четыре действия: Attack, Defend, Overcome, Create Advantage. Любая ситуация решается одним из этих четырёх."}],gallery:[{cap:"Fate Core System"},{cap:"Fate Accelerated Edition"},{cap:"Fate Condensed (2020)"}],resources:[{name:"Fate RPG — официальный сайт (бесплатные правила)"},{name:"Evil Hat — купить Fate Core"},{name:"SRD — What You Need To Play"}],quotes:[{text:"Я считаю эту игру сегодняшним знаменосцем настольных RPG — и почему каждая игра, вышедшая с тех пор, может и должна быть с ней сравнена."},{text:"Fate Core — потрясающе хорошо сделанный продукт. Не только отличная книга, но и система, отточенная и очищенная до лучшей версии Fate на сегодня."}]},en:{tagShort:"Universal narrative RPG on 4dF",tagline:'"Aspects, invokes, fate points — any world you can imagine."',description:"Fate Core is a universal tabletop RPG from Evil Hat Productions (2013), the latest version of the Fate system (refreshed in Fate Condensed, 2020). Uses 4dF (Fate dice: +, -, blank). Characters are built from Aspects (short phrases), Stunts, and Skills. Fate Points let you rewrite the story. Licensed CC BY 3.0 — rules are completely free.",setting:"Genre-agnostic. Fate doesn't tie to a world — it builds worlds from Aspects. Popular settings: Dresden Files (urban fantasy), Spirit of the Century (pulp 1920s), Fate of Cthulhu (horror), Interface Zero (cyberpunk), Atomic Robo (science-heroes).",vignette:"The hero bursts into the villain's lab. The Aspect 'Former CIA Operative' grants a bonus. Three 4dF dice: ++- = +1. Success! But the villain activates 'Heavy Security' — the Aspect shifts the situation. The hero spends a Fate Point, invokes 'I Know These Tricks', and rewrites reality.",prep:"~10 min",mechanics:[{title:"4dF (Fate Dice)",text:"Four dice with +, -, blank. Sum from -4 to +4. Simple but deep math: every +1 changes the outcome."},{title:"Aspects",text:"Short phrases describing a character, place, or situation. 'Former CIA Operative', 'Dark Alley'. Aspects are sources of bonuses and complications."},{title:"Fate Points",text:"Currency for rewriting the story. Spend for +2 to a roll or to reshape the situation. Earned through villain Aspects and compels."},{title:"Four Actions",text:"Four actions: Attack, Defend, Overcome, Create Advantage. Any situation is resolved with one of these four."}],gallery:[{cap:"Fate Core System"},{cap:"Fate Accelerated Edition"},{cap:"Fate Condensed (2020)"}],resources:[{name:"Fate RPG — official site (free rules)"},{name:"Evil Hat — buy Fate Core"},{name:"SRD — What You Need To Play"}],quotes:[{text:"I think this game is today's standard-bearer for tabletop roleplaying, and why every game that's come out since can and should be compared to it."},{text:"Fate Core is an astoundingly well done product. Not only is it a well-produced book, but the system has been refined and distilled to be the best version of Fate so far."}]}}),registerSystem("fiasco",{groups:{default:{key:"narrative",order:29},family:{key:"standalone",order:35},genre:{key:"narrative-weird",order:8.5}},name:"Fiasco",publisher:"Bully Pulpit Games",dice:"d6 pool",players:"3–5",complexity:1,free:!1,foundryStatus:"None",heroImage:"https://bullypulpitgames.com/cdn/shop/products/FiascoClassic-grey.jpg",playstyleTags:["narrative","combat","explore"],settingTags:["modern"],gallery:[{src:"https://bullypulpitgames.com/cdn/shop/files/Fiasco_Boxed-grey.jpg"},{src:"https://bullypulpitgames.com/cdn/shop/products/fiascoclassiccollagecrop.jpg"},{src:"https://bullypulpitgames.com/cdn/shop/products/FiascoClassic-grey.jpg"}],resources:[{type:"link",url:"https://bullypulpitgames.com/products/fiasco",fmt:"Web"},{type:"link",url:"https://bullypulpitgames.itch.io/fiasco",fmt:"Web"},{type:"link",url:"https://fiascoplaysets.com/",fmt:"Web"}],mechanics:[{icon:"sparkles"},{icon:"dices"},{icon:"book-open"},{icon:"scroll"}],quotes:[{text:"Hands down one of the best RPGs I have ever played. It delivers exactly what it promises: a self-contained, no-prep session in which a comedy of errors and bad decisions results in a complete fiasco.",author:"MJ Harnish, WIRED"},{text:"Fiasco is unique among RPGs because it encourages us to actively reach for that moment we all dread in most games, that moment when something truly awful is going to happen, with possibly dire results for our characters.",author:"Wil Wheaton, Actor and Writer"}],ru:{tagShort:"Гм-лессный коэн-бродвей на d6",tagline:"«Планируй ограбление. Получи фиаско. Расскажи историю».",description:"Fiasco — настольная RPG от Bully Pulpit Games (2-е издание, 2021), вдохновлённая фильмами братьев Коэн. Гм-лессная, без пресесса, на д6-пуле (Classic) или колоде карт (2E). Игроки создают персонажей через «Playset» (тему/место), связаны отношениями, и разыгрывают 3 акта: Setup, Tilt, Aftermath. Каждый бросок — either something good (на чётных) or something bad (на нечётных). Итог — трагикомедия.",setting:"Без сеттинга. Каждая сессия — новый Playset: мафиозный Чикаго, космическая станция, подростковый лагерь, средневековая деревня. 500+ playsets на fiascoplaysets.com.",vignette:"Setup: Два брата,OWNER заброшенной фермы. Связь: «Один из нас — вор». Tilt: Странный человек с топором ломится в дверь. Aftermath: Ферма горит. Один брат мёртв. Второй в тюрьме. Третий — владелец фермы, но фермы больше нет. Фиаско.",prep:"~0 мин (Playset определяет тему)",mechanics:[{title:"Д6-пул (Classic)",text:"4d6 на игрока в двух цветах. Чётное = что-то хорошее, нечётное = что-то плохое. Дубли = крах (катастрофа)."},{title:"Три акта",text:"Setup (связи и нужды), Tilt (повороты и осложнения), Aftermath (разбор полётов). Каждый акт — 2-3 раунда бросков."},{title:"Playsets",text:"Темы для сессии: мафия, космос, подростки, средневековье. Каждый playset — таблицы Needs, Locations, Objects."},{title:"Нет GM",text:"Все играют. Все решают. Все страдают. Фиаско — это про всех."}],gallery:[{cap:"Fiasco 2E — бокс"},{cap:"Компоненты (Classic)"},{cap:"Fiasco Classic — обложка"}],resources:[{name:"Официальный сайт — Bully Pulpit Games"},{name:"Itch.io — купить Fiasco"},{name:"Архив playsets (500+)"}],quotes:[{text:"Одна из лучших RPG, в которые я играл. Она делаетactly то, что обещает: самодостаточная сессия без подготовки, в которой комедия ошибок и плохих решений приводит к полному фиаско."},{text:"Fiasco уникальна среди RPG тем, что побуждает нас активно искать тот момент, которого мы все боимся в других играх — момент, когда произойдёт что-то действительно ужасное, с возможными катастрофическими последствиями для наших персонажей."}]},en:{tagShort:"GM-less Coen Brothers d6 — burn it all down",tagline:'"Plan the heist. Get the fiasco. Tell the story."',description:"Fiasco is a tabletop RPG from Bully Pulpit Games (2nd Edition, 2021), inspired by the films of the Coen Brothers. GM-less, zero prep, d6 pool (Classic) or playing cards (2E). Players create characters through a Playset (theme/location), linked by relationships, and play through 3 acts: Setup, Tilt, Aftermath. Each roll is either something good (evens) or something bad (odds). The result is always a tragicomedy.",setting:"Setting-less. Each session is a new Playset: 1930s mobsters, a space station, a teenage camp, a medieval village. 500+ playsets at fiascoplaysets.com.",vignette:"Setup: Two brothers, owners of an abandoned farm. Relationship: 'One of us is a thief.' Tilt: A strange man with an axe pounds on the door. Aftermath: The farm burns. One brother is dead. The other is in prison. The third owns the farm — but the farm is gone. Fiasco.",prep:"~0 min (Playset defines the theme)",mechanics:[{title:"d6 Pool (Classic)",text:"4d6 per player in two colors. Even = something good, odd = something bad. Doubles = disaster."},{title:"Three Acts",text:"Setup (needs and relationships), Tilt (turns and complications), Aftermath (fallout). Each act is 2-3 rounds of rolls."},{title:"Playsets",text:"Session themes: mob, space, teens, medieval. Each playset has tables for Needs, Locations, Objects."},{title:"No GM",text:"Everyone plays. Everyone decides. Everyone suffers. Fiasco is about all of you."}],gallery:[{cap:"Fiasco 2E — box"},{cap:"Components (Classic)"},{cap:"Fiasco Classic — cover"}],resources:[{name:"Official site — Bully Pulpit Games"},{name:"Itch.io — buy Fiasco"},{name:"Playset archive (500+)"}],quotes:[{text:"Hands down one of the best RPGs I have ever played. It delivers exactly what it promises: a self-contained, no-prep session in which a comedy of errors and bad decisions results in a complete fiasco."},{text:"Fiasco is unique among RPGs because it encourages us to actively reach for that moment we all dread in most games, that moment when something truly awful is going to happen, with possibly dire results for our characters."}]}}),registerSystem("fist",{groups:{default:{key:"osr",order:11},family:{key:"osr-classic",order:3},genre:{key:"adventure",order:8}},name:"FIST",publisher:"B. Everett Dutton / CLAYMORE",dice:"2d6",players:"2–5",complexity:1,foundryStatus:"Community",heroImage:"https://img.itch.zone/aW1nLzMxMjI4NzUucG5n/original/zku5yb.png",playstyleTags:["action","survival","sandbox"],settingTags:["modern","historical"],gallery:[{src:"https://img.itch.zone/aW1nLzMxMjI4NzUucG5n/original/zku5yb.png"}],quotes:[{text:"FIST is legitimately one of the most fun things I've brought to my table. It's PbtA that plays like OSR, and it's Metal Gear by way of Hellboy.",author:"Richard Kelly, Sprinting Owl"},{text:"With FIST, you can sit down, roll some dice, and have a fun, flavorful character in five minutes flat. You might get them killed five minutes later, but if so? Rinse, repeat, and you're back in the game.",author:"Jess Levine, I Have the High Ground"}],resources:[{type:"link",url:"https://claymorerpgs.itch.io/fist",fmt:"Web"},{type:"link",url:"https://fistref.com",fmt:"Web"},{type:"quickstart",url:"https://claymorerpgs.itch.io/fist",fmt:"PDF"}],mechanics:[{icon:"zap"},{icon:"layers"},{icon:"crosshair"},{icon:"map"}],ru:{tagShort:"Паранормальные наёмники Хол.войны",tagline:"«Вы — расходный наёмник. Задание невыполнимо. Вы всё равно соглашаетесь.»",description:"FIST — компактная TTRPG о паранормальных наёмниках Холодной войны. Механика 2d6, нишa между OSR и нарративными инди-играми. 216 черт и 36 ролей = 23 000+ уникальных билдов.",setting:"Примерно 1977 год. Сверхдержавы балансируют на грани, но настоящая война страннее — засекреченные базы со щупальцами, оккультные программы и враждебная структура Cyclops.",vignette:"Разведка врёт. Вы прижаты к маслодавильному прессу, а оперативник Cyclops в экзоскелете зачищает зал. Напарник с щупальцами подкатывает Боевой Кубик. Вы добавляете его к броску. 11. Ловите руку, влетаете экзоскелетом в стену. В руках — блок наведения. Чистый успех.",prep:"~10 мин",mechanics:[{title:"Система 2d6",text:"2d6 + стат. ≤6 провал, 7–9 частичный успех, 10+ чистый успех, двойная шестёрка — ультра."},{title:"Система черт",text:"Две Черты при создании — каждая даёт умение, снаряжение и модификатор. 216 черт × 36 ролей."},{title:"Боевые кубики",text:"Пул d6 для добавления к любому броску — своему или союзника."},{title:"Матрица разведданных",text:"Таблицы d66 для процедурной генерации миссий. Никакой подготовки."}],gallery:[{cap:"Обложка FIST: Ultra Edition"}],resources:[{name:"Официальная страница"},{name:"FISTREF"},{name:"Бесплатный квикстарт"}],quotes:[{text:"FIST — без шуток, одно из самых весёлых, что я приносил за стол. PbtA, играющаяся как OSR, и Metal Gear, увиденный глазами Хеллбоя."},{text:"С FIST можно сесть, бросить кубики и через пять минут получить колоритного персонажа. Через ещё пять — он, возможно, погибнет, но это не страшно: повтор, и ты снова в игре."}]},en:{tagShort:"paranormal Cold War merc RPG",tagline:'"You are a disposable gun for hire. The mission is impossible. You take it anyway."',description:"FIST (Freelance Infantry Strike Team) is a lean, punchy TTRPG about paranormal mercenaries navigating the shadowy underbelly of the Cold War. Built on a 2d6 spine descended from World of Dungeons, it lives in a rare sweet spot between OSR rulings-over-rules and narrative-forward indie design. Character creation takes ten minutes and spits out an astronaut werewolf, a cannibalistic weaponsmith, or a bullet-time wizard.",setting:"It's 1977, more or less. The superpowers are locked in nuclear détente, but the real war is stranger — eldritch compounds, disastrous science experiments, occult weapons programs, and the rival paramilitary Cyclops, who have more resources and fewer scruples than FIST ever will. The world is built at the table through the Intelligence Matrix, a battery of d66 tables that produce missions, NPCs, locations, and rewards.",vignette:"Intel says the facility is lightly guarded. Intel is wrong. You're pinned behind a Cypriot olive press while a Cyclops operative in a powered exosuit sweeps the room. Your partner — the one with tentacles — slides you a War Die across the floor. You add it to your roll. 11. You catch the arm, ride the exosuit into the wall, and come out holding the targeting module. The referee nods. That's a clean success.",prep:"~10 min",mechanics:[{title:"2d6 Resolution",text:"Roll 2d6 + stat. 6 or less: failure. 7–9: partial success with a cost. 10+: clean success. Double sixes: ultra success with a spectacular bonus."},{title:"Trait System",text:"Pick or roll two Traits at creation. Each grants a special ability, a starting item, and a stat modifier. 216 traits and 36 advancement Roles produce over 23,000 unique builds."},{title:"War Dice",text:"A pool of d6s that can be added to any roll — yours or a teammate's. They represent the unit's collective momentum."},{title:"Intelligence Matrix",text:"The referee's toolbox: d66 tables that procedurally generate mission prompts, locations, enemies, and rewards. No prep needed."}],gallery:[{cap:"FIST: Ultra Edition cover"}],resources:[{name:"Official page (itch.io)"},{name:"FISTREF — online traits & roles index"},{name:"Free Quickstart Guide"}]}}),registerSystem("forbidden-lands",{groups:{default:{key:"fl",order:4},family:{key:"year-zero",order:4},genre:{key:"dark-fantasy",order:5},solo:{key:"solo-compatible",order:2}},name:"Forbidden Lands",publisher:"Free League / Year Zero Engine",dice:"Пул d6–d12",players:"3–5",complexity:3,foundryStatus:"Official контент",heroImage:"https://freeleaguepublishing.com/wp-content/uploads/2023/09/Forbidden-Lands-cover-art_wide-1440x720.jpg",playstyleTags:["explore","survival","sandbox","combat"],settingTags:["fantasy"],gallery:[{src:"https://freeleaguepublishing.com/wp-content/uploads/2023/09/ForbiddenLands_drakorm_pergament_core_art-1.jpg"},{src:"https://freeleaguepublishing.com/wp-content/uploads/2023/08/ForbiddenLands_TheBloodmarch_Landscape.jpg"},{src:"https://freeleaguepublishing.com/wp-content/uploads/2023/09/ForbiddenLands_orch_pergament_kvadrat.jpg"}],resources:[{type:"link",url:"https://freeleaguepublishing.com/games/forbidden-lands/",fmt:"Web"},{type:"sheet",url:"https://freeleaguepublishing.com/wp-content/uploads/2023/09/Forbidden_Lands_Sheets_BW.pdf",fmt:"PDF"},{type:"sheet",url:"https://freeleaguepublishing.com/wp-content/uploads/2023/09/Forbidden_Lands_Sheets_Color.pdf",fmt:"PDF"},{type:"quickstart",url:"https://freeleaguepublishing.com/shop/forbidden-lands/free-quickstart-pdf/",fmt:"PDF"},{type:"map",url:"https://freeleaguepublishing.com/wp-content/uploads/2023/09/Forbidden_Lands_Legends.pdf",fmt:"PDF"}],mechanics:[{icon:"castle"},{icon:"compass"},{icon:"tent"},{icon:"skull"}],quotes:[{text:"It's like someone took hazy childhood memories of a classic D&D game and mixed them with a dash of bleak Scandinavian darkness.",author:"Richard Jansen-Parkes, Tabletop Gaming"},{text:"It truly brings something new to the dark fantasy genre. And these days that's really something to celebrate.",author:"R.M. Jansen-Parkes, Drop Lowest"}],ru:{tagShort:"Тёмное фэнтези гексплорейшн",tagline:"«Земли, запечатанные Кровавым Туманом, наконец открыты».",description:"Открытый гексплорейшн (исследование карты гекс за гексом, как в тумане войны) в тёмном фэнтези. 300 лет Кровавый Туман делал путешествия смертельными — люди жили в изолированных поселениях. Теперь туман рассеялся, и вы — первые, кто осмеливается исследовать забытые земли. Строите крепость, открываете карту, выживаете.",setting:"Мрачный мир, напоминающий «Ведьмака» и «Тёмные души». Разрушенные замки, забытые демоны, клановые конфликты. Каждый гекс — тайна: заброшенная деревня, логово демона или руины цивилизации, погибшей во время Кровавого Тумана.",vignette:"Ночёвка в руинах. Бросок на случайное событие — «Чужаки у лагеря.» Еда кончается, воды на один день. Мечник форсирует бросок на Выносливость — успех, но бонус снаряжения его меча падает на 1 (единица на кубике при форсировании). Чужаки предлагают обмен: провиант за вашу карту. Без карты вы заблудитесь. Без еды — не дойдёте до крепости.",prep:"~20 мин",mechanics:[{title:"Строительство крепости",text:"Находите руины — строите своё убежище. Каждая постройка даёт бонусы и меняет геополитику региона."},{title:"Гексплорейшн",text:"Открытая карта с тайнами. Каждый гекс — случайная или запланированная локация. Мир раскрывается с каждым шагом."},{title:"Лагерь и ресурсы",text:"Еда, вода, сон — отслеживается. Привал в опасных землях — мини-игра выживания."},{title:"Критические раны",text:"Раны калечат навсегда. Потерянный глаз не вырастет. Бой — последний вариант, не первый."}],gallery:[{cap:"Дракон — арт из книги"},{cap:"Кровавый Марш — ландшафт"},{cap:"Орк"}],resources:[{name:"Официальный сайт"},{name:"Листы (ч/б)"},{name:"Листы (цветные)"},{name:"Quickstart (152 стр.! + приключение)"},{name:"Легенды к карты"}],quotes:[{text:"Как будто кто-то взял туманные детские воспоминания о классической D&D и добавил щепотку мрачной скандинавской тьмы."},{text:"Игра по-настоящему привносит в жанр тёмного фэнтези что-то новое. А в наши дни это уже само по себе повод для радости."}]},en:{tagShort:"dark-fantasy hexcrawl RPG",tagline:'"The lands sealed by the Blood Mist are finally open."',description:"Open-world hexploration (exploring the map hex by hex, like fog of war) in dark fantasy. For 300 years the Blood Mist made travel deadly — people lived in isolated settlements. Now the mist has cleared, and you are the first to dare explore the forgotten lands. Build a stronghold, uncover the map, survive.",setting:"A grim world evoking The Witcher and Dark Souls. Ruined castles, forgotten demons, clan conflicts. Every hex holds a secret: an abandoned village, a demon's lair, or ruins of a civilization that perished during the Blood Mist.",vignette:"Camping in the ruins. Random event roll — 'Strangers at the camp.' Food is running out, one day of water left. The swordsman pushes an Endurance roll — success, but his sword's gear bonus drops by 1. The strangers offer a trade: provisions for your map. Without the map you'll get lost. Without food — you won't reach the stronghold.",prep:"~20 min",mechanics:[{title:"Stronghold building",text:"Find ruins — build your refuge. Every structure grants bonuses and shifts the region's geopolitics."},{title:"Hexploration",text:"An open map full of secrets. Each hex is a random or planned location. The world reveals itself with every step."},{title:"Camp and resources",text:"Food, water, sleep — all tracked. Making camp in dangerous lands is a survival mini-game."},{title:"Critical wounds",text:"Wounds maim permanently. A lost eye won't grow back. Combat is the last resort, not the first."}],gallery:[{cap:"Dragon — book art"},{cap:"The Bloodmarch — landscape"},{cap:"Orc"}],resources:[{name:"Official website"},{name:"Sheets (B&W)"},{name:"Sheets (color)"},{name:"Quickstart (152 pp.! + adventure)"},{name:"Map legends"}]}}),registerSystem("genesys",{groups:{default:{key:"narrative",order:49},family:{key:"standalone",order:54},genre:{key:"adventure",order:29}},name:"Genesys",publisher:"Edge Studio",dice:"Custom narrative dice (Boost, Ability, Proficiency vs Setback, Difficulty, Challenge)",players:"2–5",complexity:3,free:!1,edition:null,foundryStatus:"Community",heroImage:"https://image.nobleknight.com/f/jpg1500/ffggns01.jpg",playstyleTags:["narrative","action","social"],settingTags:["fantasy","cyberpunk"],gallery:[{src:"https://image.nobleknight.com/f/jpg1500/ffggns03.jpg"},{src:"https://image.nobleknight.com/f/jpg1500/ffggns04.jpg"},{src:"https://image.nobleknight.com/f/jpg1500/ffggns12.jpg"}],resources:[{type:"link",url:"https://www.edge-studio.net/games/genesys-core-rulebook/",fmt:"Web"},{type:"rules",url:"https://www.drivethrurpg.com/en/product/228813/genesys-core-rulebook",fmt:"PDF"},{type:"link",url:"https://foundryvtt.com/packages/genesys/",fmt:"VTT"},{type:"link",url:"https://en.wikipedia.org/wiki/Genesys_(RPG)",fmt:"Web"}],mechanics:[{icon:"dice-6"},{icon:"sparkles"},{icon:"globe"},{icon:"wand-sparkles"}],quotes:[{text:"The system is elegant and easy to understand",author:"Richard Jansen-Parkes, Tabletop Gaming"},{text:"The core game is a good one; the success of Star Wars is not just built on the license.",author:"Aaron Marks, Cannibal Halfling Gaming"}],ru:{tagShort:"Повествовательные кости для любого жанра",tagline:"«Одна книга правил, любой мир — на повествовательных костях».",description:"Genesys — жанрово-нейтральный инструментарий на основе Системы повествовательных костей. Вместо чисел вы собираете пул костей Усиления, Способности и Мастерства против костей Помехи, Сложности и Вызова, а затем читаете символы: чистый Успех или Провал вместе с Преимуществом или Угрозой, плюс редкие Триумф и Отчаяние. Эти побочные результаты превращают каждый бросок в сюжетный момент. С модульными правилами магии и техники и шестью примерами сеттингов одна книга водит фэнтези, киберпанк, фантастику или хоррор.",setting:"Никакого и все сразу. У Genesys нет мира по умолчанию — вместо него вы получаете жанрово-нейтральный движок и шесть примеров сеттингов: от меча-и-магии до киберпанка, странной войны и далёкого будущего, с модульными правилами магии и техники, которые вы собираете под свою кампанию.",vignette:"Вы прыгаете к отчаливающему дирижаблю, бросая две зелёные кости Способности и жёлтую кость Мастерства против фиолетовой кости Сложности мастера. Символы выпадают: два чистых Успеха, три Преимущества и золотой Триумф. Вы цепляетесь за поручень (Успех), ваш плащ зацепляет стражника и сбивает его с ног (Преимущество), а Триумф заклинивает лебёдку — и трап за вами уже не поднять.",prep:"~30 мин",mechanics:[{title:"Повествовательные кости",text:"Собирайте пул костей Усиления, Способности и Мастерства против костей Помехи, Сложности и Вызова мастера. Исход решают выгравированные символы, а не числа."},{title:"Преимущество и Триумф",text:"Каждый бросок читается по двум осям: Успех или Провал и Преимущество или Угроза. Редкие грани Триумфа и Отчаяния запускают драматичные повороты сверх самой задачи."},{title:"Любой жанр",text:"Один движок водит фэнтези, фантастику, киберпанк или хоррор. Шесть примеров сеттингов и настройки тона помогают задать именно ту кампанию, которую хочет стол."},{title:"Инструментарий магии и техники",text:"Модульные подсистемы охватывают заклинания, крафт снаряжения, транспорт и социальные дуэли, так что файербол мага и взлом хакера говорят на одном языке костей."}],gallery:[{cap:"Realms of Terrinoth привносит высокое фэнтези — расы, магию и профессии — в инструментарий Genesys."},{cap:"Shadow of the Beanstalk переносит систему в неоновый киберпанк-мегаполис Нью-Анджелес."},{cap:"Secrets of the Crucible адаптирует Genesys для причудливого лоскутного мира KeyForge."}],resources:[{name:"Genesys на Edge Studio"},{name:"Основная книга на DriveThruRPG"},{name:"Сообщественная система для Foundry VTT"},{name:"Genesys в Википедии"}],quotes:[{text:"Система элегантна и проста для понимания."},{text:"Основная игра хороша: успех «Звёздных войн» держится не только на лицензии."}]},en:{tagShort:"Any-genre narrative dice",tagline:'"One rulebook, every world — powered by narrative dice."',description:"Genesys is a setting-agnostic toolkit built on the Narrative Dice System. Instead of numbers, you assemble a pool of Boost, Ability, and Proficiency dice against Setback, Difficulty, and Challenge dice, then read the symbols: net Success or Failure alongside Advantage or Threat, plus rare Triumph and Despair. Those side results turn every roll into a story beat. With modular rules for magic and technology and six sample settings, one core book runs fantasy, cyberpunk, sci-fi, or horror.",setting:"None and all of them. Genesys ships no default world; it hands you a genre-neutral engine plus six sample settings — from swords-and-sorcery fantasy to cyberpunk, weird war, and far-future sci-fi — with modular rules for magic and technology you bolt on to build your own campaign.",vignette:"You leap for the departing airship, rolling two green Ability dice and a yellow Proficiency against the GM's purple Difficulty. The symbols land: two net Success, three Advantage, and a golden Triumph. You catch the rail (Success), your cloak snags a guard and drags them off balance (Advantage), and the Triumph jams the winch so no one can raise the ramp behind you.",prep:"~30 min",mechanics:[{title:"Narrative Dice",text:"Build a pool of Boost, Ability, and Proficiency dice against the GM's Setback, Difficulty, and Challenge dice. Etched symbols, not numbers, decide what happens."},{title:"Advantage & Triumph",text:"Every roll reads on two axes: Success or Failure, and Advantage or Threat. Rare Triumph and Despair faces trigger dramatic swings far beyond the task itself."},{title:"Any Genre",text:"One core engine runs fantasy, sci-fi, cyberpunk, or horror. Six sample settings and tone dials help you frame exactly the campaign your table wants."},{title:"Magic & Tech Toolkit",text:"Modular subsystems cover spellcasting, gear crafting, vehicles, and social duels, so a wizard's fireball and a hacker's intrusion speak the same dice language."}],gallery:[{cap:"Realms of Terrinoth brings high fantasy — races, magic, and careers — to the Genesys toolkit."},{cap:"Shadow of the Beanstalk drops the system into the neon cyberpunk sprawl of New Angeles."},{cap:"Secrets of the Crucible adapts Genesys for the wondrous, patchwork world of KeyForge."}],resources:[{name:"Genesys at Edge Studio"},{name:"Core Rulebook on DriveThruRPG"},{name:"Community Foundry VTT system"},{name:"Genesys on Wikipedia"}],quotes:[{text:"The system is elegant and easy to understand"},{text:"The core game is a good one; the success of Star Wars is not just built on the license."}]}}),registerSystem("gurps",{groups:{default:{key:"tactical",order:11},family:{key:"standalone",order:32},genre:{key:"tactical",order:8}},name:"GURPS",publisher:"Steve Jackson Games",dice:"3d6",players:"3–6",complexity:4,free:!0,foundryStatus:"Community",heroImage:"https://www.sjgames.com/gurps/books/basic/img/basic1_lg.jpg",playstyleTags:["tactical","explore","combat"],settingTags:[],gallery:[{src:"https://www.sjgames.com/gurps/books/basic/img/basic2_lg.jpg"},{src:"https://www.sjgames.com/gurps/books/basic/img/commando.jpg"},{src:"https://www.sjgames.com/gurps/books/basic/img/basic1_lg.jpg"}],resources:[{type:"link",url:"https://www.sjgames.com/gurps/",fmt:"Web"},{type:"quickstart",url:"https://www.warehouse23.com/products/SJG31-0004",fmt:"PDF"},{type:"link",url:"https://www.sjgames.com/gurps/books/basic",fmt:"Web"}],mechanics:[{icon:"swords"},{icon:"dices"},{icon:"book-open"},{icon:"scroll"}],quotes:[{text:"An ambitious design by Steve Jackson that attempts to cover every imaginable genre, setting and character type in the same game. That it achieves this goal at all is impressive; that it does so with imagination, elegance, and innovation is stunning.",author:"Rick Swan, The Complete Guide to Role-Playing Games"},{text:"GURPS is a promising game in many ways. There are some problems and omissions, but the rules are mostly simple and logical.",author:"Dave Nalle, Abyss magazine"}],ru:{tagShort:"Универсальная симуляционная на 3d6",tagline:"«Любой жанр, любая эпоха, любая реальность — один набор правил».",description:"GURPS (Generic Universal RolePlaying System) — универсальная настольная RPG от Steve Jackson Games (4-е издание, 2004). Система 3d6: бросок под значение навыка/атрибута. Модульная: ядро простое, но опциональные правила (бой с позиционированием, попадания по локациям, магия, псионика) делают её одной из самых crunchy систем. 250+ книг по десяткам жанров. GURPS Lite — бесплатный 32-страничный квикстарт.",setting:"Жанр-agnostic. GURPS не привязана к миру — она создаёт мир из модулей. Фэнтези, sci-fi, хоррор, шпионаж, супергерои, история, постапокалипсис — всё в одном наборе правил. Infinite Worlds — встроенный сеттинг для путешествий во времени.",vignette:"Три кубика. 4+5+3 = 12. Против 13 (Difficulty 12). Успех на 1. Один уровень успеха — минимальный. Варвар пролезает через окно, но ломает себе руку. «Ты мог выбрать Buy at 14,» — напоминает GM. «Мне не хватило очков,» — вздыхает игрок. Добро пожаловать в GURPS.",prep:"~20 мин",mechanics:[{title:"Система 3d6",text:"Бросок 3d6 против значения навыка или атрибута. Чем ниже результат, тем лучше. Криты на тройных (18 = фал, 3 = крит). Простая, но элегантная математика."},{title:"Модульность",text:"Ядро — ~200 страниц. Опциональные правила добавляют глубину: позиционирование в бою, попадания по локациям, крафт, социальные взаимодействия. Выбираете сложность сами."},{title:"Points-based création",text:"Создание персонажа на очки (Character Points). Более 100 черт (Advantages), 200+ навыков, 50+ недостатков (Disadvantages). Каждый персонаж уникален."},{title:"250+ книг",text:"Большой мир книг: от GURPS Space и GURPS Horror до GURPS Vikings и GURPS WWII. Каждая книга — отдельный мир или жанр."}],gallery:[{cap:"Basic Set: Campaigns"},{cap:"Иллюстрация — Commando"},{cap:"Basic Set: Characters"}],resources:[{name:"Официальный сайт — Steve Jackson Games"},{name:"GURPS Lite (бесплатный квикстарт PDF)"},{name:"GURPS Basic Set — продукт"}],quotes:[{text:"Амбициозный дизайн Стива Джексона, пытающийся охватить каждый воображаемый жанр, сеттинг и тип персонажа в одной игре. То, что он вообще достигает этой цели, впечатляет; то, что делает это с воображением, элегантностью и инновацией — поражает."},{text:"GURPS — многообещающая игра во многих отношениях. Есть проблемы и пробелы, но правила в основном просты и логичны."}]},en:{tagShort:"Universal simulationist RPG on 3d6",tagline:'"Any genre, any era, any reality — one ruleset."',description:"GURPS (Generic Universal RolePlaying System) is a universal tabletop RPG from Steve Jackson Games (4th Edition, 2004). 3d6 system: roll under your skill/attribute value. Modular: core is learnable, but optional rules (combat maneuvering, hit locations, detailed magic/psionics) push it firmly into crunchy simulationist territory. 250+ sourcebooks spanning dozens of genres. GURPS Lite is a free 32-page quickstart.",setting:"Genre-agnostic by design. GURPS doesn't tie to a world — it builds worlds from modules. Fantasy, sci-fi, horror, espionage, superheroes, historical, post-apocalyptic — all in one ruleset. Infinite Worlds is the built-in setting for timeline-hopping.",vignette:"Three dice. 4+5+3 = 12. Against 13 (Difficulty 12). Success by 1. One level of success — bare minimum. The barbarian squeezes through the window but breaks his arm. 'You could have bought at 14,' the GM reminds. 'I didn't have the points,' the player sighs. Welcome to GURPS.",prep:"~20 min",mechanics:[{title:"3d6 System",text:"Roll 3d6 against your skill or attribute value. The lower the result, the better. Crits on triples (18 = fumble, 3 = crit). Simple but elegant math."},{title:"Modularity",text:"Core is ~200 pages. Optional rules add depth: combat positioning, hit locations, crafting, social encounters. You choose the complexity."},{title:"Points-based Creation",text:"Character creation uses Character Points. 100+ Advantages, 200+ Skills, 50+ Disadvantages. Every character is unique."},{title:"250+ Books",text:"A massive world of books: from GURPS Space and GURPS Horror to GURPS Vikings and GURPS WWII. Each book is its own world or genre."}],gallery:[{cap:"Basic Set: Campaigns"},{cap:"Interior art — Commando"},{cap:"Basic Set: Characters"}],resources:[{name:"Official site — Steve Jackson Games"},{name:"GURPS Lite (free quickstart PDF)"},{name:"GURPS Basic Set — product page"}],quotes:[{text:"An ambitious design by Steve Jackson that attempts to cover every imaginable genre, setting and character type in the same game. That it achieves this goal at all is impressive; that it does so with imagination, elegance, and innovation is stunning."},{text:"GURPS is a promising game in many ways. There are some problems and omissions, but the rules are mostly simple and logical."}]}}),registerSystem("heart",{groups:{default:{key:"narrative",order:1},family:{key:"resistance",order:1},genre:{key:"horror",order:4}},name:"Heart: The City Beneath",publisher:"Rowan Rook & Decard",dice:"d10",players:"3–5",complexity:3,foundryStatus:"Community",heroImage:"https://rowanrookanddecard.com/wp-content/uploads/2020/07/THE-WORLD-OF-HEART-scaled-e1595931454162.jpg",playstyleTags:["narrative","horror","explore"],settingTags:["fantasy","weird"],gallery:[{src:"https://rowanrookanddecard.com/wp-content/uploads/2020/04/Heart-The-City-Beneath-RPG-COMBAT-scaled.jpg"},{src:"https://rowanrookanddecard.com/wp-content/uploads/2020/04/Heart-The-City-Beneath-RPG-ANGEL.webp"},{src:"https://rowanrookanddecard.com/wp-content/uploads/2021/10/Heart_Character_Sheet_Product_Photo_Front-600x600.png.webp"},{src:"https://img.itch.zone/aW1nLzMyNTE2MzgucG5n/original/2W%2BgAK.png"}],resources:[{type:"link",url:"https://rowanrookanddecard.com/product/heart-the-city-beneath-rpg/",fmt:"Web"},{type:"quickstart",url:"https://rowanrookanddecard.itch.io/heart-the-city-beneath-quickstart",fmt:"PDF"}],mechanics:[{icon:"heart-pulse"},{icon:"route"},{icon:"bug"},{icon:"drama"}],quotes:[{text:"Heart: The City Beneath — my group's current indie TTRPG du jour — deals with this like no other game I've played, and it's hugely refreshing.",author:"Alex Evans, Wargamer"}],ru:{tagShort:"Нарративный спуск",tagline:"«Спускайтесь в живой подземный город, который исполняет желания — за чудовищную цену».",description:"Нарративный (история и драма важнее точных правил) данжен-кроул наоборот. Вместо подъёма к сокровищам — спуск в Сердце, живой подземный мегаданжен, который реагирует на желания и страхи. Каждый класс имеет уникальную историю: от Зенита (входа) до Надира (финала). Персонаж буквально проходит нарративную арку.",setting:"Под городом Спайр (из одноимённой игры) бьётся Сердце — немыслимое пространство, меняющее реальность. Рынки из костей, библиотеки из снов, леса из мяса. Чем глубже спускаешься — тем безумнее становится мир и ты сам.",vignette:"Вы на Рынке Костей, третий ярус Сердца. Торговец продаёт воспоминания в стеклянных флаконах. Бросок d10 — 7, частичный успех. Вы получаете нужную карту, но берёте стресс на трек Эхо. Три отметки из пяти. Ещё одна — и Сердце заберёт ваш голос. Навсегда. Ваш Зенит: «Найти дорогу обратно.» Ваш Надир: «Забыть, зачем вы пришли.»",prep:"~20 мин",mechanics:[{title:"5 стресс-треков",text:"Кровь, Разум, Эхо, Удача, Запасы. Каждый — путь к гибели или трансформации. Стресс распределяете вы."},{title:"Зенит → Надир",text:"У каждого класса — арка от входа до финала. Вы знаете, куда идёт история. Вопрос — какой ценой."},{title:"Живой данжен",text:"Сердце — существо, не место. Оно меняется, реагирует, создаёт пространства из ваших страхов."},{title:"Нарратив первым",text:"Броски решают не «попал/не попал», а «какую цену ты платишь». Фикшн определяет механику."}],gallery:[{cap:"Бой в Сердце"},{cap:"Ангел"},{cap:"Лист персонажа"},{cap:"Обложка"}],resources:[{name:"Официальный сайт"},{name:"Quickstart (правила + приключение)"}],quotes:[{text:"Heart: The City Beneath — текущий инди-фаворит нашей группы — решает это как ни одна другая игра, что я водил. Дико свежо."}]},en:{tagShort:"weird descent RPG",tagline:'"Descend into a living underground city that grants wishes — for a monstrous price."',description:"A narrative dungeon crawl in reverse. Instead of climbing toward treasure — a descent into the Heart, a living underground megadungeon that responds to desires and fears. Each class has a unique story arc: from Zenith (entry) to Nadir (finale). Characters literally progress through a narrative arc.",setting:"Beneath the city of Spire beats the Heart — an inconceivable space that warps reality. Markets of bone, libraries of dreams, forests of flesh. The deeper you descend, the more insane the world — and you — become.",vignette:"You're at the Bone Market, third tier of the Heart. A merchant sells memories in glass vials. Roll d10 — 7, partial success. You get the map you need, but take stress on the Echo track. Three marks out of five. One more — and the Heart takes your voice. Forever. Your Zenith: 'Find the way back.' Your Nadir: 'Forget why you came.'",prep:"~20 min",mechanics:[{title:"5 stress tracks",text:"Blood, Mind, Echo, Fortune, Supplies. Each is a path to doom or transformation. You choose where stress goes."},{title:"Zenith to Nadir",text:"Every class has an arc from entry to finale. You know where the story goes. The question is — at what cost."},{title:"Living dungeon",text:"The Heart is a creature, not a place. It shifts, reacts, creates spaces from your fears."},{title:"Narrative first",text:"Rolls don't decide 'hit or miss' but 'what price do you pay.' Fiction drives the mechanics."}],gallery:[{cap:"Combat in the Heart"},{cap:"Angel"},{cap:"Character sheet"},{cap:"Cover"}],resources:[{name:"Official website"},{name:"Quickstart (rules + adventure)"}]}}),registerSystem("his-majesty-the-worm",{groups:{default:{key:"osr",order:27},family:{key:"standalone",order:48},genre:{key:"narrative-weird",order:12}},name:"His Majesty the Worm",publisher:"Rise Up Comus / Exalted Funeral",dice:"d6 dice pools + a tarot deck",players:"3–5",complexity:2,foundryStatus:"None",free:!1,edition:null,heroImage:"https://www.exaltedfuneral.com/cdn/shop/files/HMtW-CA-Hero.jpg?v=1763530083&width=1920",playstyleTags:["explore","combat","mystery"],settingTags:["fantasy","weird"],gallery:[{src:"https://www.exaltedfuneral.com/cdn/shop/files/his-majesty-the-worm-book-888110.jpg?v=1763412737&width=2000"},{src:"https://www.exaltedfuneral.com/cdn/shop/files/his-majesty-the-worm-book-950216.jpg?v=1763412737&width=2000"},{src:"https://www.exaltedfuneral.com/cdn/shop/files/his-majesty-the-worm-book-480645.jpg?v=1763412737&width=2000"}],resources:[{type:"link",url:"https://www.hismajestytheworm.games/",fmt:"Web"},{type:"rules",url:"https://www.drivethrurpg.com/en/product/488062/his-majesty-the-worm-digital-edition",fmt:"PDF"},{type:"link",url:"https://www.exaltedfuneral.com/products/his-majesty-the-worm",fmt:"Print"},{type:"link",url:"https://riseupcomus.itch.io/his-majesty-the-worm",fmt:"Web"}],mechanics:[{icon:"shuffle"},{icon:"users"},{icon:"compass"},{icon:"flame"}],quotes:[{text:"His Majesty the Worm is a dungeon crawler masterpiece, bridging the way to the next generation of tabletop fantasy games.",author:"W.F. Smith, Prismatic Wasteland"}],ru:{tagShort:"данжен-кроулер на картах таро",tagline:"«Спустись под Город на Краю Света».",description:"404-страничный том о походах в подземелья: новые механики на старой школьной основе. Вместо одних кубов партия тянет карты из колоды таро — они решают бой, гадание и драму. Слотовый инвентарь, свет, еда и Узы между героями здесь не бухгалтерия, а сердце долгого метроидвания-спуска.",setting:"Искатели спускаются в подземелья под Городом на Краю Света — последним городом, окружённым тьмой. Таро вершит судьбу: карты для боя, для чтения знамений, для запутанных связей между героями. Труппная игра про отношения, где кого любит ваш герой важно не меньше, чем что он несёт.",vignette:"Свет факела дрожит — вы тянете карту на встречу: Башня, перевёрнутая. Рефери улыбается. Слоты инвентаря почти забиты: верёвка, фонарь, реликвия без имени, — а свет на исходе. Кто-то должен что-то бросить или повернуть назад. Ваши Узы с вором говорят: вы его не оставите. Вы тянете снова.",prep:"~30 мин",mechanics:[{title:"Движок на таро",text:"Одна колода решает всё: бой, проверки, гадание, драматические повороты. Механика свежая, но осваивается сразу и работает за столом без лишних правил."},{title:"Слоты и свет",text:"Груз, свет и еда — настоящие ограничения, и это весело. То, что вы несёте, определяет, кто вы и как глубоко решитесь спуститься."},{title:"Узы и труппа",text:"Создание персонажа геймифицирует отношения. Узы дают восстановление и втягивают партию в интересные сцены вместо бессмысленной резни."},{title:"Процедуры данжа и города",text:"Прозрачные процедуры для походов в подземелья и интриг в Городе. Каждая подсистема объясняет, ЗАЧЕМ она нужна — прямо в книге."}],gallery:[{cap:"Твёрдый переплёт с фольгой"},{cap:"Внутренний разворот"},{cap:"Игра на картах таро"}],resources:[{name:"Официальный сайт"},{name:"Цифровое издание (DriveThruRPG)"},{name:"Печатное издание (Exalted Funeral)"},{name:"Страница на itch.io"}],quotes:[{text:"His Majesty the Worm — шедевр данжен-кроулера, прокладывающий путь к следующему поколению настольных фэнтези-игр."}]},en:{tagShort:"tarot-driven dungeon crawler",tagline:'"Descend beneath the City at the End of the World."',description:"A 404-page dungeon-crawling tome with new-school mechanics and old-school sensibilities. Instead of dice alone, the party draws from a tarot deck that drives combat, divination, and drama. Slot-based inventory, light, food, and character Bonds aren't bookkeeping — they're the heart of a long, Metroidvania-like descent.",setting:"Adventurers delve the dungeons beneath the City at the End of the World — the last city, ringed by darkness. The tarot shapes fate: cards for combat, for reading omens, for the tangled bonds between characters. Troupe-style, relationship-driven play where who your character loves matters as much as what they carry.",vignette:"Torchlight gutters as you draw for the encounter: the Tower, reversed. The Referee smiles. Your slot inventory is nearly full — rope, lantern, a relic you can't yet name — and the light is running out. Someone has to drop something, or turn back. Your Bond with the thief says you won't leave them behind. You draw again.",prep:"~30 min",mechanics:[{title:"The Tarot Engine",text:"One deck resolves everything: combat, skill tests, divination, and dramatic reveals. Novel but easy to grasp, and it works at the table without a translation layer."},{title:"Slot Inventory & Light",text:"Encumbrance, light, and food are real constraints made fun. What you carry defines who you are and how deep you dare go."},{title:"Bonds & Troupe Play",text:"Character creation gamifies relationships. Bonds power recovery and pull the party into interesting roleplay scenes instead of murderhoboing."},{title:"Dungeon & City Procedures",text:"Robust, transparent procedures for crawling dungeons and plotting in the City. Every subsystem explains WHY it exists, right in the book."}],gallery:[{cap:"Foil-stamped hardcover"},{cap:"Interior spread"},{cap:"Tarot-driven play"}],resources:[{name:"Official website"},{name:"Digital edition (DriveThruRPG)"},{name:"Print edition (Exalted Funeral)"},{name:"itch.io page"}],quotes:[{text:"His Majesty the Worm is a dungeon crawler masterpiece, bridging the way to the next generation of tabletop fantasy games."}]}}),registerSystem("hyperborea-3",{groups:{default:{key:"osr",order:5.5},family:{key:"osr-classic",order:6},genre:{key:"sword-and-sorcery",order:4}},name:"Hyperborea 3",publisher:"North Wind Adventures",dice:"d20 + d4–d20",players:"3–6",complexity:3,foundryStatus:"Community",heroImage:"https://www.hyperborea.tv/uploads/4/4/6/6/44662451/hyperborean-scene_orig.jpg",playstyleTags:["combat","explore","sandbox","survival","horror"],settingTags:["sword-and-sorcery","fantasy"],gallery:[{src:"https://www.hyperborea.tv/uploads/4/4/6/6/44662451/1000027114_orig.png"},{src:"https://www.hyperborea.tv/uploads/4/4/6/6/44662451/20241016-112234_orig.jpg"},{src:"https://www.hyperborea.tv/uploads/4/4/6/6/44662451/1000027125_orig.png"}],resources:[{type:"link",url:"https://www.hyperborea.tv",fmt:"Web"},{type:"sheet",url:"https://www.hyperborea.tv/uploads/4/4/6/6/44662451/hype3e-charsheet.pdf",fmt:"PDF"}],mechanics:[{icon:"swords"},{icon:"wand-sparkles"},{icon:"skull"},{icon:"compass"}],quotes:[{text:"I consider Hyperborea the best modern restatement of AD&D.",author:"James Maliszewski, Grognardia"},{text:"These are books that want you to be playing with them for years and they give you the tools to do that.",author:"Tim Clare, Tabletop Gaming Magazine (Issue #82, Sep 2023)"}],ru:{tagShort:"Sword-and-sorcery с налётом science-fantasy",tagline:"«Под Северным Ветром, под алым солнцем — приключения стали и чародейства».",description:"Hyperborea 3e — отполированная версия AD&D 1e, заточенная под sword-and-sorcery и weird science-fantasy. Джеффри Таланян объединил гайгаксовский барок с интуитивными улучшениями: единый спасбросок, упрощённые матрицы атак, d6-система задач. Полная обратная совместимость с классическими модулями.",setting:"Гиперборея — плоский гексагональный мир за Северным Ветром под багровым умирающим солнцем. Аметистовые города, лучемёты (radium pistols), каннибалы-пикты, спящие древние ужасы. Вдохновлено Ховардом, Лавкрафтом и Кларком Эштоном Смитом. Мир, где выживание считается успехом.",vignette:"Группа выходит из червивого леса к Хромиуму — Городу-Государству, распростёртому под алым закатом. В порту одноглазая ведьма предлагает карту к Гробнице Свёрнутой Змеи за тень сильнейшего воина. Прежде чем ответить — вой из катакомб под Бронзовой Улицей. Древний проснулся.",prep:"~20 мин",mechanics:[{title:"4 базовых класса, 22 подкласса",text:"Воин, Маг, Клирик, Вор — и 22 подкласса (Варвар, Пиромаг, Рунепис, Катафракт, Ведьма...). У каждого свои требования, способности и таблица опыта."},{title:"Унифицированный спасбросок",text:"Вместо AD&D-матриц с пятью категориями — один спасбросок с модификаторами по классу и уровню. Проще, но олдскульно."},{title:"Мастерство оружия + DR брони",text:"Воины получают бонусы к атакам с избранным оружием. Средняя и тяжёлая броня дают поглощение урона (DR). Броня — не просто AC, а тактический выбор."},{title:"d6-система задач",text:"Для не-боевых действий (лазание, скрытность, переговоры) — d6-бросок рефери. Нагрузка упрощена до веса брони. Игра не вязнет в деталях."}],gallery:[{cap:"Referee's Manual"},{cap:"Карта Гипербореи"},{cap:"Арт"}],resources:[{name:"Официальный сайт"},{name:"Лист персонажа (PDF)"}],quotes:[{text:"Я считаю Hyperborea лучшим современным изложением AD&D."},{text:"Это книги, которые хотят, чтобы вы играли с ними годами, и они дают вам инструменты для этого."}]},en:{tagShort:"Sword-and-sorcery with weird science-fantasy",tagline:'"Beyond the North Wind, under a dying crimson sun — adventure by steel and sorcery."',description:"Hyperborea 3e is a streamlined restatement of Gygaxian AD&D tailored for sword-and-sorcery and weird science-fantasy. Jeffrey Talanian combines the baroque class-and-level framework of 1E AD&D with intuitive modernizations — unified saving throw, simplified combat matrices, and a d6 task resolution — while preserving full backwards compatibility with classic modules.",setting:"Hyperborea is a flat hexagonal realm hemmed in by the mystical North Wind, lit by a bloated dying red sun. Inspired by Howard, Lovecraft, and Clark Ashton Smith — ancient amethyst cities, radium pistols, cannibal Picts, cyclopean ruins, and slumbering alien horrors. A world where survival itself is considered thriving.",vignette:"The party emerges from the worm-riddled forest to find the City-State of Khromarium sprawling beneath a scarlet dusk. On the harbourfront, a one-eyed witch offers a map to the Tomb of the Coiled Serpent for the price of their strongest warrior's shadow. Before they can answer — a howl from the catacombs beneath the Street of Bronze. Something ancient has awakened.",prep:"~20 min",mechanics:[{title:"4 Base Classes, 22 Subclasses",text:"Fighter, Magician, Cleric, or Thief — or one of 22 subclasses (Barbarian, Pyromancer, Runegraver, Cataphract, Witch...). Each with distinct requirements, abilities, and XP tables."},{title:"Unified Saving Throw",text:"Instead of AD&D's five saving throw categories — a single roll with class- and level-based modifiers. Simpler, yet old-school."},{title:"Weapon Mastery & Armour DR",text:"Fighters gain bonuses with chosen weapons. Medium and heavy armour grant damage reduction (DR). Armour is a tactical choice, not just AC."},{title:"D6 Task Resolution",text:"A referee-facing d6 system for non-combat actions (climbing, stealth, persuasion). Encumbrance simplified to armour weight. The game keeps moving."}],gallery:[{cap:"Referee's Manual"},{cap:"Map of Hyperborea"},{cap:"Interior art"}],resources:[{name:"Official website"},{name:"Character sheet (PDF)"}]}}),registerSystem("into-the-odd",{groups:{default:{key:"osr",order:1},family:{key:"into-the-odd",order:1},genre:{key:"adventure",order:1}},name:"Into the Odd",publisher:"Chris McDowell / Free League",dice:"d20 + d6",players:"2–5",complexity:1,foundryStatus:"Community",heroImage:"https://freeleaguepublishing.com/wp-content/uploads/2023/09/into_the_odd-1440x720.jpg",playstyleTags:["explore","survival","sandbox"],settingTags:["fantasy","weird"],gallery:[{src:"https://freeleaguepublishing.com/wp-content/uploads/2023/09/ITO_standing-TM-1200x1200.jpg"}],resources:[{type:"link",url:"https://freeleaguepublishing.com/games/into-the-odd/",fmt:"Web"},{type:"sheet",url:"https://gm-lazarus.itch.io/into-the-odd-character-sheet",fmt:"PDF"}],mechanics:[{icon:"zap"},{icon:"gem"},{icon:"skull"},{icon:"feather"}],quotes:[{text:"Both seem to be great for one shots, convention games, OSR intros, or games where rapidly generating a new and evocative character is the goal.",author:"Skerples, Coins and Scrolls (2019)"}],ru:{tagShort:"Минималистичная OSR-классика",tagline:"«Выживите в индустриальном кошмаре, где золото — единственный закон».",description:"Ультра-минималистичная OSR-игра (Old School Renaissance — стиль, вдохновлённый ранними редакциями D&D), прародитель целого жанра. Правила — 48 страниц. Создание персонажа — 2 минуты. Три характеристики (Сила, Ловкость, Воля), горстка HP и странный предмет в кармане. Всё. Вы готовы умереть в подземелье под Бастионом — гигантским индустриальным мегаполисом, полным тайн, коллекторов и живых лабиринтов.",setting:"Бастион — сюрреалистичный город-государство, напоминающий викторианский Лондон, скрещённый с кошмарами. Под ним — Подземное Море, полное Арканумов (странных артефактов с непредсказуемыми свойствами). За городом — Железная Пустошь и Золотая Земля. Мир не объясняет себя. Он просто существует и ждёт, пока вы его исследуете.",vignette:"Вы спускаетесь в коллектор под Бастионом. Впереди — гул. Ваш Арканум, стеклянный глаз, начинает вибрировать. Следопыт говорит: «Назад.» Но вы уже видите золото. Тварь бьёт — 1d8 урона. 4 — ваши 3 HP слетают, оставшийся 1 урон идёт в Силу. Спасбросок (бросок кубика на удачу, чтобы избежать беды) Силы... провал. Шрам: ваша левая рука теперь светится в темноте.",prep:"~10 мин",mechanics:[{title:"Без бросков на попадание",text:"Атаки всегда попадают. Кубик определяет только урон. Бои невероятно быстрые — решения важнее бросков."},{title:"Арканумы",text:"Магии нет. Есть странные артефакты — каждый уникален, непредсказуем и может убить владельца быстрее врагов."},{title:"HP = Hit Protection",text:"Когда HP на нуле, урон идет в Силу. Выживание при 0 Силы дарит Шрам — постоянное изменение персонажа."},{title:"Минимализм",text:"Нет классов, нет уровней, нет навыков. Персонаж определяется тем, что он несёт и что пережил."}],gallery:[{cap:"Обложка книги"}],resources:[{name:"Официальный сайт"},{name:"Лист персонажа (fan)"}],quotes:[{text:"Обе отлично подходят для ваншотов, конвенционных игр, знакомства с OSR или партий, где цель — быстро собрать колоритного персонажа."}]},en:{tagShort:"minimalist industrial OSR",tagline:'"Survive an industrial nightmare where gold is the only law."',description:"An ultra-minimalist OSR game (Old School Renaissance — a style inspired by early editions of D&D), the progenitor of an entire genre. Rules — 48 pages. Character creation — 2 minutes. Three stats (Strength, Dexterity, Willpower), a handful of HP, and a strange item in your pocket. That's it. You're ready to die in the tunnels beneath Bastion — a vast industrial megalopolis full of secrets, sewers, and living labyrinths.",setting:"Bastion — a surreal city-state resembling Victorian London crossed with nightmares. Beneath it lies the Underground Sea, teeming with Arcana (strange artifacts with unpredictable properties). Beyond the city — the Iron Wasteland and the Golden Land. The world doesn't explain itself. It simply exists and waits for you to explore it.",vignette:"You descend into the sewers beneath Bastion. Ahead — a hum. Your Arcanum, a glass eye, starts vibrating. The scout says: 'Go back.' But you've already spotted the gold. The creature strikes — 1d8 damage. 4 — your 3 HP are gone, the remaining 1 damage goes to Strength. Save (a dice roll to avoid disaster) against Strength... failed. Scar: your left hand now glows in the dark.",prep:"~10 min",mechanics:[{title:"No attack rolls",text:"Attacks always hit. The die only determines damage. Combats are incredibly fast — decisions matter more than dice."},{title:"Arcana",text:"No magic. Instead, strange artifacts — each unique, unpredictable, and capable of killing its owner faster than enemies."},{title:"HP = Hit Protection",text:"When HP hits zero, damage goes to Strength. Surviving at 0 Strength earns a Scar — a permanent change to the character."},{title:"Minimalism",text:"No classes, no levels, no skills. A character is defined by what they carry and what they've survived."}],gallery:[{cap:"Book cover"}],resources:[{name:"Official website"},{name:"Character sheet (fan)"}]}}),registerSystem("ironsworn",{groups:{default:{key:"narrative",order:15},family:{key:"standalone",order:10},genre:{key:"adventure",order:10},solo:{key:"solo-adventure",order:1}},name:"Ironsworn",publisher:"Shawn Tomkin / Ironsworn RPG",dice:"2d6 + d10",players:"1–4",complexity:2,free:!0,heroImage:"https://img.itch.zone/aW1nLzE3OTgwODguanBn/original/gRDqF5.jpg",playstyleTags:["solo","explore","narrative","combat"],settingTags:["fantasy"],gallery:[{src:"https://img.itch.zone/aW1hZ2UvMzU5NzA3LzE3OTgxMTQucG5n/347x500/4T0Q8w.png"},{src:"https://img.itch.zone/aW1hZ2UvMzU5NzA3LzE3OTgxMTUucG5n/347x500/e4qPTQ.png"},{src:"https://img.itch.zone/aW1hZ2UvMzU5NzA3LzE3OTgxMTIucG5n/347x500/A9moFn.png"}],resources:[{type:"link",url:"https://www.ironswornrpg.com/",fmt:"Web"},{type:"rules",url:"https://shawn-tomkin.itch.io/ironsworn",fmt:"Web"},{type:"rules",url:"https://shawn-tomkin.itch.io/ironsworn",fmt:"PDF"},{type:"sheet",url:"https://tomkinpress.com/products/ironsworn-playkit",fmt:"PDF"},{type:"tool",url:"https://nboughton.uk/apps/ironsworn-campaign/",fmt:"Web"}],mechanics:[{icon:"feather"},{icon:"shield"},{icon:"map"},{icon:"star"}],quotes:[{text:"Ironsworn advanced the art of solo adventure game design by leaps and bounds, bringing innovative techniques and systems to the form and helping to introduce solo rpgs to a new generation of players. It's a masterpiece.",author:"John Harper, designer of Blades in the Dark"},{text:"Ironsworn is one of the smartest, best designed, TTRPGs I've ever played, and more than that I think it's an incredible tool for writers and creatives.",author:"Mara Holmes, streamer and author"}],ru:{tagShort:"Бесплатное соло-фэнтези PbtA",tagline:"«Один игрок. Один мир. Клятвы, которые нельзя нарушить.»",description:"Железная Клятва — это THE соло-RPG тёмного фэнтези. Бесплатная, полная, без компромиссов. Играйте одни, вдвоём с ведущим или кооперативно без GM вообще. Вдохновлена Powered by the Apocalypse: ходы, не правила — нарратив на первом месте. Оракулы генерируют мир, угрозы и неожиданные повороты прямо за столом. Никакого препа. Только клятвы, ставки и железо.",setting:"Железные Земли — мрачный, враждебный север. Не героическое фэнтези с драконами и трактирами — тут люди выживают на краю выжженного мира. Кланы, обиды, тёмные леса, забытые руины. Вдохновение: скандинавский миф, кельтская меланхолия и ощущение осаждённой крепости. Каждый квест — это не «спаси мир», это «выживи. Выполни клятву. Умри с достоинством.»",vignette:"Ты один. Деревня сожжена. Ты кладёшь руку на кусок железа и клянёшься: «Я найду тех, кто это сделал.» Бросок на Клятву — 5 против 7 и 3. Слабый хит: Клятва принята, но Мастер Миров (ты сам через оракул) добавляет осложнение. Ты идёшь в лес. Кидаешь кость встречи — «Угроза приближается». Оракул: «Волк? Нет. Что-то большее». Ты пишешь в журнал. История разворачивается.",prep:"~0 мин",mechanics:[{title:"Железные Клятвы",text:"Каждый квест начинается с клятвы на железе. Трекер прогресса показывает, как далеко вы зашли. Нарушить клятву — значит потерять часть себя."},{title:"Три режима игры",text:"Полное соло (ты и оракулы), кооп без GM (все управляют нарративом совместно) или классически с ведущим. Одни правила — три опыта."},{title:"Оракулы и Мастер Миров",text:"Таблицы случайных событий, персонажей, угроз и мест заменяют ведущего. Задай вопрос — брось кубик — интерпретируй. Мир строится сам."},{title:"Ходы в стиле PbtA",text:"Без правил на каждый случай жизни — только ходы. Встреть угрозу, разведай местность, поддержи союзника. Провалы дают опыт. Успехи дают ставки."}],gallery:[{cap:"Обложка: Железные Земли"},{cap:"Разворот книги"},{cap:"Листы персонажа и оракулы"}],resources:[{name:"Официальный сайт"},{name:"Страница на itch.io (скачать бесплатно)"},{name:"PDF правил — БЕСПЛАТНО"},{name:"Лист персонажа (PDF)"},{name:"Онлайн-оракул и трекер"}],quotes:[{text:"Ironsworn продвинула искусство дизайна соло-приключений на световые годы вперёд, принесла в формат новые техники и системы и познакомила с соло-RPG новое поколение игроков. Это шедевр."},{text:"Ironsworn — одна из самых умных и грамотно спроектированных TTRPG, что я водил. Более того, это потрясающий инструмент для писателей и творческих людей."}]},en:{tagShort:"free solo PbtA dark fantasy",tagline:'"One player. One world. Vows that cannot be broken."',description:"Ironsworn is THE dark fantasy solo RPG. Free, complete, uncompromising. Play alone, co-op with a GM, or fully GM-less — the same rules support all three modes. Inspired by Powered by the Apocalypse: moves, not rules — narrative always first. Oracles generate the world, threats, and unexpected twists right at the table. Zero prep. Just vows, stakes, and iron.",setting:"The Ironlands — a grim, hostile north. Not heroic fantasy with dragons and taverns — here people cling to survival at the edge of a scorched world. Clans, feuds, dark forests, forgotten ruins. Inspiration: Norse myth, Celtic melancholy, and the feeling of a besieged frontier. Every quest isn't 'save the world' — it's 'survive. Fulfill the vow. Die with honor.'",vignette:"You're alone. The village is ash. You press your hand to a piece of iron and swear: 'I will find those who did this.' Roll on Swear a Vow — 5 against 7 and 3. Weak hit: the vow is accepted, but the Fates (you, via the oracle) add a complication. You enter the forest. Roll an encounter — 'A threat approaches.' Oracle: 'A wolf? No. Something larger.' You write it in your journal. The story unfolds.",prep:"~0 min",mechanics:[{title:"Iron Vows",text:"Every quest begins with a sworn vow on iron. A progress track shows how far you've come. Breaking a vow means losing part of yourself."},{title:"Three play modes",text:"Full solo (you and the oracles), co-op GM-less (everyone shapes the narrative together), or classic with a GM. One ruleset — three distinct experiences."},{title:"Oracles & the Fates",text:"Tables for random events, NPCs, threats, and places stand in for a GM. Ask a question — roll the dice — interpret. The world builds itself."},{title:"PbtA-style moves",text:"No rule for every situation — only moves. Face danger, undertake an expedition, aid an ally. Failures earn experience. Successes raise the stakes."}],gallery:[{cap:"Cover: The Ironlands"},{cap:"Book spread"},{cap:"Character sheets and oracles"}],resources:[{name:"Official website"},{name:"itch.io page (download free)"},{name:"Full PDF rulebook — FREE"},{name:"Character sheet (PDF)"},{name:"Online oracle & tracker"}]}}),registerSystem("ker-nethalas",{groups:{default:{key:"narrative",order:19},family:{key:"standalone",order:14},genre:{key:"dark-fantasy",order:8},solo:{key:"solo-adventure",order:3}},name:"Ker Nethalas",publisher:"Blackoath Entertainment",dice:"d100 (2d10)",players:"1",complexity:2,heroImage:"https://img.itch.zone/aW1nLzE0OTUyOTYzLnBuZw==/original/SuUuIM.png",playstyleTags:["combat","explore","survival"],settingTags:["fantasy","weird"],gallery:[{src:"https://img.itch.zone/aW1hZ2UvMjUxNTI2MS8yNjA3NzA4MC5qcGc=/347x500/c4RF8Y.jpg"},{src:"https://img.itch.zone/aW1hZ2UvMjUxNTI2MS8xNDk1MjkyOS5qcGc=/347x500/%2F3tKpz.jpg"},{src:"https://img.itch.zone/aW1hZ2UvMjUxNTI2MS8xNDk1Mjk1MC5qcGc=/347x500/x9U1UK.jpg"},{src:"https://img.itch.zone/aW1hZ2UvMjUxNTI2MS8xNDk1Mjk1Ny5qcGc=/347x500/1BPs3N.jpg"}],resources:[{type:"link",url:"https://blackoathgames.com/ker-nethalas-into-the-midnight-throne",fmt:"Web"},{type:"rules",url:"https://blackoath.itch.io/ker-nethalas-into-the-midnight-throne",fmt:"Web"},{type:"quickstart",url:"https://blackoath.itch.io/ker-nethalas-quickstart",fmt:"PDF"},{type:"link",url:"https://www.drivethrurpg.com/en/product/465235/ker-nethalas-into-the-midnight-throne",fmt:"Web"}],mechanics:[{icon:"skull"},{icon:"map"},{icon:"layers"},{icon:"heart"}],quotes:[{text:"In this first run, a solo zombie ('Flesh Eater') grappled my character, eventually crushing me to death because I couldn't break free of its grasp.",author:"Solo Skald"},{text:"Ker Nethalas is a solo RPG mega dungeon that you generate as you go.",author:"tgenedavis, Solo RPG"}],ru:{tagShort:"Соло-данжен в некрополе",tagline:"«Ты выжил на казни. Но некрополь только начинается.»",description:"Сольный подземный crawl в мрачном тёмном фэнтези, построенный с нуля для одного игрока. Вы пришли в себя в недрах Кер-Неталаса — бесконечного некрополя давно погибшей империи некромантов. Систему d100 используется для всего: боя, исследования, магии, крафта. 20 Мастерств, 100 способностей, случайная генерация подземелий, система рассудка и усталости. Аналог Diablo II или Nethack, реализованный вживую за столом.",setting:"Кер-Нетелас — Полночный Трон, колоссальный некрополь Вэлорианского Вознесения, давно уничтоженной империи некромантов. В глубине, по преданию, стоит сам Полночный Трон — чёрный базальтовый постамент, где правители-некроманты когда-то сидели, повелевая легионами мёртвых. Вдохновение — Англия XVII века и Испания эпохи инквизиции, переосмыслённые в тёмное фэнтези, где мертвецы не успокаиваются, а тьма не рассеивается.",vignette:"Вы картографируете Домен IV. Бросок генерации комнаты: 47 — Т-образный коридор. На входе срабатывает таблица встречи: d100 = 83, «Ходячий Ужас». Противостоящая проверка боя — ваш показатель Клинка 42 против его 55. Оба бросаем. Вы: 31 — успех. Он: 61 — провал. Удар. Но у вас осталось 2 заряда факела. Ещё 3 комнаты до лагеря. Исчезни тьма — и Усталость начнёт красть HP.",prep:"~15 мин",mechanics:[{title:"Противостоящий бой",text:"Никакого «моя атака, твоя защита». Оба — вы и враг — одновременно бросают d100. Это держит бой в состоянии постоянной непредсказуемости."},{title:"20 Мастерств, 100 способностей",text:"Бесклассовая система. Вы сами выбираете, каким будет ваш персонаж: берсеркер с ледяными взрывами, некромант в тяжёлой броне, невидимый мастер рукопашного боя."},{title:"Случайный некрополь",text:"Каждая комната, коридор и Домен генерируются случайно. Вы буквально рисуете карту, которой не существовало до начала сессии. Перепрохождение — всегда новый некрополь."},{title:"Ресурсы и выживание",text:"Следите за факелами — без света наступает Тьма и нарастает Усталость. Ешьте и отдыхайте, укрепив лагерь. Рассудок рушится от ужасающих существ. Смерть реальна."}],gallery:[{cap:"Обложка — Кер-Нетелас"},{cap:"Интерьерный арт"},{cap:"Карта подземелья"},{cap:"Существа некрополя"}],resources:[{name:"Официальный сайт"},{name:"Страница на itch.io"},{name:"Quickstart (бесплатно)"},{name:"DriveThruRPG"}],quotes:[{text:"В первом же забеге одинокий зомби («Пожиратель Плоти») схватил моего персонажа в захват и в итоге раздавил насмерть — я не смог из этого выкрутиться."},{text:"Ker Nethalas — соло-RPG в формате мегаподземелья, которое ты генерируешь на ходу."}]},en:{tagShort:"solo necropolis crawler",tagline:'"You survived the execution. The necropolis is just beginning."',description:"A solo dungeon crawler built from the ground up for a single player, set in a dark fantasy necropolis. You regain consciousness deep within Ker Nethalas — the endless underground realm of a long-dead necromancer empire. A d100 system resolves everything: combat, exploration, magic, crafting. 20 Masteries, 100 abilities, procedural dungeon generation, sanity and exhaustion systems. Think Diablo II or Nethack, realized at the tabletop.",setting:"Ker Nethalas — the Midnight Throne — is the colossal necropolis of the Vaelorian Ascendancy, a necromancer empire lost to history. At its heart, legend holds, stands the Midnight Throne itself: a great black dais where the ancient rulers once sat, channeling the essence of death and commanding legions of undead. Inspired by 17th-century England and the height of the Spanish Inquisition, reimagined as dark fantasy where the dead never rest and the darkness never lifts.",vignette:"You are mapping Domain IV. Room generation roll: 47 — T-shaped corridor. The encounter table triggers at the entrance: d100 = 83, 'Shambling Horror.' Opposed combat check — your Blade skill 42 versus its 55. Both roll. You: 31 — success. It: 61 — failure. Strike. But you have 2 torch charges left. Three more rooms to camp. Let the darkness come, and the Exhaustion starts eating your HP.",prep:"~15 min",mechanics:[{title:"Opposed combat",text:"No 'my attack, your defense.' You and the enemy both roll d100 simultaneously. This keeps every fight in a state of permanent, unscripted tension."},{title:"20 Masteries, 100 abilities",text:"A classless system. You decide who your character becomes: a berserker who launches cold blasts, a warlock in heavy armor who raises the dead, an invisible hand-to-hand specialist."},{title:"Procedural necropolis",text:"Every room, corridor, and Domain is generated randomly. You are literally drawing a map that did not exist before you sat down. Each run is a necropolis no one has ever walked before."},{title:"Resources and survival",text:"Track your torches — darkness triggers Exhaustion. Eat and rest; fortify your camp first. Sanity erodes against abominations. Death is permanent. Camp wisely. Map carefully."}],gallery:[{cap:"Cover — Ker Nethalas"},{cap:"Interior art"},{cap:"Dungeon map"},{cap:"Necropolis creatures"}],resources:[{name:"Official website"},{name:"itch.io page"},{name:"Quickstart (free)"},{name:"DriveThruRPG"}]}}),registerSystem("knave",{groups:{default:{key:"osr",order:24},family:{key:"osr-modern",order:3},genre:{key:"adventure",order:22}},name:"Knave",publisher:"Questing Beast Games / Ben Milton",dice:"d20 roll-over",players:"3–6",complexity:1,foundryStatus:"Community",heroImage:"https://img.itch.zone/aW1hZ2UvMjc3NTUyNy8xNjU2NDM2Ni5wbmc=/original/r0dEmj.png",playstyleTags:["explore","combat","sandbox"],settingTags:["fantasy"],gallery:[{src:"https://img.itch.zone/aW1hZ2UvMjc3NTUyNy8xNjU2NDM3NC5qcGc=/original/e4mJTJ.jpg"},{src:"https://img.itch.zone/aW1hZ2UvMjc3NTUyNy8xNjU2NDM4MC5qcGc=/original/0JHiXM.jpg"},{src:"https://image.nobleknight.com/2/jpg1500/24194440115h.jpg"}],resources:[{type:"link",url:"https://questingbeast.itch.io/knave-second-edition",fmt:"Web"}],mechanics:[{icon:"backpack"},{icon:"dices"},{icon:"shuffle"},{icon:"feather"}],quotes:[{text:"Knave 2E's random roll tables will find their way into other games. They're that good.",author:"Clayton Notestine, Explorers Design"},{text:"Knave is lightweight, flexible, and powerful. Its elegant design equally empowers players and GMs.",author:"John Hodson, Michael Ghelfi Studios"}],ru:{tagShort:"Ультралёгкий бесклассовый OSR-каркас",tagline:"«Твой инвентарь — это твой билд».",description:"Knave — предельно лёгкая OSR-игра Бена Милтона (Questing Beast). Персонаж без класса: его определяют характеристики и предметы в слотах инвентаря. 80 страниц — почти сплошь генераторы (NPC, монстры, заклинания, подземелья, гексы), превращающие подготовку в бросок пары таблиц. Идеальный хакаемый каркас под свою кампанию.",setting:"Система-агностик классического фэнтези. Knave ничего не навязывает: ни сеттинга, ни классов, ни длинных списков умений. Дух — олдскульный данжен-кроул и гексокроул, где смекалка игрока важнее циферок. Пустой холст с мощнейшим набором таблиц, чтобы заполнить его на лету.",vignette:"Взломщик тянется к рычагу в стене. Ведущий назначает сложность 14. Бросок d20 + бонус Ловкости, нужно 14 или выше. Выпало 16 — рычаг поддаётся, решётка ползёт вверх. Но слоты инвентаря почти полны: факел, верёвка, добытый идол... что-то придётся бросить, чтобы освободить руки. В Knave вес и место решают не меньше боя.",prep:"~15 мин",mechanics:[{title:"Бесклассовость через инвентарь",text:"Классов нет: кто ты — определяют характеристики и предметы. Инвентарь измеряется слотами (по Силе), и то, что ты носишь, буквально задаёт твои возможности."},{title:"Бросок «больше» на d20",text:"Проверка — d20 + бонус характеристики против сложности. Одна механика на всё: атаки, спасброски, навыки. Учится за минуту, играется мгновенно."},{title:"Генераторы на всё",text:"Сердце книги — таблицы: NPC, монстры, заклинания, подземелья, гексы, зацепки. Целые куски мира собираются броском кубика. Подготовка почти исчезает."},{title:"Лёгкий и хакаемый",text:"Ядро правил умещается на пару страниц. Knave создан, чтобы его растаскивали и хакали — таблицы и слоты легко вставляются в любую другую олдскульную игру."}],gallery:[{cap:"Разворот книги"},{cap:"Интерьерный арт"},{cap:"Premium Edition"}],resources:[{name:"Официальная страница (itch.io)"}]},en:{tagShort:"An ultra-light, classless OSR toolkit",tagline:'"Your inventory is your build."',description:"Knave is Ben Milton's (Questing Beast) ultra-light OSR game. Characters are classless — defined by their attributes and the items in their inventory slots. Its 80 pages are mostly generators (NPCs, monsters, spells, dungeons, hexes) that turn prep into rolling a couple of tables. The perfect hackable frame for your own campaign.",setting:"Setting-agnostic classic fantasy. Knave imposes nothing — no setting, no classes, no long skill lists. The spirit is old-school dungeon- and hex-crawling where player cunning beats stat blocks. A blank canvas with a powerhouse set of tables to fill it on the fly.",vignette:"The burglar reaches for a lever in the wall. The GM sets the difficulty at 14. Roll d20 + Dexterity bonus, need 14 or higher. A 16 — the lever gives, the portcullis grinds upward. But the inventory slots are nearly full: torch, rope, the looted idol... something has to be dropped to free your hands. In Knave, weight and space matter as much as combat.",prep:"~15 min",mechanics:[{title:"Classless via inventory",text:"No classes: who you are is defined by attributes and items. Inventory is measured in slots (by Strength), and what you carry literally sets what you can do."},{title:"Roll-over d20",text:"A test is d20 + attribute bonus against a difficulty. One mechanic for everything: attacks, saves, skills. Learned in a minute, played instantly."},{title:"Generators for everything",text:"The heart of the book is its tables: NPCs, monsters, spells, dungeons, hexes, hooks. Whole chunks of the world come together on a die roll. Prep nearly vanishes."},{title:"Light & hackable",text:"The core rules fit on a couple of pages. Knave is built to be plundered and hacked — its tables and slots drop easily into any other old-school game."}],gallery:[{cap:"Book spread"},{cap:"Interior art"},{cap:"Premium Edition"}],resources:[{name:"Official page (itch.io)"}]}}),registerSystem("koriko",{groups:{default:{key:"narrative",order:19.5},family:{key:"standalone",order:14.5},genre:{key:"narrative-weird",order:8},solo:{key:"solo-journaling",order:3}},name:"Koriko: A Magical Year",publisher:"Jack Harrison / Mousehole Press",dice:"Таро + d6 (башня)",players:"1",complexity:1,heroImage:"https://img.itch.zone/aW1nLzEyNTk3MTMwLmpwZw==/original/Jupq7g.jpg",heroImageStyle:"object-fit: cover; object-position: center top; background: linear-gradient(135deg, #1a0a2e, #2d1b69 40%, #4a1942 70%, #1a0a2e);",playstyleTags:["narrative","mystery","social"],settingTags:["urban-fantasy"],gallery:[{src:"https://img.itch.zone/aW1hZ2UvMjEzNjgwOS8xMjU5NzE4NC5wbmc=/347x500/RbMZ%2Fd.png"},{src:"https://img.itch.zone/aW1hZ2UvMjEzNjgwOS8xMjU5NzE4NS5wbmc=/347x500/2%2BGCSI.png"},{src:"https://img.itch.zone/aW1hZ2UvMjEzNjgwOS8xMjU5NzE4My5wbmc=/347x500/MJC9%2BC.png"}],resources:[{type:"link",url:"https://mouseholepress.itch.io/koriko",fmt:"Web"},{type:"link",url:"https://mousehole.press/products/koriko-a-magical-year",fmt:"Web"}],mechanics:[{icon:"star"},{icon:"layers"},{icon:"heart"},{icon:"feather"}],quotes:[{text:"Koriko confidently guides new players and experienced solo role-players alike",author:"Eleanor Hingley, Destructoid"}],ru:{tagShort:"Соло-журнал ведьмы",tagline:"«Ты — молодая ведьма. Незнакомый город. Год, который изменит тебя навсегда.»",description:"Koriko — соло-дневниковая игра о взрослении через магию и одиночество. Вдохновлённая «Ведьминой службой доставки» Хаяо Миядзаки, она предлагает провести целый год вместе со своей ведьмой: семь томов, каждый по 1–2 часа, каждый — новая глава её жизни в Корико. Колода таро формирует события и знакомства. Башня из 21 кубика d6 решает, что происходит, когда она рискует. И ведётся дневник — живой, личный, твой.",setting:"Город Корико — шумный, тёплый, совершенно чужой. Твоя ведьма приехала сюда одна, без наставника, без карты. Булочные с привидениями, рынки, где продают зелья рядом с оливковым маслом, крыши с видом на море, вечеринки, на которые тебя позвали и которые тебя пугают. Год пройдёт — что останется?",vignette:"Том второй. Ты тянешь карту — Пятёрка Кубков. Промпт: «Ты потеряла что-то важное. Что именно?» Риск: можно написать тяжелее и добавить кубик к башне. Ты добавляешь. Башня шатается — шесть кубиков высотой. Ты пишешь: метла сломана, а её починил незнакомец с тихими руками. Теперь он — конфидант. Его зовут Том. Башня устояла.",prep:"~15 мин",mechanics:[{title:"Таро как оракул",text:"Колода делится на масти (промпты) и Старшие Арканы (конфиданты — значимые NPC). Каждый том начинается с формирования новой «Том-колоды». Карты задают направление истории, не диктуя её."},{title:"Башня из кубиков",text:"Когда ведьма рискует, ты добавляешь d6 к физической башне. Чем выше — тем опаснее. Когда башня падает, ты считаешь грани упавших кубиков: они определяют одно из шести Последствий. Физическое, тактильное, незабываемое."},{title:"Конфиданты",text:"22 уникальных персонажа, каждый из Старших Арканов. Они возвращаются, меняются, иногда исчезают. Их судьбы переплетаются с твоей историей через все семь томов."},{title:"Твисты и уроки",text:"Рискованные промпты открывают Твисты — повороты истории. Успешные броски дают Уроки: расходуемые бонусы, которые ведьма применяет в трудный момент."}],gallery:[{cap:"Разворот книги — интерьер"},{cap:"Страницы правил"},{cap:"Карты конфидантов"}],resources:[{name:"Itch.io (PDF, pay-what-you-want)"},{name:"Официальный сайт Mousehole Press"}],quotes:[{text:"Koriko уверенно ведёт за руку и новичков, и опытных соло-ролевиков."}]},en:{tagShort:"solo witch RPG",tagline:'"You are a young witch. An unfamiliar city. A year that will change you forever."',description:"Koriko is a solo journaling game about coming of age through magic and solitude. Inspired by Kiki's Delivery Service — both Miyazaki's film and Eiko Kadono's novel — it asks you to spend a whole year alongside your witch: seven volumes, each one or two hours, each a new chapter of her life in the city of Koriko. A tarot deck shapes her encounters and crises. A tower of 21 d6 dice decides what happens when she dares to take a risk. And through it all, you keep a journal — alive, personal, and entirely your own.",setting:"Koriko is a city that hums and buzzes and doesn't care that you just arrived. Your witch came alone — no mentor, no map, no plan. There are bakeries haunted by friendly ghosts, markets selling love potions next to olive oil, rooftops with sea views, parties you've been invited to and parties that terrify you. By the end of the year, what will still be standing?",vignette:"Volume Two. You draw a card — Five of Cups. Prompt: 'You have lost something that mattered. What was it?' The risky option lets you write something harder and add a die to the tower. You add it. The tower wobbles — six dice tall now. You write: the broom snapped, and a quiet-handed stranger fixed it. He becomes a confidante. His name is Tom. The tower holds.",prep:"~15 min",mechanics:[{title:"Tarot as oracle",text:"The deck is split into suits (prompts) and Major Arcana (confidantes — significant NPCs). Each volume begins by building a fresh 'Volume Deck'. Cards steer the story without dictating it; the writing is always yours."},{title:"Dice tower",text:"When your witch takes a risk, you physically add a d6 to a stacking tower. The higher it climbs, the more precarious it becomes. When it collapses, you count the faces of the fallen dice — they determine one of six Consequences. Tactile, unpredictable, and genuinely thrilling."},{title:"Confidantes",text:"22 unique characters, each drawn from the Major Arcana. They return, develop, and sometimes vanish. Their fates interweave with your witch's story across all seven volumes, making each playthrough feel like a real novel."},{title:"Twists and lessons",text:"Risky prompts unlock Twists — narrative curveballs that reshape the story. Successful dice-stacking earns Lessons: spendable bonuses your witch can call on in a difficult moment, a tangible record of how much she has grown."}],gallery:[{cap:"Book spread — interior"},{cap:"Rules pages"},{cap:"Confidante cards"}],resources:[{name:"Itch.io (PDF, pay-what-you-want)"},{name:"Mousehole Press official store"}]}}),registerSystem("kult-divinity-lost",{groups:{default:{key:"narrative",order:31},family:{key:"pbta-fitd",order:27},genre:{key:"horror",order:7}},name:"Kult: Divinity Lost",publisher:"Helmgast",dice:"2d10 + модификатор (PbtA)",players:"3–5",complexity:2,free:!0,foundryStatus:"Community",heroImage:"https://modiphius.net/cdn/shop/products/Gamemaster_Screen.png",playstyleTags:["horror","narrative","mystery"],settingTags:["modern","weird"],gallery:[{src:"https://modiphius.net/cdn/shop/products/Kult_Core_Book.png"},{src:"https://modiphius.net/cdn/shop/products/The_Black_Madonna.png"},{src:"https://modiphius.net/cdn/shop/products/Taroticum_and_Other_Tales.png"}],resources:[{type:"link",url:"https://helmgast.se/kult/",fmt:"Web"},{type:"quickstart",url:"https://modiphius.net/en-us/products/kult-divinity-lost-quickstart-rules-free-pdf",fmt:"PDF"}],mechanics:[{icon:"dices"},{icon:"brain"},{icon:"eye"},{icon:"skull"}],quotes:[{text:"Just because I can't see running Kult: Divinity Lost with my gang doesn't mean this isn't an exceptionally well done roleplaying game.",author:"Jeff McAleer, The Gaming Gang"},{text:"If you fall into its target group you will discover a rich and well-researched setting that will make your imagination run wild.",author:"Antonios S, RPGnet"}],ru:{tagShort:"Оккультный хоррор: реальность — тюрьма",tagline:"«Мы — падшие божества, а мир вокруг — Иллюзия, скрывающая правду».",description:"Kult: Divinity Lost — 4-я редакция культового шведского хоррора от Helmgast, теперь на движке Powered by the Apocalypse (2d10). Реальность — ложь, темница для человечества, некогда божественного. Прорвавшись сквозь Иллюзию, персонажи видят истинный кошмар за фасадом. Взрослый, философский и по-настоящему тревожный хоррор.",setting:"Современный мир — это Иллюзия, сотканная, чтобы держать людей в плену и забвении их божественной природы. За ней — Метрополис (мёртвый город-первооснова) и Инферно (десять чистилищ страдания). Ангелы Смерти, ликторы, сущности Смерти и Страсти. Личный, психологический хоррор о деградации и прозрении.",vignette:"Ваш герой находит фотографию, которой не должно существовать: на ней он сам — в месте, где никогда не был. Ход «Разобраться в ситуации»: 2d10 + Проницательность. Выпало 8 — частичный успех, правда приходит с ценой. Ведущий: «Ты вспоминаешь. И с этим воспоминанием твоя Стабильность рушится». Стены комнаты на миг становятся прозрачными — за ними шевелится Метрополис.",prep:"~15 мин",mechanics:[{title:"Ходы на 2d10 (PbtA)",text:"Действие запускает «ход»: 2d10 + характеристика. 15+ — полный успех, 10–14 — с осложнением, 9 и ниже — провал и ход ведущего. Фикшн-первый подход, знакомый по Apocalypse World."},{title:"Тёмные секреты и Недостатки",text:"У каждого персонажа есть Тёмный секрет и Недостатки, вплетающие его в кошмар. Это не флаф, а мотор сюжета: именно они тянут героя к правде и гибели."},{title:"Стабильность",text:"Шкала рассудка. Прозрение сквозь Иллюзию, насилие и ужас подтачивают Стабильность. Чем ниже — тем ближе персонаж к безумию, одержимости или Пробуждению."},{title:"Пробуждение сквозь Иллюзию",text:"Игра — о том, чтобы увидеть истину за фасадом реальности. Каждое откровение опасно: знание освобождает и уничтожает одновременно. Сеттинг встроен в саму механику ужаса."}],gallery:[{cap:"Core Book"},{cap:"The Black Madonna"},{cap:"Taroticum & Other Tales"}],resources:[{name:"Официальный сайт — Helmgast"},{name:"Бесплатные Quickstart-правила"}],quotes:[{text:"То, что я не вижу, как вести Kult: Divinity Lost со своей компанией, не значит, что это не исключительно хорошо сделанная ролевая игра."},{text:"Если вы попадаете в её целевую аудиторию, вы откроете богатый и тщательно проработанный сеттинг, который заставит воображение разгуляться."}]},en:{tagShort:"Occult horror: reality is a prison",tagline:'"We are fallen divinities, and the world around us is an Illusion hiding the truth."',description:"Kult: Divinity Lost is the 4th edition of Helmgast's cult Swedish horror game, now Powered by the Apocalypse (2d10). Reality is a lie — a prison for a humanity that was once divine. Breaking through the Illusion, characters glimpse the true nightmare behind the facade. Adult, philosophical, and genuinely disturbing horror.",setting:"The modern world is an Illusion woven to keep humanity captive and forgetful of its divine nature. Behind it lie Metropolis (the dead primordial city) and Inferno (ten purgatories of suffering). Angels of Death, lictors, entities of Death and Passion. Personal, psychological horror about degradation and revelation.",vignette:"Your character finds a photograph that shouldn't exist: it's them, in a place they've never been. The move 'See Through the Illusion': 2d10 + Perception. You roll an 8 — a partial success; the truth comes at a cost. The GM: 'You remember. And with the memory, your Stability cracks.' The room's walls turn briefly transparent — behind them, Metropolis stirs.",prep:"~15 min",mechanics:[{title:"2d10 moves (PbtA)",text:"An action triggers a 'move': 2d10 + stat. 15+ is a full success, 10–14 comes with a complication, 9 or under fails and hands the GM a move. A fiction-first approach familiar from Apocalypse World."},{title:"Dark Secrets & Disadvantages",text:"Every character has a Dark Secret and Disadvantages that weave them into the nightmare. Not flavor but the engine of the story — they drag the hero toward the truth and their doom."},{title:"Stability",text:"A sanity track. Seeing through the Illusion, violence, and horror erode Stability. The lower it falls, the closer the character comes to madness, possession, or Awakening."},{title:"Awakening through the Illusion",text:"The game is about seeing the truth behind reality's facade. Every revelation is dangerous: knowledge frees and destroys at once. The setting is built into the very mechanics of horror."}],gallery:[{cap:"Core Book"},{cap:"The Black Madonna"},{cap:"Taroticum & Other Tales"}],resources:[{name:"Official site — Helmgast"},{name:"Free Quickstart rules"}]}}),registerSystem("l5r",{groups:{default:{key:"narrative",order:12},family:{key:"standalone",order:8},genre:{key:"tactical",order:4}},name:"Legend of the Five Rings 5e",publisher:"Edge Studio (formerly FFG)",dice:"Кастомные (Ring d6 + Skill d12)",players:"3–5",complexity:4,foundryStatus:"Community",heroImage:"https://cdn.svc.asmodee.net/production-l5r/uploads/image-converter/2023/06/04_Image_L5R-1900x1040.webp",heroStyle:"background: linear-gradient(135deg, #7c1d1d, #1a1a2e, #1e3a5f);",playstyleTags:["social","narrative","combat"],settingTags:["fantasy","historical"],gallery:[{src:"https://cdn.svc.asmodee.net/production-l5r/uploads/image-converter/2023/06/01a_Cover_Illustration-1900x1900.webp"},{src:"https://cdn.svc.asmodee.net/production-l5r/uploads/image-converter/2023/06/04_Image_L5R-1900x1040.webp"}],resources:[{type:"link",url:"https://www.edge-studio.net/shares/legend-of-the-five-rings/",fmt:"Web"}],mechanics:[{icon:"circle-dot"},{icon:"heart-crack"},{icon:"file-pen"},{icon:"crown"}],quotes:[{text:"This latest incarnation of Legend of the Five Rings is a shining example of how an RPG can commit so deeply to a setting and playstyle that it's impossible to imagine one existing without the other.",author:"Richard Jansen-Parkes, Tabletop Gaming"},{text:"Combining that with the elemental ring approach really sells me on the new edition of the L5R roleplaying game.",author:"Strange Assembly"},{text:"It teaches the system well, it gives a good introduction to the setting and society, and there are plenty of interesting encounters and chances for the players to shine.",author:"Seamus Conneely, Cannibal Halfling Gaming"}],ru:{tagShort:"Самурайская RPG",tagline:"«Ваш меч остр, но ваши слова — острее. Один неверный жест — и клан падёт.»",description:"Самурайская драма с уникальной системой кастомных кубиков. Кольцевые кубики (d6) и кубики навыков (d12) используют специальные символы вместо цифр. Игрок выбирает подход к каждой проверке через одно из пяти Колец — Огонь, Вода, Земля, Воздух, Пустота — каждое даёт принципиально разный результат. Создание персонажа — через 20 вопросов о прошлом, клане и мотивации. Последний вопрос: «Как умрёт ваш персонаж?»",setting:"Рокуган — фэнтези-Япония: самураи, кланы, честь, долг. Семь Великих Кланов борются за власть при Императорском дворе. Мир основан на японской, китайской и корейской мифологии.",vignette:"Совет клана Журавля. Вы должны убедить даймё поддержать ваш план. Бросок Убеждения через Кольцо Огня — страстная речь. Два успеха, но на кубике — символ Раздора. Ваш голос дрожит. Раздор растёт до 5 — вы на грани. Ещё один Раздор — и маска слетит. Весь зал увидит ваш гнев. Для самурая это хуже смерти.",prep:"~30 мин",mechanics:[{title:"Система Колец",text:"5 колец: Огонь, Вода, Земля, Воздух, Пустота — игрок выбирает через какое Кольцо подходить к проверке, каждое даёт разный результат."},{title:"Раздор (Strife)",text:"Эмоциональное напряжение копится при бросках. Переполнение → «снятие маски» — потеря контроля на публике. В обществе где честь = жизнь, показать эмоции = позор."},{title:"20 вопросов",text:"Создание персонажа через 20 вопросов о его прошлом, клане, мотивации. Последний: «Как умрёт ваш персонаж?»"},{title:"Честь, Слава, Статус",text:"Три отдельные шкалы репутации, каждая влияет на разные социальные ситуации."}],gallery:[{cap:"Обложка Core Rulebook"},{cap:"Самураи Рокугана"}],resources:[{name:"Официальный сайт"}],quotes:[{text:"Свежее воплощение Legend of the Five Rings — яркий пример того, как RPG может настолько глубоко вписаться в сеттинг и стиль игры, что одно невозможно представить без другого."},{text:"В сочетании с подходом колец стихий это окончательно убеждает меня в новом издании L5R."},{text:"Хорошо обучает системе, аккуратно знакомит с сеттингом и обществом, и в нём достаточно интересных встреч и поводов игрокам блеснуть."}]},en:{tagShort:"samurai RPG",tagline:'"Your blade is sharp, but your words are sharper. One wrong gesture — and your clan falls."',description:"A samurai drama with a unique custom dice system. Ring dice (d6) and skill dice (d12) use special symbols instead of numbers. The player chooses their approach to each check through one of five Rings — Fire, Water, Earth, Air, Void — each yielding a fundamentally different result. Character creation through 20 questions about background, clan, and motivation. The last question: 'How will your character die?'",setting:"Rokugan — fantasy Japan: samurai, clans, honor, duty. Seven Great Clans vie for power at the Imperial Court. The world draws from Japanese, Chinese, and Korean mythology.",vignette:"Crane clan council. You must convince the daimyo to support your plan. Persuasion roll through the Fire Ring — a passionate speech. Two successes, but a die shows the Strife symbol. Your voice trembles. Strife rises to 5 — you're on the edge. One more Strife and the mask cracks. The entire court sees your rage. For a samurai, that's worse than death.",prep:"~30 min",mechanics:[{title:"Ring system",text:"5 Rings: Fire, Water, Earth, Air, Void — the player chooses which Ring to approach the check through, each yields a different result."},{title:"Strife",text:"Emotional tension builds on rolls. Overflow means 'unmasking' — losing control in public. In a society where honor = life, showing emotion = disgrace."},{title:"20 Questions",text:"Character creation through 20 questions about background, clan, motivation. The last: 'How will your character die?'"},{title:"Honor, Glory, Status",text:"Three separate reputation tracks, each affecting different social situations."}],gallery:[{cap:"Core Rulebook cover"},{cap:"Samurai of Rokugan"}],resources:[{name:"Official website"}]}}),registerSystem("labyrinth-lord",{groups:{default:{key:"osr",order:19},family:{key:"osr-classic",order:11},genre:{key:"adventure",order:18}},name:"Labyrinth Lord",publisher:"Goblinoid Games",dice:"d20 + B/X resolution",players:"3–6",complexity:2,edition:"B/X",free:!0,foundryStatus:"None",heroImage:"https://image.nobleknight.com/i/jpg1500/impgbn1001.jpg",playstyleTags:["combat","explore","sandbox"],settingTags:["fantasy"],gallery:[{src:"https://image.nobleknight.com/g/jpg1500/gbd1003-dragon.jpg"},{src:"https://image.nobleknight.com/g/jpg1500/gbd1002.jpg"},{src:"https://image.nobleknight.com/i/jpg1500/impgbdmonlist.jpg"}],resources:[{type:"link",url:"https://www.goblinoidgames.com/",fmt:"Web"},{type:"quickstart",url:"https://www.drivethrurpg.com/en/product/64331/labyrinth-lord-revised-edition-no-art-version",fmt:"PDF"}],mechanics:[{icon:"dices"},{icon:"book-open"},{icon:"swords"},{icon:"gift"}],quotes:[{text:"Advanced Labyrinth Lord is absolutely playable, very convenient, and a pleasantly complete package deal.",author:"Dungeons & Possums"}],ru:{tagShort:"Точный ретроклон B/X, опора OSR",tagline:"«D&D Basic/Expert 1981 года — верно, полно и бесплатно».",description:"Labyrinth Lord — верный ретроклон D&D Basic/Expert (B/X) 1981 года от Дэниела Проктора (Goblinoid Games, 2007). Один из первых и самых уважаемых клонов OSR, десятилетиями служащий эталоном совместимости. «Advanced Edition Companion» добавляет опции в духе AD&D (классы, расы, заклинания). Бесплатная версия без иллюстраций — на все правила.",setting:"Система-агностик в духе классического подземельного фэнтези. Раса-как-класс (Эльф, Дварф, Полурослик), демихьюманы с лимитами уровней, картирование по клеточкам, реакции монстров и жажда сокровищ. Любой модуль эпохи B/X идёт без конвертации — Labyrinth Lord создан именно ради этой совместимости.",vignette:"Партия у развилки в подземелье. Ведущий кидает реакцию монстра — из тьмы выходит отряд кобольдов, но бросок 2d6 показывает «нерешительность»: они колеблются. Клерик пытается договориться. Не выйдет — боец бьёт: d20 против AC, классическая таблица атак. Золото ждёт за дверью, и партия чует его запах.",prep:"~20 мин",mechanics:[{title:"Верный клон B/X",text:"Почти дословные правила Молдвея/Кука 1981 года. Любой модуль и супплемент эпохи Basic/Expert запускается без правок. Эталон совместимости всего OSR-движения."},{title:"Advanced Edition Companion",text:"Опциональный том добавляет классы, расы и заклинания в духе AD&D — так рождается «Advanced Labyrinth Lord». Хотите проще — играете чистый B/X; хотите глубже — подключаете AEC."},{title:"Раса-как-класс",text:"Классический олдскул: Эльф, Дварф и Полурослик — это классы, а не расы поверх класса. Простое создание персонажа и тот самый ретро-вкус ранней D&D."},{title:"Бесплатная версия без арта",text:"Полные правила доступны бесплатным PDF (без иллюстраций). Порог входа — нулевой. С 2007 года это опорный справочник-ретроклон старой школы."}],gallery:[{cap:"Иллюстрация — дракон"},{cap:"Модуль-приключение"},{cap:"Список монстров"}],resources:[{name:"Официальный сайт — Goblinoid Games"},{name:"Бесплатная версия без арта (PDF)"}],quotes:[{text:"Advanced Labyrinth Lord абсолютно играбелен, очень удобен и приятно завершённый комплект «всё в одном»."}]},en:{tagShort:"A faithful B/X retroclone, an OSR cornerstone",tagline:'"1981 D&D Basic/Expert — faithful, complete, and free."',description:"Labyrinth Lord is Daniel Proctor's faithful retroclone of 1981 D&D Basic/Expert (B/X), from Goblinoid Games (2007). One of the earliest and most respected OSR clones, it has served as the compatibility benchmark for decades. The 'Advanced Edition Companion' adds AD&D-style options (classes, races, spells). A free no-art version covers the full rules.",setting:"Setting-agnostic in the classic dungeon-fantasy mold. Race-as-class (Elf, Dwarf, Halfling), demihuman level limits, graph-paper mapping, monster reactions, and the lust for treasure. Any B/X-era module runs without conversion — Labyrinth Lord was built for exactly that compatibility.",vignette:"The party halts at a dungeon fork. The GM rolls a monster reaction — a kobold band emerges from the dark, but a 2d6 result reads 'uncertain': they hesitate. The cleric tries to parley. If it fails, the fighter swings: d20 against AC on the classic attack matrix. Gold waits behind the door, and the party can smell it.",prep:"~20 min",mechanics:[{title:"Faithful B/X clone",text:"Near-verbatim 1981 Moldvay/Cook rules. Any Basic/Expert-era module or supplement runs unedited. The compatibility benchmark for the whole OSR movement."},{title:"Advanced Edition Companion",text:"An optional volume adds AD&D-style classes, races, and spells — this is how 'Advanced Labyrinth Lord' is born. Want it simpler? Play pure B/X. Want more depth? Bolt on the AEC."},{title:"Race-as-class",text:"Classic old-school: Elf, Dwarf, and Halfling are classes, not races layered onto a class. Simple character creation and that authentic early-D&D flavor."},{title:"Free no-art version",text:"The complete rules are available as a free PDF (without illustrations). A zero-cost on-ramp. Since 2007 it has been the old-school movement's reference retroclone."}],gallery:[{cap:"Dragon illustration"},{cap:"Adventure module"},{cap:"Monster listing"}],resources:[{name:"Official site — Goblinoid Games"},{name:"Free no-art version (PDF)"}],quotes:[{text:"Advanced Labyrinth Lord is absolutely playable, very convenient, and a pleasantly complete package deal."}]}}),registerSystem("lancer",{groups:{default:{key:"tactical",order:3},family:{key:"standalone",order:11},genre:{key:"tactical",order:3}},name:"Lancer",publisher:"Massif Press",dice:"d20 + d6",players:"3–5",complexity:3,foundryStatus:"Community",heroImage:"https://img.itch.zone/aW1nLzI3MzE0ODYuanBn/original/PF05J1.jpg",playstyleTags:["tactical","combat","narrative"],settingTags:["space"],gallery:[{src:"https://img.itch.zone/aW1nLzI3MzE0ODYuanBn/original/PF05J1.jpg"}],quotes:[{text:"It feels like an actual mech skirmish game that's genuinely merged with an indie RPG.",author:"Andrew Girdwood, Geek Native"},{text:"The leveling in Lancer is where the game's unique system of completely modular mech design shines.",author:"Zachary Pilon, CBR"}],resources:[{type:"link",url:"https://massifpress.com/lancer",fmt:"Web"},{type:"quickstart",url:"https://massif-press.itch.io/corebook-pdf-free",fmt:"PDF"},{type:"tool",url:"https://compcon.app/",fmt:"Web"}],mechanics:[{icon:"wrench"},{icon:"flame"},{icon:"brain"},{icon:"users"}],ru:{tagShort:"Тактический sci-fi мех-RPG",tagline:"«В галактике много пилотов, но ты — один.»",description:"LANCER — научно-фантастическая тактическая RPG о пилотах мехов, сражающихся за лучшее будущее на переднем крае постдефицитной утопии. Глубокая модульная тактика боёв на мехах + лёгкие нарративные правила.",setting:"Через десять тысяч лет человечество выстроило Союз — посткапиталистическое межзвёздное правительство. Золотой век реален для Ядра; для фронтира — обещание, написанное выхлопом мехов и огнём рельсотронов.",vignette:"В 3:00 туман сходит с эстуария, IFF мигает красным. Твой SSC Dusk Wing затаился в мангровых зарослях. NHP нашёптывает решение для стрельбы через нейросвязь. «Лансер-Актуал — оружие свободно». Мангры исчезают в белой вспышке плазмы.",prep:"~30 мин",mechanics:[{title:"Система лицензий",text:"Очки лицензий открывают рамы, оружие и системы четырёх производителей. Комбинируй в любых сочетаниях."},{title:"Перегрев и стресс реактора",text:"Мехи перегреваются. Переполнение шкалы жара — броски по таблице стресса, вплоть до расплавления."},{title:"Нечеловеческие личности",text:"NHP — паракаузальные разумы в ядрах мехов. Перегрузи — войдут в Каскад с непредсказуемыми последствиями."},{title:"Два режима игры",text:"Тактический бой на сетке + свободный нарративный режим для всего остального."}],gallery:[{cap:"Обложка основной книги"}],resources:[{name:"Официальный сайт"},{name:"Бесплатная основная книга"},{name:"Приложение COMP/CON"}],quotes:[{text:"Ощущается как настоящая варгеймовая стычка мехов, по-настоящему сросшаяся с инди-RPG."},{text:"Прокачка в Lancer — это то, где раскрывается уникальная система полностью модульного дизайна мехов."}]},en:{tagShort:"tactical sci-fi mech combat RPG",tagline:'"There are many pilots in the galaxy, but only one of you."',description:"LANCER is a science fiction tactical RPG about mech pilots — lancers — who fight for a better future on the bleeding edge of a post-scarcity utopia still being born. It blends gritty, deeply customizable mech combat with rules-light narrative roleplay, giving equal weight to what you do in the cockpit and who you are outside it.",setting:"Ten thousand years from now, humanity survived ecological collapse, spread to the stars, and built Union — a communal, post-capital interstellar government working toward a genuine utopia. The golden age is real for the Galactic Core; for the frontier worlds, it is still a promise written in mech exhaust and railgun fire. Megacorporate manufacturers supply the frames that lancers ride into a galaxy where the work of liberation is never quite finished.",vignette:"The fog rolls off the estuary at 0300 when ANANSI's IFF pings red. Your mech, a SSC Dusk Wing, is already crouching in the mangroves — legs locked, passive sensors drinking in the heat of twelve colonial militia walkers moving in column. Your NHP whispers a firing solution across the neural link, patient as mathematics. 'Lancer-Actual, this is Able Flight — we are weapons free.' The mangroves vanish in a white bloom of plasma.",prep:"~30 min",mechanics:[{title:"Mech Licensing",text:"Pilots earn License Points each level to unlock frames, weapons, and systems from four rival manufacturers. Mix and match across any frame — no two builds are ever the same."},{title:"Heat & Stress",text:"Mechs overheat. Pushing weapons and systems fills your Heat Cap; overflow triggers Stress rolls on the reactor table, up to and including catastrophic meltdown."},{title:"Non-Human Persons",text:"NHPs are paracausal intelligences bound inside mech cores. Push them too hard and they Cascade, breaking free of restraint with unpredictable and often terrifying results."},{title:"Two Modes of Play",text:"Structured tactical grid combat handles the battles; freeform Narrative Mode handles everything else — downtime, piloting intrigue, on-foot action."}],gallery:[{cap:"Lancer Core Book cover"}],resources:[{name:"Official website"},{name:"Free core book (itch.io)"},{name:"COMP/CON digital companion"}]}}),registerSystem("land-of-eem",{groups:{default:{key:"narrative",order:23},family:{key:"standalone",order:21},genre:{key:"adventure",order:13},solo:{key:"solo-compatible",order:11}},name:"Land of Eem",publisher:"Exalted Funeral / Ben Costa & James Parks",dice:"1d12 + skill",players:"3–5",complexity:2,foundryStatus:"None",heroImage:"https://sessionzero.games/images/heroes/land-of-eem.webp",playstyleTags:["explore","narrative","social"],settingTags:["fantasy","weird"],gallery:[{src:"https://www.exaltedfuneral.com/cdn/shop/files/land-of-eem-deluxe-box-set-box-set-720484.jpg?v=1763753731&width=2000"},{src:"https://www.exaltedfuneral.com/cdn/shop/files/land-of-eem-deluxe-box-set-box-set-5160976.jpg?v=1763753731&width=2000"},{src:"https://www.exaltedfuneral.com/cdn/shop/files/land-of-eem-deluxe-box-set-box-set-394591.jpg?v=1763753731&width=2000"},{src:"https://www.exaltedfuneral.com/cdn/shop/files/land-of-eem-core-rulebook-book-1056389.jpg"}],resources:[{type:"link",url:"https://landofeem.com/",fmt:"Web"},{type:"link",url:"https://landofeem.com/ttrpg-srd/",fmt:"Web"},{type:"quickstart",url:"https://www.exaltedfuneral.com/products/land-of-eem-quickstart",fmt:"PDF"},{type:"sheet",url:"https://landofeem.com/land-of-eem-rpg-character-sheets/",fmt:"Web"}],mechanics:[{icon:"compass"},{icon:"users"},{icon:"shield"},{icon:"book-open"}],quotes:[{text:"Whimsical fantasy RPG Land of Eem is like Lord of the Rings with Muppets, and it looks as great as that sounds.",author:"Matt Jarvis, Dicebreaker"},{text:"Land of Eem is great in the same way the best cartoons are: wrapping serious themes in a goofy bow that rewards curiosity and social connections.",author:"Rowan Zeoli, Polygon"}],ru:{tagShort:"Уютное иллюстрированное фэнтези",tagline:"«Властелин колец встречает Маппет-шоу» — мультяшное фэнтези с отвагой вместо хитов.",description:"Лёгкая ламповая RPG от Бена Косты и Джеймса Паркса (авторы графической новеллы «Rickety Stitch and the Gelatinous Goo»). Бросай 1d12 + навык, читай таблицу из пяти ступеней — от провала до критического успеха, всегда с «да, но» или «нет, и». Боя в привычном смысле нет: вместо HP — Отвага против Ужаса, бои выигрываются, когда враг сдаётся или сбегает. Идеально для смешанных компаний: дети, новички и ветераны за одним столом.",setting:"Мир Eem — пёстрая фэнтези-страна, где живут 16 видов народцев: гелевый куб, скелет-музыкант, черепахоподобный квортл, шрим, грибнецы, гоблины, гномы, мохнатые лоялчамы. Стартовый сеттинг — Mucklands: разорённое болотистое королевство с гексовой картой (1 гекс = 6 миль), сотнями локаций и квестов. Тон — детская книжка с картинками, в которой иногда становится по-настоящему страшно. Смесь высокого фэнтези Толкина, мультяшности «Времени приключений» и пыли постапокалипсиса.",vignette:"Скелет-бард, гоблин-проныра и квортл-рыцарь стоят перед мостом через болотную трясину. Из-под моста вылезает тролль и рычит. Бард не достаёт меч — он бросает Performance: 1d12 + 3. Выпадает 8 — это «Hit with Counterattack»: песня очаровывает тролля, но тот всё равно успевает рявкнуть. Тролль наносит 1 Ужас, бард теряет каплю Отваги. Следующий куплет — рыцарь подхватывает припев на Knowhow. 11 — почти крит. Тролль смущён, садится на камень и просит автограф.",prep:"~10 мин",mechanics:[{title:"1d12 + навык, пять ступеней",text:"Один кубик, пять степеней успеха: критический провал, провал-но, попадание-но, попадание-и, крит. Всегда есть, что описать — никаких пустых бросков."},{title:"Отвага против Ужаса",text:"Хитов нет. У вас Courage, у врагов Dread. Кто первым морально сломается — тот и проиграл стычку. Бои короткие и комичные."},{title:"Гексокроул Mucklands",text:"Готовая песочница: гексы по 6 миль, сотни локаций, NPC и квестов. Можно водить годами без своих заготовок."},{title:"Очки квеста и роли",text:"XP за исследование и отыгрыш, не за убийства. Quest Points тратятся на способности и буст бросков задним числом."}],gallery:[{cap:"Бокс-сет"},{cap:"Содержимое набора"},{cap:"Карта Mucklands"},{cap:"Корбук"}],resources:[{name:"Официальный сайт"},{name:"SRD"},{name:"Бесплатный Quickstart"},{name:"Листы персонажей"}],quotes:[{text:"Уютная фэнтези-RPG Land of Eem — это «Властелин колец», встретивший «Маппет-шоу», и выглядит она ровно настолько круто, как звучит."},{text:"Land of Eem прекрасна в том же смысле, что и лучшие мультфильмы: серьёзные темы заворачиваются в дурашливую обёртку, поощряющую любопытство и социальные связи."}]},en:{tagShort:"Cozy illustrated fantasy RPG",tagline:'"Lord of the Rings meets the Muppets" — comic-book fantasy with Courage instead of hit points.',description:"A lighthearted RPG by Ben Costa and James Parks (creators of the graphic novel 'Rickety Stitch and the Gelatinous Goo'). Roll 1d12 + skill, read a five-tier table — from critical fail to critical hit, always with a 'yes, but' or 'no, and.' Combat ditches HP for Courage vs Dread: fights end when one side breaks morale, not when bodies hit the floor. Built for mixed tables — kids, first-timers, and veterans on the same map.",setting:"Eem is a riotous fantasy world home to 16 playable folk: a gelatinous goo, a skeleton bard, a turtle-like quortle, shryms, mushrums, goblins, gnomes, the loyal chums. The default setting is The Mucklands: a ravaged swamp-kingdom on a hex map (1 hex = 6 miles) packed with hundreds of locations and quests. Tone is illustrated children's book that occasionally turns genuinely creepy — Tolkien high fantasy + Adventure Time whimsy + a dusting of Mad Max grime.",vignette:"A skeleton bard, a goblin rascal, and a quortle knight-errant stand at a bridge over a muck pit. A troll lumbers out and roars. The bard doesn't draw steel — they roll Performance: 1d12 + 3. An 8 lands as 'Hit with Counterattack': the song charms the troll but it gets a parting roar in. 1 Dread to the bard's Courage. The knight picks up the chorus on Knowhow — 11, just shy of a crit. The troll, embarrassed, sits down on a rock and asks for an autograph.",prep:"~10 min",mechanics:[{title:"1d12 + skill, five tiers",text:"One die, five outcomes: crit fail, fail-but, hit-with-counter, hit-and, crit. Every roll has narrative meat — no empty whiffs."},{title:"Courage vs Dread",text:"No hit points. You have Courage; foes have Dread. First side to break morale loses the scene. Fights stay short and funny."},{title:"Mucklands hexcrawl",text:"Sandbox out of the box: 6-mile hexes, hundreds of locations, NPCs, and quest hooks. Years of play without prepping a session."},{title:"Quest & roleplay XP",text:"XP for exploration and roleplay, not kills. Quest Points fuel abilities and let you nudge a roll after seeing the result."}],gallery:[{cap:"Deluxe box set"},{cap:"Box contents"},{cap:"Mucklands map"},{cap:"Core rulebook"}],resources:[{name:"Official site"},{name:"SRD"},{name:"Free Quickstart"},{name:"Character sheets"}]}}),registerSystem("last-tea-shop",{groups:{default:{key:"narrative",order:20},family:{key:"standalone",order:15},genre:{key:"narrative-weird",order:9},solo:{key:"solo-journaling",order:4}},name:"Last Tea Shop",publisher:"Spring Villager",dice:"1–2d6",players:"1",complexity:1,heroImage:"https://img.itch.zone/aW1nLzY4MzMyNTcuanBn/original/NOvzui.jpg",heroImageStyle:"object-fit: cover; object-position: center; background: linear-gradient(135deg, #0d1b2a, #1b3a4b 40%, #2d6a7f 70%, #0d1b2a);",playstyleTags:["narrative","mystery","social"],settingTags:["weird"],gallery:[{src:"https://img.itch.zone/aW1hZ2UvMTE2NzU4MC83NjkwNjc1LnBuZw==/347x500/KWkPXM.png"},{src:"https://img.itch.zone/aW1hZ2UvMTE2NzU4MC83Njg0MzA3LnBuZw==/347x500/fubDRC.png"},{src:"https://img.itch.zone/aW1hZ2UvMTE2NzU4MC83Njg0MzA1LnBuZw==/347x500/XSOA2A.png"}],resources:[{type:"link",url:"https://springvillager.itch.io/last-tea-shop",fmt:"Web"},{type:"link",url:"https://springvillager.itch.io/last-tea-shop-complete",fmt:"Web"}],mechanics:[{icon:"ghost"},{icon:"clock"},{icon:"heart"},{icon:"feather"}],quotes:[{text:"The settings, the ingredients, the recipes, the weather and the emotions, the variety of visitors, they pack a lot of flavor into a single page.",author:"Seamus Conneely, Cannibal Halfling Gaming"}],ru:{tagShort:"Соло-журнал у границы миров",tagline:"«Ты варишь чай. Они мертвы. У них остался последний час.»",description:"Last Tea Shop — камерная соло-дневниковая игра о чайной лавке на границе между миром живых и миром мёртвых. К тебе приходят недавно умершие — солдат, маяковщик, странница — каждый за последней чашкой перед долгим путём. Ты слушаешь. Ты завариваешь чай. Ты записываешь их истории. Классическая версия — одна страница, бесплатно навсегда. Полная редакция — 16-страничный зин с расширенными таблицами, новыми посетителями и иллюстрациями Stoneshore.",setting:"Пограничье — туманное место, где время тянется, как запах жасминового чая. Твоя лавка стоит там, где заканчиваются пути живых и начинается дорога в Земли Мёртвых. Сюда не приходят случайно. Каждый посетитель нашёл тебя, потому что ему или ей нужно поговорить. И когда придёт Завуалированная — последний гость — твоя история тоже подойдёт к концу.",vignette:"Бросок 2d6: одна кость — группа места, другая — конкретное место. Выпало «маяк». Посетитель: Смотритель маяка. Ты тянешь вопрос: «О чём ты жалеешь больше всего?» Он молчит долго. Потом говорит о свете, который гасили по ночам, и о кораблях, которых не было. Ты записываешь. Ты завариваешь ему чай с мятой и можжевельником. Он уходит в туман.",prep:"~5 мин",mechanics:[{title:"Посетители с двух путей",text:"Игрок выбирает: гости приходят по Тропе Костей (Dice Trail) или Тропе Фонаря (Lantern Path). Каждый путь ведёт разных странников. Некоторые переключают тропу — и следующий гость придёт иначе."},{title:"Сродство (Affinity)",text:"Перед игрой ты выбираешь или бросаешь кубик, чтобы определить Сродство — особое умение хозяина. Элементальное и физическое начала соединяются, давая тебе уникальный способ управлять разговором."},{title:"Ингредиенты чая",text:"Бросок d6 определяет локацию для сбора ингредиентов. Двойник — особая удача: ты собираешь два. Ингредиенты влияют на разговор и атмосферу записи."},{title:"Завуалированная",text:"Последний гость. Когда она появляется — игра заканчивается. Её приход непредсказуем. Её разговор — самый важный. Всё, что ты записал до этого, было ради этого момента."}],gallery:[{cap:"Обложка зина"},{cap:"Разворот — иллюстрация Stoneshore"},{cap:"Страница правил"}],resources:[{name:"Классическая версия (бесплатно)"},{name:"Полная редакция — зин (itch.io)"}],quotes:[{text:"Сеттинги, ингредиенты, рецепты, погода и эмоции, разнообразие посетителей — всё это вмещает уйму атмосферы в одну страницу."}]},en:{tagShort:"solo afterlife journal RPG",tagline:'"You brew tea. They are dead. They have one last hour."',description:"Last Tea Shop is an intimate solo journaling game about a tea stall on the border between the living and the dead. The recently departed find their way to you — a soldier, a lighthouse keeper, a wanderer — each one seeking a last cup before the long journey. You listen. You brew. You write down what they say. The classic version is one page and free forever. The complete edition is a 16-page zine with expanded tables, new visitor types, and illustrations by Stoneshore that are quiet and haunting in exactly the right way.",setting:"The borderlands are a misty place where time moves like steam from a clay pot. Your stall stands where the roads of the living end and the path into the Lands of the Dead begins. Nobody arrives by accident. Each visitor found you because they need to talk — about regret, love, an old promise, a light they forgot to leave on. And when the Veiled One finally comes, your own story draws to a close.",vignette:"Roll 2d6: one die for the location group, one for the specific place. Doubles: you gather two ingredients instead of choosing a spot. It came up lighthouse. Visitor: the Lighthouse Keeper. You draw a question: 'What do you regret most?' A long silence. Then he speaks about a light that was doused on certain nights, and ships that were never seen again. You write it down. You brew him tea with mint and juniper. He walks into the fog.",prep:"~5 min",mechanics:[{title:"Two paths, different dead",text:"Choose whether visitors arrive by the Dice Trail or the Lantern Path — each has its own collection of possible souls. Certain visitors are path-switchers: the next guest arrives from the opposite route, keeping the roster unpredictable."},{title:"Affinity",text:"Before play, choose or roll your Affinity — a special skill shaping how you guide conversation. It combines an elemental aspect with a physical one, giving your shopkeeper a distinct presence that quietly colours every exchange."},{title:"Tea ingredients",text:"A d6 roll determines where you forage for ingredients before a guest arrives. Roll doubles and you collect two. What you brew matters — ingredients influence the mood of the conversation and what your journal entry becomes."},{title:"The Veiled One",text:"The last guest. When she arrives, the game ends. Her coming is unannounced. Her conversation is the most important one. Everything you have written until now was preparation for this moment — and you will not know it was coming until she is already there."}],gallery:[{cap:"Zine cover"},{cap:"Interior — Stoneshore illustration"},{cap:"Rules page"}],resources:[{name:"Classic version (free)"},{name:"Complete edition — zine (itch.io)"}]}}),registerSystem("liminal-horror",{groups:{default:{key:"osr",order:28},family:{key:"into-the-odd",order:6},genre:{key:"horror",order:13},solo:{key:"solo-compatible",order:12.5}},name:"Liminal Horror",publisher:"Goblin Archives",dice:"d20 + d6 damage (Into the Odd-based)",players:"3–5",complexity:1,foundryStatus:"Community",free:!0,edition:null,heroImage:"https://img.itch.zone/aW1nLzE1NTgwMzU0LnBuZw==/original/Fiylam.png",playstyleTags:["horror","mystery","explore"],settingTags:["modern","weird"],gallery:[{src:"https://img.itch.zone/aW1hZ2UvMTA1MDI4NC8xNzcwNTQ3Ni5wbmc=/original/O7koxW.png"},{src:"https://img.itch.zone/aW1hZ2UvMTA1MDI4NC8xNzcwNTQ4Ny5wbmc=/original/ANpkT0.png"},{src:"https://img.itch.zone/aW1hZ2UvMTA1MDI4NC8xNzcwNTQ4OS5wbmc=/original/qlrF86.png"}],resources:[{type:"rules",url:"https://liminalhorrorrpg.com/",fmt:"Web"},{type:"rules",url:"https://goblinarchives.itch.io/liminal-horror",fmt:"PDF"},{type:"srd",url:"https://liminalhorrorrpg.com/srd/",fmt:"Web"}],mechanics:[{icon:"brain"},{icon:"skull"},{icon:"search"},{icon:"plug"}],quotes:[{text:"Liminal Horror is not a game where you can get out of trouble by flipping through the rulebook, the only way out is to look up and start talking to both your GM and the other people at your table.",author:"Moreau Vazh, Taskerland"}],ru:{tagShort:"лёгкий современный космический хоррор",tagline:"«Обычные люди против того, что таится в темноте».",description:"Лёгкая хоррор-игра на движке Into the Odd (через Cairn). Обычные люди расследуют ползучий космический ужас — и опасность не только в смерти, но и в распаде личности. По мере роста напряжения копится СТРЕСС, персонаж ломается и получает Fallout — сверхъестественные последствия, которые остаются с ним до конца истории.",setting:"Наши дни, отделённые от чего-то неправильного одной тонкой мембраной. Пустые парковки, лиминальные офисные коридоры, городки с гнилью под кожей. Никаких бестиариев для зубрёжки — ужас уникален, а из инструментов только любопытство, нервы и готовность говорить.",vignette:"Вы загоняете тварь в подвал. Броска на попадание нет — удар просто проходит, d6 урона, а когда Hit Protection кончается, кости вгрызаются в СИЛУ. Комнату вы пережили. Но проверка СТРЕССА провалена, срабатывает Critical Fallout — и теперь отражение отстаёт от вас на полсекунды. И идёт за вами домой.",prep:"~10 мин",mechanics:[{title:"СТРЕСС и Fallout",text:"Страх и напряжение копятся как СТРЕСС. Провал проверки — бросок по таблице Fallout: стойкие сверхъестественные эффекты, а не список психических расстройств. Разум уходит в странное."},{title:"Бой Into the Odd",text:"Никаких бросков на попадание. Атаки проходят автоматически на урон; выживание держится на Hit Protection и характеристиках. Драки быстры, смертельны и редко того стоят."},{title:"Решения важнее правил",text:"Около 35 страниц. Отговориться правилами нельзя — единственный выход из беды — поднять глаза от листа и заговорить со столом."},{title:"Бесплатно и открыто",text:"Бесплатные веб-правила, бесплатный PDF и SRD под CC BY-SA. Вокруг того же движка выросла целая экосистема сторонних модулей и хаков."}],gallery:[{cap:"Обложка корбука"},{cap:"Разворот"},{cap:"Разворот"}],resources:[{name:"Бесплатные веб-правила"},{name:"Бесплатный PDF (itch.io)"},{name:"SRD (CC BY-SA)"}],quotes:[{text:"Liminal Horror — не та игра, где можно выпутаться, листая книгу правил; единственный выход — поднять глаза и начать говорить с ведущим и остальными за столом."}]},en:{tagShort:"rules-light modern cosmic horror",tagline:'"Normal people against the things that go bump in the night."',description:"A rules-light modern horror game built on the Into the Odd engine (by way of Cairn). Ordinary characters investigate creeping, cosmic dread — and the danger isn't just dying, it's coming apart. As the pressure mounts, STRESS accumulates and characters break down, gaining supernatural Fallout that lingers on them for the rest of the story.",setting:"The modern day, one thin membrane away from something wrong. Empty parking garages, liminal office corridors, small towns with a rot underneath. There are no monster manuals to memorize — the horror is bespoke, and the only tools are curiosity, nerve, and a willingness to talk it through.",vignette:"You corner the thing in the basement. There is no attack roll — the strike simply lands, d6 damage, and once your Hit Protection is gone the dice bite into STRENGTH. You survive the room. But the STRESS check fails, Critical Fallout triggers, and now your reflection lags a half-second behind you. That follows you home.",prep:"~10 min",mechanics:[{title:"STRESS & Fallout",text:"Fear and strain build as STRESS. Fail a check and you roll on Fallout — lingering supernatural effects, not a mental-illness table. The mind frays into the weird."},{title:"Into the Odd combat",text:"No to-hit rolls. Attacks land automatically for damage; survival rides on Hit Protection and ability scores. Fights are fast, lethal, and rarely worth starting."},{title:"Rulings over rules",text:"About 35 pages. You can't lawyer your way out — the only exit from trouble is looking up from the sheet and talking to the table."},{title:"Free & open",text:"Free web rules, free PDF, and a CC BY-SA SRD. A whole ecosystem of third-party modules and hacks builds on the same engine."}],gallery:[{cap:"Core book cover"},{cap:"Interior spread"},{cap:"Interior spread"}],resources:[{name:"Free web rules"},{name:"Free PDF (itch.io)"},{name:"SRD (CC BY-SA)"}],quotes:[{text:"Liminal Horror is not a game where you can get out of trouble by flipping through the rulebook, the only way out is to look up and start talking to both your GM and the other people at your table."}]}}),registerSystem("lotfp",{groups:{default:{key:"osr",order:23},family:{key:"osr-classic",order:14},genre:{key:"horror",order:8}},name:"Lamentations of the Flame Princess",publisher:"Lamentations of the Flame Princess",dice:"d20 + B/X resolution",players:"3–6",complexity:2,edition:"B/X",free:!0,foundryStatus:"Community",heroImage:"https://us.lotfp.com/store/image/cache/catalog/CoverDisplay2-500x500.jpg",playstyleTags:["horror","explore","survival"],settingTags:["historical","weird"],gallery:[{src:"https://us.lotfp.com/store/image/cache/catalog/BroodmotherCoverDisplay-500x500.jpg"},{src:"https://us.lotfp.com/store/image/cache/catalog/AABloodCoverDisplay-500x500.jpg"},{src:"https://us.lotfp.com/store/image/cache/catalog/AAFCoverDisplay-500x500.jpg"}],resources:[{type:"link",url:"https://lotfp.com/store/",fmt:"Web"},{type:"quickstart",url:"https://archive.org/details/lot-fprules-magic-free-no-art",fmt:"PDF"}],mechanics:[{icon:"skull"},{icon:"dices"},{icon:"flame"},{icon:"gift"}],quotes:[{text:"if you're looking for OSR-rules, through a shade darkly, then this book will deliver in spades.",author:"Endzeitgeist, RPGnet"},{text:"You can complain about the aesthetics, they are a matter of taste; but I can't see any true faults with the rules presented herein.",author:"Endzeitgeist, RPGnet"}],ru:{tagShort:"Вирд-хоррор OSR в реальной Европе XVII века",tagline:"«Раннее Новое время, куда прорывается космический ужас».",description:"Lamentations of the Flame Princess — OSR-игра вирд-хоррора Джеймса Эдварда Рагги IV. Правила — производная от B/X D&D, но подача другая: мрачное, взрослое, часто шокирующее фэнтези ужасов. Магия здесь опасна и чужеродна, а сокровища — проклятия. Знаменита сильнейшими самостоятельными модулями и бескомпромиссным тоном.",setting:"Не выдуманный мир, а реальная Европа примерно XVII века — грязная, суеверная, жестокая — куда вторгается лавкрафтовский и хоуардовский космический ужас. Магия редка и извращает мир; сверхъестественное всегда чуждо и неправильно. Играбельно и как исторический хоррор, и как гримдарк-фэнтези с зубами.",vignette:"Специалист вскрывает замок древнего сундука — d6 против навыка, у профессионала шанс выше среднего. Успех. Внутри — не золото, а книга в переплёте из кожи. Маг распознаёт заклинание: оно работает, но цена в тексте написана мелким шрифтом. В LotFP находка сокровища — это чаще начало беды, чем награда.",prep:"~15 мин",mechanics:[{title:"Ядро B/X с навыками",text:"d20 на атаку, классы и уровни B/X, но со специалистом-вором и системой навыков на d6. Совместимо с олдскульными модулями, при этом чуть современнее в мелочах."},{title:"Опасная, чуждая магия",text:"Заклинания не «фаерболы по кнопке», а нечто неправильное и рискованное. Магия ломает реальность и часто героя вместе с ней — ровно тот вирд-тон, что задаёт вся игра."},{title:"Реальная историческая Европа",text:"Действие — в настоящем раннем Новом времени с датами и местами, куда прорывается космический ужас. Приземлённость истории делает сверхъестественное вдвойне жутким."},{title:"Бесплатная версия без арта",text:"Официальный «Rules & Magic» в версии без иллюстраций — бесплатный PDF (арт LotFP часто NSFW). Полные правила — с нулевым порогом входа."}],gallery:[{cap:"Broodmother SkyFortress"},{cap:"Adventure Anthology: Blood"},{cap:"Adventure Anthology: Fire"}],resources:[{name:"Официальный магазин — LotFP"},{name:"Бесплатная версия без арта (PDF)"}],quotes:[{text:"Если вы ищете OSR-правила с тёмным оттенком — эта книга выдаст их сполна."},{text:"Можно ворчать на эстетику — это дело вкуса; но никаких настоящих изъянов в изложенных правилах я не вижу."}]},en:{tagShort:"Weird-horror OSR in real 17th-century Europe",tagline:'"The early modern era, into which cosmic horror breaks through."',description:"Lamentations of the Flame Princess is James Edward Raggi IV's weird-horror OSR game. The rules are a B/X D&D derivative, but the presentation is different: dark, adult, often shocking horror fantasy. Magic here is dangerous and alien, and treasure is a curse. Famous for its outstanding standalone modules and uncompromising tone.",setting:"Not an invented world but a real, roughly 17th-century Europe — filthy, superstitious, brutal — into which Lovecraftian and Howardian cosmic horror intrudes. Magic is rare and warps the world; the supernatural is always alien and wrong. It plays as historical horror or as grimdark fantasy with teeth.",vignette:"The Specialist picks the lock on an ancient chest — d6 against a skill, better than even odds for a pro. Success. Inside isn't gold but a book bound in skin. The magic-user identifies the spell: it works, but the price is written in the fine print. In LotFP, finding treasure is more often the start of trouble than a reward.",prep:"~15 min",mechanics:[{title:"B/X core with skills",text:"d20 to hit, B/X classes and levels, but with a Specialist (thief) and a d6 skill system. Compatible with old-school modules while a touch more modern in the details."},{title:"Dangerous, alien magic",text:"Spells aren't push-button fireballs but something wrong and risky. Magic breaks reality, and often the caster with it — exactly the weird tone the whole game sets."},{title:"A real historical Europe",text:"Set in an actual early-modern era with dates and places, into which cosmic horror erupts. The grounded history makes the supernatural doubly unsettling."},{title:"Free no-art version",text:"The official 'Rules & Magic' in a no-illustrations version is a free PDF (LotFP art is often NSFW). The full rules with a zero-cost on-ramp."}],gallery:[{cap:"Broodmother SkyFortress"},{cap:"Adventure Anthology: Blood"},{cap:"Adventure Anthology: Fire"}],resources:[{name:"Official store — LotFP"},{name:"Free no-art version (PDF)"}]}}),registerSystem("mage-the-ascension",{groups:{default:{key:"narrative",order:32},family:{key:"standalone",order:40},genre:{key:"horror",order:9}},name:"Mage: The Ascension",publisher:"Onyx Path Publishing / White Wolf",dice:"d10 dice pool (Storyteller System)",players:"3–5",complexity:3,foundryStatus:"Community",heroImage:"https://image.nobleknight.com/m/jpg1500/mta20thpremium.jpg",playstyleTags:["narrative","social","horror"],settingTags:["modern","urban-fantasy"],gallery:[{src:"https://image.nobleknight.com/m/jpg1500/mta20thpremium1.jpg"},{src:"https://image.nobleknight.com/m/jpg1500/magequickstart20th.jpg"},{src:"https://image.nobleknight.com/m/jpg1500/m20dqe.jpg"}],resources:[{type:"link",url:"https://theonyxpath.com/mage-the-ascension-20th-anniversary-edition/",fmt:"Web"}],mechanics:[{icon:"dices"},{icon:"sparkles"},{icon:"triangle-alert"},{icon:"eye"}],quotes:[{text:"It's an absolutely terrific premise and one that works well within a modern-day setting.",author:"James Maliszewski, Grognardia"},{text:"The Technocracy is both a terrific adversary and brilliant bit of worldbuilding.",author:"James Maliszewski, Grognardia"}],ru:{tagShort:"Тайная война магов за саму природу реальности",tagline:"«Реальность — это то, во что верит большинство. Маги знают, как её переписать».",description:"Mage: The Ascension — классика Мира Тьмы о просветлённых магах (Willworkers), ведущих тайную войну за то, каким будет реальность. Магия здесь — не заклинания из книжки, а сила воли и парадигмы: ты меняешь мир, потому что знаешь, что он может быть иным. Технократия против мистических Традиций, наука против веры. Философский, амбициозный оккультный хоррор.",setting:"Современный мир, где реальность держится на «консенсусе» — общей вере масс. Маги пробудились и видят: правила можно переписать. Технократия куёт мир порядка, науки и контроля; девять Традиций хранят мистику и чудо. Между ними — Война Вознесения за душу человечества. Оккультизм, паранойя и большие идеи.",vignette:"Маг Культа Экстаза хочет исцелить умирающего одной волей. Это «вульгарная» магия — она противоречит тому, что видят обычные свидетели. Он собирает пул: Arete + Сфера Жизни, бросок d10, успехи против сложности. Рана затягивается на глазах медсестры — и реальность мстит. Ведущий начисляет Парадокс: где-то рядом уже сгущается кара за нарушение законов мира.",prep:"~30 мин",mechanics:[{title:"Storyteller System (d10)",text:"Действие — пул d10 из Атрибута и Способности. Каждый кубик выше сложности — успех. Классическая механика Мира Тьмы: быстро, драматично, с местом для нарратива."},{title:"Девять Сфер магии",text:"Магия разбита на девять Сфер (Силы, Жизнь, Разум, Время, Дух…). Точки в Сферах определяют, как далеко ты можешь изменить реальность. Не список заклинаний, а свободное творчество воли."},{title:"Парадокс",text:"Твори «вульгарную» магию на глазах непосвящённых — и реальность бьёт в ответ Парадоксом: от неудач до катастроф и «парадоксных духов». Чудо всегда имеет цену."},{title:"Технократия против Традиций",text:"Сеттинг — тайная Война Вознесения за то, во что будет верить человечество. Наука и контроль против мистики и чуда. Убеждения буквально формируют мир — идейный конфликт вшит в правила."}],gallery:[{cap:"M20 Core (арт)"},{cap:"M20 Quickstart"},{cap:"Deluxe Edition"}],resources:[{name:"Официальная страница — Onyx Path"}],quotes:[{text:"Это совершенно потрясающая посылка, и она отлично работает в современном сеттинге."},{text:"Технократия — и великолепный противник, и блестящий образец мироустройства."}]},en:{tagShort:"A secret war of mages over the nature of reality",tagline:'"Reality is what the majority believes. Mages know how to rewrite it."',description:"Mage: The Ascension is the World of Darkness classic about enlightened mages (Willworkers) waging a secret war over what reality will be. Magic here isn't spells from a book but willpower and paradigm: you change the world because you know it could be otherwise. The Technocracy against the mystic Traditions, science against faith. Philosophical, ambitious occult horror.",setting:"A modern world where reality rests on 'consensus' — the shared belief of the masses. Mages have Awakened and see that the rules can be rewritten. The Technocracy forges a world of order, science, and control; the nine Traditions guard mysticism and wonder. Between them, the Ascension War for the soul of humanity. Occultism, paranoia, and big ideas.",vignette:"A Cult of Ecstasy mage wants to heal a dying man by will alone. That's 'vulgar' magic — it defies what ordinary witnesses see. He gathers a pool: Arete + the Life Sphere, rolls d10s, successes against a difficulty. The wound knits shut before the nurse's eyes — and reality retaliates. The GM assigns Paradox: somewhere nearby, punishment for breaking the world's laws is already gathering.",prep:"~30 min",mechanics:[{title:"Storyteller System (d10)",text:"An action is a d10 pool from an Attribute and an Ability. Each die over the difficulty is a success. The classic World of Darkness mechanic: fast, dramatic, with room for narrative."},{title:"The nine Spheres of magic",text:"Magic is split into nine Spheres (Forces, Life, Mind, Time, Spirit…). Your dots in each set how far you can reshape reality. Not a spell list but the free creativity of will."},{title:"Paradox",text:"Work 'vulgar' magic in front of the uninitiated and reality strikes back with Paradox: from botches to catastrophes and 'Paradox spirits.' A miracle always has a price."},{title:"Technocracy vs Traditions",text:"The setting is a secret Ascension War over what humanity will believe. Science and control against mysticism and wonder. Belief literally shapes the world — an ideological conflict built into the rules."}],gallery:[{cap:"M20 Core (art)"},{cap:"M20 Quickstart"},{cap:"Deluxe Edition"}],resources:[{name:"Official page — Onyx Path"}]}}),registerSystem("marvel-multiverse",{groups:{default:{key:"tactical",order:14},family:{key:"standalone",order:36.5},genre:{key:"tactical",order:10}},name:"Marvel Multiverse RPG",publisher:"Marvel",dice:"d616 (3d6)",players:"3–5",complexity:2,free:!0,foundryStatus:"Community",heroImage:"https://images2.penguinrandomhouse.com/cover/9781302927837",playstyleTags:["combat","narrative","explore"],settingTags:["modern"],gallery:[{src:"https://images-na.ssl-images-amazon.com/images/P/1302927833.01._SCLZZZZZZZ_SX300_.jpg"},{src:"https://static0.cbrimages.com/wordpress/wp-content/uploads/2023/08/marvel-multiverse-rpg.jpg"},{src:"https://images2.penguinrandomhouse.com/cover/9781302927837"}],resources:[{type:"link",url:"https://www.marvel.com/rpg",fmt:"Web"},{type:"quickstart",url:"https://www.marvel.com/rpg",fmt:"Web"},{type:"link",url:"https://www.demiplane.com/nexus/marvel-multiverse",fmt:"Web"}],mechanics:[{icon:"swords"},{icon:"dices"},{icon:"book-open"},{icon:"scroll"}],quotes:[{text:"Marvel Multiverse Role-Playing Game is an excellent choice for fans of Marvel comics who want to try out an RPG or Dungeons & Dragons fans who want to move onto a system that's different while still having familiar elements.",author:"Rob Wieland, Forbes"},{text:"The system is easy, streamlined, and really carries the four-color comic book flavor — this is a must-have book that will bring hours of enjoyment.",author:"Polygon"}],ru:{tagShort:"Марвел на d616 — супергерои комиксов",tagline:"«Жми 6-1-6 для Ultimate Fantastic Roll. Добро пожаловать в Мультивселенную».",description:"Marvel Multiverse RPG — настольная RPG от Marvel (2023), действие в Мультивселенной Marvel (Earth-616). Система d616: бросок 3d6 (один — Marvel Die) + Способность vs сложность. Выпадение 6-1-6 = Ultimate Fantastic Roll (авто-успех). 128 страниц профилей персонажей (Железный Человек, Человек-паук, Мстители, Люди Икс). Бесплатный квикстарт на marvel.com/rpg.",setting:"Вселенная Marvel — Earth-616 и шире. Мстители, Люди Икс, Стражи Галактики, Космическая Спираль — всё в одном каталоге. Каждый расширение (X-Men, Spider-Verse, Avengers) добавляет локации и персонажей.",vignette:"Железный Человек бросает 3d6 (Marvel Die — красный): 4+1+6 = 11 + Intelligence 5 = 16. Против Difficulty 14. Успех на 2! repulsor blast бьёт в банду. Но 6-1-6? Нет — просто 6 и 1. Добро пожаловать в Мультивселенную, где даже удача — это суперсила.",prep:"~15 мин",mechanics:[{title:"d616 System",text:"Бросок 3d6 (Marvel Die — особый) + Способность vs сложность. 6-1-6 = Ultimate Fantastic Roll (авто-успех). Простая, но драматичная математика."},{title:"Marvel Die",text:"Один кубик — Marvel Die (обычно красный). Определяет урон и особые эффекты. Делает каждый бросок визуально ярким."},{title:"128 персонажей",text:"Готовые профили: Железный Человек, Человек-паук, Капитан Америка, Росомаха, Доктор Стрэндж и десятки других. Каждый — уникальные способности."},{title:"Ранги (1–6)",text:"Шесть рангов: от Street Level до Cosmic. Каждый ранг — новый уровень силы и возможностей."}],gallery:[{cap:"Core Rulebook (Amazon)"},{cap:"Обзор (CBR)"},{cap:"Core Rulebook (PRH)"}],resources:[{name:"Официальный сайт — marvel.com/rpg"},{name:"Бесплатный квикстарт (Thunderbolts)"},{name:"Demiplane — цифровой инструментарий"}],quotes:[{text:"Marvel Multiverse Role-Playing Game — отличный выбор для фанатов комиксов Marvel, которые хотят попробовать RPG, или фанатов D&D, которые хотят перейти на систему с знакомыми элементами."},{text:"Система простая, удобная и передаёт дух четырёхцветных комиксов — этоmust-have книга, которая подарит часы удовольствия."}]},en:{tagShort:"Marvel d616 — comic book superheroes",tagline:'"Roll 6-1-6 for the Ultimate Fantastic Roll. Welcome to the Multiverse."',description:"Marvel Multiverse RPG is a tabletop RPG from Marvel (2023), set in the Marvel Multiverse (Earth-616). d616 system: roll 3d6 (one is the Marvel Die) + Ability vs difficulty. Rolling 6-1-6 = Ultimate Fantastic Roll (auto-succeed). 128 pages of character profiles (Iron Man, Spider-Man, Avengers, X-Men). Free quickstart at marvel.com/rpg.",setting:"The Marvel Universe — Earth-616 and beyond. Avengers, X-Men, Guardians of the Galaxy, the Cosmic Spiral — all in one catalog. Each expansion (X-Men, Spider-Verse, Avengers) adds locations and characters.",vignette:"Iron Man rolls 3d6 (Marvel Die — red): 4+1+6 = 11 + Intelligence 5 = 16. Against Difficulty 14. Success by 2! A repulsor blast tears through the gang. But 6-1-6? No — just a 6 and a 1. Welcome to the Multiverse, where even luck is a superpower.",prep:"~15 min",mechanics:[{title:"d616 System",text:"Roll 3d6 (Marvel Die — special) + Ability vs difficulty. 6-1-6 = Ultimate Fantastic Roll (auto-succeed). Simple but dramatic math."},{title:"Marvel Die",text:"One die is the Marvel Die (usually red). Determines damage and special effects. Makes every roll visually striking."},{title:"128 Characters",text:"Ready-made profiles: Iron Man, Spider-Man, Captain America, Wolverine, Doctor Strange, and dozens more. Each with unique powers."},{title:"Ranks (1–6)",text:"Six ranks: Street Level to Cosmic. Each rank brings new power levels and capabilities."}],gallery:[{cap:"Core Rulebook (Amazon)"},{cap:"Review art (CBR)"},{cap:"Core Rulebook (PRH)"}],resources:[{name:"Official site — marvel.com/rpg"},{name:"Free quickstart (Thunderbolts)"},{name:"Demiplane — digital toolset"}],quotes:[{text:"Marvel Multiverse Role-Playing Game is an excellent choice for fans of Marvel comics who want to try out an RPG or Dungeons & Dragons fans who want to move onto a system that's different while still having familiar elements."},{text:"The system is easy, streamlined, and really carries the four-color comic book flavor — this is a must-have book that will bring hours of enjoyment."}]}}),registerSystem("masks",{groups:{default:{key:"narrative",order:34},family:{key:"pbta-fitd",order:28},genre:{key:"adventure",order:24}},name:"Masks: A New Generation",publisher:"Magpie Games",dice:"2d6 + stat (PbtA)",players:"3–5",complexity:2,foundryStatus:"Community",heroImage:"https://magpiegames.com/cdn/shop/files/Masks-Core-softcover_1.jpg?v=1734448458",playstyleTags:["narrative","social","combat"],settingTags:["modern"],gallery:[{src:"https://magpiegames.com/cdn/shop/files/Masks-Core-softcover_2.jpg?v=1734448458"},{src:"https://magpiegames.com/cdn/shop/files/Masks-Core-softcover_3.jpg?v=1734448581"},{src:"https://magpiegames.com/cdn/shop/files/Masks-Core-softcover_4.jpg?v=1734448581"}],resources:[{type:"link",url:"https://magpiegames.com/collections/masks",fmt:"Web"}],mechanics:[{icon:"dices"},{icon:"drama"},{icon:"users"},{icon:"venetian-mask"}],quotes:[{text:"It's a really fun way of looking at characters as people rather than mere skill sets.",author:"Maddie Cullen, Dicebreaker"}],ru:{tagShort:"PbtA о юных супергероях и поиске себя",tagline:"«Ты — не тот, кем тебя считают. Или всё-таки тот?».",description:"Masks: A New Generation — ролевая игра на движке Powered by the Apocalypse о команде юных супергероев. Спасать город — половина дела; вторая половина — понять, кто ты, когда все вокруг твердят, кем тебе быть. Игра не про билды и урон, а про эмоции, идентичность и взросление под масками.",setting:"Халсион-Сити — мегаполис, трижды отстроенный поколениями героев. Молодые супергерои бьются со злодеями и спасают жизни, но настоящая борьба — внутри: ожидания менторов, давление кумиров, страх не оправдать. Яркий, четырёхцветный комикс-мир, где взрослеть тяжелее, чем драться.",vignette:"Наставник отчитывает вашу героиню перед всей командой: «Ты снова полезла на рожон». Он давит своим Влиянием — и сдвигает ваши Ярлыки: Savior растёт, Freak падает. Вы бросаете «Прямой отпор»: 2d6 + Danger. Выпало 9 — успех с ценой. Вы отбиваетесь, но в глазах команды становитесь чуть более безрассудной. Кем вы себя считаете — меняется на ходу.",prep:"~10 мин",mechanics:[{title:"Ходы на 2d6 (PbtA)",text:"Действие запускает «ход»: 2d6 + характеристика. 10+ — успех, 7–9 — с осложнением, 6 и ниже — провал и ход ведущего. Правила лёгкие, вся драма — в фикшене."},{title:"Ярлыки вместо статов",text:"Пять эмоциональных Ярлыков: Danger, Freak, Savior, Superior, Mundane. Они не фиксированы — сдвигаются по ходу игры. Механика буквально отражает, как меняется самоощущение подростка."},{title:"Влияние",text:"Другие — злодеи, товарищи, взрослые — держат над героем Влияние и могут двигать его Ярлыки, хвалить и ранить. Отобрать Влияние или поддаться ему — ключевой выбор о том, чьё мнение о тебе важно."},{title:"Плейбуки-архетипы",text:"The Bull, The Nova, The Doomed, The Legacy и другие — архетипы по классике супергероики. Каждый задаёт свою драму взросления и свои ходы, а не только набор сил."}],gallery:[{cap:"Обложка (варианты)"},{cap:"Разворот"},{cap:"Интерьер"}],resources:[{name:"Официальная страница — Magpie Games"}],quotes:[{text:"Это по-настоящему увлекательный взгляд на персонажей как на людей, а не просто наборы навыков."}]},en:{tagShort:"PbtA about teen superheroes finding themselves",tagline:`"You're not who they think you are. Or are you?"`,description:"Masks: A New Generation is a Powered by the Apocalypse RPG about a team of young superheroes. Saving the city is half the job; the other half is figuring out who you are when everyone around you keeps telling you who to be. This isn't a game about builds and damage — it's about emotion, identity, and coming of age behind the mask.",setting:"Halcyon City — a metropolis rebuilt three times over by generations of heroes. Young supers fight villains and save lives, but the real struggle is inside: mentors' expectations, idols' pressure, the fear of falling short. A bright, four-color comic-book world where growing up is harder than the fight.",vignette:"A mentor dresses your hero down in front of the whole team: 'You charged in again.' He leans on his Influence — and shifts your Labels: Savior up, Freak down. You roll 'Directly Engage': 2d6 + Danger. A 9 — success at a cost. You win the fight, but in the team's eyes you become a little more reckless. Who you think you are is changing in real time.",prep:"~10 min",mechanics:[{title:"2d6 moves (PbtA)",text:"An action triggers a 'move': 2d6 + stat. 10+ is a hit, 7–9 comes with a complication, 6 or under fails and hands the GM a move. The rules are light; all the drama lives in the fiction."},{title:"Labels instead of stats",text:"Five emotional Labels: Danger, Freak, Savior, Superior, Mundane. They aren't fixed — they shift during play. The mechanic literally models how a teen's self-image changes."},{title:"Influence",text:"Others — villains, teammates, adults — hold Influence over a hero and can shift their Labels, praise and wound them. Taking back Influence or giving in is the key choice about whose opinion of you matters."},{title:"Archetype playbooks",text:"The Bull, The Nova, The Doomed, The Legacy, and more — archetypes drawn from superhero canon. Each frames a coming-of-age drama and its own moves, not just a power set."}],gallery:[{cap:"Cover (variants)"},{cap:"Spread"},{cap:"Interior"}],resources:[{name:"Official page — Magpie Games"}]}}),registerSystem("mausritter",{groups:{default:{key:"osr",order:9},family:{key:"into-the-odd",order:5},genre:{key:"adventure",order:6}},name:"Mausritter",publisher:"Losing Games / Isaac Williams",dice:"d20 + d6",players:"2–5",complexity:1,free:!0,foundryStatus:"Community",heroImage:"https://preview.redd.it/about-mausritter-v0-9ddnjzceq2gf1.png?width=820&format=png&auto=webp&s=4720e331d3fc15268eadfcf8aa1a42a16b917bef",playstyleTags:["explore","survival","sandbox"],settingTags:["fantasy"],gallery:[{src:"https://img.itch.zone/aW1nLzQ1Nzc4OTYucG5n/original/Dnexgj.png"}],quotes:[{text:"Mausritter offers players a very simple, slick, and classic RPG experience in a teensy, squeaky package.",author:"Gab Hernandez, Wargamer"}],resources:[{type:"link",url:"https://mausritter.com/",fmt:"Web"},{type:"quickstart",url:"https://mausritter.com/srd/",fmt:"Web"},{type:"sheet",url:"https://mausritter.com/assets/static/mausritter-character-sheets.DRBL-AQl.pdf",fmt:"PDF"}],mechanics:[{icon:"zap"},{icon:"package"},{icon:"gem"},{icon:"map"}],ru:{tagShort:"OSR-приключения мышат",tagline:"«Храбрая маленькая мышь. Мир огромен, жесток и полон чудес.»",description:"Mausritter — OSR-игра о приключениях мышей на движке Into the Odd. Правила на двух страницах, персонаж за три минуты — и при этом одна из самых атмосферных игр в жанре.",setting:"Нет фиксированной карты — только инструментарий: руины людских строений, мышиные деревушки, соборные стропила с совами-чародеями, садовые стены с котами-тиранами. Капля дождя — опасность, спичечный коробок — комната.",vignette:"Три мыши у входа в жестяную банку. Внутри — синее свечение. Фенник проверяет инвентарь: терновый меч в левой лапе, фонарь мерцает. Мира достаёт камень заклинания. «Падение пёрышком — поможет?» Никто не знает. Они входят.",prep:"~10 мин",mechanics:[{title:"Удар всегда попадает",text:"Атаки не промахиваются — только урон. Бой стремителен и смертоносен."},{title:"Инвентарь как игра",text:"Предметы — карточки в ячейках. Состояния «Голоден» или «Истощён» тоже занимают место."},{title:"Камни заклинаний",text:"Магия в виде найденных камней. Мощные, одноразовые, тяжёлые."},{title:"Инструментарий гекс-кравла",text:"Процедурные таблицы для создания живого мира за минуты."}],gallery:[{cap:"Обложка"}],resources:[{name:"Официальный сайт"},{name:"Правила бесплатно (SRD)"},{name:"Лист персонажа"}],quotes:[{text:"Mausritter предлагает игрокам очень простой, гладкий и классический RPG-опыт в крошечной пищащей упаковке."}]},en:{tagShort:"OSR mouse adventure RPG",tagline:'"Brave little mouse. The world is vast and cruel and full of wonder."',description:"Mausritter is a sword-and-whiskers OSR adventure game built on the engine of Into the Odd. You play mice — small, fragile, clever — navigating a world that is ancient, indifferent, and enormous. Rules fit on two pages; character creation takes three minutes; and somehow, none of that stops it from being one of the most imaginative games in the genre.",setting:"There is no fixed map, only a toolbox: hex-crawl wilderness, crumbling human ruins, underground mouse settlements, cathedral rafters haunted by owl-sorcerers, and garden walls patrolled by cat-tyrants. The scale is everything — a single raindrop is a hazard, a matchbox is a room, a boot is a dungeon.",vignette:"Three mice crouch at the entrance of a tin can half-buried in mud. Inside — a faint blue glow. Fennick checks his inventory: a thorn-sword slotted into his left paw, a lantern guttering low. Mira draws the spell stone from her pack. 'Feather Fall — good in there or useless?' Nobody knows. She palms it anyway. They go in.",prep:"~10 min",mechanics:[{title:"Always Hit",text:"Attacks never miss — you only roll damage. Combat is brutally fast and terrifyingly decisive. Run, trick, or win: you choose."},{title:"Inventory as Play",text:"Items are physical cards slotted into a grid. Conditions like Hungry or Exhausted take up space. Encumbrance is a real tactical problem, not a bookkeeping chore."},{title:"Spell Stones",text:"Magic comes in the form of found stones engraved with spells. They're powerful, single-use, and heavy. The decision to burn one is always dramatic."},{title:"Hexcrawl Toolkit",text:"Procedural tables for terrain, settlements, factions, and encounter sites let a GM build a living, dangerous wilderness in minutes."}],gallery:[{cap:"Mausritter cover"}],resources:[{name:"Official website"},{name:"Free rules (SRD)"},{name:"Character sheet"}]}}),registerSystem("microscope",{groups:{default:{key:"narrative",order:9},family:{key:"standalone",order:5},genre:{key:"narrative-weird",order:6}},name:"Microscope",publisher:"Ben Robbins / Lame Mage",dice:"Не нужны",players:"2–5",complexity:1,foundryStatus:"Не нужен",heroImage:"https://img.itch.zone/aW1nLzgzOTE4NjkucG5n/original/hf%2BAZJ.png",heroImageStyle:"object-fit: contain; padding: 80px 120px; background: linear-gradient(135deg, #0f0e2e, #1e1b4b 40%, #312e81 70%, #1a1747);",playstyleTags:["worldbuild","narrative","social"],gallery:[{src:"https://www.indiepressrevolution.com/xcart/image.php?type=P&id=17540"},{src:"https://www.indiepressrevolution.com/xcart/image.php?type=P&id=19891"},{src:"https://cf.geekdo-images.com/C1ox8bAodvWDJqhqAk0w-Q__itemrep/img/XgQ1Act3YETvDkEtU1j27cyIoKQ=/fit-in/246x300/filters:strip_icc()/pic931050.jpg"}],resources:[{type:"link",url:"https://lamemage.com/microscope/",fmt:"Web"}],mechanics:[{icon:"history"},{icon:"ban"},{icon:"shuffle"},{icon:"lightbulb"}],quotes:[{text:"If you're a writer or a frequent game master for RPGs, I think it deserves a place in your library.",author:"Matthew J. Constantine, matthewjconstantine.com"},{text:"Microscope is one of my favorite collaborative storytelling games.",author:"Kathy L. Brown, kathylbrown.com"}],ru:{tagShort:"GMless игра-история без кубиков",tagline:"«Создайте историю целой цивилизации за один вечер».",description:"Не RPG в привычном смысле. Это инструмент для совместного создания истории. Без ведущего, без кубиков. Игроки создают эпохи, события внутри эпох и сцены внутри событий — в любом порядке. Масштаб: от тысячелетий до одного разговора. Идеально как Session Zero для любой кампании.",setting:"Любой! Вы создаёте его сами. Хотите — история галактической империи от рождения до краха. Хотите — история одной семьи через 500 лет. Хотите — история магии от открытия до запрета. Ограничение — только воображение.",vignette:"Кубиков нет. Мастера нет. Антон создаёт Эпоху: «Восстание машин.» Маша добавляет Событие внутри неё: «Последний человеческий город сдаётся.» Но потом Дима ставит Событие ДО этого: «Люди и машины подписывают мирный договор.» Значит, договор был нарушен? Кем? Маша создаёт Сцену, чтобы ответить на этот вопрос.",prep:"0 мин",mechanics:[{title:"Фрактальная история",text:"Эпохи → События → Сцены. Зум от тысячелетий до одного диалога. Бесконечная глубина."},{title:"Без ведущего",text:"Все равны. Каждый раунд кто-то задаёт фокус. Все строят историю вокруг него."},{title:"Нелинейность",text:"Сначала финал, потом причина. Любой момент в любом порядке. Переворачивает восприятие нарратива."},{title:"Session Zero",text:"Идеально для создания мира перед кампанией. Создайте вселенную вместе, потом играйте в ней."}],gallery:[{cap:"Разворот книги"},{cap:"Страница правил"},{cap:"Пример игры"}],resources:[{name:"Официальный сайт"}],quotes:[{text:"Если вы писатель или часто водите RPG, ей точно место на вашей полке."},{text:"Microscope — одна из моих любимых игр про совместное сочинительство."}]},en:{tagShort:"GMless history-building game",tagline:'"Create the history of an entire civilization in a single evening."',description:"Not an RPG in the traditional sense. It's a collaborative history-building tool. No GM, no dice. Players create eras, events within eras, and scenes within events — in any order. Scale: from millennia to a single conversation. Perfect as a Session Zero for any campaign.",setting:"Any! You create it yourselves. Want the history of a galactic empire from birth to collapse? A family's story across 500 years? The history of magic from discovery to prohibition? The only limit is imagination.",vignette:"No dice. No GM. Anton creates an Era: 'The Machine Uprising.' Masha adds an Event within it: 'The last human city surrenders.' But then Dima places an Event BEFORE that: 'Humans and machines sign a peace treaty.' So the treaty was broken? By whom? Masha creates a Scene to answer that question.",prep:"0 min",mechanics:[{title:"Fractal history",text:"Eras, Events, Scenes. Zoom from millennia to a single conversation. Infinite depth."},{title:"No GM",text:"Everyone is equal. Each round someone sets the focus. Everyone builds the story around it."},{title:"Non-linearity",text:"The ending first, then the cause. Any moment in any order. Turns narrative perception inside out."},{title:"Session Zero",text:"Perfect for building a world before a campaign. Create the universe together, then play in it."}],gallery:[{cap:"Book spread"},{cap:"Rules page"},{cap:"Play example"}],resources:[{name:"Official website"}]}}),registerSystem("monsterhearts",{groups:{default:{key:"narrative",order:45},family:{key:"pbta-fitd",order:31},genre:{key:"horror",order:15}},name:"Monsterhearts 2",publisher:"Buried Without Ceremony",dice:"2d6 + stat (PbtA)",players:"3–5",complexity:2,free:!1,edition:"Second Edition",foundryStatus:"Community",heroImage:"https://buriedwithoutceremony.com/wp-content/uploads/2019/11/Monsterhearts-Cover-Characters-scaled.jpg",playstyleTags:["narrative","social","horror"],settingTags:["urban-fantasy","modern"],gallery:[{src:"https://image.nobleknight.com/m/jpg1500/monasteryheartilytoorealllllll.jpg"},{src:"https://cdn.shopify.com/s/files/1/0271/4022/7143/files/Monsterhearts_Print.png?v=1748123322"},{src:"https://cdn.shopify.com/s/files/1/0271/4022/7143/files/Monsterhearts_PDF.png?v=1748123228"}],resources:[{type:"link",url:"https://buriedwithoutceremony.com/monsterhearts",fmt:"Web"},{type:"link",url:"https://buriedwithoutceremony.itch.io/monsterhearts-2",fmt:"Itch.io"},{type:"link",url:"https://store.buriedwithoutceremony.com/products/monsterhearts-2",fmt:"Print/PDF"},{type:"link",url:"https://foundryvtt.com/packages/monsterhearts",fmt:"VTT"}],mechanics:[{icon:"dices"},{icon:"link"},{icon:"heart"},{icon:"venetian-mask"}],quotes:[{text:"All told, Monsterhearts 2 is a real credit to designer/author Avery Alder.",author:"Strange Assembly"},{text:"It's very nicely done. Alder's art is atmospheric, reminiscent (to my untrained eye) of Tim Bradstreet.",author:"James Davis Nicoll"}],ru:{tagShort:"PbtA о неуклюжих подростках-монстрах и квир-драме",tagline:"«Порок живёт в твоём сердце, голод течёт по венам».",description:"Monsterhearts 2 — ролевая игра на движке Powered by the Apocalypse о неуклюжей и опасной жизни подростков-монстров. Вампиры, оборотни, ведьмы и призраки ходят в обычную старшую школу, скрывая чудовищную природу за подростковой драмой. Игра о желании, власти, взрослении и квир-идентичности: тело меняется без твоего согласия, а настоящий хоррор рождается не из монстров, а из отношений между ними.",setting:"Захолустный американский городок и его старшая школа. Днём — уроки, вечеринки, сплетни и разбитые сердца; под этим — голод, порок и тайные силы. Здесь монструозность и половое созревание неотличимы: каждый герой скрывает опасную природу, и любой всплеск чувств может обернуться катастрофой.",vignette:"Ты зажимаешь квотербека у его шкафчика и пускаешь в ход обаяние — ход «Соблазнить», 2d6 + Жар. На кубиках выпадает 8, это результат 7–9. Он смущён и увлечён, но открылась именно ты — так что он получает Ниточку на тебя. Теперь он может дёрнуть за неё в любой момент. Ты добилась своего; расплата придёт позже.",prep:"~15 мин",mechanics:[{title:"Ходы на 2d6 (PbtA)",text:"Любое рискованное действие запускает ход: 2d6 + характеристика (Жар, Холод, Пыл или Тьма). 10+ — успех, 7–9 — успех с ценой, 6 и ниже — провал и жёсткий ход Мастера Церемоний."},{title:"Ниточки",text:"Ниточки (Strings) — социальная валюта игры: эмоциональная власть над другим. Потрать её ради +1, чтобы навредить или вынудить к выбору. В итоге все опутаны ниточками всех."},{title:"Ход на секс",text:"У каждого Обличья свой уникальный Ход на секс — он срабатывает только после близости по обоюдному согласию со значимым персонажем, превращая самые уязвимые сцены в конкретные механические последствия."},{title:"Обличья и Тёмное «я»",text:"Играй за Вампира, Оборотня, Призрака, Фейри, Ведьму и других. У каждого Обличья свои ходы и Тёмное «я» — чудовищный срыв, в который герой проваливается, когда всё идёт не так."}],gallery:[{cap:"Обложка"},{cap:"Книга в мягкой обложке"},{cap:"Задняя обложка и завязка"}],resources:[{name:"Официальная страница — Buried Without Ceremony"},{name:"Купить на itch.io (плати сколько хочешь)"},{name:"Магазин: печать и PDF"},{name:"Foundry VTT — модуль сообщества"}],quotes:[{text:"В итоге Monsterhearts 2 делает честь дизайнеру и автору Эйвери Олдер."},{text:"Сделано очень славно. Графика Олдер атмосферна и напоминает — на мой неискушённый взгляд — Тима Брэдстрита."}]},en:{tagShort:"PbtA of messy teenage monsters and queer drama",tagline:'"Wickedness dwells within your heart, hunger courses through your veins."',description:"Monsterhearts 2 is a Powered by the Apocalypse RPG about the messy, dangerous lives of teenage monsters. Vampires, werewolves, witches, and ghosts attend an ordinary high school, hiding a monstrous nature beneath adolescent drama. It's a game about desire, power, growing up, and queer identity — where your body changes without permission and the real horror grows out of the relationships between characters, not the monsters themselves.",setting:"A small American town and its high school. By day: classes, parties, gossip, and broken hearts; underneath it all: hunger, wickedness, and secret power. Here monstrosity and puberty are indistinguishable — every character hides a dangerous nature, and any surge of feeling can turn catastrophic.",vignette:"You corner the quarterback by his locker and pour on the charm — Turn Someone On, 2d6 + Hot. The dice come up 8, a 7–9. He's flustered and into it, but you're the one left exposed, so he takes a String on you. Now he can pull that thread whenever he likes. You got what you wanted; it'll cost you later.",prep:"~15 min",mechanics:[{title:"2d6 moves (PbtA)",text:"Every risky action triggers a move: roll 2d6 + a stat (Hot, Cold, Volatile, or Dark). 10+ succeeds, 7–9 succeeds with a cost, and 6 or under misses as the MC makes a hard move against you."},{title:"Strings",text:"Strings are the game's social currency — emotional holds you gain over others. Spend one for a +1, to inflict harm, or to force a hard choice. Everyone ends up tangled in everyone else's threads."},{title:"The Sex Move",text:"Each Skin carries a unique Sex Move that fires only after consensual intimacy with another significant character, turning the most vulnerable scenes into concrete mechanical consequences."},{title:"Skins & the Darkest Self",text:"Play a Vampire, Werewolf, Ghost, Fae, Witch, and more. Each Skin brings its own moves and a Darkest Self — the monstrous spiral you fall into when everything goes wrong."}],gallery:[{cap:"Cover"},{cap:"The softcover book"},{cap:"Back cover & premise"}],resources:[{name:"Official page — Buried Without Ceremony"},{name:"Buy on itch.io (pay what you want)"},{name:"Print & PDF store"},{name:"Foundry VTT — community module"}],quotes:[{text:"All told, Monsterhearts 2 is a real credit to designer/author Avery Alder."},{text:"It's very nicely done. Alder's art is atmospheric, reminiscent (to my untrained eye) of Tim Bradstreet."}]}}),registerSystem("mork-borg",{groups:{default:{key:"osr",order:5},family:{key:"borg",order:1},genre:{key:"dark-fantasy",order:1},solo:{key:"solo-compatible",order:3}},name:"MÖRK BORG",publisher:"Ockult Örtmästare Games / Free League",dice:"d20 + d4–d10",players:"2–5",complexity:1,foundryStatus:"Official + Community",heroImage:"https://freeleaguepublishing.com/wp-content/uploads/2023/08/herbmasters_crop-1440x720.jpg",heroStyle:"border: 2px solid var(--yellow);",playstyleTags:["combat","horror","explore"],settingTags:["fantasy","weird","postapoc"],gallery:[{src:"https://freeleaguepublishing.com/wp-content/uploads/2023/08/MB_skeleton_kvad-1200x1200.jpg"},{src:"https://freeleaguepublishing.com/wp-content/uploads/2023/08/MB_lich-1-1200x1200.jpg"},{src:"https://freeleaguepublishing.com/wp-content/uploads/2023/08/MB_02EN_Anthelia_kvad-1200x1200.jpg"},{src:"https://freeleaguepublishing.com/wp-content/uploads/2023/08/MB_05EN_Basilisks_kvad-1200x1200.jpg"},{src:"https://freeleaguepublishing.com/wp-content/uploads/2023/08/MB_06EN_Violence_kvad-1200x1200.jpg"},{src:"https://freeleaguepublishing.com/wp-content/uploads/2023/08/MB_07EN_Troll-Zombie_kvad-1200x1200.jpg"}],resources:[{type:"link",url:"https://morkborg.com/",fmt:"Web"},{type:"rules",url:"https://jnohr.itch.io/mrk-borg-free",fmt:"PDF"},{type:"sheet",url:"https://morkborg.com/content/",fmt:"PDF"},{type:"sheet",url:"https://polyhedralnonsense.com/2020/11/05/mork-borg-fillable-character-sheet/",fmt:"PDF"}],mechanics:[{icon:"calendar"},{icon:"paintbrush"},{icon:"shuffle"},{icon:"plug"}],quotes:[{text:"A headbanger of a game that is the latest example of the fertile cross-pollination between tabletop role-playing and extreme metal: a love letter to the hellraising imagery, lyrics, and album art of metal.",author:"Pearse Anderson, The Guardian"},{text:"A pitch-black apocalyptic fantasy RPG.",author:"Sara Elsam, Dicebreaker"}],ru:{tagShort:"Doom-metal арт-панк фэнтези",tagline:"«Мир кончается. Книга должна сгореть».",description:"Арт-панк RPG про последние дни умирающего мира. Правила умещаются на нескольких страницах, но книга — произведение искусства: кислотные цвета, безумная вёрстка, атмосфера блэк-метала. Каждая сессия может стать последней — буквально, потому что мир кончается по расписанию.",setting:"Умирающий мир, которым правят два обезумевших Василиска. Пророчества предвещают конец. Каждое утро бросается кубик — и мир становится чуть ближе к гибели. Бесконечные болота, проклятые деревни, тёмные катакомбы и НЕТ надежды. Но есть добыча.",vignette:"Утро. Бросок Календаря Несчастий — единица. Шестое Несчастие: «Солнце больше не заходит. Тени исчезают. Без тени невозможно спать.» Ваш персонаж — Проклятый Скинлинг с d4 HP и ржавым мечом. В катакомбах скелет бьёт вас на 5 урона. Вы мертвы. Генерация нового персонажа — 3 минуты. Снова в бой.",prep:"~5 мин",mechanics:[{title:"Календарь Несчастий",text:"Каждое утро — бросок. На 7-й Несчастии мир официально гибнет. Кампания окончена. Навсегда."},{title:"Арт как геймплей",text:"Книга — арт-объект. Йохан Нор создал визуальный язык, который стал жанром. Десятки хаков копируют этот стиль."},{title:"Случайность всего",text:"Персонаж и снаряжение — случайны. Классы опциональны и могут быть выбраны. Мир не щадит никого."},{title:"Экосистема",text:"Сотни дополнений от сообщества. Cy_Borg (киберпанк), Pirate Borg, Vast Grimm (космос) — всё на одном движке."}],gallery:[{cap:"Скелет — интерьерный арт"},{cap:"Лич"},{cap:"Антелия"},{cap:"Василиски"},{cap:"Violence"},{cap:"Тролль-зомби"}],resources:[{name:"Официальный сайт"},{name:"Bare Bones Edition (76 стр. бесплатно!)"},{name:"Официальные листы"},{name:"Fillable лист"}],quotes:[{text:"Игра-хедбенгер, последнее свидетельство плодотворного перекрёстного опыления настольных RPG и экстремального метала: любовное письмо к адскому визуальному ряду, текстам и обложкам металлических альбомов."},{text:"Беспросветно чёрная апокалиптическая фэнтези-RPG."}]},en:{tagShort:"doom-metal art-punk fantasy RPG",tagline:'"The world is ending. The book should burn."',description:"An art-punk RPG about the final days of a dying world. The rules fit on a few pages, but the book is a work of art: acid colors, deranged layout, black metal atmosphere. Every session could be your last — literally, because the world ends on a schedule.",setting:"A dying world ruled by two maddened Basilisks. Prophecies foretell the end. Every morning a die is rolled — and the world inches closer to oblivion. Endless swamps, cursed villages, dark catacombs, and NO hope. But there is loot.",vignette:"Morning. Calendar of Miseries roll — a one. The Sixth Misery: 'The sun no longer sets. Shadows vanish. Without a shadow, sleep is impossible.' Your character — a Cursed Skinkling with d4 HP and a rusty sword. In the catacombs, a skeleton hits you for 5 damage. You're dead. New character generation — 3 minutes. Back into the fray.",prep:"~5 min",mechanics:[{title:"Calendar of Miseries",text:"Every morning — a roll. On the 7th Misery the world officially dies. Campaign over. Forever."},{title:"Art as gameplay",text:"The book is an art object. Johan Nohr created a visual language that became a genre. Dozens of hacks copy this style."},{title:"Everything is random",text:"Character and gear are random. Classes are optional. The world spares no one."},{title:"Ecosystem",text:"Hundreds of community supplements. Cy_Borg (cyberpunk), Pirate Borg, Vast Grimm (space) — all on the same engine."}],gallery:[{cap:"Skeleton — interior art"},{cap:"Lich"},{cap:"Anthelia"},{cap:"Basilisks"},{cap:"Violence"},{cap:"Troll zombie"}],resources:[{name:"Official website"},{name:"Bare Bones Edition (76 pp. free!)"},{name:"Official sheets"},{name:"Fillable sheet"}]}}),registerSystem("mothership",{groups:{default:{key:"narrative",order:4},family:{key:"standalone",order:1},genre:{key:"sci-fi",order:3},solo:{key:"solo-compatible",order:6}},name:"Mothership",publisher:"Tuesday Knight Games",dice:"d100 (d%)",players:"3–5",complexity:2,foundryStatus:"Community",heroImage:"https://www.tuesdayknightgames.com/cdn/shop/files/ms-new-header_13.jpg?v=1714335559&width=2400",playstyleTags:["horror","survival","explore"],settingTags:["space"],gallery:[{src:"https://www.tuesdayknightgames.com/cdn/shop/files/PSD-004.png?v=1713671746&width=1080"},{src:"https://www.tuesdayknightgames.com/cdn/shop/files/Mothership-PSG-armor-mockup.png?v=1713671968&width=1080"},{src:"https://www.tuesdayknightgames.com/cdn/shop/files/Mothership-Character-Sheet-mockup.png?v=1713672259&width=1080"},{src:"https://www.tuesdayknightgames.com/cdn/shop/files/CoreComponentSpread2024.jpg?v=1714488145&width=1080"}],resources:[{type:"link",url:"https://www.tuesdayknightgames.com/pages/mothership-rpg",fmt:"Web"},{type:"sheet",url:"https://cdn.shopify.com/s/files/1/0022/2727/3817/files/Mothership-Character-Sheet.pdf?v=1713672550",fmt:"PDF"},{type:"sheet",url:"https://cdn.shopify.com/s/files/1/0022/2727/3817/files/Mothership_1E_-_Advanced_Character_Sheet_Outlined.pdf?v=1713673196",fmt:"PDF"},{type:"sheet",url:"https://cdn.shopify.com/s/files/1/0022/2727/3817/files/Mothership-Ship-Manifest.pdf?v=1713672727",fmt:"PDF"},{type:"tool",url:"https://cdn.shopify.com/s/files/1/0022/2727/3817/files/Mothership_Warden_s_Screen.pdf?v=1718223085",fmt:"PDF"}],mechanics:[{icon:"brain"},{icon:"wrench"},{icon:"file-text"},{icon:"book"}],quotes:[{text:"The genre defining Mothership RPG might just be the absolute best way to die alone in space with your friends.",author:"Chris Lowry, Tabletop Gaming"}],ru:{tagShort:"Sci-fi хоррор на процентах",tagline:"«Научно-фантастический хоррор, где ваш корабль — ваш гроб».",description:"Sci-fi хоррор на процентных кубиках. Вы — рабочие, учёные и морпехи на космических кораблях, где всё идёт не так. Система стресса и паники делает каждую ситуацию непредсказуемой. Модульная структура: десятки блестящих сценариев от сообщества. Создание персонажа — 10 минут.",setting:"Далёкое будущее. Корпорации отправляют экипажи на заброшенные станции, в астероидные шахты и на мёртвые корабли. Что-то ждёт в темноте: инопланетные паразиты, сбойные ИИ, экзистенциальные аномалии. Эстетика — Alien встречает Event Horizon.",vignette:"Проверка стресса. Вы — Учёный, стресс: 3. Нужно открыть шлюз на мёртвой станции. Бросок Механики — d100 против 35. Выпало 42, провал. Стресс +1. Теперь 4. Проверка паники: d20 + стресс. Выпало 18 — итого 22. «Оцепенение: вы не можете двигаться один раунд.» Морпех кричит: «Давай!» А вы стоите, парализованные, глядя в темноту за шлюзом.",prep:"~15 мин",mechanics:[{title:"Паника и стресс",text:"Стресс копится. Переполнение → таблица паники. От заикания до «вы стреляете в ближайшего союзника»."},{title:"4 класса",text:"Водитель, Учёный, Андроид, Морпех. Каждый меняет динамику группы и подход к проблемам."},{title:"Одностраничный лист",text:"Создание — 10 минут. Идеально для ваншотов, конвенций и мини-кампаний."},{title:"Модули",text:"«A Pound of Flesh», «Gradient Descent», «Hull Breach» — каждый модуль сообщества — шедевр."}],gallery:[{cap:"Интерьерный арт"},{cap:"Броня — справочник"},{cap:"Лист персонажа"},{cap:"Содержимое набора"}],resources:[{name:"Официальный сайт"},{name:"Лист персонажа"},{name:"Расширенный лист"},{name:"Манифест корабля"},{name:"Ширма ведущего"}],quotes:[{text:"Жанрообразующая Mothership RPG — пожалуй, лучший способ умереть в одиночестве в космосе вместе с друзьями."}]},en:{tagShort:"Alien-style sci-fi horror RPG",tagline:'"Sci-fi horror where your ship is your coffin."',description:"Sci-fi horror on percentile dice. You are workers, scientists, and marines on spaceships where everything goes wrong. The stress and panic system makes every situation unpredictable. Modular structure: dozens of brilliant community scenarios. Character creation — 10 minutes.",setting:"The far future. Corporations send crews to abandoned stations, asteroid mines, and dead ships. Something waits in the dark: alien parasites, malfunctioning AIs, existential anomalies. The aesthetic — Alien meets Event Horizon.",vignette:"Stress check. You're a Scientist, stress: 3. You need to open an airlock on a dead station. Mechanics roll — d100 vs 35. Rolled 42, failure. Stress +1. Now 4. Panic check: d20 + stress. Rolled 18 — total 22. 'Paralysis: you can't move for one round.' The Marine screams: 'Move!' But you stand frozen, staring into the darkness beyond the airlock.",prep:"~15 min",mechanics:[{title:"Panic and stress",text:"Stress accumulates. Overflow triggers the panic table. From stuttering to 'you shoot the nearest ally.'"},{title:"4 classes",text:"Teamster, Scientist, Android, Marine. Each changes group dynamics and approach to problems."},{title:"One-page sheet",text:"Creation takes 10 minutes. Perfect for one-shots, conventions, and mini-campaigns."},{title:"Modules",text:"'A Pound of Flesh', 'Gradient Descent', 'Hull Breach' — every community module is a masterpiece."}],gallery:[{cap:"Interior art"},{cap:"Armor reference"},{cap:"Character sheet"},{cap:"Box contents"}],resources:[{name:"Official website"},{name:"Character sheet"},{name:"Advanced sheet"},{name:"Ship manifest"},{name:"Warden's screen"}]}}),registerSystem("mutant-year-zero",{groups:{default:{key:"fl",order:10},family:{key:"year-zero",order:10},genre:{key:"sci-fi",order:6},solo:{key:"solo-compatible",order:15}},name:"Mutant: Year Zero",publisher:"Free League / Year Zero Engine",dice:"d6 pool (push your luck)",players:"3–5",complexity:2,foundryStatus:"Community",heroImage:"https://freeleaguepublishing.com/wp-content/uploads/2023/11/MutantMechatron_banner.jpg",playstyleTags:["survival","explore","social"],settingTags:["postapoc"],gallery:[{src:"https://freeleaguepublishing.com/wp-content/uploads/2023/09/Zone-Wars-photo-9.jpg"},{src:"https://freeleaguepublishing.com/wp-content/uploads/2023/09/Zone-Wars-photo-2.jpg"},{src:"https://freeleaguepublishing.com/wp-content/uploads/2023/09/Zone-Wars-photo-5.jpg"},{src:"https://freeleaguepublishing.com/wp-content/uploads/2023/09/Zone-Wars-photo-7.jpg"}],resources:[{type:"link",url:"https://freeleaguepublishing.com/games/mutant-year-zero/",fmt:"Web"},{type:"sheet",url:"https://freeleaguepublishing.com/wp-content/uploads/2023/08/Character_Sheet.pdf",fmt:"PDF"},{type:"sheet",url:"https://freeleaguepublishing.com/wp-content/uploads/2023/08/Ark_Sheet.pdf",fmt:"PDF"},{type:"sheet",url:"https://freeleaguepublishing.com/wp-content/uploads/2023/08/Zone_Log.pdf",fmt:"PDF"},{type:"map",url:"https://freeleaguepublishing.com/wp-content/uploads/2023/08/The_Big_Smoke.pdf",fmt:"PDF"},{type:"map",url:"https://freeleaguepublishing.com/wp-content/uploads/2023/08/The_Dead_Apple.pdf",fmt:"PDF"}],mechanics:[{icon:"biohazard"},{icon:"dice-6"},{icon:"home"},{icon:"compass"}],quotes:[{text:"If you are into post-apocalypse RPGs you definitely should give Mutant a chance!",author:"Michael Wolf, Stargazer's World"},{text:"Choosing relationships is where the system shined for me, as both a player and a DM.",author:"Preston Dozsa, CGMagazine"}],ru:{tagShort:"Постапок выживание у руин Ковчега",tagline:"«Старейшины умирают. Паёк кончается. Зона зовёт. Это — Год Ноль».",description:"Игра, с которой начался Year Zero Engine (2014). Постапокалипсис: вы — мутанты Ковчега, последнего убежища в мире, погибшем сто лет назад. Старейшины при смерти, и больше никто не помнит, откуда вы взялись. Бросаете пулы шестигранников, форсируете провалы — но каждая «пушнутая» единица ломает снаряжение или запускает мутацию. Год Ноль — это год, когда ваше поколение должно решить: спасти Ковчег или найти Эдем за Зоной.",setting:"Земля после неназванного коллапса. Поля радиации, ржавые мегаполисы, мутировавшие звери и растения. Ковчег — горстка лачуг под властью Старейшин — даёт паёк (универсальную еду) и иллюзию безопасности. Вокруг — Зона: бывшие города, лаборатории, бункеры. Мутанты не знают истории, не знают мира до Падения, но в Зоне лежат артефакты, которые могут всё изменить. Атмосфера — Сталкер встречает Безумного Макса с привкусом скандинавской меланхолии.",vignette:"Сталкер Ковчега в подвале старого торгового центра. Бросок Пробивы: 4 кубика навыка, ни одной шестёрки. Рискуете — пушаете. Перебрасываете пять кубиков (можно и снаряжения), выпадает шестёрка — успех. Но на двух кубиках выпали единицы: ваша заточка ломается. Зато на кубике мутации тоже единица — вы зарабатываете Очко Мутации. Тратите его и активируете «Костяные шипы»: из ладоней растут отростки, вы корчитесь от боли и пробиваете дверь насквозь. За дверью — ящик с патронами. Ковчег получит +1 Паёк. А вы получите шрам на всю кампанию.",prep:"~20 мин",mechanics:[{title:"Пуш роллы",text:"Провалили бросок? Перебросьте все кубики — даже снаряжения. Но каждая выпавшая 1 ломает снаряжение или ранит вас. На кубиках мутации единица = вы тратите Очко Мутации, чтобы выжить."},{title:"Развитие Ковчега",text:"Между сессиями вы голосуете, во что вложить Очки Развития: Война, Еда, Технологии, Культура. Ваш Ковчег — общая овца. Каждый сектор открывает новые проекты и угрозы."},{title:"Гексокроул Зоны",text:"Зона — генерируемая на лету сетка гексов. Бросаете на угрозы, артефакты, мутировавшую фауну. Полевые экспедиции = поиск пайка, патронов и обломков прошлого."},{title:"Мутации",text:"У каждого PC — стартовая мутация (телекинез, костяные шипы, отравленная кровь и т.д.). Тратите Очки Мутации, чтобы её активировать. Заработать новые очки — только пушнуть бросок и поймать единицу. Игра наказывает осторожность."}],gallery:[{cap:"Сцена в Зоне"},{cap:"Мутанты Ковчега"},{cap:"Боевая стычка"},{cap:"Руины старого мира"}],resources:[{name:"Официальный сайт"},{name:"Лист персонажа"},{name:"Лист Ковчега"},{name:"Журнал Зоны"},{name:"Карта The Big Smoke"},{name:"Карта The Dead Apple"}],quotes:[{text:"Если вам нравятся постапокалиптические RPG, обязательно дайте Mutant шанс!"},{text:"Выбор отношений — то, в чём система засияла для меня и как для игрока, и как для мастера."}]},en:{tagShort:"Post-apocalyptic mutant survival at the Ark",tagline:'"The Elders are dying. The grub is running out. The Zone is calling. This is Year Zero."',description:"The game that birthed the Year Zero Engine (2014). Post-apocalypse: you are mutants of the Ark, the last refuge in a world that died a hundred years ago. The Elders are passing, and nobody remembers where you came from. You roll pools of d6s and push failures — but every pushed 1 breaks gear or triggers a mutation. Year Zero is the year your generation has to decide: save the Ark, or find Eden beyond the Zone.",setting:"Earth after an unnamed collapse. Radioactive fields, rusted megacities, mutated beasts and plants. The Ark — a cluster of shacks ruled by the Elders — provides grub (universal food) and the illusion of safety. Around it: the Zone — former cities, labs, bunkers. Mutants don't know history, don't know the world before the Fall, but the Zone holds artifacts that could change everything. The vibe is Stalker meets Mad Max with a streak of Scandinavian melancholy.",vignette:"An Ark Stalker in the basement of an old shopping mall. Force roll: 4 skill dice, no sixes. You take the risk — you push. Reroll all five dice (gear dice too); a six lands — success. But two ones: your shiv breaks, and your mutation 'Bone Spikes' triggers. Spikes burst from your palms, you scream in pain — and you punch through the door. Behind it: a crate of bullets. The Ark gets +1 Warfare. You get a scar that lasts the whole campaign.",prep:"~20 min",mechanics:[{title:"Pushing rolls",text:"Failed your roll? Reroll all dice — gear dice included. But every 1 that lands breaks gear or wounds you. A 1 on a mutation die means you spend a Mutation Point to survive. Risk is the only currency."},{title:"Building the Ark",text:"Between sessions, the players vote where to spend Development Points: Warfare, Food Supply, Technology, Culture. The Ark is shared property. Each sector unlocks new Projects — and new Threats."},{title:"Zone hexcrawl",text:"The Zone is a hex grid generated at the table. You roll for threats, artifacts, mutated wildlife. Field expeditions are the only way to bring back grub, bullets, and shards of the old world."},{title:"Mutations",text:"Every PC starts with one mutation (telekinesis, bone spikes, toxic blood, etc.). You spend Mutation Points to fire it. The only way to earn new points: push a roll and catch a 1. The game punishes caution."}],gallery:[{cap:"Scene in the Zone"},{cap:"Mutants of the Ark"},{cap:"Combat encounter"},{cap:"Ruins of the old world"}],resources:[{name:"Official website"},{name:"Character sheet"},{name:"Ark sheet"},{name:"Zone log"},{name:"The Big Smoke map"},{name:"The Dead Apple map"}]}}),registerSystem("mythic-bastionland",{groups:{default:{key:"osr",order:3},family:{key:"into-the-odd",order:3},genre:{key:"adventure",order:3}},name:"Mythic Bastionland",publisher:"Chris McDowell / Bastionland Press",dice:"d20 + d6",players:"2–5",complexity:2,foundryStatus:"Community",heroImage:"https://sessionzero.games/images/systems/mythic-bastionland-hero.jpg",playstyleTags:["explore","narrative","sandbox"],settingTags:["fantasy"],gallery:[{src:"https://sessionzero.games/images/systems/mythic-bastionland-hero.jpg"},{src:"https://cdn.shopify.com/s/files/1/0025/6006/5625/files/mythic-bastionland-book-9307117.png?v=1765482428"},{src:"https://img.itch.zone/aW1hZ2UvMjY0MjkzMi8xNjA1NzI2NS5wbmc=/original/M5VEoN.png"},{src:"https://img.itch.zone/aW1hZ2UvMzM4ODYxNy8yMDIyODgxNS5wbmc=/original/IQzFQ3.png"},{src:"https://img.itch.zone/aW1hZ2UvMzM4ODYxNy8yMDIyODgwOC5wbmc=/original/GKDyIn.png"},{src:"https://img.itch.zone/aW1hZ2UvMzM4ODYxNy8yMDIyODgwNy5wbmc=/original/n%2BjtLe.png"},{src:"https://img.itch.zone/aW1hZ2UvMzM4ODYxNy8yMDIyODk1Mi5wbmc=/original/DrzoXq.png"}],resources:[{type:"link",url:"https://www.bastionland.com/",fmt:"Web"},{type:"sheet",url:"https://manadawnttg.itch.io/mythic-bastionland-character-sheet",fmt:"PDF"}],mechanics:[{icon:"shield"},{icon:"map-pin"},{icon:"crown"},{icon:"dices"}],quotes:[{text:"It is an incredibly thoughtful and well designed product that feels like it is begging you to play it.",author:"Iain McAllister, The Giant Brain"}],ru:{tagShort:"Мифический рыцарский RPG",tagline:"«Рыцари мифа в мире, который помнит больше, чем рассказывает».",description:"Третья и самая масштабная игра на движке Into the Odd. Вы — рыцари-скитальцы, путешествующие по мифическим землям. Каждый рыцарь несёт свой Миф — личное предназначение, вплетённое в ткань мира. Мир генерируется процедурно прямо за столом: оракулы, таблицы и гексы (шестиугольные клетки карты) создают уникальную карту для каждой группы.",setting:"Тёмное артуровское фэнтези без эльфов и файерболлов. Туманные болота, каменные круги, забытые королевства. Мир — это смесь «Зелёного рыцаря», бретонских легенд и скандинавских саг. Монстры здесь — мифические существа, а не мешки с хитами.",vignette:"Новый гекс. Вы бросаете по таблице оракула — «Каменный круг. Внутри — рыцарь без лица, привязанный к дубу». Ваш Миф говорит: «Найди того, кто знает имя реки.» Это он? Вы спрашиваете рыцаря. Он отвечает голосом вашего отца. Сезон меняется — наступает зима, и мир вокруг реагирует.",prep:"~15 мин",mechanics:[{title:"Мифы рыцарей",text:"Каждый рыцарь начинает с Мифа — личного предназначения. Это не квест от NPC, а часть самого персонажа."},{title:"Процедурный мир",text:"Оракулы и таблицы создают мир прямо за столом. Каждый гекс — сюрприз для ведущего и игроков одновременно."},{title:"Сезонная структура",text:"Кампания делится на сезоны. Между приключениями мир меняется — крестьяне строят, враги крепнут."},{title:"Ядро Into the Odd",text:"Автопопадания, спасброски, минимум правил — в обёртке тёмного артуровского мифа."}],gallery:[{cap:"Рыцари мифа"},{cap:"Мифический мир"},{cap:"Арт из книги"},{cap:"Витраж и гобелен"},{cap:"Разворот книги"},{cap:"Мифические существа"},{cap:"Рыцари и легенды"}],resources:[{name:"Официальный сайт"},{name:"Лист персонажа"}],quotes:[{text:"Невероятно продуманный и грамотно спроектированный продукт, который буквально умоляет в него играть."}]},en:{tagShort:"mythic Arthurian RPG",tagline:'"Knights of myth in a world that remembers more than it tells."',description:"The third and most ambitious game built on the Into the Odd engine. You are wandering knights traveling through mythic lands. Each knight carries their own Myth — a personal destiny woven into the fabric of the world. The world is procedurally generated right at the table: oracles, tables, and hexes create a unique map for each group.",setting:"Dark Arthurian fantasy without elves or fireballs. Misty bogs, stone circles, forgotten kingdoms. The world is a blend of The Green Knight, Breton legends, and Norse sagas. Monsters here are mythic creatures, not bags of hit points.",vignette:"A new hex. You roll on the oracle table — 'A stone circle. Inside — a faceless knight, bound to an oak.' Your Myth says: 'Find the one who knows the river's name.' Is this him? You ask the knight. He answers in your father's voice. The season changes — winter arrives, and the world around you responds.",prep:"~15 min",mechanics:[{title:"Knight Myths",text:"Each knight starts with a Myth — a personal destiny. It's not a quest from an NPC, but part of the character themselves."},{title:"Procedural world",text:"Oracles and tables create the world right at the table. Each hex is a surprise for the GM and players alike."},{title:"Seasonal structure",text:"The campaign is divided into seasons. Between adventures, the world changes — peasants build, enemies grow stronger."},{title:"Into the Odd core",text:"Auto-hit attacks, saves, minimal rules — wrapped in dark Arthurian myth."}],gallery:[{cap:"Knights of myth"},{cap:"Mythic world"},{cap:"Book art"},{cap:"Stained glass and tapestry"},{cap:"Book spread"},{cap:"Mythic creatures"},{cap:"Knights and legends"}],resources:[{name:"Official website"},{name:"Character sheet"}]}}),registerSystem("nimble",{groups:{default:{key:"tactical",order:2},family:{key:"standalone",order:10.5},genre:{key:"tactical",order:2}},name:"Nimble 2e",publisher:"Nimble Co.",dice:"Только урон (d6-d12, взрыв.)",players:"3–6",complexity:2,foundryStatus:"Нет",heroImage:"https://nimblerpg.com/cdn/shop/files/HeroesFullArt.jpg?v=1741803078&width=3840",heroStyle:"background: linear-gradient(135deg, #1a3a2a, #0f1a0f, #2d1b00);",playstyleTags:["combat","explore"],settingTags:["fantasy"],gallery:[{src:"https://nimblerpg.com/cdn/shop/files/HeroesFullArt.jpg?v=1741803078&width=3840"},{src:"https://nimblerpg.com/cdn/shop/files/Maw.jpg?v=1741832672&width=3840"},{src:"https://nimblerpg.com/cdn/shop/files/GMScreenWrap1.jpg?v=1741797122"},{src:"https://nimblerpg.com/cdn/shop/articles/dragonArtFullB.jpg?v=1770732852&width=300"}],resources:[{type:"link",url:"https://nimblerpg.com/",fmt:"Web"}],mechanics:[{icon:"zap"},{icon:"dumbbell"},{icon:"dices"},{icon:"swords"}],quotes:[{text:"Nimble is easily one of the best 5E-adjacent RPGs ever made and delivers on its promise of speed and tactical play without sacrificing the best parts of modern D&D.",author:"Jason Volk, TTRPGfans"},{text:"Even those who adore D&D can agree that it sometimes feels like a slog, and that's the experience Nimble RPG vehemently avoids.",author:"Gab Hernandez, Wargamer"}],ru:{tagShort:"Быстрая альтернатива D&D 5e",tagline:"«D&D 5e, но быстрее, проще и без бросков на попадание. Бой за 20 минут, а не за 2 часа.»",description:"Сеттинг-агностик. Совместим с D&D 5e контентом — монстры, приключения, магические предметы конвертируются. Любой фэнтези-мир. Атаки всегда попадают: нет броска на попадание, бросается только урон. 1 = промах, всё остальное — попадание. Бои в 3 раза быстрее.",setting:"Сеттинг-агностик. Совместим с D&D 5e контентом (монстры, приключения, магические предметы конвертируются). Любой фэнтези-мир.",vignette:"Ваш ход: три действия. Первое — перемещение за колонну. Второе — удар мечом: d8 урона, выпало 8! Взрыв! Ещё d8 — 5. Итого 13 урона, огр шатается. Третье действие — «Рывок»: ещё одно перемещение, вы отступаете за укрытие. Следующий игрок — маг: три действия, три заклинания. Бой длится 20 минут, не 2 часа.",prep:"~10 мин",mechanics:[{title:"Атаки всегда попадают",text:"Нет броска на попадание. Бросается только урон. 1 = промах. Всё остальное — попадание. Бои в 3 раза быстрее."},{title:"3 действия за ход",text:"Вместо действие + бонусное + реакция — три «героических действия»: атака, перемещение, заклинание — в любой комбинации."},{title:"Взрывающиеся кубики",text:"Максимум на кубике = бросай ещё и добавляй. d6 → 6 → ещё d6 → 4 = 10 урона!"},{title:"Легендарные монстры с фазами",text:"Как в видеоиграх. Босс меняет способности при потере HP. Каждая фаза — новый бой."}],gallery:[{cap:"Герои Nimble"},{cap:"Легендарный монстр Maw"},{cap:"Ширма мастера"},{cap:"Дракон"}],resources:[{name:"Официальный сайт"}],quotes:[{text:"Nimble — без преувеличения, одна из лучших RPG на базе 5E из когда-либо сделанных, и она держит обещание скорости и тактичной игры, не жертвуя лучшим из современной D&D."},{text:"Даже фанаты D&D признают, что иногда она ощущается как болото — и именно от этого ощущения Nimble RPG яростно бежит."}]},en:{tagShort:"fast D&D 5e-compatible RPG",tagline:'"D&D 5e, but faster, simpler, and no attack rolls. Combat in 20 minutes, not 2 hours."',description:"Setting-agnostic. Compatible with D&D 5e content — monsters, adventures, magic items all convert. Any fantasy world. Attacks always hit: no attack roll, only damage is rolled. 1 = miss, everything else = hit. Combat is 3 times faster.",setting:"Setting-agnostic. Compatible with D&D 5e content (monsters, adventures, magic items convert). Any fantasy world.",vignette:"Your turn: three actions. First — move behind a pillar. Second — sword strike: d8 damage, rolled an 8! Exploding die! Another d8 — 5. Total 13 damage, the ogre staggers. Third action — 'Dash': another move, you fall back behind cover. Next player — the mage: three actions, three spells. Combat takes 20 minutes, not 2 hours.",prep:"~10 min",mechanics:[{title:"Attacks always hit",text:"No attack roll. Only damage is rolled. 1 = miss. Everything else = hit. Combat is 3 times faster."},{title:"3 actions per turn",text:"Instead of action + bonus + reaction — three 'heroic actions': attack, move, spell — in any combination."},{title:"Exploding dice",text:"Max on a die = roll again and add. d6 rolls 6, then d6 rolls 4 = 10 damage!"},{title:"Legendary phased monsters",text:"Like video games. The boss changes abilities when losing HP. Each phase is a new fight."}],gallery:[{cap:"Nimble heroes"},{cap:"Legendary monster Maw"},{cap:"GM screen"},{cap:"Dragon"}],resources:[{name:"Official website"}]}}),registerSystem("numenera",{groups:{default:{key:"narrative",order:30},family:{key:"standalone",order:37},genre:{key:"sci-fi",order:9.5}},name:"Numenera",publisher:"Monte Cook Games",dice:"d20 (Cypher System)",players:"3–6",complexity:3,free:!0,foundryStatus:"Official",heroImage:"https://www.montecookgames.com/store/wp-content/uploads/2018/04/N2-Slipcase-Set-Tags-2-1.jpg",playstyleTags:["narrative","combat","explore"],settingTags:["weird"],gallery:[{src:"https://www.montecookgames.com/store/wp-content/uploads/2015/11/Ninth-World-Bestiary.jpg"},{src:"https://www.montecookgames.com/store/wp-content/uploads/2015/11/Ninth-World-Guidebook.jpg"},{src:"https://www.montecookgames.com/store/wp-content/uploads/2016/11/NSS-3D-Cover-Tags.jpg"}],resources:[{type:"link",url:"https://www.montecookgames.com/numenera/",fmt:"Web"},{type:"quickstart",url:"https://www.montecookgames.com/numenera-primer/",fmt:"Web"},{type:"link",url:"https://www.montecookgames.com/store/product-category/numenera/",fmt:"Web"}],mechanics:[{icon:"sparkles"},{icon:"dices"},{icon:"book-open"},{icon:"scroll"}],quotes:[{text:"Shut Up and Sit Down highly recommends that you leap into the vast abyss of Numenera, which might be packed with more sheer, marvelous, possibility than any other RPG.",author:"Cynthia, Shut Up & Sit Down"},{text:"Numenera is literally the best role-playing game effort I have played in the past 10 years.",author:"Trask, Living Dice"}],ru:{tagShort:"Cypher System — «Я есть descriptor type who focus»",tagline:"«Одинокий ученый, который ищет правду. Девятый мир ждет».",description:"Numenera — настольная RPG от Monte Cook Games (2013, Discovery/Destiny 2018), действие в Девятом Мире — Земле через миллиард лет, где цивилизации возводили и исчезали, оставляя нуменеру (артефакты). Система Cypher: персонаж создаётся фразой «I am a (descriptor) (type) who (focus)» — например, «Одинокий ученый, который ищет правду». Бросок d20, но НЕ d20-система. GM никогда не бросает кубики. Игроки тратят очки Способности (Might, Speed, Intellect) на «усилие» (effort), снижая сложность задачи.",setting:"Девятый Мир — мир через миллиард лет после нашего. Земля, на которой возводились и исчезали целые эпохи. Остатки технологий — нуменера — повсюду: от городов до лесов. Люди живут в средневековье, но используют артефакты, не понимая их. Три типа персонажей: Glaive (воин), Jack (авантюрист), Nano (ученый/колдун).",vignette:"ГМ объявляет: Сложность 6 (целевое число 18). Игрок тратит 2 очка Интеллекта на усилие (снижает до 4), использует тренировку (снижает до 3). Бросает d20: 14. Успех! Но ГМ делает «вторжение» (GM intrusion): внезапно появляется ещё один враг. Игрок получает 2 XP, один из которых отдаёт союзнику.",prep:"~20 мин",mechanics:[{title:"Cypher System (d20)",text:"Бросок d20 vs целевого числа (сложность ×3). Игроки ТРАТЯТ очки способностей на снижение сложности, а не добавляют бонусы к броску. GM никогда не бросает кубики."},{title:"Фраза-создание",text:"«I am a (descriptor) (type) who (focus)». Пример: «Tough Glaive who Rides the Lightning». Три выбора определяют всё."},{title:"Усилие и тренировка",text:"Тратя очки, игрок снижает сложность на 1 шаг. Тренировка снижает ещё. Вместе — до 0 (авто-успех)."},{title:"GM Intrusions",text:"ГМ предлагает неожиданное событие. Игрок получает 2 XP (один отдаёт другу). ГМ получает свободу для драмы."}],gallery:[{cap:"Numenera Discovery + Destiny (слэйкейс)"},{cap:"Numenera Player's Guide"},{cap:"Numenera — обложка"}],resources:[{name:"Официальный сайт — Monte Cook Games"},{name:"Бесплатный Primer (введение)"},{name:"Каталог продуктов Numenera"}],quotes:[{text:"Shut Up & Sit Down настоятельно рекомендует нырнуть в бескрайнюю бездну Numenera — возможно, в ней больше чистых, восхитительных возможностей, чем в любой другой RPG."},{text:"Numenera — буквально лучшая ролевая игра, в которую я играл за последние 10 лет."}]},en:{tagShort:"Cypher System — 'I am a descriptor type who focus'",tagline:'"A lonely scholar who seeks truth. The Ninth World awaits."',description:"Numenera is a tabletop RPG from Monte Cook Games (2013, Discovery/Destiny 2018), set in the Ninth World — Earth a billion years hence, where civilizations have risen and fallen, leaving behind numenera (artifacts). The Cypher System: characters are built from the sentence 'I am a (descriptor) (type) who (focus)' — e.g. 'A tough glaive who rides the lightning.' d20 roll, but NOT the d20 system. The GM never rolls dice. Players spend Ability points (Might, Speed, Intellect) on Effort, lowering task difficulty.",setting:"The Ninth World — Earth a billion years after our era. The remnants of past civilizations are numenera: artifacts of incomprehensible power scattered everywhere. People live in a medieval state but use artifacts without understanding them. Three character types: Glaive (warrior), Jack (adventurer), Nano (scientist/witch).",vignette:"The GM announces: Difficulty 6 (target number 18). The player spends 2 Intellect points on Effort (lowers to 4), uses training (lowers to 3). Rolls d20: 14. Success! But the GM makes an intrusion: another enemy appears. The player gets 2 XP, one of which goes to an ally.",prep:"~20 min",mechanics:[{title:"Cypher System (d20)",text:"Roll d20 vs target number (difficulty ×3). Players SPEND ability points to lower difficulty, rather than adding bonuses. The GM never rolls dice."},{title:"Sentence Creation",text:"'I am a (descriptor) (type) who (focus).' Example: 'Tough Glaive who Rides the Lightning.' Three choices define everything."},{title:"Effort and Training",text:"Spending points lowers difficulty by 1 step. Training lowers it further. Combined — down to 0 (auto-succeed)."},{title:"GM Intrusions",text:"The GM introduces a sudden twist. The player gets 2 XP (gives one to a friend). The GM gets freedom for drama."}],gallery:[{cap:"Numenera Discovery + Destiny (slipcase)"},{cap:"Numenera Player's Guide"},{cap:"Numenera — cover"}],resources:[{name:"Official site — Monte Cook Games"},{name:"Free Numenera Primer"},{name:"Numenera product catalog"}],quotes:[{text:"Shut Up and Sit Down highly recommends that you leap into the vast abyss of Numenera, which might be packed with more sheer, marvelous, possibility than any other RPG."},{text:"Numenera is literally the best role-playing game effort I have played in the past 10 years."}]}}),registerSystem("one-ring",{groups:{default:{key:"narrative",order:10},family:{key:"standalone",order:6},genre:{key:"adventure",order:5},solo:{key:"solo-compatible",order:1}},name:"The One Ring",publisher:"Free League / Francesco Nepitello",dice:"d12 + d6",players:"3–5",complexity:3,foundryStatus:"Community",heroImage:"https://freeleaguepublishing.com/wp-content/uploads/2023/08/The_one_ring_tower-1440x720.jpg",playstyleTags:["explore","narrative","social"],settingTags:["fantasy"],gallery:[{src:"https://freeleaguepublishing.com/wp-content/uploads/2023/08/The_one_ring_Combat-edited-scaled.jpg"},{src:"https://freeleaguepublishing.com/wp-content/uploads/2023/08/The_one_ring_20_220-Ranger-Virtue-scaled.jpg"},{src:"https://freeleaguepublishing.com/wp-content/uploads/2023/08/The_one_ring_19_119_The-Nine-2-scaled.jpg"},{src:"https://freeleaguepublishing.com/wp-content/uploads/2023/08/the_one_ring_019_gandalf_frodo_FINAL-scaled.jpg"}],resources:[{type:"link",url:"https://freeleaguepublishing.com/games/the-one-ring/",fmt:"Web"},{type:"sheet",url:"https://freeleaguepublishing.com/wp-content/uploads/2025/09/TOR_Character-Sheets.zip",fmt:"ZIP"}],mechanics:[{icon:"mountain-snow"},{icon:"moon"},{icon:"home"},{icon:"heart"}],quotes:[{text:"Must play. A staggeringly beautiful adaptation of Middle-earth.",author:"Tabletop Gaming Magazine"}],ru:{tagShort:"RPG по Средиземью Толкина",tagline:"«Единственная игра, достойная Средиземья».",description:"Не «D&D в Средиземье», а игра, созданная для передачи духа Толкина. Путешествие — полноценная механика, а не пропуск. Тень — метафизическая угроза, разрушающая героев изнутри. Советы в безопасных гаванях — отдельная фаза с социалкой и развитием. Игра про надежду, а не про убийство орков.",setting:"Средиземье между «Хоббитом» и «Властелином Колец» (~2946–2977 Т.Э.). Эриадор, Дикоземье, Ривенделл, Шир. Тень Саурона растёт. Хоббиты, гномы, эльфы, люди — каждая культура детально проработана и верна канону. Карты, NPC, локации — всё с любовью к первоисточнику.",vignette:"Фаза путешествия. Вы — хоббит-разведчик. Путь через Лихолесье: бросок Исследования, d12 + два d6. На кубике Судьбы — Око Саурона. Провал с осложнением: тропа заводит в паутину. Тень растёт — +1 к счётчику Тени. У вас 4 Надежды и 3 Тени. Ещё немного — и Отчаяние. Но впереди Ривенделл. Фаза Совета: отдых, песни, и Элронд, который расскажет о дороге на восток.",prep:"~25 мин",mechanics:[{title:"Фаза путешествия",text:"Роли: проводник, разведчик, охотник, наблюдатель. Путь — не пропуск, а полноценный геймплей."},{title:"Тень",text:"Тьма проникает в сердце. Каждый героический поступок может обернуться Тенью — и герой станет злодеем."},{title:"Советы в гаванях",text:"Отдых в Ривенделле или Бэг-Энде. Общение с NPC, получение покровителей, восстановление."},{title:"Надежда и отчаяние",text:"Ресурс Надежды тратится на героические поступки. Когда Надежда кончается — Отчаяние берёт верх."}],gallery:[{cap:"Бой"},{cap:"Следопыт"},{cap:"Девять"},{cap:"Гендальф и Фродо"}],resources:[{name:"Официальный сайт"},{name:"Официальный лист"}],quotes:[{text:"Обязательно сыграть. Ошеломляюще красивая адаптация Средиземья."}]},en:{tagShort:"Middle-earth Tolkien RPG",tagline:'"The only game worthy of Middle-earth."',description:"Not 'D&D in Middle-earth,' but a game designed to convey the spirit of Tolkien. Travel is a full mechanic, not a skip. Shadow is a metaphysical threat that destroys heroes from within. Councils in safe havens are a separate phase with social interaction and development. A game about hope, not about killing orcs.",setting:"Middle-earth between The Hobbit and The Lord of the Rings (~2946-2977 T.A.). Eriador, the Wilderland, Rivendell, the Shire. Sauron's Shadow grows. Hobbits, dwarves, elves, men — every culture is meticulously detailed and true to canon. Maps, NPCs, locations — all crafted with love for the source.",vignette:"Travel phase. You're a hobbit scout. The path through Mirkwood: Exploration roll, d12 + two d6. The Feat die shows the Eye of Sauron. Failure with complication: the trail leads into webs. Shadow grows — +1 to the Shadow counter. You have 4 Hope and 3 Shadow. A little more and Despair sets in. But Rivendell lies ahead. Council phase: rest, songs, and Elrond, who will speak of the road east.",prep:"~25 min",mechanics:[{title:"Travel phase",text:"Roles: guide, scout, hunter, lookout. The journey isn't a skip — it's full gameplay."},{title:"Shadow",text:"Darkness seeps into the heart. Every heroic deed can invite Shadow — and the hero may become the villain."},{title:"Councils in havens",text:"Rest in Rivendell or Bag End. Interact with NPCs, gain patrons, recover."},{title:"Hope and despair",text:"Hope is spent on heroic deeds. When Hope runs out — Despair takes hold."}],gallery:[{cap:"Combat"},{cap:"Ranger"},{cap:"The Nine"},{cap:"Gandalf and Frodo"}],resources:[{name:"Official website"},{name:"Official sheet"}]}}),registerSystem("ose",{groups:{default:{key:"osr",order:10},family:{key:"osr-classic",order:2},genre:{key:"dark-fantasy",order:7}},name:"Old-School Essentials",publisher:"Necrotic Gnome / Gavin Norman",dice:"d20 + стандарт",players:"2–6",complexity:2,edition:"B/X",free:!0,foundryStatus:"Community",heroImage:"https://necroticgnome.com/cdn/shop/files/AFM_Cover_-_C_2022_David_Hoskins_13c53e3d-e120-43b0-8085-87d125f9aa7b.jpg?v=1669315843&width=3200",playstyleTags:["explore","survival","sandbox","combat"],settingTags:["fantasy"],gallery:[{src:"https://necroticgnome.com/cdn/shop/files/AFM_Cover_-_C_2022_David_Hoskins_13c53e3d-e120-43b0-8085-87d125f9aa7b.jpg?v=1669315843&width=3200"}],quotes:[{text:"This is about as perfect a set of old school rules as we've encountered – light, fast, streamlined, concise and polished to gleaming.",author:"Stu Horvath, Unwinnable (Vintage RPG, Feb 2020)"},{text:"As a dungeon master, it's a dream come true: fewer rules to juggle, easier to find the ones I do forget.",author:"Matt Thrower, There Will Be Games"}],resources:[{type:"link",url:"https://necroticgnome.com/pages/about-old-school-essentials",fmt:"Web"},{type:"link",url:"https://oldschoolessentials.necroticgnome.com/srd/index.php/Main_Page",fmt:"Web"},{type:"quickstart",url:"https://www.drivethrurpg.com/en/product/272802/old-school-essentials-basic-rules",fmt:"PDF"}],mechanics:[{icon:"compass"},{icon:"users"},{icon:"layers"},{icon:"book-open"}],ru:{tagShort:"Ретроклон B/X D&D",tagline:"«Подземелью всё равно, какова ваша предыстория. Оно смотрит только на ваш факел.»",description:"Old-School Essentials — эталонный клон B/X D&D 1981 года. Гэвин Норман переорганизовал правила с такой точностью, что любое правило находится за секунды. Лучшая версия блестяще простой игры.",setting:"Сеттинг-агностичная система. Подразумеваемый мир — опасная местность с подземельями, коррумпированными городами и руинами павших империй. Персонажи — охотники за сокровищами, не герои.",vignette:"Третий уровень подземелья. Мастер бросает реакцию орков за дверью. 12: дружелюбны. Переговоры: им нужен выход наверх, вам — идол из комнаты 14. Сделка. Десять минут спустя, с оплывающими факелами и золотом, вы слышите позади что-то крупное — то, чего не было на карте.",prep:"~10 мин",mechanics:[{title:"Процедуры исследования",text:"Каждые 10 минут — Ход. Проверка встреч, расход факелов, шум. Время и свет — ресурсы."},{title:"Реакция и моральный дух",text:"Монстры не запрограммированы сражаться. 2d6 реакции определяет их поведение. Каждая встреча — переговоры."},{title:"Два варианта AC",text:"Нисходящая и восходящая системы AC параллельно. Каждый блок статистики работает с обеими."},{title:"Модульная архитектура",text:"Взаимозаменяемые модули: Classic + Advanced Fantasy. Замените блоки, не сломав игру."}],gallery:[{cap:"Rules Tome"}],resources:[{name:"Официальный сайт"},{name:"Бесплатный SRD"},{name:"Basic Rules — бесплатный PDF"}],quotes:[{text:"Это, пожалуй, самый совершенный набор олдскульных правил, который нам встречался — лёгкий, быстрый, выверенный, лаконичный и отполированный до блеска."},{text:"Для мастера это сбывшаяся мечта: меньше правил жонглировать, и забытое легче отыскать."}]},en:{tagShort:"B/X retroclone OSR",tagline:`"The dungeon doesn't care about your backstory. It cares about your torch."`,description:"Old-School Essentials is the gold-standard retroclone of the 1981 B/X Dungeons & Dragons rules. Designer Gavin Norman took those rules and made them even clearer: reorganized, cross-referenced, and laid out so precisely that any rule you need is findable in seconds. This is not a nostalgia trip. It's the best version of a brilliantly simple game that was already perfect.",setting:"OSE is setting-agnostic — the rules support any flavor of fantasy, from sword-and-sorcery pulp to dark fairy tales to gonzo science-fantasy. The implied world is a dangerous wilderness dotted with crumbling dungeons, corrupt city-states, and ruins of fallen empires. Player characters are treasure-hunters first and heroes second, if ever.",vignette:"Third level of the dungeon. The map shows a door at the end of the corridor. The Referee rolls in secret — reaction check for the orcs behind it. A twelve: friendly. You could fight. Instead you parley. They want safe passage to the surface. You want the idol in room 14. A deal is struck. Ten minutes later, torches guttering, encumbered with gold, you hear something large moving in the dark behind you — something that wasn't on the map.",prep:"~10 min",mechanics:[{title:"Dungeon Procedures",text:"Every 10 minutes underground is a Turn. Each Turn: check for wandering monsters, track torch burn, manage noise. Time pressure is a resource. Light is a resource."},{title:"Reaction & Morale Rolls",text:"Monsters aren't pre-programmed to fight. A 2d6 reaction roll determines if they're hostile, curious, or open to bargain. Morale rolls decide when they flee."},{title:"Ascending & Descending AC",text:"OSE ships with old-school descending AC and THAC0 plus optional ascending AC rules side-by-side. Every stat block works for both systems."},{title:"Modular Design",text:"Genre Rules, Class options, Advanced Fantasy expansions — OSE is built as interchangeable modules. Classic B/X core plus Advanced classes? Done."}],gallery:[{cap:"Rules Tome — cover by Peter Mullen"}],resources:[{name:"Official website — Necrotic Gnome"},{name:"Free SRD — complete rules online"},{name:"Basic Rules — free PDF"}]}}),registerSystem("osric-3",{groups:{default:{key:"osr",order:3.5},family:{key:"osr-classic",order:3.5},genre:{key:"dark-fantasy",order:8.5}},name:"OSRIC 3",publisher:"Mythmere Games",dice:"d20 + d4–d100",players:"2–6",complexity:3,edition:"AD&D 1e",free:!0,foundryStatus:"Official",heroImage:"https://www.mythmeregames.com/cdn/shop/files/PDFCovers3.png",playstyleTags:["explore","combat","sandbox","survival"],settingTags:["fantasy","sword-and-sorcery"],gallery:[{src:"https://www.mythmeregames.com/cdn/shop/files/PDFCovers2.png"},{src:"https://www.mythmeregames.com/cdn/shop/files/PDFCovers4_91571dbb-8283-418b-9d4b-42d9a1a3af3f.png"},{src:"https://www.mythmeregames.com/cdn/shop/files/OSRIC3.0GMScreen.png"}],resources:[{type:"link",url:"https://www.mythmeregames.com/collections/osric-3-0",fmt:"Web"},{type:"link",url:"https://www.drivethrurpg.com/en/product/550861/osric-3-0-player-guide",fmt:"Web"},{type:"sheet",url:"https://dragonsfoot.org/php4/archive.php?sectioninit=SG&fileid=386",fmt:"PDF"}],mechanics:[{icon:"dices"},{icon:"swords"},{icon:"book-open"},{icon:"shield"}],quotes:[{text:"OSRIC 3e aims to reintroduce an old game for a new cultural context of play. I just adore it for that.",author:"Traverse Fantasy"},{text:"If I were starting new players with 1E, I would be playing OSRIC 3.0. Never has there been a clearer, easier-to-learn, and well-represented version of the game than this.",author:"Hak, SBRPG"}],ru:{tagShort:"AD&D 1e ретроклон",tagline:"«Оригинальный ретроклон, возрождённый для нового поколения».",description:"OSRIC 3.0 — точное изложение AD&D 1e, полностью переписанное для ясности и доступности. Золотая середина между правил-лайт OSR и сложными современными RPG. Рефери — судья, механика достаточно глубока для хай-левела. Бесплатные PDF, открытая лицензия на модули, совместимость с тысячами приключений. Вход в AD&D — здесь.",setting:"Система-агностик. Подразумеваемый мир — псевдо-средневековое фэнтези начала 80-х: руины, драконы, древняя магия и сверкающие сокровища. Опасный фронтир, где авантюристы либо вписывают свои имена в легенды, либо умирают забытыми в темноте.",vignette:"Факел мерцает. Ниорвия, воительница, приоткрывает дверь — за ней зал в паутине. Скрип когтей по камню где-то впереди. Джарвиан-вор показывает на отпечаток плиты в пыли. Полдарк-маг шепчет арканное слово, его глаза стекленеют — ESP нащупывает сознание за дверью. Воительница поднимает меч и шагает во тьму.",prep:"~15 мин",mechanics:[{title:"Сегментная инициатива",text:"Раунд поделён на 10 сегментов. Каждая сторона кидает 1d6 — результат определяет сегмент действия. Время заклинаний, скорость оружия и движение взаимодействуют с этой шкалой."},{title:"Четыре режима генерации",text:"От «хардкор» (3d6 по порядку) до «гибкий» (4d6 с отбрасыванием по выбору). Модификаторы возраста и расы. Потолок — 18."},{title:"Heroic Assault (Cleave)",text:"Воин, убивший врага до 0 хп, немедленно атакует соседнего. На высоких уровнях — несколько атак за раунд. Механика не работает одновременно, заменяет себя."},{title:"Backstab и навыки вора",text:"Процентные навыки: скрытность, тишина, взлом, поиск/обезвреживание ловушек. Backstab: +4 к атаке, множитель урона. Чёткие правила: скрытное приближение или атака из тени."}],gallery:[{cap:"Player Guide + GM Guide"},{cap:"Корешки книг"},{cap:"GM Screen"}],resources:[{name:"Официальный сайт — Mythmere Games"},{name:"Player Guide (Free/PWYW на DriveThruRPG)"},{name:"Лист персонажа — Dragonsfoot"}],quotes:[{text:"OSRIC 3e стремится заново представить старую игру для нового культурного контекста. Я просто обожаю это."},{text:"Если бы я начинал новых игроков с 1E, я бы играл в OSRIC 3.0. Никогда не было более ясной, лёгкой для изучения и хорошо представленной версии этой игры."}]},en:{tagShort:"AD&D 1e retro-clone",tagline:'"The original retro-clone, reborn for a new generation."',description:"OSRIC 3.0 is a faithful restatement and reorganization of first-edition Advanced Dungeons & Dragons, fully rewritten for clarity and accessibility. It occupies a middle ground between rules-light OSR and modern complex RPGs, relying on the GM as referee while providing enough mechanical depth to hold together at high-level play. Free PDFs, third-party licensing, and compatibility with thousands of existing adventures.",setting:"Setting-agnostic. The implied world is pseudo-medieval early-1980s fantasy: ruined dungeons, ancient magic, fierce dragons, glittering treasure. A dangerous frontier where adventurers carve their names into legend or die forgotten in the dark.",vignette:"The torchlight flickers. Niorvia the fighter eases the dungeon door open — a chamber thick with cobwebs. A faint scraping sound — claws on stone. Jarvian the thief points at a faint pressure plate impression in the dust. Poldark the mage whispers an arcane syllable, his eyes glazing as he reaches out with ESP. The fighter nods once, raises her blade, and steps into the dark.",prep:"~15 min",mechanics:[{title:"Segment-Based Initiative",text:"Combat rounds divided into 10 segments. Each side rolls 1d6 for initiative — the result is the segment when their actions resolve. Spell casting times, weapon speeds, and movement interact with this granular timeline."},{title:"Four Ability Generation Modes",text:"From Hardest Mode (3d6 down the line) to Flexible Mode (4d6 drop lowest, arrange as desired). Age and racial modifiers apply, hard cap at 18."},{title:"Heroic Assault (Cleave)",text:"Fighters who reduce a foe to 0 HP may immediately make an additional attack against an adjacent enemy. At higher levels this becomes multiple attacks per round."},{title:"Backstab & Thief Skills",text:"Thieves use percentile skills for hide, move silently, pick locks, and find/remove traps. Backstab grants +4 to hit and multiplies damage dice. Clear rules for when it applies."}],gallery:[{cap:"Player Guide + GM Guide"},{cap:"Spine art"},{cap:"GM Screen"}],resources:[{name:"Official website — Mythmere Games"},{name:"Player Guide (Free/PWYW on DriveThruRPG)"},{name:"Character sheet — Dragonsfoot"}]}}),registerSystem("outcast-silver-raiders",{groups:{default:{key:"osr",order:22},family:{key:"standalone",order:25},genre:{key:"dark-fantasy",order:10}},name:"Outcast Silver Raiders",publisher:"Esoteric Ludology / Isaac VanDuyn",dice:"d20 / d10 / d6 (roll-high)",players:"3–6",complexity:2,foundryStatus:"None",heroImage:"https://images.squarespace-cdn.com/content/v1/5e669e911f689d55045f96b8/41b71530-99c4-4e85-abae-6f6b7edabcff/church+battle.png",playstyleTags:["explore","survival","horror"],settingTags:["fantasy","weird"],gallery:[{src:"https://images.squarespace-cdn.com/content/v1/5e669e911f689d55045f96b8/1a8bbe5d-2ba9-4488-bb91-947de0692570/warlock+tower.png"},{src:"https://images.squarespace-cdn.com/content/v1/5e669e911f689d55045f96b8/26b1d141-9da5-466a-98ef-ca74538ebb1c/warriors.png"},{src:"https://images.squarespace-cdn.com/content/v1/5e669e911f689d55045f96b8/55cdd122-0ce9-4b01-83ec-3436bec05bb6/rogues.png"}],resources:[{type:"link",url:"https://www.osr-rpg.com/",fmt:"Web"},{type:"link",url:"https://www.exaltedfuneral.com/products/outcast-silver-raiders",fmt:"Web"}],mechanics:[{icon:"dices"},{icon:"cross"},{icon:"lightbulb"},{icon:"swords"}],quotes:[{text:"Standing among the many titles that have emerged in this tradition, Outcast Silver Raiders offers a particularly innovative, evocative and immersive experience to potential players.",author:"Justin Reeve, Unwinnable"},{text:"The game's blend of old school mechanics, dark thematic elements and stunning artwork all come together to create a unique experience that stands out in the sometimes crowded landscape of TTRPGs.",author:"Justin Reeve, Unwinnable"}],ru:{tagShort:"Кроваво-оккультный OSR в Мифическом Севере",tagline:"«Окровавленное средневековое фэнтези по мотивам шотландского фольклора XII века».",description:"Outcast Silver Raiders — OSR-игра с оглушительным арт-стилем (красное-чёрное-белое, экстрим-метал-эстетика Кима Диаса Хольма). Изгои-наёмники добывают серебро в жестоком мифическом мире. Своя механика «всегда бросай высоко» с разными кубами под ситуацию. Влияния — Lamentations of the Flame Princess, The Black Hack, Swordfish Islands.",setting:"Мифический Север — окровавленное оккультное средневековье по мотивам фольклора Шотландии XII века и средневековой католической церкви. Мир низкой магии с хоррор-подтекстом: гниющие крепости, еретики, святые и твари из-под земли. Не героика — выживание изгоев, которым нужно серебро, чтобы протянуть ещё зиму.",vignette:"Отряд крадётся в разорённое аббатство за серебром алтаря. Вор проверяет навык — бросок d6, всегда «высоко»: выпало 5, порог пройден, реликвия у вас. Но снаружи звонит колокол. Стычка неизбежна — атака бросается d20 «высоко» против защиты. Здесь ценят не резню, а хитрость: лучший бой — тот, которого удалось избежать.",prep:"~5 мин",mechanics:[{title:"Всегда бросай высоко",text:"Под каждую ситуацию — свой куб: d20 на атаки, d10 на спасброски, d6 на проверки. Всегда бросаете «высоко». Простая, интуитивная система без таблиц модификаторов."},{title:"Мифический Север",text:"Оккультное средневековье, вдохновлённое Шотландией XII века и католической церковью. Низкая магия, хоррор-подтекст, кровь и святость — цельный, мрачный сеттинг в комплекте."},{title:"Квест важнее боя",text:"Стычки поощряют смекалку и решение проблем, а не убийство. Играет мастерство игрока: обмануть, обойти, договориться. Прямой бой — крайняя и опасная мера."},{title:"Кампания без подготовки",text:"Игра создана, чтобы запускаться прямо из коробки: кубы связывают фракции и встречи на лету. Минимум прикидок для ведущего — максимум игры за столом."}],gallery:[{cap:"Башня чернокнижника"},{cap:"Воины"},{cap:"Разбойники"}],resources:[{name:"Официальный сайт — osr-rpg.com"},{name:"Boxed Set (Exalted Funeral)"}],quotes:[{text:"Среди множества игр этой традиции Outcast Silver Raiders предлагает особенно новаторский, выразительный и погружающий опыт."},{text:"Смесь олдскульных механик, мрачных тем и потрясающего арта создаёт уникальный опыт, выделяющийся в порой перенасыщенном ландшафте настолок."}]},en:{tagShort:"Blood-soaked occult OSR in the Mythic North",tagline:'"Blood-drenched medieval fantasy drawn from 12th-century Scottish folklore."',description:"Outcast Silver Raiders is an OSR game with a jaw-dropping art style — red, black, and white, in the extreme-metal aesthetic of Kim Diaz Holm. Outcast mercenaries scrape silver from a brutal mythic world. Its own 'always roll high' engine uses a different die per situation. Influences: Lamentations of the Flame Princess, The Black Hack, and The Swordfish Islands.",setting:"The Mythic North — a blood-drenched occult medieval world inspired by 12th-century Scottish folklore and the medieval Catholic church. Low magic with a horror undercurrent: rotting keeps, heretics, saints, and things from underground. Not heroism — the survival of outcasts who need silver to last one more winter.",vignette:"The party creeps into a ruined abbey for the altar's silver. The thief tests a skill — a d6, always rolled high: a 5 clears the target, and the relic is yours. But a bell tolls outside. A clash is coming — an attack rolls d20 high against a defense. Here cunning beats slaughter: the best fight is the one you avoid.",prep:"~5 min",mechanics:[{title:"Always roll high",text:"Each situation uses its own die: d20 for attacks, d10 for saving throws, d6 for checks. You always roll high. A simple, intuitive system with no modifier tables."},{title:"The Mythic North",text:"An occult medieval world inspired by 12th-century Scotland and the Catholic church. Low magic, a horror undercurrent, blood and sanctity — a complete, grim setting in the box."},{title:"Quest over combat",text:"Encounters reward ingenuity and problem-solving, not killing. Player skill is what matters: trick it, bypass it, talk your way past. Open combat is a last, dangerous resort."},{title:"No-prep campaign",text:"Built to run right out of the box: dice tie factions and encounters together on the fly. Minimal GM prep — maximal play at the table."}],gallery:[{cap:"Warlock's tower"},{cap:"Warriors"},{cap:"Rogues"}],resources:[{name:"Official site — osr-rpg.com"},{name:"Boxed Set (Exalted Funeral)"}],quotes:[{text:"Standing among the many titles that have emerged in this tradition, Outcast Silver Raiders offers a particularly innovative, evocative and immersive experience to potential players."},{text:"The game's blend of old school mechanics, dark thematic elements and stunning artwork all come together to create a unique experience that stands out in the sometimes crowded landscape of TTRPGs."}]}}),registerSystem("outgunned",{groups:{default:{key:"narrative",order:11},family:{key:"standalone",order:7},genre:{key:"adventure",order:9}},name:"Outgunned",publisher:"Two Little Mice / Director's Cut",dice:"Пул d6",players:"3-5",complexity:2,foundryStatus:"Community",heroImage:"https://www.belloflostsouls.net/wp-content/uploads/2023/05/Outgunned_Splash2.jpg",playstyleTags:["combat","narrative","social"],settingTags:["modern"],gallery:[{src:"https://twolittlemice.net/wp-content/uploads/2024/01/Cover_OG_Site.jpg"},{src:"https://sessionzero.games/images/systems/outgunned-g1.jpg"},{src:"https://twolittlemice.net/wp-content/uploads/2024/01/DL_Hero_Sheets.jpg"},{src:"https://twolittlemice.net/wp-content/uploads/2024/01/Download_QS_Site.jpg"}],resources:[{type:"link",url:"https://twolittlemice.net/outgunned/",fmt:"Web"},{type:"sheet",url:"https://legacy.drivethrurpg.com/product/501993/Outgunned--Outgunned-Adventure--Character-Sheets",fmt:"PDF"},{type:"quickstart",url:"https://i0.wp.com/twolittlemice.net/wp-content/uploads/2024/01/Download_QS_Site.jpg",fmt:"PDF"}],mechanics:[{icon:"dices"},{icon:"flame"},{icon:"zap"},{icon:"drama"}],quotes:[{text:"Outgunned is the best cinematic action RPG since Feng Shui.",author:"Rob Wieland, EN World"},{text:"Outgunned keeps the promise of a TTRPG system that lets you create games like action movies.",author:"Andrew Girdwood, Geek Native"}],ru:{tagShort:"Кинематографичная экшн-RPG",tagline:"Die Hard, John Wick, Ocean's Eleven — теперь это ваш фильм.",description:"Кинематографичная экшн-RPG, где вы играете героев боевиков. Система Director's Cut: бросаете пул d6, успех — это совпадения (пары, тройки, каре). Создание персонажа за минуты: Роль (Мускул, Мозг, Лицо) + Троп (Отставной коп, Шпион на пенсии, Хакер-подросток). Идеально для ваншотов и мини-кампаний.",setting:"Любой экшн-фильм. Модули под жанры: шпионский триллер (James Bond), полицейский боевик (Die Hard), ограбление (Ocean's Eleven), боевые искусства (John Wick). Action Flicks добавляют Ghostbusters, Indiana Jones, палп. Ваш стол — съёмочная площадка.",vignette:"Крыша небоскрёба. Вертолёт злодея взлетает. «Я прыгаю на шасси!» Бросок: 4 кубика. Две тройки — пара! Успех, вы цепляетесь. Heat растёт. Ведущий: «Пилот замечает вас и резко кренит машину.» Следующий игрок: «Стреляю в хвостовой ротор из окна соседнего здания.» Три шестёрки. Тройка! Эпический успех. Вертолёт теряет управление. Стол взрывается.",prep:"~15 мин",mechanics:[{title:"Совпадения на d6",text:"Пары, тройки, каре — каждое совпадение круче предыдущего. Push your luck: добавляй кубики, но рискуй провалом."},{title:"Heat (Накал)",text:"Мера эскалации. Чем дальше — тем больше врагов, ближе дедлайн. Как саундтрек к кульминации."},{title:"Мгновенный старт",text:"Создание персонажа — 5 минут. Роль + Троп = готовый герой. Сел и играй."},{title:"Action Flicks",text:"Модули-жанры. Каждый меняет тон и добавляет уникальные механики под конкретный жанр боевика."}],gallery:[{cap:"Погоня — арт из книги"},{cap:"Экшн-сцена"},{cap:"Листы героев"},{cap:"Лист персонажа"}],resources:[{name:"Официальный сайт"},{name:"Листы героев (EN/IT)"},{name:"Quickstart"}],quotes:[{text:"Outgunned — лучшая кинематографичная боевиковая RPG со времён Feng Shui."},{text:"Outgunned держит обещание: TTRPG-система, в которой получаются игры, как боевики."}]},en:{tagShort:"Die Hard cinematic action RPG",tagline:"Die Hard, John Wick, Ocean's Eleven — now it's your movie.",description:"A cinematic action RPG where you play action movie heroes. The Director's Cut system: roll a d6 pool, successes are matches (pairs, triples, four-of-a-kind). Character creation in minutes: Role (Muscle, Brain, Face) + Trope (Retired Cop, Spy on Sabbatical, Teenage Hacker). Perfect for one-shots and mini-campaigns.",setting:"Any action movie. Genre modules: spy thriller (James Bond), cop action (Die Hard), heist (Ocean's Eleven), martial arts (John Wick). Action Flicks add Ghostbusters, Indiana Jones, pulp. Your table is a film set.",vignette:"Skyscraper rooftop. The villain's helicopter takes off. 'I jump onto the landing gear!' Roll: 4 dice. Two threes — a pair! Success, you grab hold. Heat rises. GM: 'The pilot spots you and banks hard.' Next player: 'I shoot the tail rotor from a window in the next building.' Three sixes. Triple! Epic success. The helicopter spins out of control. The table erupts.",prep:"~15 min",mechanics:[{title:"d6 matches",text:"Pairs, triples, four-of-a-kind — each match is bigger than the last. Push your luck: add dice, but risk failure."},{title:"Heat",text:"An escalation meter. The longer it goes, the more enemies, the tighter the deadline. Like a soundtrack building to the climax."},{title:"Instant start",text:"Character creation — 5 minutes. Role + Trope = ready hero. Sit down and play."},{title:"Action Flicks",text:"Genre modules. Each changes the tone and adds unique mechanics for a specific action genre."}],gallery:[{cap:"Car chase — book art"},{cap:"Action scene"},{cap:"Hero sheets"},{cap:"Character sheet"}],resources:[{name:"Official website"},{name:"Hero sheets (EN/IT)"},{name:"Quickstart"}]}}),registerSystem("paranoia",{groups:{default:{key:"narrative",order:38},family:{key:"standalone",order:46},genre:{key:"sci-fi",order:17}},name:"Paranoia",publisher:"Mongoose Publishing",dice:"d6 pool (NODE) + Computer Die",players:"4–6",complexity:2,foundryStatus:"Community",heroImage:"https://www.mongoosepublishing.com/cdn/shop/files/ParanoiaCoreCoverEbook_1317x.jpg?v=1694683887",playstyleTags:["social","combat","narrative"],settingTags:["postapoc","weird"],gallery:[{src:"https://www.mongoosepublishing.com/cdn/shop/files/Spread1_32fd11ed-e1e2-4b52-b6a4-0c2a29cc769b_1530x.jpg?v=1694683895"},{src:"https://www.mongoosepublishing.com/cdn/shop/files/Spread2_3431dc85-32c3-469d-8fed-c556587eb96e_1530x.jpg?v=1694683894"},{src:"https://www.mongoosepublishing.com/cdn/shop/files/Spread3_a177d5d6-a299-4069-adba-5f12cac67c6f_1530x.jpg?v=1694683895"}],resources:[{type:"link",url:"https://www.mongoosepublishing.com/collections/paranoia",fmt:"Web"},{type:"link",url:"https://www.drivethrurpg.com/en/product/453042/the-paranoia-core-book",fmt:"PDF"}],mechanics:[{icon:"dices"},{icon:"cpu"},{icon:"skull"},{icon:"drama"}],quotes:[{text:"This is a good edition of Paranoia, and moves the needle in the right direction from Red Clearance Edition.",author:"Aaron Marks, Cannibal Halfling Gaming"},{text:"The rules cleanup is kept and largely not messed with, but the game regains a bit of its self-awareness and edge.",author:"Aaron Marks, Cannibal Halfling Gaming"}],ru:{tagShort:"Сатирическая антиутопия чёрного юмора",tagline:"«Компьютер — твой друг. Компьютер счастлив. Будь счастлив и ты. Или это измена».",description:"Paranoia — комедийная RPG об абсурдной антиутопии Альфа-Комплекса, которым правит безумный Компьютер. Вы — Устранители (Troubleshooters): находите неполадки и устраняете их, а заодно друг друга. У каждого шесть клонов, тайное членство в запрещённом обществе и куча измен за пазухой. Правила намеренно лёгкие — всё держится на паранойе, доносах и чёрном юморе.",setting:"Альфа-Комплекс — герметичный подземный бункер будущего под управлением параноидального ИИ по имени Компьютер. Общество разделено на цветовые уровни допуска; знать о вещах не своего уровня — измена. Мутанты — измена. Тайные общества — измена. И почти все — мутанты в тайных обществах. Снаружи — Внешний Мир, о котором Компьютер предпочитает не думать.",vignette:"Компьютер: «Гражданин, ваш допуск КРАСНЫЙ. Почему у вас СИНЯЯ карточка?» Ты: «Это... улика, я конфисковал её у изменника». Сосед по команде тихо тянется к лазеру. Ты бросаешь NODE: четыре кубика плюс Компьютерный. Две шестёрки — успех! Но Компьютерный кубик показывает 1. «Гражданин, зафиксирован сбой. Отправляю ремонтную бригаду... и клона на замену».",prep:"~30 мин",mechanics:[{title:"NODE-кубики",text:"Характеристика + навык = число кубиков (Number Of DicE). Бросаешь пул d6, 5 и 6 — успехи. Просто и быстро — система не мешает балагану."},{title:"Компьютерный кубик",text:"Красный кубик в каждом броске. Единица на нём — вмешательство Компьютера: сбой, донос, внезапная «помощь». Хаос строго по расписанию."},{title:"Шесть клонов и Мокси",text:"У персонажа шесть сменных клонов и запас Мокси на трюки и выживание. Смерть — не конец, а неудобство и бумажная волокита."},{title:"Измена и тайные общества",text:"У каждого своя скрытая повестка и запрещённое членство. Доноси первым — пока не донесли на тебя. Предательство встроено прямо в правила."}],gallery:[{cap:"Разворот — арт Альфа-Комплекса"},{cap:"Разворот — Устранители"},{cap:"Разворот — правила и Компьютер"}],resources:[{name:"Страница Paranoia (Mongoose)"},{name:"Core Book (DriveThruRPG)"}],quotes:[{text:"Хорошее издание Paranoia — движется в правильном направлении относительно Red Clearance Edition."},{text:"Чистка правил сохранена, но игра вернула себе самоиронию и остроту."}]},en:{tagShort:"Satirical dystopian dark-comedy RPG",tagline:`"The Computer is your friend. The Computer is happy. Be happy too. Or it's treason."`,description:"Paranoia is a comedic RPG set in the absurd dystopia of Alpha Complex, ruled by an insane Computer. You are Troubleshooters: you find trouble and shoot it — often each other. Everyone has six clones, secret membership in an illegal society, and a pile of treason to hide. The rules are deliberately light; everything runs on paranoia, backstabbing, and dark humour.",setting:"Alpha Complex is a sealed underground bunker of the future run by a paranoid AI called The Computer. Society is split into colour-coded security clearances; knowing about things above your clearance is treason. Mutants are treason. Secret societies are treason. And nearly everyone is a mutant in a secret society. Outside lies the Outdoors, which The Computer prefers not to think about.",vignette:"The Computer: 'Citizen, your clearance is RED. Why do you hold a BLUE card?' You: 'It's... evidence, I confiscated it from a traitor.' Your teammate quietly reaches for their laser. You roll NODE: four dice plus the Computer Die. Two sixes — success! But the Computer Die shows a 1. 'Citizen, malfunction logged. Dispatching a repair crew... and a replacement clone.'",prep:"~30 min",mechanics:[{title:"NODE dice",text:"Stat + skill = the Number Of DicE. Roll that d6 pool; 5s and 6s are successes. Simple and fast — the system stays out of the farce's way."},{title:"The Computer Die",text:"A red die in every roll. A 1 on it is the Computer intervening: a malfunction, a denouncement, sudden 'help'. Chaos strictly on schedule."},{title:"Six clones and Moxie",text:"Each character has six replacement clones and a pool of Moxie for stunts and survival. Death isn't the end, just an inconvenience and paperwork."},{title:"Treason and secret societies",text:"Everyone has a hidden agenda and forbidden membership. Denounce first — before you're denounced. Betrayal is built right into the rules."}],gallery:[{cap:"Spread — Alpha Complex art"},{cap:"Spread — the Troubleshooters"},{cap:"Spread — rules and The Computer"}],resources:[{name:"Paranoia page (Mongoose)"},{name:"Core Book (DriveThruRPG)"}],quotes:[{text:"This is a good edition of Paranoia, and moves the needle in the right direction from Red Clearance Edition."},{text:"The rules cleanup is kept and largely not messed with, but the game regains a bit of its self-awareness and edge."}]}}),registerSystem("pathfinder",{groups:{default:{key:"tactical",order:8},family:{key:"standalone",order:27},genre:{key:"tactical",order:6}},name:"Pathfinder 2e",publisher:"Paizo",dice:"d20 + modifiers",players:"3–6",complexity:4,free:!0,foundryStatus:"Community",heroImage:"https://cdn11.bigcommerce.com/s-e0sdfpgiwh/images/stencil/1280x1280/products/13791/458/XmlXLh1R__42781.1757988737.jpg?c=1",playstyleTags:["combat","explore","tactical"],settingTags:["fantasy"],gallery:[{src:"https://cdn11.bigcommerce.com/s-e0sdfpgiwh/images/stencil/1280x1280/products/13791/458/XmlXLh1R__42781.1757988737.jpg?c=1"},{src:"https://cdn11.bigcommerce.com/s-e0sdfpgiwh/images/stencil/1280x1280/products/13806/467/H2_5tOuE__42476.1755060900.jpg?c=1"},{src:"https://cdn11.bigcommerce.com/s-e0sdfpgiwh/images/stencil/1280x1280/products/184/472/2P9NAHsZ__09634.1755061996.jpg?c=1"}],resources:[{type:"link",url:"https://paizo.com/pathfinder/getstarted",fmt:"Web"},{type:"link",url:"https://2e.aonprd.com/PlayersGuide.aspx",fmt:"Web"},{type:"quickstart",url:"https://paizo.com/pathfinder/getstarted",fmt:"Web"}],mechanics:[{icon:"swords"},{icon:"dices"},{icon:"book-open"},{icon:"scroll"}],quotes:[{text:"Second Edition refines Pathfinder's tactical combat without losing the complexity that makes it so much fun at the table.",author:"Charlie Hall, Polygon"},{text:"I love this system. The mechanics of 2nd edition Pathfinder are a mix of 3.5, Pathfinder, and 4th edition and 5th edition DnD. Since I love all those games, I had no issues with all the best being blended together to make the best of everything.",author:"Edward Kabara, RPGnet"}],ru:{tagShort:"Тактическое d20-фэнтези",tagline:"«Глубина кастомизации и три действия — вот что делает бой живым».",description:"Pathfinder Second Edition — тактическая RPG от Paizo, вышедшая в 2019 году и обновлённая в рамках Remaster Project (2023–2024). d20-система с тремя действиями за ход, 16+ классами, десятками рас и архетипов, сотнями заклинаний. Полный SRD доступен бесплатно на Archives of Nethys. Игра, созданная из любви к D&D 3.5, ставшая самостоятельным гигантом.",setting:"Golarion — мир, где высокое фэнтези соседствует с пиратскими регионами, нежитью, стимпанком и мифическими царствами. Каждый континент — отдельный жанр: от Гаrunда (африканское вдохновение) до Мана-Пустошей (постапокалипсис). Другие планы и звёзды доступны через Planescapes.",vignette:"Три действия. Варвар берёт одно на рывок, второе — на удар топором, третье — на Regain Stamina. Жрец тратит два на Heal, одно на поддержку щита. Враг — огненный элементаль — атакует реакций. Бой быстр, но каждый бросок весомый: +10 к результату даёт критическое попадание.",prep:"~20 мин",mechanics:[{title:"Три действия (3-Action Economy)",text:"Каждый ход — ровно три действия. Рывок, атака, магия — всё стоит по одному. Никаких полудействий и конфигураций. Просто и элегантно."},{title:"Четыре градации успеха",text:"Критический провал → провал → успех → критический успех. Разница в 10 и более результатов меняет всё. Каждый +1 имеет значение."},{title:"Глубокая кастомизация",text:"Каждый класс с подклассами, наследия, архетипы, фиты на каждом уровне. Ваш варвар может стать заклинателем через мультикласс, а воровка — паладином."},{title:"Сбалансованная математика",text:"Уровень персонажа добавляется ко всем проверкам. Враг на 5 уровней выше почти неуязвим. Encounter-building математика — одна из лучших в индустрии."}],gallery:[{cap:"Player Core (Remaster, 2023)"},{cap:"Core Rulebook (2019)"},{cap:"Player Core 2 (2024)"}],resources:[{name:"Официальный сайт — Paizo"},{name:"Archives of Nethys (SRD)"},{name:"Beginner Box (быстрый старт)"}],quotes:[{text:"Второе издание усовершенствовало тактический бой Pathfinder, не теряя глубины, которая делает эту игру такой увлекательной за столом."},{text:"Я обожаю эту систему. Механики второго издания — это смесь 3.5, Pathfinder, 4-го и 5-го изданий DnD. Всё лучшее собрано воедино."}]},en:{tagShort:"Tactical d20 fantasy with deep customization",tagline:'"Three actions, four degrees of success — every roll matters."',description:"Pathfinder Second Edition is a tactical tabletop RPG from Paizo, released in 2019 and refreshed through the Remaster Project (2023–2024). A d20 system with a 3-action economy, 16+ classes, dozens of ancestries and archetypes, and hundreds of spells. The full SRD is free on Archives of Nethys. Born from love of D&D 3.5, it became a giant in its own right.",setting:"Golarion — a world where high fantasy sits alongside pirate kingdoms, undead realms, steampunk, and mythic planes. Each continent is its own genre: from Arcadia to the Mwangi Expanse to the Lands of the Linnorm Kings. Other planes and stars are reachable through Planescape-like portals.",vignette:"Three actions. The barbarian spends one to Rage, one to Strike with his axe, one to Regain Stamina. The cleric burns two on Heal, one to raise a shield. The enemy — an fire elemental — attacks with a reaction. Combat is fast, but every roll carries weight: +10 to the result means a critical hit.",prep:"~20 min",mechanics:[{title:"3-Action Economy",text:"Every turn is exactly three actions. Stride, Strike, cast — each costs one. No half-actions, no configurations. Simple and elegant."},{title:"Four Degrees of Success",text:"Critical failure → failure → success → critical success. A 10+ difference in the result changes everything. Every +1 matters."},{title:"Deep Customization",text:"Every class with subclasses, heritages, archetypes, feats at every level. Your barbarian can become a caster through multiclassing, your rogue can become a paladin."},{title:"Balanced Math",text:"Character level adds to all checks. An enemy 5 levels higher is nearly invulnerable. Encounter-building math is among the best in the industry."}],gallery:[{cap:"Player Core (Remaster, 2023)"},{cap:"Core Rulebook (2019)"},{cap:"Player Core 2 (2024)"}],resources:[{name:"Official site — Paizo"},{name:"Archives of Nethys (SRD)"},{name:"Beginner Box (quick start)"}],quotes:[{text:"Second Edition refines Pathfinder's tactical combat without losing the complexity that makes it so much fun at the table."},{text:"I love this system. The mechanics of 2nd edition Pathfinder are a mix of 3.5, Pathfinder, and 4th edition and 5th edition DnD. All the best being blended together."}]}}),registerSystem("pendragon",{groups:{default:{key:"narrative",order:42},family:{key:"standalone",order:50},genre:{key:"historical",order:1}},name:"Pendragon",publisher:"Chaosium",dice:"d20 roll-under",players:"2–6",complexity:4,free:!1,edition:"6th ed. (2024)",foundryStatus:"Community",heroImage:"https://cdn11.bigcommerce.com/s-9zhx02uo/images/stencil/1280x996/products/2413/6075/Pendragon_Core_Rulebook_-_Front_Cover_-_700x900__17451.1714992659.png?c=2",playstyleTags:["narrative","social","combat"],settingTags:["historical","fantasy"],gallery:[{src:"https://cdn11.bigcommerce.com/s-9zhx02uo/images/stencil/1280x996/products/2413/6116/Pendragon_-_Core_-_Spread_1__48660.1715007255.png?c=2"},{src:"https://cdn11.bigcommerce.com/s-9zhx02uo/images/stencil/1280x996/products/2413/6117/Pendragon_-_Core_-_Spread_2__38931.1715007255.png?c=2"},{src:"https://cdn11.bigcommerce.com/s-9zhx02uo/images/stencil/1280x996/products/2413/6073/Pendragon_Core_Rulebook_-_Introduction_1_-_700x900__83987.1707309893.1280.1280__57661.1715007253.png?c=2"}],resources:[{type:"quickstart",url:"https://www.chaosium.com/pendragon-quick-start/",fmt:"PDF"},{type:"rules",url:"https://www.chaosium.com/pendragon-core-rulebook-hardcover/",fmt:"Print/PDF"},{type:"link",url:"https://foundryvtt.com/packages/pendragon",fmt:"Foundry VTT"}],mechanics:[{icon:"scale"},{icon:"heart"},{icon:"crown"},{icon:"hourglass"}],quotes:[{text:"This new edition of the classic Pendragon roleplaying game is absolutely terrific and is no doubt going to be the crowning achievement in the series.",author:"Jeff McAleer, The Gaming Gang"},{text:"It's a flawed restatement of a game that has earned its place in the pantheon of foundational RPGs.",author:"Jared Rascher, Gnome Stew"}],ru:{tagShort:"Рыцарство Артура сквозь поколения",tagline:"«Добывайте Славу, чтите свои Страсти и передавайте меч наследнику».",description:"Pendragon делает вас рыцарем легендарной Британии короля Артура, начиная с бурного периода Юного Короля. Вместо добычи из подземелий вы стремитесь к Славе, боретесь с противоположными добродетелями и позволяете Страстям — любви, верности — вести вас к героическим и трагическим решениям. Игра охватывает десятилетия: рыцари стареют, женятся и гибнут, передавая хронику наследникам. Итоговое шестое издание Chaosium оттачивает прославленную систему Грега Стаффорда в широкое повествование о чести, войне и любви.",setting:"Постримская Британия, переосмысленная через артуровский роман. Рыцари игроков происходят из Солсбери в королевстве Логрия и служат среди саксонских вторжений, распрей знати, колдовства фей и медленного восхода Камелота — хроника, разворачивающаяся год за годом.",vignette:"Саксонский берсерк бросается на вашего рыцаря у брода. Вы объявляете попытку вдохновения по Страсти Верность (Сеньору) 15 и бросаете d20 — выпадает 9, ниже значения. Вдохновлённый, вы прибавляете +10 к Мечу 18; ваш встречный бросок сокрушает его защиту, и вы выбиваете его из седла с одного захода.",prep:"~45 мин",mechanics:[{title:"Черты характера",text:"Тринадцать пар противоположных добродетелей, каждая в сумме даёт 20 — например, Отважный против Трусливого. Бросок ниже Черты может заставить рыцаря повести себя благородно или постыдно, хотели вы того или нет."},{title:"Страсти",text:"Любовь, Верность, Гостеприимство и Ненависть отражают глубинные порывы рыцаря. Призовите одну и бросьте ниже её значения ради прилива вдохновения в кризис — но провал оставит вас в унынии или безумии."},{title:"Слава",text:"Каждый подвиг, пир и акт щедрости приносит Славу вместо опыта. Она измеряет известность рыцаря за всю жизнь и может даже возвысить целый род до легендарного статуса."},{title:"Игра поколений",text:"Каждый игровой год завершается Зимней фазой: старение, раны, урожай и рождение детей. Рыцари стареют и гибнут, и кампания переходит к сыновьям, дочерям и наследникам сквозь десятилетия."}],gallery:[{cap:"Разворот из основной книги шестого издания."},{cap:"Правила и артуровские иллюстрации бок о бок."},{cap:"Внутренний арт, передающий дух легендарной Британии."}],resources:[{name:"Быстрый старт Pendragon (бесплатно)"},{name:"Основная книга правил (твёрдый переплёт + PDF)"},{name:"Любительская система для Foundry VTT"}],quotes:[{text:"Это новое издание классической ролевой игры Pendragon совершенно великолепно и, без сомнения, станет вершиной серии."},{text:"Это небезупречное переизложение игры, заслужившей своё место в пантеоне основополагающих настольных ролевых игр."}]},en:{tagShort:"Arthurian chivalry across generations",tagline:'"Win Glory, honor your Passions, and pass the sword to your heir."',description:"Pendragon casts you as a knight in the legendary Britain of King Arthur, from the turbulent Boy King period onward. Rather than dungeon loot, you chase Glory, wrestle with opposed virtues, and let Passions like love and loyalty drive heroic and tragic choices. Play spans decades: knights age, marry, and die, handing the campaign to their heirs. Chaosium's definitive 6th edition refines Greg Stafford's celebrated system into a sweeping chronicle of honor, war, and romance.",setting:"Sub-Roman Britain reimagined through Arthurian romance. Player-knights hail from Salisbury in the kingdom of Logres, serving amid Saxon invasions, feuding nobles, faerie enchantment, and the slow rise of Camelot across a chronicle that unfolds year by year.",vignette:"A Saxon berserker charges your knight at the ford. You declare an inspiration attempt on your Passion Loyalty (Lord) 15 and roll a d20 — a 9, under the value. Inspired, you add +10 to your Sword of 18; your opposed roll crushes his defense and you unhorse him in a single pass.",prep:"~45 min",mechanics:[{title:"Personality Traits",text:"Thirteen opposed virtue pairs, each summing to 20 — like Valorous versus Cowardly. A roll under your Trait can compel your knight to act nobly or shamefully, whether you wanted it or not."},{title:"Passions",text:"Love, Loyalty, Hospitality, and Hate rate your knight's deepest drives. Invoke one and roll under it for a surge of inspiration in a crisis — but failure can leave you melancholic or maddened."},{title:"Glory",text:"Every deed, feast, and act of largesse earns Glory instead of experience. It measures a knight's renown across a lifetime and can even raise a whole family line toward legendary status."},{title:"Generational Play",text:"Each game year closes with a Winter Phase resolving aging, wounds, harvests, and childbirth. Knights grow old and fall, so the campaign passes to sons, daughters, and heirs across decades."}],gallery:[{cap:"A double-page spread from the 6th edition core rulebook."},{cap:"Rules and Arthurian illustration set side by side."},{cap:"Interior art evoking the legendary Britain of the setting."}],resources:[{name:"Pendragon Quick-Start (free)"},{name:"Core Rulebook (hardcover + PDF)"},{name:"Community Foundry VTT system"}],quotes:[{text:"This new edition of the classic Pendragon roleplaying game is absolutely terrific and is no doubt going to be the crowning achievement in the series."},{text:"It's a flawed restatement of a game that has earned its place in the pantheon of foundational RPGs."}]}}),registerSystem("pirate-borg",{groups:{default:{key:"osr",order:7},family:{key:"borg",order:3},genre:{key:"dark-fantasy",order:3}},name:"Pirate Borg",publisher:"Limithron / Free League Publishing",dice:"d20 + d6",players:"2–6",complexity:1,foundryStatus:"Community",heroImage:"https://freeleaguepublishing.com/wp-content/uploads/2023/09/pirateborg-1440x720.jpg",playstyleTags:["explore","survival","sandbox"],settingTags:["historical","fantasy"],gallery:[{src:"https://freeleaguepublishing.com/wp-content/uploads/2023/09/pirateborg-1440x720.jpg"}],resources:[{type:"link",url:"https://www.limithron.com/pirateborg",fmt:"Web"},{type:"link",url:"https://freeleaguepublishing.com/games/pirate-borg/",fmt:"Web"}],mechanics:[{icon:"anchor"},{icon:"skull"},{icon:"zap"},{icon:"users"}],quotes:[{text:"With nautical lore, naval combat, and Lovecraftian horror, Pirate Borg is everything anyone could want in a sea-faring TTRPG.",author:"Austin King, Screen Rant"}],ru:{tagShort:"Проклятые пираты арт-панк RPG",tagline:"«Ваша сабля и пистоль не спасут вас от орд скелетов, Кракена и даже собственной команды.»",description:"PIRATE BORG — прогнившая, лёгкая на правила и тяжёлая на искусство RPG, выросшая из art-punk движка Mörk Borg и пересаженная на проклятые Карибы, пропитанные ромом, порохом и нежитью. Восемь классов, правила морских сражений, 18 кораблей и 80+ монстров.",setting:"Тёмные Карибы: колониальный архипелаг, сломленный в день солнцестояния, когда из моря поднялось то, что назвали Скверной. Плоты, набитые голодными зомби, дрейфуют по волнам; проклятые галеоны рыщут по торговым путям; в глубинах ворочается Кракен.",vignette:"Шлюп огибает мыс, и вот он — призрачный галеон: ни фонарей, сидит слишком высоко в воде. Буканьер говорит: «Поворачиваем.» Бродяга уже считает его пушки. Вы бросаете Присутствие, чтобы прочитать ветер... 14. На планшире появляется фигура. Она в капитанском камзоле, который вы схоронили два года назад.",prep:"~15 мин",mechanics:[{title:"Морской бой",text:"Корабли имеют характеристики, как персонажи: бортовой залп, таран, команда, груз. Тактическое движение по гексам, абордаж и морские шанти."},{title:"Дьявольская Удача",text:"Пул очков для перебросов, автоуспехов или чтобы не умереть. Когда закончатся — молитесь."},{title:"Броски только у игроков",text:"Враги никогда не бросают. d20 + модификатор против сложности 12. Бои стремительны и смертоносны."},{title:"Восемь классов",text:"Бродяга, Головорез, Громила, Фанатик, Чародей, Буканьер, Байки и Душа-Призрак."}],gallery:[{cap:"Обложка основной книги"}],resources:[{name:"Официальный сайт (Limithron)"},{name:"Free League Publishing"}],quotes:[{text:"С морским лором, морскими боями и лавкрафтовским ужасом Pirate Borg — это всё, чего можно желать от настольной игры о море."}]},en:{tagShort:"cursed pirate art-punk RPG",tagline:`"Your cutlass and flintlock won't save you from the hordes of skeletons, the Kraken, or even your own crew."`,description:"PIRATE BORG is a scurvy-ridden, rules-light, art-heavy RPG built on the doom art-punk engine of Mörk Borg — transplanted to a cursed Caribbean soaked in rum, gunpowder, and undead horror. Eight character classes, naval combat rules, 18 vessels, and 80+ monsters fit into 168 gorgeous, chaotic pages.",setting:"The Dark Caribbean: a colonial-era archipelago that broke during a solstice when something called the Scourge rose from the sea. Rafts overflowing with flesh-hungry zombies drift on the waves; cursed galleons crewed by skeletons prowl the shipping lanes; the Kraken stirs in the deep. Port towns cling to survival behind cannon walls.",vignette:"The sloop rounds a headland and there it is — a ghost galleon, no lanterns, riding too high in the water. The Buccaneer says: 'We turn back.' The Rapscallion is already counting the cannons. You roll Presence to read the wind... 14. The galleon is drifting, no crew visible. You close the distance. A figure appears at the rail. It's wearing the captain's coat you buried two years ago.",prep:"~15 min",mechanics:[{title:"Naval Combat",text:"Ships have stats like characters — broadsides, ram, crew, cargo. Tactical hex movement, boarding actions, and sea shanties that give your whole crew a bonus."},{title:"Devil's Luck",text:"A pool of points each character starts with. Spend them to reroll dice, pass a test automatically, or cheat death. Once gone, pray."},{title:"Player-Side Rolls",text:"Enemies never roll. PCs roll to defend against attacks, d20 + ability modifier vs. difficulty 12. Combats are fast and lethal."},{title:"Eight Classes",text:"Rapscallion, Swashbuckler, Brute, Zealot, Sorcerer, Buccaneer — plus the wild-card Tall Tale and the cursed Haunted Soul. Each plays completely differently."}],gallery:[{cap:"Core Rulebook cover"}],resources:[{name:"Official website (Limithron)"},{name:"Free League Publishing page"}]}}),registerSystem("runequest",{groups:{default:{key:"tactical",order:4},family:{key:"standalone",order:18},genre:{key:"dark-fantasy",order:9},solo:{key:"solo-compatible",order:14}},name:"RuneQuest",publisher:"Chaosium",dice:"d100 (BRP)",players:"3–5",complexity:4,foundryStatus:"Community",heroImage:"https://cdn11.bigcommerce.com/s-9zhx02uo/images/stencil/1280x996/products/2008/3329/CHA4028%5F-%5FRuneQuest%5F-%5FRoleplaying%5Fin%5FGlorantha%5F-%5FFront%5FCover%5F700x900%5F-%5FPDF%5F%5F35886.1552356121.jpg?c=2",playstyleTags:["combat","worldbuild","explore"],settingTags:["fantasy"],gallery:[{src:"https://cdn11.bigcommerce.com/s-9zhx02uo/images/stencil/1280x996/products/2008/2530/CHA4028%5F-%5FRuneQuest%5F-%5FRoleplaying%5Fin%5FGlorantha%5F-%5FBack%5FCover%5F%5F80526.1527905727.jpg?c=2"},{src:"https://cdn11.bigcommerce.com/s-9zhx02uo/images/stencil/1280x996/products/2008/2539/CHA4028%5F-%5FRuneQuest%5F-%5FRoleplaying%5Fin%5FGlorantha%5F-%5FPage%5F13%5F-%5FGlorantha%5F%5F97403.1527905728.jpg?c=2"},{src:"https://cdn11.bigcommerce.com/s-9zhx02uo/images/stencil/1280x996/products/2008/2548/CHA4028%5F-%5FRuneQuest%5F-%5FRoleplaying%5Fin%5FGlorantha%5F-%5FPage%5F84%5F-%5FPreGen%5F%5F56787.1527905729.jpg?c=2"},{src:"https://cdn11.bigcommerce.com/s-9zhx02uo/images/stencil/1280x996/products/2008/2531/CHA4028%5F-%5FRuneQuest%5F-%5FRoleplaying%5Fin%5FGlorantha%5F-%5FPage%5F5%5F-%5FIntroduction%5F%5F52469.1527905727.jpg?c=2"}],resources:[{type:"link",url:"https://www.chaosium.com/runequest-rpg/",fmt:"Web"},{type:"sheet",url:"https://www.chaosium.com/content/FreePDFs/RuneQuest/Character%20Sheets/RuneQuest%20Glorantha%20-%20Character%20Sheet%20-%20Fillable.pdf",fmt:"PDF"},{type:"quickstart",url:"https://www.chaosium.com/content/FreePDFs/RuneQuest/CHA4027%20-%20RuneQuest%20Quickstart.pdf",fmt:"PDF"},{type:"quickstart",url:"https://www.chaosium.com/content/FreePDFs/RuneQuest/CHA4027%20-%20RuneQuest%20Quickstart%20Adventurers.pdf",fmt:"PDF"}],mechanics:[{icon:"circle"},{icon:"target"},{icon:"heart"},{icon:"flame"}],quotes:[{text:"where historic realism mixes with raw, primitive magic that hangs in the air like early morning mist",author:"Richard Jansen-Parkes, Tabletop Gaming"},{text:"breaks away from the core tropes of gleaming armour and codified magic that have come to dominate fantasy in recent decades and replaces it with something that feels closer to ancient myths and legends – more The Odyssey than Lord of the Rings.",author:"EN World"}],ru:{tagShort:"Бронзовый век, мифы и руны Глоранты",tagline:"«Не фэнтези про эльфов. Мифический мир, где боги ходят по земле, а руна Истины — это не флаф, а механика».",description:"Прародитель всей линейки BRP — той самой системы, что породила Call of Cthulhu. d100 процентные навыки, зоны попадания, никаких уровней: персонаж растёт через применение умений. Издание 2018 года — прямой наследник RQ2 1980-го, переизданный Chaosium с подачи Грега Стаффорда. Жёсткая, вдумчивая, мифологическая.",setting:"Глоранта — бронзовый век, придуманный Грегом Стаффордом ещё в 1966 году. Здесь мифы буквальны: солнце — это бог, который умер и вернулся, руны — реальные силы мироздания, а культы определяют судьбу сильнее, чем класс или раса. Драгон Пасс, Сартар, Лунная Империя. Орланти-варвары против лунарской магии. Утки, тролли, эльфы-растения. Мир, который НЕ похож на Толкина — он глубже, страннее, антропологичнее.",vignette:"Васана, всадница Орланти с рунами Воздуха 75% и Движения 60%, страсть «Любовь к Сартару 80%». Бой с лунарским пехотинцем. Кидаете d100 на Меч (Broadsword): 23, успех. Локация попадания — d20: 07, левая нога. Урон 1d8+1d4: 9 пунктов, броня кожи поглощает 2. Нога повреждена — половина HP локации. Васана хромает, штраф к Движению. Следующий ход: тратите Магические Очки на спирит-магию «Heal 4». Рука мага на ноге, рана закрывается. Но руна Истины ноет — вы поклялись не отступать.",prep:"~60 мин",mechanics:[{title:"Руны и страсти",text:"У персонажа есть рунические сродства (Воздух, Истина, Движение…) и страсти («Ненависть к лунарам 80%»). Это не просто декорация — вы кидаете по ним d100 как по навыку, и они меняют исход сцен."},{title:"Зоны попадания",text:"Каждый удар — d20 на локацию: голова, грудь, рука, нога. Руки и ноги имеют свой HP. Сломали ногу — персонаж падает. Голову — почти смерть. Бой решает всё."},{title:"d100 без уровней",text:"Процентные навыки. Используете умение — растёт. Никаких уровней, никаких классов. Кузнец после 20 сессий — реально кузнец на 90%, а не «воин 5 уровня»."},{title:"Магия от культов",text:"Спирит-магия (Heal, Disrupt) доступна почти всем; Рун-магия — это чудеса вашего бога. Орланти даёт Wind Words и Lightning, Хумакт — Sword Trance. Магия — часть веры, не сборник заклинаний."}],gallery:[{cap:"Задняя обложка"},{cap:"Глоранта — мир"},{cap:"Преген-персонажи"},{cap:"Введение"}],resources:[{name:"Официальный сайт"},{name:"Лист персонажа (fillable)"},{name:"Quickstart The Broken Tower"},{name:"Преген-персонажи Quickstart"}],quotes:[{text:"где исторический реализм смешан с сырой первобытной магией, что висит в воздухе как утренний туман"},{text:"уходит от расхожих тропов сверкающих доспехов и кодифицированной магии, что захватили фэнтези в последние десятилетия, и заменяет их чем-то, что ближе к древним мифам и легендам — скорее «Одиссея», чем «Властелин колец»."}]},en:{tagShort:"Bronze-age myth, runes, hit locations",tagline:'"Not fantasy with elves. A mythic world where gods walk and the Truth rune is mechanics, not flavor."',description:"The grandparent of the entire BRP family — the system that birthed Call of Cthulhu. d100 percentile skills, hit locations, no levels: characters grow by using skills. The 2018 edition is a direct sequel to RQ2 (1980), reissued by Chaosium under Greg Stafford's guidance. Gritty, deliberate, mythological.",setting:"Glorantha — a bronze-age world Greg Stafford has been building since 1966. Myths are literal: the sun is a god who died and returned, runes are actual cosmic forces, and cults shape destiny more than class or race ever could. Dragon Pass, Sartar, the Lunar Empire. Orlanthi barbarians vs. Lunar magic. Ducks, trolls, plant-elves. A world that is NOT Tolkien — deeper, weirder, anthropological.",vignette:"Vasana, an Orlanthi rider with Air rune 75%, Movement 60%, passion 'Love (Sartar) 80%'. Fighting a Lunar hoplite. Roll d100 vs. Broadsword: 23, success. Hit location d20: 07, left leg. Damage 1d8+1d4: 9 points, leather absorbs 2. The leg is wounded — half HP for that location. Vasana limps, Movement penalty. Next round: spend Magic Points on Spirit Magic 'Heal 4'. Your hand on the leg, the wound knits. But your Truth rune aches — you swore never to retreat.",prep:"~60 min",mechanics:[{title:"Runes & passions",text:"Your character has rune affinities (Air, Truth, Movement…) and passions ('Hate Lunars 80%'). Not flavor text — you roll them as d100 skills, and they swing scenes."},{title:"Hit locations",text:"Every hit rolls d20 for body part: head, chest, arm, leg. Limbs have their own HP. Break a leg — your fighter drops. Head shot — likely fatal. Combat is consequential."},{title:"d100 with no levels",text:"Percentile skills. Use a skill, it grows. No levels, no classes. After 20 sessions, your blacksmith is genuinely 90% at smithing — not a 'fighter 5 with tool proficiency'."},{title:"Cult magic",text:"Spirit Magic (Heal, Disrupt) is broadly available; Rune Magic is the miraculous gift of your god. Orlanth grants Wind Words and Lightning; Humakt grants Sword Trance. Magic is faith, not a spellbook."}],gallery:[{cap:"Back cover"},{cap:"Glorantha — the world"},{cap:"Pregen characters"},{cap:"Introduction"}],resources:[{name:"Official website"},{name:"Fillable character sheet"},{name:"Quickstart The Broken Tower"},{name:"Quickstart pregen adventurers"}]}}),registerSystem("savage-worlds",{groups:{default:{key:"tactical",order:13},family:{key:"standalone",order:34},genre:{key:"tactical",order:9}},name:"Savage Worlds",publisher:"Pinnacle Entertainment Group",dice:"step-dice (d4–d12)",players:"3–5",complexity:2,free:!0,foundryStatus:"Official",heroImage:"https://www.belloflostsouls.net/wp-content/uploads/2020/05/savage-worlds.png",playstyleTags:["combat","narrative","explore"],settingTags:[],gallery:[{src:"https://www.seekpng.com/png/detail/890-8905220_savage-worlds-savage-worlds-adventure-edition.png"},{src:"https://sessionzero.games/images/systems/savage-worlds-g1.jpeg"},{src:"https://www.belloflostsouls.net/wp-content/uploads/2020/05/savage-worlds.png"}],resources:[{type:"link",url:"https://peginc.com/savage-settings/savage-worlds/",fmt:"Web"},{type:"link",url:"https://shop.peginc.com/collections/savage-worlds-adventure-edition",fmt:"Web"},{type:"quickstart",url:"https://peginc.com/store/deadlands-the-weird-west-blood-on-the-range-savage-worlds-test-drive-swade/",fmt:"PDF"}],mechanics:[{icon:"swords"},{icon:"dices"},{icon:"book-open"},{icon:"scroll"}],quotes:[{text:"Got a life? d20 becoming too much work? Savage Worlds is a lean, mean gaming machine. If you've been looking for an rpg that combines a minimum of prep time with a maximum of useful, crunchy bits — this one's for you.",author:"Creel, RPGnet"},{text:"Fast, Furious, Fun — it's not just a tagline, it's a mission statement!",author:"Jamie Herbert, RPGnet"}],ru:{tagShort:"Универсальная pulpy на step-dice",tagline:"«Быстро, яростно, весело! — это не слоган, это манифест».",description:"Savage Worlds — универсальная настольная RPG от Pinnacle Entertainment Group (Adventure Edition, 2018). Step-dice система: персонажи (Wild Cards) бросают свой трейт-кубик + d6 (Wild Die), оставляя больший. Кубики взрываются (Aces) на максимуме. Цель — 4, превышение на +4+ даёт Raise. Инициатива — через колоду карт. Бенни — мета-валюта для перебросов. Мир Deadlands, Rifts, Pathfinder — всё на одном движке.",setting:"Жанр-agnostic. Savage Worlds не привязана к миру — она создаёт мир через Setting Rules и модульные Edge/Hindrances. Официальные сеттинги: Deadlands (хоррор-вестерн), Rifts (межпространственный хаос), Pathfinder (фэнтези), Necessary Evil (суперзлодеи), 50 Fathoms (пиратское фэнтези).",vignette:"Ковбой бросает d8 (Shooting) + Wild Die d6. Взрыв на d8: 8+6+4 = 18! Два Raise! Пуля прошивает.bandit'а насквозь. Бенни лежит на столе — ждёт следующего хода. Карты инициативы разложены: туз — первый ход. Добро пожаловать в Дикую Запад.",prep:"~10 мин",mechanics:[{title:"Step-Dice (d4–d12)",text:"Каждый трейт — от d4 до d12. Бросаешь трейт + Wild Die d6, оставляешь больший. Кубики взрываются (Aces) на максимуме. Простая, но драматичная математика."},{title:"Wild Cards и Extras",text:"Игроки — Wild Cards (3 Wounds до incapacitate). Враги — Extras (up, down, или off the table). Простая эскалация: от одиночек до армий."},{title:"Бенни",text:"Мета-валюта: перебрось провал, впитай урон, получи Raise. Заработай через ролеплей или щедрость MC."},{title:"Колода инициативы",text:"Стандартная колода карт для определения порядка ходов. Туз — первый. Джокер — +2 ко всему и ход когда хочешь."}],gallery:[{cap:"SWADE — логотип"},{cap:"Обложка (Geekerati)"},{cap:"SWADE Core Rulebook"}],resources:[{name:"Официальный сайт — Pinnacle Entertainment Group"},{name:"Магазин — купить SWADE"},{name:"Test Drive (бесплатный квикстарт PDF)"}],quotes:[{text:"Есть жизнь? d20 стало слишком сложно? Savage Worlds — это стройная, голодная игровая машина. Если вы искали RPG, совмещающую минимум подготовки с максимумом полезных, хрунчевых деталей — это для вас."},{text:"Быстро, яростно, весело — это не просто слоган, это манифест!"}]},en:{tagShort:"Universal pulpy step-dice — Fast! Furious! Fun!",tagline:`"Fast, Furious, Fun — it's not just a tagline, it's a mission statement!"`,description:"Savage Worlds is a universal tabletop RPG from Pinnacle Entertainment Group (Adventure Edition, 2018). Step-dice system: Wild Cards roll their trait die + a Wild Die d6, keeping the higher. Dice explode (Ace) on their max. Target is 4; beating by +4+ gives a Raise. Initiative via playing cards. Bennies are metagame currency for rerolls. Settings include Deadlands, Rifts, Pathfinder — all on one engine.",setting:"Genre-agnostic. Savage Worlds builds worlds through Setting Rules and modular Edges/Hindrances. Official settings: Deadlands (horror-western), Rifts (dimensional chaos), Pathfinder (fantasy), Necessary Evil (supervillains), 50 Fathoms (swashbuckling fantasy).",vignette:"The cowboy rolls d8 (Shooting) + Wild Die d6. Ace on d8: 8+6+4 = 18! Two Raises! The bullet tears through the bandit. Bennies sit on the table — waiting for the next turn. Initiative cards spread: Ace goes first. Welcome to the Weird West.",prep:"~10 min",mechanics:[{title:"Step-Dice (d4–d12)",text:"Each trait runs from d4 to d12. Roll trait + Wild Die d6, keep higher. Dice explode (Ace) on max. Simple but dramatic math."},{title:"Wild Cards & Extras",text:"Players are Wild Cards (3 Wounds to incapacitate). Enemies are Extras (up, down, or off the table). Simple escalation: from loners to armies."},{title:"Bennies",text:"Metagame currency: reroll a failure, soak damage, get a Raise. Earned through roleplay or GM generosity."},{title:"Initiative Deck",text:"Standard poker deck determines turn order. Ace goes first. Joker = +2 to everything and go whenever you want."}],gallery:[{cap:"SWADE — logo"},{cap:"Cover art (Geekerati)"},{cap:"SWADE Core Rulebook"}],resources:[{name:"Official site — Pinnacle Entertainment Group"},{name:"Store — buy SWADE"},{name:"Test Drive (free quickstart PDF)"}],quotes:[{text:"Got a life? d20 becoming too much work? Savage Worlds is a lean, mean gaming machine. If you've been looking for an rpg that combines a minimum of prep time with a maximum of useful, crunchy bits — this one's for you."},{text:"Fast, Furious, Fun — it's not just a tagline, it's a mission statement!"}]}}),registerSystem("scum-and-villainy",{groups:{default:{key:"narrative",order:37},family:{key:"pbta-fitd",order:29},genre:{key:"sci-fi",order:15}},name:"Scum and Villainy",publisher:"Evil Hat Productions",dice:"Forged in the Dark (d6 pools)",players:"3–5",complexity:2,foundryStatus:"Community",heroImage:"https://evilhat.com/wp-content/uploads/2018/06/SV_1.jpg",playstyleTags:["narrative","social","combat"],settingTags:["space"],gallery:[{src:"https://evilhat.com/wp-content/uploads/2018/06/SV_2.jpg"},{src:"https://evilhat.com/wp-content/uploads/2018/06/SV_3.jpg"},{src:"https://evilhat.com/wp-content/uploads/2018/06/SV_4.jpg"}],resources:[{type:"link",url:"https://evilhat.com/product/scum-and-villainy/",fmt:"Web"}],mechanics:[{icon:"dices"},{icon:"rocket"},{icon:"target"},{icon:"users"}],quotes:[{text:"It captures the feel of being a space criminal, bound for fortune and glory, while providing some substantive rules on which to hang a narrative.",author:"Jared Rascher, Gnome Stew"},{text:"If you love Firefly, Star Wars, or Killjoys I can really recommend this as a great introduction to what I think is one of the finest systems around.",author:"Iain McAllister, There Will Be Games"}],ru:{tagShort:"Космические жулики на движке Forged in the Dark",tagline:"«Разношёрстный экипаж, ушатанный корабль и работа, от которой не отказываются».",description:"Scum and Villainy — космическая опера на движке Forged in the Dark (том же, что в Blades in the Dark). Вы — экипаж потрёпанного звездолёта на окраине сектора Проциона: контрабандисты, охотники за головами и бунтари, что берутся за рискованные дела. Дух «Светлячка» и «Звёздных войн»: слишком много долгов, слишком мало топлива и слишком опасная работа.",setting:"Сектор Проциона под железной пятой Галактической Гегемонии. Криминальные синдикаты, враждующие благородные дома, чужие расы и странные мистики. Ваш корабль — дом и главный актив, а Гегемония дышит в спину. Романтика космических отбросов: свобода дорого стоит, а каждый удачный куш лишь оттягивает расплату.",vignette:"Груз спрятан, но патруль Гегемонии стыкуется для досмотра. Пилот хочет проскочить: бросок действия — пул d6 по рейтингу. Позиция рискованная, эффект стандартный. Выпало 4 — успех с осложнением. Вы отрываетесь, но сжигаете последнее топливо и получаете Жар. В FitD провалов «в пустоту» нет — есть цена, которую платит экипаж.",prep:"~15 мин",mechanics:[{title:"Forged in the Dark",text:"Действие — пул d6 с Позицией и Эффектом; 6 — успех, 4–5 — успех с ценой, 1–3 — провал. Последствия можно сопротивляться через Стресс. Тот же движок, что в Blades in the Dark."},{title:"Корабль как персонаж",text:"Звездолёт (Stardancer, Cerberus…) — полноценный «герой» со своими апгрейдами, характером и уроном. Это дом экипажа, его гордость и вечная статья расходов."},{title:"Дела и передышки",text:"Структура «дело → передышка»: берёте рискованный заказ, затем восстанавливаетесь, лечите Стресс и ведёте проекты. Жар и Гегемония преследуют вас между кушами."},{title:"Плейбуки космических отбросов",text:"Механик, Мускул, Пилот, Пройдоха, Оратор, Штопальщик, Мистик — архетипы прямиком из «Светлячка» и «Звёздных войн». Каждый задаёт свою роль в экипаже."}],gallery:[{cap:"Интерьерный арт"},{cap:"Сцена в секторе Проциона"},{cap:"Экипаж и корабль"}],resources:[{name:"Официальная страница — Evil Hat"}],quotes:[{text:"Игра ухватывает ощущение космического преступника в погоне за богатством и славой, при этом давая содержательные правила, на которые можно опереть повествование."},{text:"Если вы любите «Светлячка», «Звёздные войны» или «Killjoys» — от всей души рекомендую это как отличное знакомство с одной из лучших, на мой взгляд, систем."}]},en:{tagShort:"Space scoundrels on the Forged in the Dark engine",tagline:`"A ragtag crew, a beat-up ship, and a job you can't turn down."`,description:"Scum and Villainy is a space opera on the Forged in the Dark engine (the same one behind Blades in the Dark). You're the crew of a battered starship on the edge of the Procyon Sector: smugglers, bounty hunters, and rebels taking on risky jobs. The vibe is Firefly and Star Wars: too much debt, too little fuel, and work that's far too dangerous.",setting:"The Procyon Sector under the iron heel of the Galactic Hegemony. Criminal syndicates, feuding noble houses, dangerous aliens, and strange mystics. Your ship is home and your main asset, and the Hegemony breathes down your neck. The romance of space scum: freedom is costly, and every big score just delays the reckoning.",vignette:"The cargo is hidden, but a Hegemony patrol docks for inspection. The pilot wants to run: an action roll — a d6 pool by rating. Risky position, standard effect. A 4 — success with a complication. You break away, but burn the last of your fuel and take Heat. In FitD there are no failures 'into the void' — only a price the crew pays.",prep:"~15 min",mechanics:[{title:"Forged in the Dark",text:"An action is a d6 pool with Position and Effect; a 6 succeeds, 4–5 succeeds at a cost, 1–3 fails. Consequences can be resisted with Stress. The same engine as Blades in the Dark."},{title:"The ship as a character",text:"The starship (the Stardancer, the Cerberus…) is a full 'character' with its own upgrades, personality, and damage. It's the crew's home, their pride, and a permanent line of expenses."},{title:"Jobs and downtime",text:"A 'score → downtime' structure: take a risky job, then recover, heal Stress, and run projects. Heat and the Hegemony hound you between scores."},{title:"Space-scoundrel playbooks",text:"Mechanic, Muscle, Pilot, Scoundrel, Speaker, Stitch, Mystic — archetypes straight out of Firefly and Star Wars. Each frames your role in the crew."}],gallery:[{cap:"Interior art"},{cap:"A scene in the Procyon Sector"},{cap:"Crew and ship"}],resources:[{name:"Official page — Evil Hat"}],quotes:[{text:"It captures the feel of being a space criminal, bound for fortune and glory, while providing some substantive rules on which to hang a narrative."},{text:"If you love Firefly, Star Wars, or Killjoys I can really recommend this as a great introduction to what I think is one of the finest systems around."}]}}),registerSystem("shadowdark",{groups:{default:{key:"osr",order:8},family:{key:"osr-classic",order:1},genre:{key:"dark-fantasy",order:6},solo:{key:"solo-compatible",order:7}},name:"Shadowdark",publisher:"Kelsey Dionne / The Arcane Library",dice:"d20 + стандарт",players:"3–6",complexity:2,foundryStatus:"Community",heroImage:"https://www.rpgtabletopgames.com/wp-content/uploads/shadowdark-780x400.jpg",playstyleTags:["explore","combat","survival"],settingTags:["fantasy"],gallery:[{src:"https://www.thearcanelibrary.com/cdn/shop/files/ShadowdarkRPGDigitalPDF5_1200x.jpg?v=1684273611"},{src:"https://www.thearcanelibrary.com/cdn/shop/files/ShadowdarkRPGDigitalPDF13_1200x.jpg?v=1684273502"},{src:"https://img.itch.zone/aW1nLzE1MDUyMDQwLnBuZw==/original/j6pJeS.png"}],resources:[{type:"link",url:"https://www.thearcanelibrary.com/pages/shadowdark",fmt:"Web"},{type:"sheet",url:"https://www.thearcanelibrary.com/blogs/shadowdark-blog/shadowdark-rpg-character-sheet",fmt:"PDF"},{type:"quickstart",url:"https://www.thearcanelibrary.com/products/shadowdark-rpg-quickstart-set-pdf",fmt:"PDF"}],mechanics:[{icon:"flame"},{icon:"trending-up"},{icon:"dices"},{icon:"skull"}],quotes:[{text:"Shadowdark cuts most of the fat of other versions of D&D, leaving a lean, mean dungeon crawling machine.",author:"Rob Wieland, EN World"},{text:"It's not the only OSR game, but it's certainly one of the most successful, striking a good balance of ease of play and thematic depth.",author:"Timothy Linward, Wargamer"}],ru:{tagShort:"Современный OSR с факелами",tagline:"«Олдскульный данжен-кроул (исследование подземелий: комната за комнатой, ловушки и сокровища) в современной обёртке».",description:"Мост между OSR и современными RPG. Использует знакомые d20-механики (атрибуты, AC, спасброски), но с летальностью и ощущением опасности старой школы. Самый успешный Kickstarter RPG за последние годы. Если D&D кажется раздутой — Shadowdark это лекарство.",setting:"Сеттинг-агностичная система. Любой фэнтези-мир подойдёт. Но дух игры — тёмные подземелья, где факел решает всё. Без света вы слепы, а в темноте живут вещи, которые видят прекрасно.",vignette:"Таймер факела на столе: 12 минут осталось. Вы на развилке — направо сундук, налево лестница вниз. Бросок на Ловкость, чтобы обезвредить ловушку на сундуке — d20 + модификатор, нужно 14 или выше. Выпало 9, провал. Ловушка срабатывает, d6 урона. Таймер тикает. Факел гаснет через три минуты. Вы бежите к лестнице — в темноту.",prep:"~15 мин",mechanics:[{title:"Таймер факелов",text:"Факел горит в РЕАЛЬНОМ ВРЕМЕНИ. Час реала = час в игре. Когда он гаснет — абсолютная тьма и паника."},{title:"Случайное повышение",text:"Левел-ап в конце сессии по броску кубика. Случайный талант вместо запланированного билда."},{title:"D&D-совместимость",text:"d20, AC, 6 атрибутов. Если играли в D&D — 80% правил уже знаете. Конвертация модулей тривиальна."},{title:"Лёгкость обучения",text:"Новичок создаёт персонажа за 5 минут и начинает играть. Нет анализа-паралича 5e-билдов."}],gallery:[{cap:"Разворот книги"},{cap:"Интерьерный арт"},{cap:"Арт персонажей"}],resources:[{name:"Официальный сайт"},{name:"Официальный лист"},{name:"Quickstart Set (136 стр.!)"}],quotes:[{text:"Shadowdark срезает почти весь жир с других версий D&D, оставляя поджарую и злую машину для подземельных вылазок."},{text:"Это не единственная OSR-игра, но определённо одна из самых успешных — она удачно сочетает простоту игры и тематическую глубину."}]},en:{tagShort:"OSR with real-time torches",tagline:'"Old-school dungeon crawling in a modern wrapper."',description:"A bridge between OSR and modern RPGs. Uses familiar d20 mechanics (attributes, AC, saves) but with old-school lethality and sense of danger. The most successful RPG Kickstarter in recent years. If D&D feels bloated — Shadowdark is the cure.",setting:"A setting-agnostic system. Any fantasy world will do. But the spirit of the game is dark dungeons where the torch decides everything. Without light you're blind, and in the darkness dwell things that see perfectly.",vignette:"Torch timer on the table: 12 minutes left. You're at a fork — right leads to a chest, left to stairs going down. Dexterity check to disarm the trap on the chest — d20 + modifier, need 14 or higher. Rolled a 9, failure. The trap triggers, d6 damage. The timer ticks. The torch goes out in three minutes. You run for the stairs — into the dark.",prep:"~15 min",mechanics:[{title:"Real-time torch timer",text:"The torch burns in REAL TIME. One real hour = one in-game hour. When it goes out — total darkness and panic."},{title:"Random leveling",text:"Level up at end of session by dice roll. A random talent instead of a planned build."},{title:"D&D compatibility",text:"d20, AC, 6 attributes. If you've played D&D — you already know 80% of the rules. Module conversion is trivial."},{title:"Easy to learn",text:"A newcomer creates a character in 5 minutes and starts playing. No 5e build analysis paralysis."}],gallery:[{cap:"Book spread"},{cap:"Interior art"},{cap:"Character art"}],resources:[{name:"Official website"},{name:"Official sheet"},{name:"Quickstart Set (136 pp.!)"}]}}),registerSystem("shadowrun",{groups:{default:{key:"tactical",order:12},family:{key:"standalone",order:33},genre:{key:"sci-fi",order:8.5}},name:"Shadowrun",publisher:"Catalyst Game Labs",dice:"d6 pool",players:"3–6",complexity:4,free:!0,foundryStatus:"Community",heroImage:"https://cdn11.bigcommerce.com/s-ua4dd/images/stencil/500x659/products/36460/415229/Copy_of_Website_Image_Template3360__18385.1751897343.png?c=2",playstyleTags:["tactical","combat","narrative"],settingTags:["cyberpunk","fantasy"],gallery:[{src:"https://seaofstarsrpg.wordpress.com/wp-content/uploads/2021/05/sr-sw.png"},{src:"https://seaofstarsrpg.wordpress.com/wp-content/uploads/2020/06/cat28002_firing-squad.png"},{src:"https://cdn11.bigcommerce.com/s-ua4dd/images/stencil/500x659/products/36460/415229/Copy_of_Website_Image_Template3360__18385.1751897343.png?c=2"}],resources:[{type:"link",url:"https://shadowrunsixthworld.com/",fmt:"Web"},{type:"link",url:"https://store.catalystgamelabs.com/collections/shadowrun",fmt:"Web"},{type:"quickstart",url:"https://pages.roll20.net/shadowrun",fmt:"Web"}],mechanics:[{icon:"swords"},{icon:"dices"},{icon:"book-open"},{icon:"scroll"}],quotes:[{text:"While Shadowrun players may not like all the mechanical choices from the system, almost everyone loves the fluff the world provides. It's deep and engaging with lots of short stories. This will make you want some cyberpunk tabletop in your life.",author:"Edward Kabara, RPGnet"},{text:"The roleplaying classic of magic and cybertech comes of age with a streamlined, unified system that produces a fluid and fun game. Sets a real benchmark for how to layout, write and design a game.",author:"Conan McKegg, RPGnet"}],ru:{tagShort:"Киберпанк + фэнтези на d6-пуле",tagline:"«Киберимпланты, магия и драконы в мире корпораций».",description:"Shadowrun — настольная RPG от Catalyst Game Labs (6-е издание, 2019), уникальный гибрид киберпанка и фэнтези. Действие в 2080 году (Sixth World): магия вернулась на Землю, металюди (эльфы, орки, тролли, дварфы) сосуществуют с киберимплантами и Матрицей. Система d6-пула: бросок Атрибут + Навык, успехи на 5 и 6. Шаодраннеры — наёмники, выполняющие теневые задания для корпораций.",setting:"Шестой Мир, 2080 — мегакорпорации правят миром, магия вернулась, метлюди — полноправные граждане. Seattle — основной сеттинг. Три жанра в одном: киберпанк (хакинг, киберимпланты), фэнтези (магия, драконы, эльфы) и хист (наёмные операции).",vignette:"Шаодраннер-шаман вызывает духов ветра. Пять d6: 3, 5, 1, 6, 2 = два хита. Хакер подключается к Матрице — его decks блокирует ICE. Сэмurai с катаной прорезает путь через охрану. Дилер кричит: «Время уходит!» Дракон-мегамагнат смотрит из башни Aztechnology. Добро пожаловать в Шестой Мир.",prep:"~25 мин",mechanics:[{title:"d6-пул",text:"Бросок Атрибут + Навык в d6. Успехи на 5 и 6. Простая, но элегантная математика. Криты на шести в пуле."},{title:"Edge",text:"Уникальный ресурс: удача, интуиция, дерзость. Позволяет перебросить кубики, добавить хиты или активировать особые способности. Пополняется через Историю персонажа."},{title:"Четыре слоя",text:"Физический мир, Магия, Матрица (хакинг), Риггинг (меха). Каждый слой — отдельная подсистема. Вместе — сложная, но увлекательная механика."},{title:"Метлюди",text:"Эльфы, орки, дварфы, тролли, люди — каждый с уникальными модификаторами атрибутов и чертами. Магия и киберимпланты конфликтуют через Essence."}],gallery:[{cap:"Street Wyrd — магический справочник"},{cap:"Firing Squad — боевой справочник"},{cap:"Core Rulebook (Seattle Edition)"}],resources:[{name:"Официальный сайт — Shadowrun Sixth World"},{name:"Catalyst Game Labs — магазин"},{name:"Бесплатные правила на Roll20"}],quotes:[{text:"Хотя игроки Shadowrun могут не любить все механические выборы системы, почти все обожают сеттинг. Он глубокий и захватывающий, с множеством рассказов. Это захочется стола в вашей жизни."},{text:"Классика RPG — магия и кибертех — повзрослела с потоковой, единой системой, создающей плавную и весёлую игру. Настоящий benchmark для того, как оформлять, писать и проектировать игру."}]},en:{tagShort:"Cyberpunk + fantasy d6-pool — magic meets the Matrix",tagline:'"Cyberware, magic, and dragons in a world of megacorps."',description:"Shadowrun is a tabletop RPG from Catalyst Game Labs (6th Edition, 2019), a unique hybrid of cyberpunk and fantasy. Set in 2080 (the Sixth World) — magic has returned to Earth, metahumans (elves, orks, trolls, dwarves) coexist with cyberware and the Matrix. d6 pool system: roll Attribute + Skill, count hits on 5s and 6s. Shadowrunners are deniable assets who take illegal jobs from corporations.",setting:"The Sixth World, 2080 — megacorporations rule, magic has returned, metahumans are full citizens. Seattle is the primary setting. Three genres in one: cyberpunk (hacking, cyberware), fantasy (magic, dragons, elves), and heist (shadow operations).",vignette:"A shaman Shadowrunner summons a wind spirit. Five d6: 3, 5, 1, 6, 2 = two hits. A decker jacks into the Matrix — ICE locks him out. A street samurai with a katana carves through security. The dealer screams: 'Time's running out!' A dragon-megamogul watches from the Aztechnology tower. Welcome to the Sixth World.",prep:"~25 min",mechanics:[{title:"d6 Pool",text:"Roll Attribute + Skill in d6s. Hits on 5s and 6s. Simple but elegant math. Crits on sixes in the pool."},{title:"Edge",text:"A unique resource: luck, intuition, daring. Lets you reroll dice, add hits, or activate special abilities. Replenished through character backstory."},{title:"Four Layers",text:"Physical world, Magic, Matrix (hacking), Rigging (mecha). Each layer is its own subsystem. Together — complex but rewarding mechanics."},{title:"Metahumans",text:"Elves, orks, dwarves, trolls, humans — each with unique attribute modifiers and traits. Magic and cyberware clash through Essence."}],gallery:[{cap:"Street Wyrd — magic sourcebook"},{cap:"Firing Squad — combat sourcebook"},{cap:"Core Rulebook (Seattle Edition)"}],resources:[{name:"Official site — Shadowrun Sixth World"},{name:"Catalyst Game Labs — store"},{name:"Free rules on Roll20"}],quotes:[{text:"While Shadowrun players may not like all the mechanical choices from the system, almost everyone loves the fluff the world provides. It's deep and engaging with lots of short stories. This will make you want some cyberpunk tabletop in your life."},{text:"The roleplaying classic of magic and cybertech comes of age with a streamlined, unified system that produces a fluid and fun game. Sets a real benchmark for how to layout, write and design a game."}]}}),registerSystem("spire",{groups:{default:{key:"narrative",order:2},family:{key:"resistance",order:2},genre:{key:"narrative-weird",order:2}},name:"Spire: The City Must Fall",publisher:"Rowan, Rook & Decard",dice:"d10",players:"3–5",complexity:3,foundryStatus:"Community",heroImage:"https://rowanrookanddecard.com/wp-content/uploads/2018/09/Necropolis2-1.jpg",playstyleTags:["narrative","social","mystery"],settingTags:["urban-fantasy"],gallery:[{src:"https://rowanrookanddecard.com/wp-content/uploads/2018/09/Necropolis2-1.jpg"},{src:"https://rowanrookanddecard.com/wp-content/uploads/2018/01/Spire-1.2.jpg"},{src:"https://rowanrookanddecard.com/wp-content/uploads/2018/09/Combat_Example2.jpg"}],quotes:[{text:"A moody game in a dark city full of spies, revolutionaries and strange magic.",author:"Rob Wieland, EN World"},{text:"The mechanics of stress and fallout are both familiar and combined in a new and exciting fashion, and I think that even people that are a little burned out on fantasy may want to keep an eye on these mechanics and how they managed to promote and resolve story elements.",author:"Jared Rascher, Gnome Stew"}],resources:[{type:"link",url:"https://rowanrookanddecard.com/product/spire-rpg/",fmt:"Web"},{type:"quickstart",url:"https://rowanrookanddecard.itch.io/spire-quickstart",fmt:"PDF"},{type:"sheet",url:"https://rowanrookanddecard.com/product/spire-character-sheet/",fmt:"PDF"}],mechanics:[{icon:"layers"},{icon:"skull"},{icon:"users"},{icon:"target"}],ru:{tagShort:"Восстание дроу",tagline:"«Вы — тёмные эльфы. Вы живёте в самом низу города высотой с милю. Вы собираетесь его снести.»",description:"Фэнтези-панк RPG о революции, тайных операциях и цене отчаяния. Вы — дроу, члены запрещённого Министерства, поклявшегося свергнуть оккупантов-аэльфир. Не история о героях — история о том, как далеко вы зайдёте.",setting:"Спайр — город-миля, построенный дроу и захваченный аэльфир. Ярусы громоздятся: ледяные высоты Амаранта, задымленный Завод, трущобный Красный Ряд — и под всем кровоточащая прореха в реальности, Сердце.",vignette:"В конспиративной квартире пахнет плесенью. Ваш Идол сочинял песни под чужим именем. Частичный успех: листовки разошлись, но кто-то проговорился. Стресс Тени: две отметки. Жрец Мертвечины поджигает станок. Песни уже у людей на устах. Аэльфир это не сожгут.",prep:"~20 мин",mechanics:[{title:"5 стресс-треков",text:"Кровь, Разум, Серебро, Тень, Репутация. Каждый провал бьёт по конкретному ресурсу."},{title:"Последствия (Fallout)",text:"Стресс застывает в конкретные беды: сломанная нога, сожжённый контакт, стражник с вашим описанием."},{title:"10 уникальных классов",text:"Жрец Мертвечины, Идол, Мудрец Вермиссиана, Акушерка, Связанный, Рыцарь — срезы общества дроу."},{title:"Система Сопротивления",text:"1–4 d10, берите наибольший. Быстро и всегда с последствиями."}],gallery:[{cap:"Некрополь Спайра"},{cap:"Город-миля"},{cap:"Пример боя"}],resources:[{name:"Официальный сайт"},{name:"Quickstart"},{name:"Лист персонажа"}],quotes:[{text:"Атмосферная игра в тёмном городе, кишащем шпионами, революционерами и странной магией."},{text:"Механика стресса и последствий и знакома, и собрана новым, увлекательным образом — стоит присмотреться даже тем, кто немного выгорел на фэнтези: ради того, как через эту механику двигаются и разрешаются сюжетные элементы."}]},en:{tagShort:"drow rebellion",tagline:'"You are dark elves. You live at the bottom of a mile-high city. You are going to tear it down."',description:"A fantasy-punk RPG of revolution, subterfuge, and desperate consequence. You play as drow — dark elves living under the boot of aelfir occupation in the towering city of Spire — members of the Ministry, a forbidden paramilitary cult devoted to the violent overthrow of their oppressors. This is not a game about heroes; it's a game about how far you'll go, and what the city takes from you in return.",setting:"Spire is a mile-tall city built by the drow and seized by the aelfir two hundred years ago. Its districts stack one atop another: the frozen aristocratic heights of Amaranth, the smoke-choked industrial Works, the lawless squalor of Red Row down-Spire, and — beneath it all — the bleeding hole in reality known as the Heart (the subject of its companion game).",vignette:"The safe house smells of mildew and cheap incense. Your Idol has been composing revolutionary songs under a false name. Roll the dice — partial success. The pamphlets spread, but someone talked. Shadow stress: two marks. The Ministry's silence team is already in the district. Your Carrion-Priest says a prayer over the printing press, then sets it alight. That's fine. The songs are already in people's mouths. The aelfir can't burn that.",prep:"~20 min",mechanics:[{title:"5 Stress Tracks",text:"Blood, Mind, Silver, Shadow, Reputation. Every failure costs you something specific. Lose Shadow — your cover burns. Lose Silver — you owe loan sharks."},{title:"Fallout",text:"Stress doesn't just accumulate — it solidifies into concrete consequences: a broken leg, a burned contact, an aelfir magistrate with your description."},{title:"10 Distinct Classes",text:"Carrion-Priest, Idol, Vermissian Sage, Midwife, Bound, Knight, and more — each a slice of drow society, each with unique magic and ways of being ground down by the city."},{title:"The Resistance System",text:"Roll 1–4 d10s, take the highest. Results read as: critical failure, failure with stress, partial success, full success, critical success. Fast and always consequential."}],gallery:[{cap:"The Necropolis of Spire"},{cap:"The mile-high city"},{cap:"Combat example"}],resources:[{name:"Official website"},{name:"Quickstart (rules + adventure)"},{name:"Character sheet"}]}}),registerSystem("star-trek-adventures",{groups:{default:{key:"tactical",order:34},family:{key:"standalone",order:38},genre:{key:"sci-fi",order:13}},name:"Star Trek Adventures",publisher:"Modiphius Entertainment",dice:"2d20 System",players:"3–6",complexity:3,free:!0,foundryStatus:"Community",heroImage:"https://cdn.shopify.com/s/files/1/0225/4035/files/star-trek-adventures-second-edition-core-rulebook-star-trek-adventures-modiphius-entertainment-267752.jpg",playstyleTags:["narrative","social","explore"],settingTags:["space"],gallery:[{src:"https://cdn.shopify.com/s/files/1/0225/4035/files/star-trek-adventures-second-edition-core-rulebook-star-trek-adventures-modiphius-entertainment-759196.jpg"},{src:"https://modiphius.net/cdn/shop/files/star-trek-adventures-second-edition-exploration-guide-star-trek-adventures-modiphius-entertainment-894023.jpg"},{src:"https://modiphius.net/cdn/shop/files/star-trek-adventures-second-edition-technical-manual-star-trek-adventures-modiphius-entertainment-380562.jpg"}],resources:[{type:"link",url:"https://www.modiphius.net/pages/star-trek-adventures",fmt:"Web"},{type:"quickstart",url:"https://modiphius.net/en-us/products/star-trek-adventures-the-roleplaying-game-second-edition-quickstart-guide-pdf",fmt:"Web"}],mechanics:[{icon:"dices"},{icon:"activity"},{icon:"star"},{icon:"rocket"}],quotes:[{text:"Star Trek Adventures 2nd Edition finds the right balance, and really leans more into creativity and story telling.",author:"Matt Crowther, Sprues & Brews"},{text:"even Star Trek fans who have never dabbled with an RPG before will find this worth adding to their collection.",author:"Matt Crowther, Sprues & Brews"}],ru:{tagShort:"Официальная ролёвка по «Стартреку» на 2d20",tagline:"«Смело идите туда, где не ступала нога человека — целым экипажем звездолёта».",description:"Star Trek Adventures — официальная RPG по вселенной «Звёздного пути» от Modiphius на движке 2d20. Играете экипажем звездолёта Флота: капитан, наука, инженерия, тактика. Упор на исследование, дипломатию и моральные дилеммы в духе сериалов, а не на пострелушки. 2-е издание (2024) отшлифовало систему до чистого «трек-фила».",setting:"Галактика «Звёздного пути»: Объединённая Федерация Планет, Звёздный Флот, Главная Директива. Клингоны, ромуланцы, борг и неизведанный космос. Тон — оптимистичная научная фантастика: проблемы решаются умом, эмпатией и наукой чаще, чем фазером. От эпохи TOS до TNG и дальше.",vignette:"Мостик. Неизвестный корабль не отвечает. Капитан приказывает офицеру по науке просканировать: проверка Разума + Науки — бросок 2d20, каждый кубик ниже цели даёт успех. Нужно 2 успеха, выпало 1. Офицер тратит Momentum из общего пула — ещё d20, ещё успех. Сенсоры оживают: корабль полон споровой формы жизни. Теперь — что с этим делать по Главной Директиве?",prep:"~30 мин",mechanics:[{title:"Движок 2d20",text:"Проверка: 2d20, каждый кубик «меньше» суммы Атрибут+Дисциплина — успех. Нужное число успехов задаёт сложность. Можно докупать кубики за Momentum или рискуя."},{title:"Momentum и Threat",text:"Успехи сверх нормы копятся в общий пул Momentum — тратится на бонусы всей командой. У ведущего зеркальный пул Threat для осложнений. Экономика драмы за столом."},{title:"Ценности и Решимость",text:"У героя есть Values — убеждения в духе трековских монологов. Действуя по ним (или против), персонаж получает Determination на героические свершения."},{title:"Звездолёт как персонаж",text:"Корабль — полноценный «герой» со своими характеристиками и уроном по системам. Космический бой — командная работа: каждый на своём посту решает исход."}],gallery:[{cap:"Core Rulebook (2-е издание)"},{cap:"Exploration Guide"},{cap:"Technical Manual"}],resources:[{name:"Официальная страница — Modiphius"},{name:"Бесплатный Quickstart"}],quotes:[{text:"Второе издание Star Trek Adventures нашло верный баланс и по-настоящему делает упор на творчество и рассказывание истории."},{text:"Даже фанаты «Стартрека», никогда не игравшие в RPG, сочтут это достойным пополнением коллекции."}]},en:{tagShort:"The official Star Trek RPG on the 2d20 System",tagline:'"Boldly go where no one has gone before — as a whole starship crew."',description:"Star Trek Adventures is Modiphius's official RPG of the Star Trek universe, on the 2d20 System. You play a Starfleet crew — captain, science, engineering, tactical. The emphasis is exploration, diplomacy, and moral dilemmas in the spirit of the shows, not shootouts. The 2nd edition (2024) polished the system into clean 'Trek feel.'",setting:"The galaxy of Star Trek: the United Federation of Planets, Starfleet, the Prime Directive. Klingons, Romulans, the Borg, and uncharted space. The tone is optimistic science fiction — problems solved with intellect, empathy, and science more often than a phaser. From the TOS era to TNG and beyond.",vignette:"The bridge. An unknown ship won't answer hails. The captain orders a scan: a Reason + Science test — roll 2d20, each die under the target scores a success. You need 2, you roll 1. The officer spends Momentum from the shared pool — another d20, another success. Sensors light up: the ship is full of a spore-based life form. Now — what does the Prime Directive say about that?",prep:"~30 min",mechanics:[{title:"The 2d20 engine",text:"A test: roll 2d20; each die under your Attribute+Discipline total is a success. The successes required set the difficulty. Buy extra dice with Momentum or by taking risks."},{title:"Momentum & Threat",text:"Successes beyond the requirement bank into a shared Momentum pool the whole crew spends on bonuses. The GM has a mirror Threat pool for complications. A shared economy of drama."},{title:"Values & Determination",text:"A hero has Values — beliefs in the vein of Trek monologues. Acting on (or against) them earns Determination for heroic feats when it matters most."},{title:"The starship as a character",text:"The ship is a full 'character' with its own stats and system damage. Space combat is teamwork — everyone at their station shapes the outcome."}],gallery:[{cap:"Core Rulebook (2nd edition)"},{cap:"Exploration Guide"},{cap:"Technical Manual"}],resources:[{name:"Official page — Modiphius"},{name:"Free Quickstart"}],quotes:[{text:"Star Trek Adventures 2nd Edition finds the right balance, and really leans more into creativity and story telling."},{text:"even Star Trek fans who have never dabbled with an RPG before will find this worth adding to their collection."}]}}),registerSystem("star-wars-ffg",{groups:{default:{key:"narrative",order:13},family:{key:"standalone",order:12},genre:{key:"sci-fi",order:7}},name:"Star Wars RPG (FFG)",publisher:"Fantasy Flight Games / Edge Studio (Asmodee)",dice:"Нарративные кубики (Narrative Dice System)",players:"3–6",complexity:3,foundryStatus:"Community",heroImage:"https://static0.srcdn.com/wordpress/wp-content/uploads/2021/01/Star-Wars-Tabletop-RPGs-Fantasy-Flight-Games-Force-And-Destiny.jpg",playstyleTags:["action","narrative","social","explore"],settingTags:["space"],gallery:[{src:"https://ttrpgfans.com/wp-content/uploads/2025/11/star-wars-rpg-reprints-1.png"},{src:"https://images.steamusercontent.com/ugc/448482024259167070/88E9804631FCAE71435C83D2A119769A7A167F11/?imw=5000&imh=5000&ima=fit&impolicy=Letterbox&imcolor=%23000000&letterbox=false"},{src:"https://www.belloflostsouls.net/wp-content/uploads/2017/07/swr10_art-1.jpg"},{src:"https://images-cdn.fantasyflightgames.com/filer_public/79/62/79625561-208b-4e9f-b7aa-ed7976cb3930/swe14_preview3.jpg"}],resources:[{type:"link",url:"https://www.edge-studio.net/shares/star-wars/",fmt:"Web"},{type:"sheet",url:"https://images-cdn.fantasyflightgames.com/ffg_content/StarWarsRPG/edge-of-the-empire/support/edge-of-the-empire-character-sheet.pdf",fmt:"PDF"},{type:"tool",url:"https://myswrpg.com/oggdudes-character-generator-and-gm-tools/",fmt:"App"},{type:"tool",url:"https://rpgsessions.com/",fmt:"Web"},{type:"tool",url:"https://dice.skyjedi.com/",fmt:"Web"},{type:"link",url:"https://www.swrpgcommunity.com/",fmt:"Web"},{type:"link",url:"https://foundryvtt.com/packages/starwarsffg",fmt:"Web"}],mechanics:[{icon:"star"},{icon:"compass"},{icon:"flame"},{icon:"sword"}],quotes:[{text:"Fantasy Flight Games made the best Star Wars RPG system imaginable.",author:"Meaghan Colleran, Bell of Lost Souls"},{text:"You can fail up or succeed your way into trouble, and to me that is very Star Wars.",author:"Meaghan Colleran, Bell of Lost Souls"},{text:"The most recent family of Star Wars TTRPGs, developed by Fantasy Flight Games, uses custom polyhedral dice.",author:"Timothy Linward, Wargamer"}],ru:{tagShort:"Нарративные дайсы RPG",tagline:"«Давным-давно, в далёкой-далёкой галактике… ваша история только начинается».",description:`Три полностью совместимых базовых книги — Edge of the Empire (2013), Age of Rebellion (2014) и Force and Destiny (2015) — охватывают все грани вселенной Звёздных войн. Сердце системы — уникальные нарративные кубики с символами вместо цифр. Каждый бросок разрешается по двум осям: Успех/Провал и Преимущество/Угроза. Можно добиться цели, но попасть в переплёт, или с треском провалиться — и всё равно обнаружить нечто полезное. Триумф и Отчаяние — редкие символы на кубиках Мастерства и Вызова — создают моменты кинематографического накала. Система поощряет совместное повествование: игроки не просто бросают кубики, а интерпретируют результат вместе с мастером, формируя историю на лету. Книги отличаются выдающимся качеством: 450+ страниц полноцветных иллюстраций, детально проработанных правил и обширного бестиария. Изначально издавалась Fantasy Flight Games, а с 2020 года поддерживается Edge Studio (дочерняя компания Asmodee).

**Edge of the Empire** — книга для историй на задворках галактики. Контрабандисты, охотники за головами, наёмники, колонисты и техники. Уникальная механика — Обязательство (Obligation): у каждого персонажа есть долг, зависимость или тёмная тайна, которая может настигнуть в самый неподходящий момент. Перед каждой сессией мастер бросает d100 — и чьё-то прошлое стучится в дверь. Тон: «Хан Соло встречает Firefly».

**Age of Rebellion** — война Альянса повстанцев против Галактической Империи. Солдаты, шпионы, командиры, дипломаты и пилоты. Уникальная механика — Долг (Duty): вклад персонажа в дело Восстания, от разведки до саботажа. По мере роста Долга группа получает доступ к ресурсам Альянса — кораблям, базам, подкреплениям. Тон: «Изгой-один» и «Звёздные войны: Повстанцы».

**Force and Destiny** — история последних форсъюзеров в эпоху, когда джедаи уничтожены, а Империя охотится на всех, кто чувствует Силу. Стражи, мистики, воины, искатели и часовые. Уникальная механика — Моральность (Morality): числовая шкала от 0 до 100, определяющая положение персонажа между Светлой и Тёмной стороной Силы. Каждый сеанс использования Силы — искушение: тёмные очки Силы мощнее, но приближают к падению. Тон: «Странствующий рыцарь-джедай ищет утраченное знание».`,setting:"Галактика Звёздных войн в эпоху Галактической гражданской войны — между Эпизодами IV и VI. Все три книги полностью совместимы: в одной партии могут сойтись контрабандист с Обязательством, повстанец с Долгом и падаван с Моральностью. Галактика охватывает тысячи миров — от экуменополиса Корусанта до пустынного Татуина, от ледяного Хота до лесных лун Эндора. Внешнее Кольцо — территория хаттов, пиратов и свободных торговцев. Ядерные Миры — под железной пятой Империи. А между ними — бесконечные возможности для приключений: заброшенные храмы джедаев, кантины на пыльных заставах, имперские тюремные баржи и астероидные поля, полные обломков войны.",vignette:"Корабль тряхнуло. «Имперский патруль», — буркнул пилот-родианец. Механик-тви'лечка собирает пул: два зелёных кубика Способности за свой навык Механики, один жёлтый кубик Мастерства за высокий Интеллект, и кубик Подъёма за недавно установленный ускоритель. Мастер добавляет два фиолетовых кубика Сложности и красный кубик Вызова — модификация двигателя в разгар погони не шутка. Бросок: два Успеха, одна Угроза и… Триумф. Двигатели взревели — корабль рванул вперёд, оставив TIE-истребители позади. Но Угроза означает, что перегрузка выбила систему жизнеобеспечения на нижней палубе. А Триумф? Пилот ухмыльнулся: «Мы только что побили рекорд Кесселя.» Корабль вошёл в гиперпространство — прямо перед носом звёздного разрушителя.",prep:"~30–60 мин",mechanics:[{title:"Нарративные кубики",text:"Семь типов кубиков с символами. Успех + Угроза, Провал + Преимущество — каждый бросок создаёт многослойную историю, а не просто «попал/промахнулся»."},{title:"Очки Судьбы",text:"Общий пул светлых и тёмных жетонов. Игроки тратят светлые для усиления бросков, мастер — тёмные. Баланс постоянно смещается, создавая напряжение."},{title:"Обязательство / Долг / Моральность",text:"Каждая книга добавляет уникальную механику драмы: долги контрабандиста, служба повстанца или борьба форсъюзера между Светом и Тьмой."},{title:"Таланты и специализации",text:"Древа талантов вместо уровней. Каждая карьера имеет несколько специализаций, и персонаж может брать деревья из других карьер, создавая уникальные комбинации."}],gallery:[{cap:"Три базовых книги — Edge of the Empire, Age of Rebellion, Force and Destiny"},{cap:"Нарративные кубики — сердце системы"},{cap:"Повстанцы в бою — арт из Age of Rebellion"},{cap:"Авантюристы Внешнего Кольца — арт из Edge of the Empire"}],resources:[{name:"Edge Studio — официальная страница"},{name:"Лист персонажа (Edge of the Empire)"},{name:"OggDude's Character Generator"},{name:"RPG Sessions — онлайн-платформа и дайс-роллер"},{name:"SkyJedi Dice Roller"},{name:"SWRPG Community — фан-портал"},{name:"Foundry VTT модуль"}],quotes:[{text:"Fantasy Flight Games сделала лучшую RPG-систему по «Звёздным войнам», какую только можно себе представить."},{text:"Можно проваливаться вверх или успешно вкатиться в неприятности — и для меня это очень «Звёздные войны»."},{text:"Самое свежее семейство TTRPG по «Звёздным войнам» от Fantasy Flight Games использует собственные многогранные кубики."}]},en:{tagShort:"narrative dice RPG",tagline:'"A long time ago in a galaxy far, far away... your story is just beginning."',description:`Three fully cross-compatible core rulebooks — Edge of the Empire (2013), Age of Rebellion (2014), and Force and Destiny (2015) — cover every facet of the Star Wars universe. At the heart of the system are unique narrative dice bearing symbols instead of numbers. Every roll resolves on two axes: Success/Failure and Advantage/Threat. You can achieve your goal but land in trouble, or fail spectacularly yet discover something useful. Triumph and Despair — rare symbols on Proficiency and Challenge dice — create moments of cinematic intensity. The system encourages collaborative storytelling: players don't just roll dice, they interpret the result together with the GM, shaping the story on the fly. The books boast outstanding production quality: 450+ pages of full-color illustrations, meticulously crafted rules, and an extensive bestiary. Originally published by Fantasy Flight Games, the line has been maintained by Edge Studio (an Asmodee subsidiary) since 2020.

**Edge of the Empire** — the book for stories on the galaxy's fringe. Smugglers, bounty hunters, mercenaries, colonists, and technicians. Unique mechanic — Obligation: every character carries a debt, addiction, or dark secret that can catch up with them at the worst possible moment. Before each session the GM rolls d100 — and someone's past comes knocking. Tone: 'Han Solo meets Firefly.'

**Age of Rebellion** — the Rebel Alliance's war against the Galactic Empire. Soldiers, spies, commanders, diplomats, and pilots. Unique mechanic — Duty: the character's contribution to the Rebellion, from recon to sabotage. As Duty grows, the group gains access to Alliance resources — ships, bases, reinforcements. Tone: 'Rogue One' and 'Star Wars Rebels.'

**Force and Destiny** — the story of the last Force-sensitives in an era when the Jedi are destroyed and the Empire hunts anyone who can feel the Force. Guardians, mystics, warriors, seekers, and sentinels. Unique mechanic — Morality: a numeric scale from 0 to 100 determining where a character stands between Light and Dark. Every use of the Force is temptation: dark side pips are more powerful but bring you closer to falling. Tone: 'A wandering Jedi knight seeking lost knowledge.'`,setting:"The Star Wars galaxy during the era of the Galactic Civil War — between Episodes IV and VI. All three books are fully compatible: a smuggler with Obligation, a rebel with Duty, and a padawan with Morality can share the same table. The galaxy spans thousands of worlds — from the ecumenopolis of Coruscant to the desert wastes of Tatooine, from the frozen plains of Hoth to the forest moons of Endor. The Outer Rim is the domain of Hutts, pirates, and free traders. The Core Worlds groan under the Empire's iron heel. And between them — endless possibilities for adventure: abandoned Jedi temples, cantinas on dusty outposts, Imperial prison barges, and asteroid fields full of war debris.",vignette:"The ship shuddered. 'Imperial patrol,' the Rodian pilot muttered. The Twi'lek mechanic assembles her pool: two green Ability dice for her Mechanics skill, one yellow Proficiency die for her high Intellect, plus a blue Boost die for the recently installed overdrive. The GM adds two purple Difficulty dice and a red Challenge die — modifying engines mid-chase is no joke. The roll: two Successes, one Threat, and... a Triumph. The engines roared — the ship surged forward, leaving the TIE fighters behind. But the Threat means the overload knocked out life support on the lower deck. And the Triumph? The pilot grinned: 'We just beat the Kessel Run record.' The ship jumped to hyperspace — right under the nose of a Star Destroyer.",prep:"~30–60 min",mechanics:[{title:"Narrative Dice",text:"Seven types of dice with symbols. Success + Threat, Failure + Advantage — every roll creates a layered story, not just 'hit or miss.'"},{title:"Destiny Points",text:"A shared pool of light and dark tokens. Players spend light tokens to boost rolls, the GM spends dark ones. The balance constantly shifts, building tension."},{title:"Obligation / Duty / Morality",text:"Each book adds a unique drama mechanic: a smuggler's debts, a rebel's service record, or a Force-user's struggle between the Light and Dark Side."},{title:"Talents & Specializations",text:"Talent trees instead of levels. Each career has multiple specializations, and characters can buy into trees from other careers, creating unique combinations."}],gallery:[{cap:"Three core rulebooks — Edge of the Empire, Age of Rebellion, Force and Destiny"},{cap:"Narrative dice — the heart of the system"},{cap:"Rebels in action — art from Age of Rebellion"},{cap:"Outer Rim adventurers — art from Edge of the Empire"}],resources:[{name:"Edge Studio — Official Page"},{name:"Character Sheet (Edge of the Empire)"},{name:"OggDude's Character Generator"},{name:"RPG Sessions — Online Platform & Dice Roller"},{name:"SkyJedi Dice Roller"},{name:"SWRPG Community — Fan Portal"},{name:"Foundry VTT Module"}]}}),registerSystem("starfinder-2e",{groups:{default:{key:"tactical",order:5},family:{key:"standalone",order:19},genre:{key:"sci-fi",order:9},solo:{key:"solo-compatible",order:13}},name:"Starfinder 2e",publisher:"Paizo",dice:"d20 + mods",players:"3–6",complexity:4,foundryStatus:"Community",heroImage:"https://cdn.paizo.com/d960ad1b-9967-00f9-1158-72274b18312d/7d90d1d7-fd31-48d5-878b-a2d7ff715e64/PZO260100_SFSS1_Hero.jpg",playstyleTags:["combat","tactical","narrative"],settingTags:["space"],gallery:[{src:"https://cdn.paizo.com/d960ad1b-9967-00f9-1158-72274b18312d/c1f8b24a-7e41-4f95-9c8b-08feaeff5fb7/Starfinder_2ELogo.png"},{src:"https://cdn.paizo.com/d960ad1b-9967-00f9-1158-72274b18312d/c51a30f9-3626-45b8-b844-ca166a0098a8/PZO22005-HC%20Galactic%20Ancestries%20Cover.jpg"},{src:"https://cdn.paizo.com/d960ad1b-9967-00f9-1158-72274b18312d/6e110863-ba68-430a-a5d4-e6c862d3abf9/PZO24007_Cover-TalesfromtheVast_1920x1080.jpg"},{src:"https://cdn.paizo.com/d960ad1b-9967-00f9-1158-72274b18312d/7d90d1d7-fd31-48d5-878b-a2d7ff715e64/PZO260100_SFSS1_Hero.jpg"}],resources:[{type:"link",url:"https://paizo.com/starfinder",fmt:"Web"},{type:"sheet",url:"https://downloads.paizo.com/StarfinderSecondEdition_CharacterSheet.pdf",fmt:"PDF"},{type:"quickstart",url:"https://paizo.com/starfinderplaytest",fmt:"Web"},{type:"link",url:"https://2e.aonsrd.com/",fmt:"SRD"}],mechanics:[{icon:"rocket"},{icon:"swords"},{icon:"cog"},{icon:"users"}],quotes:[{text:"This makes Starfinder and Pathfinder completely compatible, so if you want Gunslingers in space or Envoys on Golorian, you can have them.",author:"Dawn Dalton, EN World"},{text:"Each character will feel a bit more unique in the second edition, with each class feeling like it serves more of a unique purpose.",author:"Raven Winters, Gaming Trend"}],ru:{tagShort:"Тактическая космоопера на движке PF2e",tagline:"«Pathfinder 2e, но с лазерами, дрифт-двигателями и мистиком в скафандре».",description:"Второе издание Starfinder (август 2025) — полная переработка космической d20-системы Paizo на движке Pathfinder 2e Remastered. Та же 3-экшен-экономика, тот же кранч, но в декорациях далёкого будущего: классы вроде envoy, mystic, soldier, operative, witchwarper, mechanic, solarian, наследия (ancestries) от андроидов до касатхи, и — главное — полная кросс-совместимость с PF2e. Ваш пэйнфайндеровский паладин может зайти на космический корабль, и правила работают.",setting:"Pact Worlds — содружество планет вокруг звёзды-близнеца, удерживаемое мирным договором между разными расами. Космос пересекают на Drift-двигателях — пробивая плазменное подпространство, придуманное богиней Триуной после Gap, столетнего провала в памяти всей галактики. Никто не помнит, что было до Gap, и это — ключевая загадка сеттинга. Технология и магия работают рядом: соларианец с гравитационным мечом сражается рядом с механиком и его дроном-компаньоном.",vignette:"Ваш дредноут-фрегат вынырнул из Drift у астероида с пиратской базой. Пилот-оперативник бросает Piloting на манёвр — три экшена: Манёвр, Огонь, Перезарядка. Соларианец в невесомости переключает форму звезды с фотонной на гравитационную — третий экшен ушёл в Flare. Мистик читает заклинание сквозь стекло шлема — соматический компонент в перчатке скафандра, проверка на Concentrate. Андроид-механик с дрона взламывает турель противника — Computers DC 22, успех. Капитан кричит: «Стрелять!» — и ваш плазменный канон делает критический урон. Pathfinder, но в космосе. Тот же ритм, тот же вкус.",prep:"~30–60 мин",mechanics:[{title:"3-экшен экономика",text:"Тот же движок, что в PF2e Remastered: три экшена + реакция за ход. Move-Strike-Strike, или Cast-Aim-Fire, или что-то экзотическое. Решения принимаются быстро."},{title:"Звездолёт как персонаж",text:"Корабль — отдельный «персонаж» с ролями экипажа: пилот, наводчик, инженер, капитан, учёный. У каждого свой ход, свои броски, свои крит-эффекты. Звёздные бои — мини-игра."},{title:"Полная совместимость с PF2e",text:"Ancestries, классы, заклинания, фиты — всё работает в обе стороны. Можно водить смешанные кампании: фэнтези-герой попадает в космос, или мистик-соларианец заглядывает в Голарион."},{title:"Магия + техника",text:"Mystic и witchwarper кастуют заклинания. Mechanic чинит дрона. Solarian черпает силу из звёзд. Operative взламывает терминалы. Все играют рядом — ни одна школа не «лишняя»."}],gallery:[{cap:"Логотип Starfinder 2e"},{cap:"Galactic Ancestries"},{cap:"Tales from the Vast"},{cap:"Invasion's Edge"}],resources:[{name:"Официальный сайт"},{name:"Лист персонажа"},{name:"Бесплатный Playtest PDF"},{name:"Archives of Nethys SRD"}],quotes:[{text:"Это делает Starfinder и Pathfinder полностью совместимыми: хотите Стрелков в космосе или Послов на Голарионе — пожалуйста."},{text:"Во втором издании каждый персонаж ощущается чуть более уникальным — у каждого класса появляется собственная, более чётко выраженная роль."}]},en:{tagShort:"Tactical space-opera on the PF2e engine",tagline:'"Pathfinder 2e, but with plasma rifles, drift drives, and a mystic in a spacesuit."',description:"Starfinder Second Edition (August 2025) is Paizo's full rebuild of their space d20 system on the Pathfinder 2e Remastered chassis. Same 3-action economy, same tactical crunch, but in a far-future setting: classes like envoy, mystic, soldier, operative, witchwarper, mechanic, and solarian; ancestries from androids to kasatha; and — crucially — full cross-compatibility with PF2e. Your Pathfinder paladin can step onto a starship, and the rules just work.",setting:"The Pact Worlds — a confederation of planets around a binary star, held together by a peace treaty between wildly different species. Ships cross the void via the Drift, a plasma-subspace dimension carved out by the goddess Triune after the Gap — a galaxy-wide century of erased memory. Nobody remembers what came before the Gap, and that mystery is the setting's hook. Tech and magic share the table: a solarian wields a gravity blade beside a mechanic and her drone companion.",vignette:`Your dreadnought-frigate drops out of the Drift near an asteroid pirate base. The pilot-operative rolls Piloting for the maneuver — three actions: Манёвр, Огонь, Перезарядка. The solarian in zero-g flips their star form from photon to graviton — third action burned on a Flare. The mystic casts through their helmet visor — somatic component in a glove, Concentrate check. The android mechanic's drone hacks the enemy turret — Computers DC 22, success. The captain shouts: "Fire!" — and your plasma cannon crits. Pathfinder, but in space. Same rhythm, same flavor.`,prep:"~30–60 min",mechanics:[{title:"3-action economy",text:"Same engine as PF2e Remastered: three actions + a reaction per turn. Move-Strike-Strike, or Cast-Aim-Fire, or something exotic. Decisions land fast."},{title:"Starship as a character",text:'Your ship is its own "character" with crew roles: pilot, gunner, engineer, captain, science officer. Each gets a turn, their own checks, their own crits. Space combat is a tight mini-game.'},{title:"Full PF2e compatibility",text:"Ancestries, classes, spells, feats — they cross over both ways. You can run mixed campaigns: a fantasy hero crash-lands in space, or a solarian peeks into Golarion."},{title:"Magic meets tech",text:"Mystic and witchwarper cast spells. Mechanic repairs a drone. Solarian draws power from stars. Operative hacks terminals. Every school sits at the same table — none is filler."}],gallery:[{cap:"Starfinder 2e logo"},{cap:"Galactic Ancestries"},{cap:"Tales from the Vast"},{cap:"Invasion's Edge"}],resources:[{name:"Official website"},{name:"Character sheet"},{name:"Free Playtest PDF"},{name:"Archives of Nethys SRD"}]}}),registerSystem("starforged",{groups:{default:{key:"narrative",order:16},family:{key:"standalone",order:11.5},genre:{key:"sci-fi",order:10},solo:{key:"solo-adventure",order:2}},name:"Ironsworn: Starforged",publisher:"Tomkin Press",dice:"d6 + 2d10",players:"1–3",complexity:2,playstyleTags:["explore","narrative","sandbox"],settingTags:["space"],heroImage:"https://cdn.shopify.com/s/files/1/0712/0329/1447/files/starforged-sunset.jpg?v=1725559572",gallery:[{src:"https://img.itch.zone/aW1nLzg1MjM5MjQuanBn/original/3NcS3p.jpg"},{src:"https://cdn.shopify.com/s/files/1/0712/0329/1447/files/starforged-sunset.jpg?v=1725559572"},{src:"https://assetsio.gnwcdn.com/starforged-ironsworn-ship-alien-art.png?width=690&quality=85&format=jpg&dpr=3&auto=webp"},{src:"https://cdn.shopify.com/s/files/1/0712/0329/1447/files/ironsworn-starforged-digital-main.png?v=1767637357"},{src:"https://cdn.shopify.com/s/files/1/0712/0329/1447/files/starforged-asset-deck-1.png?v=1760647856"}],resources:[{type:"link",url:"https://tomkinpress.com/pages/ironsworn-starforged",fmt:"Web"},{type:"rules",url:"https://shawn-tomkin.itch.io/ironsworn-starforged",fmt:"PDF"},{type:"sheet",url:"https://tomkinpress.com/collections/downloads-for-ironsworn-starforged",fmt:"PDF"},{type:"tool",url:"https://nboughton.uk/apps/stargazer/",fmt:"Web"}],mechanics:[{icon:"star"},{icon:"compass"},{icon:"layers"},{icon:"anchor"},{icon:"feather"}],quotes:[{text:"Ironsworn: Starforged is an excellent follow up to the original and is highly recommended for sci-fi fans who want to explore the final frontier without the need for a GM.",author:"Rob Wieland, EN World"}],ru:{tagShort:"Соло sci-fi PbtA RPG",tagline:"«Поклянитесь на железе. Выживите в кузнице звёзд.»",description:"**Ironsworn: Starforged** — научно-фантастическая RPG для одного игрока, пары или небольшой группы без ведущего. Вы — скиталец на краю обитаемого пространства, известного как Кузница: туманность, где звёзды молоды и яростны, а человечество разбросано по горстке хрупких поселений. Не нужна подготовка, не нужен ведущий: мощные оракулы, двигатель нарративных ходов и прогресс-треки ведут историю вперёд сами. Система Клятв на железе превращает каждое данное обещание в ставку, а его выполнение — в катарсис. ENNIE-лауреат, Kickstarter-хит 2022 года.",setting:"Несколько столетий назад последние корабли беженцев покинули умирающую Старую Галактику и нырнули в туманность Кузница — густое облако молодых звёзд, где законы физики чуть другие, а Предшественники оставили в руинах свои загадочные артефакты. Сегодня человечество разделено: сотни изолированных секторов, каждый со своей историей, верованиями и бедами. Корабли бороздят Пустоту. На планетах-прецурсорах прячутся смертоносные чужие формы жизни. Ваш герой — один из немногих, кто берёт на себя миссии, от которых зависит судьба общин.",vignette:"Вы висите в пилотском кресле над Каэртой — планетой, задушенной атмосферным ядом. Сенсоры показывают обломки грузовика-разведчика на орбите. Кто-то уже был здесь. Вы активируете **Ход «Предпринять экспедицию»** и бросаете: d6+Исследование против 2d10. Сильный успех — вы замечаете маяк во обломках. Вы **отмечаете прогресс**. Но один из challenge-кубиков выпал на 10 — позиция. Оракул говорит: «Угроза сближается». Где-то за облаком отражателей — корабль. И он уже знает, что вы здесь.",prep:"~10 мин",mechanics:[{title:"Клятвы на железе",text:"Персонаж буквально клянётся на куске железа выполнить задание — от спасения поселения до раскрытия тайны тысячелетней давности. Каждая клятва обретает прогресс-трек из 10 ячеек. Выполнение клятвы даёт Наследие и опыт; провал меняет историю навсегда."},{title:"Ходы и оракулы",text:"Когда исход неясен, вы делаете Ход: бросаете d6 (действие) + стат против 2d10 (вызов). Сильный успех — идёте вперёд с импульсом. Слабый — компромисс. Промах — платите цену. Более 200 таблиц оракулов генерируют планеты, NPC, угрозы и твисты — ни одна сессия не повторится."},{title:"Импульс",text:"Ресурс, который накапливается на успехах и тратится в критический момент, чтобы перекрыть плохой бросок. Но есть предел: при некоторых обстоятельствах импульс «сгорает» и опрокидывает трек, делая провал ещё более болезненным."},{title:"Активы",text:"Навыки, корабль, спутники и снаряжение — всё это Активы с тремя ячейками улучшений. Ваш корабль — персонаж сам по себе: у него есть имя, история и собственный прогресс-трек здоровья. Активы позволяют менять правила игры под свой стиль."},{title:"Три Наследия",text:"Опыт зарабатывается через три отдельных трека: Квесты (выполненные клятвы), Связи (развитые отношения с NPC) и Исследование (завершённые экспедиции). Каждый трек растёт независимо, формируя уникальный портрет вашего героя."}],gallery:[{cap:"Обложка Starforged"},{cap:"Закат на чужой планете"},{cap:"Корабль в глубинах космоса"},{cap:"Оракулы и прогресс-треки"},{cap:"Карты активов"}],resources:[{name:"Официальный сайт"},{name:"Бесплатная PDF (itch.io)"},{name:"Листы и плейкит"},{name:"Генератор оракулов"}],quotes:[{text:"Ironsworn: Starforged — отличное продолжение оригинала и горячо рекомендована sci-fi-фанатам, что хотят исследовать последний фронтир без ведущего."}]},en:{tagShort:"solo sci-fi PbtA RPG",tagline:'"Swear iron vows. Survive the Forge."',description:"**Ironsworn: Starforged** is a sci-fi RPG for one player, a duo, or a small group — with no GM required. You are a spacefarer on the edge of inhabited space inside the Forge: a turbulent nebula of young stars where humanity clings to a handful of fragile settlements. Zero prep, zero game master: powerful oracle tables, a fiction-first move engine, and progress tracks propel the story forward on their own. The iron vow system turns every sworn promise into a dramatic stake, and its fulfillment into catharsis. ENNIE award winner and Kickstarter hit of 2022.",setting:"Centuries ago, the last refugee ships fled a dying galaxy and plunged into the Forge — a dense nebula of young, fierce stars where the Precursors left behind ruins of inscrutable purpose. Today humanity is fragmented: hundreds of isolated sectors, each with its own history, beliefs, and crises. Ships cross the Void between them. Precursor worlds hide lethal alien life. Your character is one of the rare few who takes on missions that determine the fate of whole communities — alone, if necessary.",vignette:"You hang in the pilot's seat above Kaerta — a planet strangled by toxic atmosphere. Sensors flag debris from a scout hauler in low orbit. Someone was here before you. You trigger **Begin an Expedition** and roll: d6 + Wits against 2d10. Strong hit — you spot a beacon buried in the wreckage. You **mark progress**. But one challenge die lands on 10 — a match. The oracle says: 'A threat closes in.' Somewhere behind a cloud of reflector chaff, a ship is running dark. And it already knows you're here.",prep:"~10 min",mechanics:[{title:"Iron Vows",text:"Your character literally swears on a piece of iron to complete a mission — from rescuing a settlement to unraveling a millennium-old mystery. Every vow gets a 10-box progress track. Fulfilling it earns Legacy and experience; failing it reshapes the story permanently."},{title:"Moves & Oracles",text:"When the outcome is uncertain, you make a Move: roll d6 (action die) + stat against 2d10 (challenge dice). Strong hit — press forward with momentum. Weak hit — costly success. Miss — pay a price. Over 200 oracle tables generate planets, NPCs, threats, and twists — no two sessions ever repeat."},{title:"Momentum",text:"A resource that builds on successes and can be spent at a critical moment to override a bad roll. But it has a ceiling: under certain conditions momentum 'burns', flipping the track and turning a near-miss into disaster."},{title:"Assets",text:"Skills, your starship, companions, and gear are all Assets with three upgrade boxes. Your ship is a character in its own right — it has a name, a history, and its own health progress track. Assets let you bend the rules to match your play style."},{title:"Three Legacies",text:"Experience flows through three separate tracks: Quests (fulfilled vows), Bonds (deepened NPC relationships), and Exploration (completed expeditions). Each grows independently, forming a unique portrait of who your character is becoming."}],gallery:[{cap:"Starforged cover"},{cap:"Sunset on an alien world"},{cap:"Ship in deep space"},{cap:"Oracle tables and progress tracks"},{cap:"Asset cards"}],resources:[{name:"Official website"},{name:"Free PDF (itch.io)"},{name:"Sheets & playkit"},{name:"Oracle generator tool"}]}}),registerSystem("stars-without-number",{groups:{default:{key:"osr",order:15},family:{key:"osr-classic",order:9},genre:{key:"sci-fi",order:12},solo:{key:"solo-compatible",order:16}},name:"Stars Without Number",publisher:"Sine Nomine Publishing / Kevin Crawford",dice:"d20 (combat) + 2d6 (skills)",players:"3–6",complexity:3,edition:"B/X",free:!0,foundryStatus:"Community",heroImage:"https://image.nobleknight.com/s/jpg1500/swnrevised.jpg",playstyleTags:["explore","sandbox","combat"],settingTags:["space"],gallery:[{src:"https://image.nobleknight.com/s/jpg1500/swnrre.jpg"}],resources:[{type:"quickstart",url:"https://www.drivethrurpg.com/en/product/230009/stars-without-number-revised-edition-free-version",fmt:"PDF"},{type:"link",url:"https://www.drivethrurpg.com/en/publisher/3482/Sine-Nomine-Publishing",fmt:"Web"}],mechanics:[{icon:"orbit"},{icon:"flag"},{icon:"dices"},{icon:"rocket"}],quotes:[{text:"Stars Without Number is a solid and expansive entry in the science fiction RPG genre; the OSR backbone is yet another bonus.",author:"Aaron Marks, Cannibal Halfling Gaming"},{text:"it's hard to think of a better start point for a GM who wants to write a space sandbox.",author:"Aaron Marks, Cannibal Halfling Gaming"}],ru:{tagShort:"B/X в космосе: сай-фай песочница",tagline:"«Год 3200. Империя человечества лежит в руинах — а перед вами целый сектор».",description:"Stars Without Number — олдскульная научно-фантастическая RPG, целиком заточенная под песочницу и облегчение труда ведущего. Наследие B/X в космосе: атрибуты, классы, спасброски, но с генераторами секторов, миров и фракций. Знаменита бесплатной полной версией и лучшим в жанре инструментарием для sandbox-кампаний.",setting:"Через 600 лет после «Крика» — телепатической катастрофы, оборвавшей сверхсветовые пути и обрушившей галактическую цивилизацию. Теперь человечество заново сшивает разорванные звёзды: фронтирные миры, забытые технологии Предтеч, псионики и молчаливые ИИ. Классический космический фронтир, готовый к освоению.",vignette:"Ваш экипаж высаживается на мире с тегами «Изгнанники» и «Запретные технологии». Инженер вскрывает древний терминал Предтеч — проверка навыка: 2d6 + Интеллект + Fix. Выпало 9, порог 8 — успех, но терминал пробуждается. Между сессиями ход фракции: местный культ делает бросок на «Захватить актив». Сектор живёт сам, без рельсов.",prep:"~20 мин",mechanics:[{title:"Генерация сектора и миров",text:"За вечер собирается звёздный сектор: броски по таблицам создают миры, а два «тега мира» на каждый задают конфликты и завязки. Готовая песочница почти без ручной работы."},{title:"Ходы фракций",text:"Фракции действуют между сессиями как в стратегии: строят активы, атакуют друг друга, захватывают миры. Мир меняется сам — ведущему не нужно вести игроков за руку."},{title:"Гибрид d20 + 2d6",text:"Бой — привычный d20 против AC. Навыки — 2d6 + атрибут + навык против порога. Две простые механики, знакомые всем, кто играл в олдскульную D&D."},{title:"Три класса и фокусы",text:"Воин, Эксперт, Псионик (и Авантюрист-мультикласс). «Фокусы» тонко настраивают героя. Псионика — отдельная опасная система с телепатией, телекинезом и метапсионикой."}],gallery:[{cap:"Revised Edition"}],resources:[{name:"Бесплатная полная версия (DriveThruRPG)"},{name:"Sine Nomine Publishing"}],quotes:[{text:"Stars Without Number — крепкий и обширный представитель жанра научной фантастики; OSR-основа лишь добавляет плюсов."},{text:"Трудно представить лучшую отправную точку для ведущего, который хочет написать космическую песочницу."}]},en:{tagShort:"B/X in space: a sci-fi sandbox toolkit",tagline:`"The year is 3200 and mankind's empire lies in ashes — and a whole sector waits."`,description:"Stars Without Number is an old-school-inspired sci-fi RPG built from the ground up for sandbox play and to simplify the GM's job. B/X heritage in space — attributes, classes, saves — paired with generators for sectors, worlds, and factions. Famous for its genuinely complete free edition and the best sandbox-campaign toolkit in the genre.",setting:"Six hundred years after the Scream — a psychic catastrophe that severed faster-than-light travel and collapsed galactic civilization. Now humanity re-stitches the shattered stars: frontier worlds, forgotten Precursor tech, psychics, and silent AIs. A classic space frontier, wide open to explore.",vignette:"Your crew lands on a world tagged 'Exile Colony' and 'Forbidden Tech.' The engineer cracks an ancient Precursor terminal — skill check: 2d6 + Intelligence + Fix. She rolls a 9 against difficulty 8 — success, but the terminal wakes up. Between sessions, a faction turn: a local cult rolls to Seize an Asset. The sector lives on its own, no rails required.",prep:"~20 min",mechanics:[{title:"Sector & world generation",text:"Roll up a star sector in an evening: tables generate worlds, and two 'World Tags' per world seed conflicts and adventure hooks. A ready-made sandbox with almost no hand-crafting."},{title:"Faction turns",text:"Factions act between sessions like a strategy game: building assets, attacking each other, seizing worlds. The setting evolves by itself — the GM never has to railroad."},{title:"d20 + 2d6 hybrid",text:"Combat is familiar d20 vs AC. Skills are 2d6 + attribute + skill against a difficulty. Two simple mechanics anyone who's played old-school D&D already knows."},{title:"Three classes & Foci",text:"Warrior, Expert, Psychic (plus the Adventurer multiclass). 'Foci' fine-tune a hero. Psionics is its own dangerous system of telepathy, telekinesis, and metapsionics."}],gallery:[{cap:"Revised Edition"}],resources:[{name:"Free complete edition (DriveThruRPG)"},{name:"Sine Nomine Publishing"}],quotes:[{text:"Stars Without Number is a solid and expansive entry in the science fiction RPG genre; the OSR backbone is yet another bonus."},{text:"it's hard to think of a better start point for a GM who wants to write a space sandbox."}]}}),registerSystem("sword-and-wizardry",{groups:{default:{key:"osr",order:6.5},family:{key:"osr-classic",order:5},genre:{key:"dark-fantasy",order:5.5}},name:"Swords & Wizardry",publisher:"Mythmere Games / Matt Finch",dice:"d20 + d4–d12",players:"2–6",complexity:2,edition:"OD&D",free:!0,foundryStatus:"Community",heroImage:"https://www.mythmeregames.com/cdn/shop/files/Swords_Wizardry_f97618b8-689a-4b99-a580-ca1a2182a1cc.png?v=1707749908",playstyleTags:["combat","explore","sandbox","survival"],settingTags:["fantasy","sword-and-sorcery"],gallery:[{src:"https://www.mythmeregames.com/cdn/shop/files/Swords_Wizardry_f97618b8-689a-4b99-a580-ca1a2182a1cc.png?v=1707749908"},{src:"https://www.mythmeregames.com/cdn/shop/files/SWPlayerBook20232_a8c5d191-e209-406f-878d-63f60a271a85.jpg"},{src:"https://www.mythmeregames.com/cdn/shop/files/SWPlayerBook20233_b52fdac8-d4ed-4a1d-87cf-cfff19ebea7c.jpg"},{src:"https://www.mythmeregames.com/cdn/shop/files/SWPlayerBook20234_08e48758-c05f-4ce8-ba9a-f67252765223.jpg"}],resources:[{type:"link",url:"https://www.mythmeregames.com/products/swords-wizardry-complete-revised-a-fantasy-role-playing-game",fmt:"Web"},{type:"sheet",url:"https://www.mythmeregames.com/products/swords-wizardry-character-sheets-pdf-free",fmt:"Web"}],mechanics:[{icon:"swords"},{icon:"dices"},{icon:"book-open"},{icon:"scroll"}],quotes:[{text:"This latest evolution of Swords & Wizardry is easily the best yet; a standout in the crowded retro-clone field and a legitimate contender for the honor of greatest 'D&D' rule book ever devised.",author:"Will Mistretta, It's okay; Gary sent us."},{text:"Swords & Wizardry is much more eclectic and opinionated. It's also much more playable, more hackable, and more easily used as a 'modern' RPG... S&W Complete Revised is the best of these.",author:"Mark Damon Hughes, mdhughes.tech"}],ru:{tagShort:"Ретроклон OD&D",tagline:"«Первая RPG, причёсанная и улучшенная».",description:"Swords & Wizardry Complete Revised — ENNIE-награждённый ретроклон оригинальной D&D (1974–1978). Мэтт Финч собрал все ранние супплементы в единую книгу на 144 страницы. Девять классов, пять рас, ~200 заклинаний, 160+ монстров. Философия «rulings over rules» — основа OSR-движения.",setting:"Система-агностик. Подразумеваемый мир — классическое sword-and-sorcery в духе Ховарда и Лейбера. Средневековое фэнтези с руинами, древними тайнами и силами Порядка против Хаоса. Поддерживает всё от приземистого low-fantasy до гонзо-фантастики с андроидами и марсианами.",vignette:"Гримм, дварф-воин, прижимается ухом к замшелой двери — за ней орки. Мира-воровка достаёт кинжал и проверяет замок. Факел мерцает. Гримм выбивает дверь — орки в шоке, у Миры внезапная атака. Бой быстр и летален: один хороший удар может убить любого.",prep:"~10 мин",mechanics:[{title:"Единый спасбросок",text:"Вместо пяти категорий спасбросков — один универсальный спасбросок, зависящий от класса и уровня. Просто и элегантно."},{title:"Нисходящий и восходящий AC",text:"Каждое чудовище и правило даны с обоими вариантами AC. Совместимость с любыми приключениями — как старыми, так и новыми."},{title:"Четыре системы инициативы",text:"В комплекте четыре варианта: от стандартного d6 до DEX-ранга и системы действий из Eldritch Wizardry. Выбирайте под свой стиль."},{title:"Rulings over Rules",text:"Правила намеренно оставляют пробелы для рефери. Быстрые решения вместо поиска по книге. Полиморф — 63 слова, доверьтесь ведущему."}],gallery:[{cap:"Обложка Complete Revised"},{cap:"Разворот книги"},{cap:"Интерьер"},{cap:"Иллюстрации"}],resources:[{name:"Официальный сайт — Mythmere Games"},{name:"Листы персонажей"}],quotes:[{text:"Эта последняя эволюция Swords & Wizardry — лучшая на данный момент; выдающаяся работа в переполненном поле ретроклонов и законный претендент на звание величайшей книги правил D&D из когда-либо созданных."},{text:"Swords & Wizardry гораздо более эклектичная и своеобразная. Она также куда более играбельная, хакабельная, и легче используется как «современная» RPG."}]},en:{tagShort:"OD&D retroclone, rulings over rules",tagline:'"The ENNIE award-winning retro-clone of the original fantasy roleplaying game."',description:"Swords & Wizardry Complete Revised is the definitive edition of the ENNIE award-winning retro-clone of original D&D (1974–1978). Matt Finch distilled all the early supplements into one cohesive 144-page rulebook: nine classes, five ancestries, ~200 spells, 160+ monsters, and procedures for dungeon and wilderness play. The rulings-over-rules philosophy that defined the OSR movement.",setting:"Setting-agnostic. The implied world is classic pulp sword-and-sorcery in the tradition of Howard, Leiber, and Vance — medieval fantasy with crumbling dungeons, ancient mysteries, and the war of Law vs. Chaos. Supports everything from gritty low-fantasy to gonzo sci-fantasy with androids and Martians.",vignette:"Grimm the dwarf fighter presses his ear to the moss-caked door — orcish voices beyond. Mira the thief draws her dagger and checks the lock. Torchlight flickers. Grimm kicks the door open — Surprise is theirs. Combat is swift and deadly; one good hit can fell any man, and the players know it.",prep:"~10 min",mechanics:[{title:"Single Saving Throw",text:"Instead of five traditional saving throw categories, S&W uses one unified saving throw based on class and level. Simple and elegant."},{title:"Ascending & Descending AC",text:"Every monster and rule includes both ascending and descending AC. Seamless compatibility with classic and modern adventures alike."},{title:"Four Initiative Systems",text:"The book includes four distinct initiative options — from standard d6 group roll to DEX-rank and activity-point systems from Eldritch Wizardry."},{title:"Rulings over Rules",text:"The rules deliberately leave gaps for the Referee to fill. Quick rulings over rulebook lookup. Polymorph Self: 63 words — trust the GM."}],gallery:[{cap:"Complete Revised cover"},{cap:"Book spread"},{cap:"Interior pages"},{cap:"Illustrations"}],resources:[{name:"Official website — Mythmere Games"},{name:"Character sheets (free PDF)"}]}}),registerSystem("symbaroum",{groups:{default:{key:"narrative",order:44},family:{key:"standalone",order:52},genre:{key:"dark-fantasy",order:27}},name:"Symbaroum",publisher:"Free League Publishing (Järnringen)",dice:"d20 roll-under",players:"2–6",complexity:3,free:!1,edition:null,foundryStatus:"Official",heroImage:"https://image.nobleknight.com/i/jpg1500/impmuh100001.jpg",playstyleTags:["explore","mystery","horror"],settingTags:["fantasy","weird"],gallery:[{src:"https://image.nobleknight.com/i/jpg1500/impmuh051001.jpg"},{src:"https://image.nobleknight.com/i/jpg1500/impmuh050550.jpg"},{src:"https://image.nobleknight.com/i/jpg1500/impmuh051614.jpg"}],resources:[{type:"link",url:"https://freeleaguepublishing.com/games/symbaroum/",fmt:"Web"},{type:"link",url:"https://freeleaguepublishing.com/shop/symbaroum/core-rulebook/",fmt:"Web"},{type:"link",url:"https://foundryvtt.com/packages/symbaroum/",fmt:"VTT"}],mechanics:[{icon:"dices"},{icon:"skull"},{icon:"trees"},{icon:"eye"}],quotes:[{text:"Symbaroum is a really cool dark fantasy game. It's not only a gorgeous and evocative product with brilliant art and design, it's also a setting that evokes strong melancholia and has a strong philosophical component.",author:"SKaye, The Tabletop Almanac"},{text:"The artwork is fantastic and a great accompaniment to the intricate lore of the setting.",author:"Will Worrall, Gaming Respawn"}],ru:{tagShort:"тёмное фэнтези Давокара",tagline:"«Приключения ждут в глубинах Давокара — но за жадными следует порча».",description:"Symbaroum — ролевая игра в жанре тёмного фэнтези, действие которой разворачивается вокруг Давокара, древнего леса, скрывающего руины погибшей цивилизации. Амбрийские беженцы углубляются в чащу в погоне за сокровищами, а варварские кланы и эльфы Железного Пакта предупреждают: под корнями пробуждается нечто древнее. Игра сочетает экспедиции за сокровищами, тревожную политику и наползающую порчу. Система знаменита тем, что кубики бросают только игроки: вы кидаете один d20 под свои характеристики, а монстры не бросают вовсе.",setting:"Королевство беженцев Амбрия расположено на южной кромке Давокара — огромного сумрачного леса. Под его пологом лежат руины Симбарума, павшей империи, чьи реликвии манят охотников за сокровищами, а погребённое зло отравляет всякого, кто копает слишком глубоко. Варварские кланы, ведьмы и эльфийский Железный Пакт хранят тайны чащи.",vignette:"Ваш охотник берёт на прицел искажённого порчей оленя, преградившего тропу. Меткость — 13, значит нужно выбросить 13 или меньше на d20 — вы кидаете 6. Чистое попадание. Но порча зверя растекается по поляне, и ведущий требует проверки. Ваша Решимость — 11; на d20 выпадает 15. Провал — вы получаете единицу временной порчи, и шёпот заползает вам в голову.",prep:"~30 мин",mechanics:[{title:"Броски только у игроков",text:"Кубики бросают лишь игроки. Вы кидаете один d20 и должны выбросить не больше нужной характеристики; монстры ведущего используют фиксированные значения и не бросают против вас."},{title:"Порча",text:"Колдовство и тёмные реликвии пятнают душу. За сцену копится временная порча, а превышение вашего порога делает вас Полностью Порченым — путь к превращению в чудовище."},{title:"Экспедиции в Давокар",text:"Кампании строятся вокруг вылазок за сокровищами в живой, опасный лес. Руины вознаграждают смелых, но каждый добытый артефакт грозит порчей и гневом Железного Пакта."},{title:"Сборка без классов",text:"Никаких жёстких классов. Персонажи смешивают архетипы и свободно покупают способности, силы и ритуалы, углубляя нишу или осваивая новые по мере роста опыта."}],gallery:[{cap:"Расширенное руководство игрока"},{cap:"Тистл-Холд: Гнев Стража"},{cap:"Набор приключений"}],resources:[{name:"Официальный сайт"},{name:"Базовая книга (магазин Free League)"},{name:"Система для Foundry VTT"}],quotes:[{text:"Symbaroum — по-настоящему классная игра в жанре тёмного фэнтези. Это не только великолепный и выразительный продукт с блестящим артом и дизайном, но и сеттинг, пронизанный глубокой меланхолией и сильной философской составляющей."},{text:"Иллюстрации великолепны и прекрасно дополняют богатый, детально проработанный лор сеттинга."}]},en:{tagShort:"dark fantasy of Davokar",tagline:'"Adventure awaits in the depths of Davokar — but corruption follows the greedy."',description:"Symbaroum is a dark fantasy RPG set around Davokar, an ancient forest hiding the ruins of a lost civilization. Ambrian refugees push into the wood chasing treasure, while barbarian clans and the elven Iron Pact warn that something old is stirring beneath the roots. Play blends treasure-hunting expeditions, uneasy politics, and creeping corruption. The system is famously player-facing: you roll a single d20 under your attributes, while monsters never roll at all.",setting:"The refugee kingdom of Ambria sits on the southern edge of Davokar, a vast, shadowed forest. Beneath its canopy lie the ruins of Symbaroum, a fallen empire whose relics tempt treasure hunters and whose buried evil poisons anyone who digs too deep. Barbarian clans, witches, and the elven Iron Pact all guard the wood's secrets.",vignette:"Your hunter draws a bead on the blight-twisted stag blocking the trail. Accurate is 13, so you need 13 or lower on the d20 — you roll a 6. Clean hit. But the beast's corruption leaks into the glade and the GM calls for a test. Your Resolute is 11; the d20 shows 15. Failure — you take a point of temporary corruption as whispers crawl into your skull.",prep:"~30 min",mechanics:[{title:"Player-facing d20",text:"Only players roll dice. You roll a single d20 and must land at or under the relevant attribute; the GM's monsters use fixed values and never roll against you."},{title:"Corruption",text:"Sorcery and dark relics stain the soul. Temporary corruption builds through a scene, and crossing your threshold turns you Thoroughly Corrupt — a slide toward becoming an abomination."},{title:"Davokar expeditions",text:"Campaigns revolve around treasure-hunting forays into a living, dangerous forest. Ruins reward the bold, but every unearthed artifact risks corruption and the wrath of the Iron Pact."},{title:"Classless builds",text:"No rigid classes. Characters mix archetypes and buy abilities, powers, and rituals freely, deepening a niche or branching into new ones as experience accrues."}],gallery:[{cap:"Advanced Player's Guide"},{cap:"Thistle Hold: Wrath of the Warden"},{cap:"Adventure Pack"}],resources:[{name:"Official website"},{name:"Core Rulebook (Free League shop)"},{name:"Foundry VTT system"}],quotes:[{text:"Symbaroum is a really cool dark fantasy game. It's not only a gorgeous and evocative product with brilliant art and design, it's also a setting that evokes strong melancholia and has a strong philosophical component."},{text:"The artwork is fantastic and a great accompaniment to the intricate lore of the setting."}]}}),registerSystem("tales-loop",{groups:{default:{key:"fl",order:6},family:{key:"year-zero",order:6},genre:{key:"adventure",order:7}},name:"Tales from the Loop",publisher:"Free League / Year Zero Engine",dice:"Пул d6",players:"3–5",complexity:2,foundryStatus:"Official контент",heroImage:"https://freeleaguepublishing.com/wp-content/uploads/2023/09/TalesfromtheLoop-1440x720.jpg",playstyleTags:["mystery","narrative","social"],settingTags:["modern","weird"],gallery:[{src:"https://freeleaguepublishing.com/wp-content/uploads/2023/09/lokskeppt67_1920.jpg"},{src:"https://freeleaguepublishing.com/wp-content/uploads/2023/09/talesfromtheloop2-scaled.jpg"},{src:"https://freeleaguepublishing.com/wp-content/uploads/2023/09/talesfromtheloop3-scaled.jpg"},{src:"https://freeleaguepublishing.com/wp-content/uploads/2023/09/talesfromtheloop4-scaled.jpg"},{src:"https://freeleaguepublishing.com/wp-content/uploads/2023/09/talesfromtheloop5-scaled.jpg"}],resources:[{type:"link",url:"https://freeleaguepublishing.com/games/tales-from-the-loop/",fmt:"Web"},{type:"sheet",url:"https://www.drivethrurpg.com/en/product/210617/tales-from-the-loop-character-sheet",fmt:"PDF"}],mechanics:[{icon:"baby"},{icon:"heart"},{icon:"home"},{icon:"atom"}],quotes:[{text:"Tales From The Loop RPG Will Make You Feel Like a (Stranger Things) Kid Again",author:"Beth Elderkin, io9 / Gizmodo"}],ru:{tagShort:"Альт-80-е, мистика",tagline:"«Альтернативные 80-е. Роботы, динозавры и тайны, которые видят только дети».",description:"Вы — подростки 10–15 лет в альтернативных 80-х, где гигантский подземный ускоритель частиц (Петля) создаёт аномалии. Роботы ходят по улицам, но взрослые не замечают странного. Главное правило: дети не умирают. Но теряют друзей, невинность и веру в безопасный мир.",setting:"Швеция или США 1980-х, альтернативная история. Правительство построило Петлю — подземный ускоритель. Побочные эффекты: автономные роботы, гравитационные аномалии, временные петли, динозавры в озере. Визуально — меланхоличные картины Симона Столенхага: роботы на фоне шведских лугов.",vignette:"Вам 13 лет. Робот на свалке за школой снова включился и зовёт кого-то по имени Эрик. Бросок Расследования — 3 кубика, ни одной шестёрки. Провал. Вы тратите очко Удачи и перебрасываете, но после школы мама требует, чтобы вы вернулись домой до темноты. Робот ждёт. Якорный Взрослый — учитель физики — что-то знает, но боится рассказать.",prep:"~20 мин",mechanics:[{title:"Дети не умирают",text:"Главное правило. Система защищает от смерти, но не от страха, потерь и взросления."},{title:"Повседневная драма",text:"Между тайнами — школа, родители, первая любовь. Эмоциональный якорь для приключений."},{title:"Якорный взрослый",text:"У каждого ребёнка — взрослый, к которому можно обратиться. Учитель, сосед, старший брат. Связь, которая спасает."},{title:"Тайны Петли",text:"Каждая тайна — мини-сценарий: что-то странное происходит, дети расследуют, мир никогда не будет прежним."}],gallery:[{cap:"Столенхаг — пейзаж"},{cap:"Арт из книги"},{cap:"Робот и дети"},{cap:"Зимний пейзаж"},{cap:"Мальпарн"}],resources:[{name:"Официальный сайт"},{name:"Официальный лист"}],quotes:[{text:"Tales From The Loop RPG снова заставит почувствовать себя ребёнком — в духе «Очень странных дел»."}]},en:{tagShort:"kids '80s mystery RPG",tagline:`"Alternate '80s. Robots, dinosaurs, and mysteries only kids can see."`,description:"You are teenagers aged 10-15 in an alternate 1980s, where a giant underground particle accelerator (the Loop) creates anomalies. Robots walk the streets, but adults don't notice the strange. The core rule: kids don't die. But they lose friends, innocence, and faith in a safe world.",setting:"1980s Sweden or USA, alternate history. The government built the Loop — an underground accelerator. Side effects: autonomous robots, gravitational anomalies, time loops, dinosaurs in the lake. Visually — Simon Stalenhag's melancholic paintings: robots against Swedish meadows.",vignette:"You're 13. The robot at the junkyard behind the school has powered on again and is calling for someone named Erik. Investigation roll — 3 dice, no sixes. Failure. You spend a Luck point to reroll, but after school Mom demands you be home before dark. The robot waits. Your Anchor Adult — the physics teacher — knows something but is afraid to tell.",prep:"~20 min",mechanics:[{title:"Kids don't die",text:"The core rule. The system protects from death, but not from fear, loss, and growing up."},{title:"Everyday drama",text:"Between mysteries — school, parents, first love. An emotional anchor for adventures."},{title:"Anchor adult",text:"Every kid has an adult they can turn to. A teacher, neighbor, older sibling. A bond that saves."},{title:"Mysteries of the Loop",text:"Each mystery is a mini-scenario: something strange happens, the kids investigate, and the world is never the same."}],gallery:[{cap:"Stalenhag — landscape"},{cap:"Book art"},{cap:"Robot and kids"},{cap:"Winter landscape"},{cap:"Malparen"}],resources:[{name:"Official website"},{name:"Official sheet"}]}}),registerSystem("tales-of-argosa",{groups:{default:{key:"osr",order:17},family:{key:"standalone",order:23},genre:{key:"sword-and-sorcery",order:6}},name:"Tales of Argosa",publisher:"Pickpocket Press",dice:"d20 (roll-under + roll-high combat)",players:"3–6",complexity:3,free:!0,foundryStatus:"Community",heroImage:"https://lowfantasygaming.com/wp-content/uploads/2024/07/image-1.png",playstyleTags:["combat","explore","survival"],settingTags:["fantasy","sword-and-sorcery"],gallery:[{src:"https://lowfantasygaming.com/wp-content/uploads/2024/07/image-8.png"},{src:"https://lowfantasygaming.com/wp-content/uploads/2024/01/mines-of-perinthos-thumb.png"}],resources:[{type:"link",url:"https://lowfantasygaming.com/tales-of-argosa/",fmt:"Web"}],mechanics:[{icon:"dices"},{icon:"clover"},{icon:"flame"},{icon:"swords"}],quotes:[{text:"If high-octane Sword & Sorcery action with little downtime and low-to-no-prep are what you want, Tales of Argosa is an ideal system.",author:"Brian C. Rideout, Welcome to the Deathtrap"},{text:"I find myself fighting the urge to play Tales of Argosa right away, which is usually a good sign",author:"Andy Slack, Halfway Station"}],ru:{tagShort:"Грим-фэнтези low-magic, наследник Low Fantasy Gaming",tagline:"«Меч-и-магия без прикрас: жестоко, стремительно, почти без подготовки».",description:"Tales of Argosa — самостоятельная и отшлифованная наследница Low Fantasy Gaming от Стивена Гродзицки. Собственный d20-движок для мрачного low-magic фэнтези: проверки «меньше-равно», бой «больше», отдельный стат Удачи и рискованная «Тёмная и Опасная магия». Заточена под быструю игру в духе kick-in-the-door с минимумом подготовки; поддерживает соло и игру без ведущего.",setting:"Приземлённый меч-и-магия: магия редка, опасна и внушает страх. Наёмники, воры и отчаянные авантюристы бьются за серебро на суровом фронтире — не эпические герои, а люди, которым надо выжить и не остаться без гроша. Низкое фэнтези с зубами: болота, руины, работорговцы и твари из глубин.",vignette:"Разбойник крадётся мимо спящего огра — проверка Ловкости «меньше-равно»: d20 против значения. Выпало 8, порог 12 — тихо прошёл. Дальше маг решается на заклинание: у Tales есть шанс сработать «Тёмной и Опасной магии». Бросок по таблице осечек — и посох вспыхивает не туда. Магия здесь не бесплатна.",prep:"~10 мин",mechanics:[{title:"«Меньше» и «больше»",text:"Проверки атрибутов, навыков и Удачи — бросок d20 «меньше-равно». Бой — бросок «больше» против защиты. Смешанно, но быстро: за столом решения принимаются мгновенно."},{title:"Стат Удачи",text:"У каждого героя есть Удача — её тратят, чтобы подкрутить бросок, избежать смерти или урвать преимущество. Ресурс восстанавливается; в грязном мире Аргосы удача решает многое."},{title:"Тёмная и Опасная магия",text:"Заклинания могут сорваться в хаос: бросок по таблице жутких осечек. Магия редка, страшна и никогда не рутина — ровно тот low-magic тон, что задаёт весь сеттинг."},{title:"Low-prep, kick-in-the-door",text:"Система создана ради темпа и минимальной подготовки: генераторы на лету, стремительные вылазки, высокая летальность. Поддержка соло и игры без ведущего в комплекте."}],gallery:[{cap:"Обложка"},{cap:"Mines of Perinthos — разворот"}],resources:[{name:"Официальный сайт — Low Fantasy Gaming"}],quotes:[{text:"Если вам нужен драйвовый меч-и-магии экшн с минимумом простоя и почти без подготовки — Tales of Argosa идеальная система."},{text:"Я ловлю себя на желании сыграть в Tales of Argosa прямо сейчас, а это обычно хороший знак."}]},en:{tagShort:"Grim low-magic fantasy, successor to Low Fantasy Gaming",tagline:'"Sword & sorcery with no gloss: brutal, fast, and almost prep-free."',description:"Tales of Argosa is Stephen Grodzicki's standalone, polished successor to Low Fantasy Gaming. Its own d20 engine for grim low-magic fantasy: roll-under checks, roll-high combat, a dedicated Luck stat, and risky 'Dark & Dangerous Magic'. Built for fast, kick-in-the-door play with minimal prep — and it supports solo and GM-less play out of the box.",setting:"Grounded sword-and-sorcery: magic is rare, dangerous, and feared. Mercenaries, thieves, and desperate adventurers fight over silver on a harsh frontier — not epic heroes, but people who need to survive and stay solvent. Low fantasy with teeth: swamps, ruins, slavers, and things from the deep.",vignette:"The rogue creeps past a sleeping ogre — a Dexterity roll-under check: d20 against the value. An 8 against a target of 12 — through in silence. Ahead, the mage risks a spell: in Tales, casting can trigger 'Dark & Dangerous Magic.' A roll on the mishap table — and the staff flares the wrong way. Magic here is never free.",prep:"~10 min",mechanics:[{title:"Roll-under & roll-high",text:"Attribute, skill, and Luck checks are roll-under d20. Combat rolls high against a defense. Mixed but fast — decisions land instantly at the table."},{title:"The Luck stat",text:"Every hero has Luck — spent to nudge a roll, cheat death, or seize an edge. It refreshes; in the grubby world of Argosa, luck decides a great deal."},{title:"Dark & Dangerous Magic",text:"Spells can spiral into chaos: a roll on a table of grisly mishaps. Magic is rare, frightening, and never routine — exactly the low-magic tone that defines the setting."},{title:"Low-prep, kick-in-the-door",text:"Built for pace and minimal prep: on-the-fly generators, swift raids, high lethality. Solo and GM-less support are included in the box."}],gallery:[{cap:"Cover"},{cap:"Mines of Perinthos spread"}],resources:[{name:"Official site — Low Fantasy Gaming"}],quotes:[{text:"If high-octane Sword & Sorcery action with little downtime and low-to-no-prep are what you want, Tales of Argosa is an ideal system."},{text:"I find myself fighting the urge to play Tales of Argosa right away, which is usually a good sign."}]}}),registerSystem("ten-candles",{groups:{default:{key:"narrative",order:39},family:{key:"standalone",order:47},genre:{key:"horror",order:12}},name:"Ten Candles",publisher:"Cavalry Games",dice:"d6 пулы + десять свечей-таймер",players:"3–5",complexity:1,foundryStatus:"None",heroImage:"https://images.squarespace-cdn.com/content/v1/54cbdf08e4b0b8ab2e74ea9f/1619467732729-5U8IZCJMY3ZTMC6KKUR8/tencandles-10.png",playstyleTags:["narrative","horror","survival"],settingTags:["modern"],gallery:[{src:"https://images.squarespace-cdn.com/content/v1/54cbdf08e4b0b8ab2e74ea9f/1619466008887-TFKCOGXSSKRLUUQG3G9J/Cv5dI7TWgAARHRY.jpg"},{src:"https://images.squarespace-cdn.com/content/v1/54cbdf08e4b0b8ab2e74ea9f/1619466008888-MX1KUUI84H0EQYIB52O9/CvPrqdxWIAAhsop.jpg"},{src:"https://images.squarespace-cdn.com/content/v1/54cbdf08e4b0b8ab2e74ea9f/1619466009391-V22S8NCG26F2XWDCAWTW/CwIWn07XgAEuJsH.jpg"}],resources:[{type:"link",url:"https://cavalrygames.com/ten-candles-info",fmt:"Web"}],mechanics:[{icon:"flame"},{icon:"dices"},{icon:"hourglass"},{icon:"skull"}],quotes:[{text:"Ten Candles is as much ritual as game.",author:"Cynthia Hornbeck, Shut Up & Sit Down"},{text:"Ten Candles is a masterful storytelling game by Stephen Dewey.",author:"Justin Alexander, The Alexandrian"}],ru:{tagShort:"Трагический хоррор при свете десяти свечей",tagline:"«Вы точно погибнете. Игра — о том, как именно».",description:"Ten Candles — трагический сторигейм-хоррор Стивена Дьюи для одного вечера. Мир погрузился во тьму десять дней назад, и в темноте что-то охотится. Играется буквально при свете десяти свечей: они гаснут по ходу истории и служат таймером обречённости. Без подготовки, без хэппи-энда — только то, как ваши герои встретят конец.",setting:"Через десять дней после того, как погас весь свет солнца. В темноте живут «Они» — то, что охотится на выживших. Электричество мертво, надежда тает. Это не игра о победе: финал предрешён, все персонажи погибнут. Ценность — в достоинстве, любви и страхе последних часов, рассказанных как послание тем, кто, может быть, ещё жив.",vignette:"Пять свечей ещё горят. Ваш герой пытается завести заглохшую машину, пока Они приближаются. Собираете пул d6 по числу горящих свечей; шестёрка — успех. Ни одной шестёрки — провал, и вы гасите свечу. Комната темнеет ещё на одну ступень. Осталось четыре огонька. Голосом, дрожащим в темноте, вы описываете, как надежда утекает сквозь пальцы.",prep:"~0 мин",mechanics:[{title:"Десять свечей — таймер",text:"На столе горят десять настоящих свечей. Они гаснут по ходу игры (при провалах и в конце сцен) и отсчитывают гибель. Когда погаснет последняя — умирают все. Буквальный обратный отсчёт до конца."},{title:"Тающий пул кубиков",text:"Проверки — пул d6 по числу горящих свечей и черт. С каждой погасшей свечой пул сжимается: механически надежда угасает, и мир вокруг темнеет вместе с ней."},{title:"Ноль подготовки, гарантированная гибель",text:"Ведущему не нужна подготовка. Игра честно говорит: вы погибнете. Карточки Добродетелей, Пороков, Моментов и Граней задают, за что персонаж цепляется — и что его сломает."},{title:"Ритуал и послание",text:"Сессия — почти обряд: приглушённый свет, записанные «на плёнку» голоса героев как послание будущим выжившим. Атмосфера важнее правил; один вечер — одна законченная трагедия."}],gallery:[{cap:"За столом при свечах"},{cap:"Игровая сцена"},{cap:"Атмосфера"}],resources:[{name:"Официальная страница — Cavalry Games"}]},en:{tagShort:"Tragic horror told by the light of ten candles",tagline:'"You are going to die. The game is about how."',description:"Ten Candles is Stephen Dewey's tragic story-horror game for a single evening. The world went dark ten days ago, and something hunts in the darkness. It's played by the literal light of ten candles: they go out as the story unfolds, serving as a timer of doom. Zero prep, no happy ending — only how your characters meet the end.",setting:"Ten days after all the sun's light went out. In the dark live 'Them' — the things that hunt survivors. The power is dead, hope is fading. This isn't a game about winning: the ending is fixed, every character will die. The value is in the dignity, love, and fear of the final hours, told as a message for those who might still be alive.",vignette:"Five candles still burn. Your character tries to start a dead car as They close in. You gather a d6 pool equal to the burning candles; a six is a success. No sixes — a failure, and you snuff a candle. The room darkens one step further. Four flames left. In a voice trembling in the dark, you describe hope slipping through your fingers.",prep:"~0 min",mechanics:[{title:"Ten candles — the timer",text:"Ten real candles burn on the table. They go out as play goes on (on failures and at scene ends), counting down to doom. When the last dies, everyone dies. A literal countdown to the end."},{title:"A dwindling dice pool",text:"Tests are a d6 pool sized by the burning candles and traits. With each snuffed candle the pool shrinks: hope mechanically fades, and the world darkens with it."},{title:"Zero prep, guaranteed death",text:"The GM needs no prep. The game tells you plainly: you will die. Cards for Virtues, Vices, Moments, and Brinks define what a character clings to — and what will break them."},{title:"Ritual and message",text:"A session is almost a rite: dimmed light, the heroes' voices 'recorded' as a message to future survivors. Atmosphere over rules; one evening, one complete tragedy."}],gallery:[{cap:"At the candlelit table"},{cap:"A scene of play"},{cap:"Atmosphere"}],resources:[{name:"Official page — Cavalry Games"}]}}),registerSystem("the-black-hack",{groups:{default:{key:"osr",order:18},family:{key:"osr-modern",order:2},genre:{key:"adventure",order:17}},name:"The Black Hack",publisher:"David Black / Gold Piece Publications",dice:"Roll-under d20 + Usage Dice",players:"3–6",complexity:1,foundryStatus:"Community",heroImage:"https://image.nobleknight.com/b/jpg1500/blackhack2.jpg",playstyleTags:["combat","explore","survival"],settingTags:["fantasy"],gallery:[{src:"https://image.nobleknight.com/b/jpg1500/blackhack2eboxset.jpg"},{src:"https://image.nobleknight.com/b/jpg1500/blackhack2b.jpg"}],resources:[{type:"link",url:"https://squarehex.co.uk/collections/the-black-hack",fmt:"Web"}],mechanics:[{icon:"dices"},{icon:"battery-low"},{icon:"swords"},{icon:"feather"}],quotes:[{text:"The rules are simple and get out of the way. They are easy to hack and tweak as needed.",author:"Ramanan Sivaranjan, Save vs. Total Party Kill"}],ru:{tagShort:"Ультралёгкий d20 «меньше-равно», король хаков",tagline:"«Проще некуда — и потому переделан миллион раз».",description:"The Black Hack — предельно лёгкая OSR-игра: проверки броском «меньше-равно» d20 по характеристике, и все броски делают игроки. Двадцать страниц правил, знакомые классы и уровни, но без раздутых таблиц. Самый хакаемый движок старой школы: на его основе выросли Cthulhu Hack, Rad Hack, Black Sword Hack и десятки других.",setting:"Система-агностик. Подразумеваемый мир — классическое подземельное фэнтези: свеча, паёк, монстры во тьме. Но лёгкость правил делает Black Hack идеальным каркасом под любой сеттинг — от гримдарка до гонзо. Именно поэтому его так любят хакать под что угодно.",vignette:"Боец рубит гоблина: игрок кидает d20 против Силы 14, нужно 14 или меньше. Выпало 11 — попадание. Гоблин бьёт в ответ, но защищается тоже игрок: бросок против Ловкости. Факел на исходе — кость расхода факела d6 показывает 1, шаг вниз. Ещё пара сцен — и наступит тьма.",prep:"~10 мин",mechanics:[{title:"Броски «меньше-равно» d20",text:"Проверка — киньте d20 против характеристики, нужно значение или меньше. Игроки делают все броски: и атаку, и защиту. Ведущий не бросает — только описывает мир."},{title:"Кости расхода (Usage Dice)",text:"Патроны, паёк, факелы отслеживаются одной костью: использовал — бросок; выпало 1–2 — кость шагает вниз (d20→d12→…). Кончилась — ресурс иссяк. Никакого подсчёта единиц."},{title:"Преимущество и помеха",text:"Хорошая позиция — кидаете лишний d20 и берёте лучший. Плохая — худший. Простой, интуитивный модификатор вместо стопки бонусов."},{title:"Лёгкий и хакаемый",text:"Все правила — на пару десятков страниц. Настолько гибкий, что породил целое семейство «хаков» под любой жанр. Идеальный каркас, чтобы собрать свою игру."}],gallery:[{cap:"Box Set (2-е издание)"},{cap:"Задняя обложка"}],resources:[{name:"Официальный магазин — Squarehex"}],quotes:[{text:"Правила простые и не мешаются под ногами. Их легко хакать и подстраивать под себя."}]},en:{tagShort:"Ultra-light roll-under d20, the king of hacks",tagline:`"As simple as it gets — which is why it's been remixed a thousand times."`,description:"The Black Hack is an ultra-rules-light OSR game: checks are roll-under d20 against an attribute, and the players make every roll. Twenty pages of rules, familiar classes and levels, but none of the bloated tables. The most-hacked old-school engine going — Cthulhu Hack, Rad Hack, Black Sword Hack, and dozens more were built on its chassis.",setting:"Setting-agnostic. The implied world is classic dungeon fantasy: the candle, the ration, monsters in the dark. But the featherweight rules make The Black Hack an ideal frame for any setting — from grimdark to gonzo. That flexibility is exactly why people love to hack it into anything.",vignette:"The fighter swings at a goblin: the player rolls d20 against Strength 14, needing 14 or under. An 11 — a hit. The goblin strikes back, but the player defends too, rolling against Dexterity. The torch is burning low — its Usage Die (d6) comes up 1 and steps down. A few more scenes and the dark closes in.",prep:"~10 min",mechanics:[{title:"Roll-under d20",text:"To test something, roll d20 against an attribute and score equal or under. Players make all the rolls — attack and defense both. The GM never rolls; they just narrate the world."},{title:"Usage Dice",text:"Ammo, rations, torches are tracked by a single die: use it, roll it; on a 1–2 the die steps down (d20→d12→…). When it's gone, so is the resource. No counting individual units."},{title:"Advantage & Disadvantage",text:"A good position lets you roll an extra d20 and keep the better; a bad one, the worse. A simple, intuitive modifier instead of a stack of bonuses."},{title:"Light & hackable",text:"The whole game fits in a couple dozen pages. So flexible it spawned an entire family of 'hacks' across every genre. The perfect frame for building your own game."}],gallery:[{cap:"Box Set (2nd Edition)"},{cap:"Back cover"}],resources:[{name:"Official store — Squarehex"}],quotes:[{text:"The rules are simple and get out of the way. They are easy to hack and tweak as needed."}]}}),registerSystem("the-wretched",{groups:{default:{key:"narrative",order:18},family:{key:"standalone",order:13.5},genre:{key:"horror",order:5},solo:{key:"solo-journaling",order:2}},name:"The Wretched",publisher:"Loot The Room / Chris Bissette",dice:"d6 + playing cards + Jenga tower",players:"1",complexity:1,heroImage:"https://img.itch.zone/aW1nLzMyNjgzOTMucG5n/original/kYEj5R.png",playstyleTags:["horror","survival","narrative"],settingTags:["space"],gallery:[{src:"https://img.itch.zone/aW1hZ2UvNjE0MjgzLzMyNjgzODkucG5n/347x500/1hYOtq.png"},{src:"https://img.itch.zone/aW1hZ2UvNjE0MjgzLzQzMTYyMzEuanBn/347x500/p6tHSn.jpg"},{src:"https://img.itch.zone/aW1hZ2UvNjE0MjgzLzQzMTYyMzIuanBn/347x500/sjWRTo.jpg"}],resources:[{type:"link",url:"https://loottheroom.uk/the-wretched",fmt:"Web"},{type:"rules",url:"https://loottheroom.itch.io/wretched",fmt:"Web"},{type:"link",url:"https://www.drivethrurpg.com/en/product/311334/the-wretched",fmt:"Web"}],mechanics:[{icon:"layers"},{icon:"ghost"},{icon:"feather"},{icon:"radio"}],quotes:[{text:"The Wretched is what comes after that and it's atmospheric, frightening, and downright brilliant.",author:"Anna Blackwell, Tabletop Gaming Magazine"}],ru:{tagShort:"Соло Дженга-хоррор в космосе",tagline:"«Ты последний. Корабль умирает. Запись ведётся.»",description:"Сольная RPG в жанре хоррор о выживании в открытом космосе, сыгранная с колодой карт, башней Дженга и микрофоном. Вы — единственный выживший экипаж межзвёздного спасательного корабля «The Wretched». Двигатели мертвы. Чужой выброшен в шлюз, но это не спасло вас. Каждый день вы вытягиваете карты, вытаскиваете блоки из башни и говорите в микрофон — пока не замолчите навсегда. Признана одной из лучших игр 2020 года по версии Tabletop Gaming Magazine.",setting:"Ближний будущий космос. Корабль «The Wretched» дрейфует в межзвёздном пространстве после отказа двигателей. Нет связи. Нет помощи. Существо уничтожило экипаж по одному. Теперь оно мертво или притворяется мёртвым — а вы один, в тишине, среди систем жизнеобеспечения, которые медленно гаснут одна за другой. Вдохновение: «Чужой» Ридли Скотта, Джон Карпентер, Nine Inch Nails.",vignette:"День 7. Вы тянете карту: семёрка червей. Сердца — системы корабля. Подсказка: «Один из генераторов уходит в критический режим. Опиши, что ты делаешь». Вы говорите в микрофон, голос дрожит. Потом тянете блок из башни — пальцы холодные, рука неустойчива. Башня скрипит. Устояла. Ещё один день. Потом вы вытягиваете четвёртого Короля. Она вернулась.",prep:"~5 мин",mechanics:[{title:"Башня как жизнь",text:"Башня Дженга — структурная целостность корабля и ваш рассудок одновременно. Когда она падает, игра заканчивается. Вы мертвы. Не было иного пути."},{title:"Масти — ваш мир",text:"Червы — системы корабля. Трефы — погибший экипаж. Бубны — физическая структура. Пики — существо. Каждая карта — подсказка, каждая подсказка — запись в журнал."},{title:"Четыре Короля",text:"Каждый вытянутый Король откладывается отдельно. Когда выпадают все четыре — существо возвращается. Это неизбежно. Игра не предназначена для победы."},{title:"Аудиодневник",text:"Вы записываете каждый день на микрофон как звуковой журнал. Начинаете словами: «День X, спасательный корабль The Wretched, бортинженер [имя] докладывает.» Это фиксирует то, что останется после вас."}],gallery:[{cap:"Обложка — «The Wretched»"},{cap:"Карточный оракул"},{cap:"Разворот правил"}],resources:[{name:"Официальный сайт"},{name:"Страница на itch.io"},{name:"DriveThruRPG"}],quotes:[{text:"The Wretched — это то, что остаётся после, и она атмосферна, пугающа и попросту блестяща."}]},en:{tagShort:"solo space-horror Jenga RPG",tagline:'"You are the last one. The ship is dying. The log is running."',description:"A solo horror RPG about survival in deep space, played with a deck of cards, a tumbling block tower, and a microphone. You are the sole surviving crew member of the intergalactic salvage ship The Wretched. Engines dead. The creature was vented out an airlock — but it didn't save you. Each day you draw cards, pull blocks from the tower, and speak into a microphone — until you don't. Named one of Tabletop Gaming Magazine's Best Games of 2020.",setting:"The near-future void. The salvage ship The Wretched drifts between stars following catastrophic engine failure. No signal. No rescue. The creature slaughtered the crew one by one. Now it is dead — or pretending to be — and you are alone in the silence as the life support systems wink out, one by one. Inspired by Ridley Scott's Alien, John Carpenter, and the music of Nine Inch Nails.",vignette:"Day 7. You draw a card: seven of hearts. Hearts are ship systems. The prompt: 'One of the generators is entering critical failure. Describe what you do.' You speak into the microphone, voice unsteady. Then you pull a block from the tower — fingers cold, hand not quite still. The tower groans. It holds. One more day. Then you draw the fourth King. She came back.",prep:"~5 min",mechanics:[{title:"The tower is your life",text:"The tumbling block tower represents the structural integrity of the ship — and your sanity. When it falls, the game ends. You are dead. There was no other way."},{title:"Suits are your world",text:"Hearts — ship systems. Clubs — the dead crew. Diamonds — the ship's physical structure. Spades — the creature. Every card is a prompt; every prompt is a journal entry."},{title:"The four Kings",text:"Each King drawn is set aside. When all four appear, the creature returns. This is inevitable. The Wretched is not a game designed to be won."},{title:"The audio log",text:"You record each day into a microphone as a voice log. You begin: 'Day X, salvage ship The Wretched, Flight Engineer [name] reporting.' This is what will remain after you are gone."}],gallery:[{cap:"Cover — The Wretched"},{cap:"The card oracle"},{cap:"Rules spread"}],resources:[{name:"Official website"},{name:"itch.io page"},{name:"DriveThruRPG"}]}}),registerSystem("thousand-year-old-vampire",{groups:{default:{key:"narrative",order:17},family:{key:"standalone",order:12.5},genre:{key:"narrative-weird",order:7},solo:{key:"solo-journaling",order:1}},name:"Thousand Year Old Vampire",publisher:"Tim Hutchings / Petit Guignol",dice:"d10 − d6",players:"1",complexity:1,heroImage:"https://img.itch.zone/aW1nLzIwMjQ5MjAxLnBuZw==/original/6JceU8.png",heroImageStyle:"object-fit: cover; object-position: center top; background: linear-gradient(135deg, #0a0005, #1a0010 40%, #2d0020 70%, #0f000a);",playstyleTags:["narrative","horror","mystery"],settingTags:["historical","urban-fantasy"],gallery:[{src:"https://img.itch.zone/aW1hZ2UvNTgyMDAwLzMwNjY0NDcucG5n/347x500/UYjcQP.png"},{src:"https://img.itch.zone/aW1hZ2UvNTgyMDAwLzMwNjY0NDMucG5n/347x500/ply7sR.png"},{src:"https://img.itch.zone/aW1hZ2UvNTgyMDAwLzMwNjY0NDQucG5n/347x500/ecqbKs.png"}],resources:[{type:"link",url:"https://thousandyearoldvampire.com/",fmt:"Web"},{type:"link",url:"https://timhutchings.itch.io/tyov",fmt:"Itch.io"},{type:"rules",url:"https://thousandyearoldvampire.com/products/thousand-year-old-vampire-pdf-only",fmt:"PDF"}],mechanics:[{icon:"clock"},{icon:"brain"},{icon:"feather"},{icon:"skull"}],quotes:[{text:"One of the most critically acclaimed solo journaling games ever made...",author:"Charlie L Hall, Polygon"},{text:"Most important are your memory slots, and it's here where Thousand Year Old Vampire becomes a genuinely poignant experience.",author:"Michael Heron, Meeple Like Us"}],ru:{tagShort:"Соло-дневник",tagline:"«Одна тысяча лет одиночества, потерь и крови.»",description:`Игра для одного человека, в которой вы ведёте дневник бессмертного вампира — от момента утраты смертности до неизбежного конца. Нет ведущего, нет другого игрока, только вы, кубики и страницы всё более угасающей памяти. Это не приключение. Это хроника забвения.

Игра получила золотые Ennie Awards 2020 за лучшие правила и лучшее производство, а также была признана лучшей настольной игрой на IndieCade. Физическое издание — дайджест в твёрдой обложке с фольгой и лентами — само по себе произведение искусства.`,setting:"Нет фиксированного сеттинга — есть только время. Вы выбираете историческую эпоху для рождения вашего вампира: Древний Рим, средневековая Флоренция, колониальная Индия, Лондон эпохи пара. Потом столетия сдвигаются, люди вокруг умирают, цивилизации рушатся, а вы всё ещё здесь — но помните всё меньше и меньше.",vignette:"Вы начинаете с одного воспоминания о смертной жизни. Бросаете d10 и d6, вычитаете: результат −2. Вы листаете назад две страницы и читаете подсказку: «Кто-то из ваших близких находит свидетельство вашей природы. Они в ужасе. Запишите это переживание.» Вы пишете. Потом воспоминаний становится шесть — но у вас есть место только для пяти. Надо что-то забыть. Вы выбираете лицо, которое больше не вспомните.",prep:"0 мин",mechanics:[{title:"Случайный прогресс",text:"Бросок d10 − d6 определяет, на сколько страниц вперёд или назад вы переходите. Отрицательный результат уводит в прошлое. Нет линейного порядка — история нелинейна, как память."},{title:"Пять воспоминаний",text:"У вас не может быть больше пяти воспоминаний одновременно. Каждое — до трёх переживаний. Когда шестое требует места, вы навсегда стираете одно существующее. Эта потеря механически реальна."},{title:"Дневник и забвение",text:"До четырёх воспоминаний можно записать в дневник. Но в дневник нельзя добавить новые записи — он запечатан. А если его потерять, всё написанное исчезает вместе с ним."},{title:"Персонажи, навыки, ресурсы",text:"Ваш лист состоит из смертных и бессмертных персонажей, навыков и ресурсов. Подсказки приказывают вам убивать персонажей, терять ресурсы, приобретать метки вампиризма. Всё, что вы записали, однажды исчезнет."}],gallery:[{cap:"Обложка"},{cap:"Разворот — лист персонажа"},{cap:"Страница подсказок"}],resources:[{name:"Официальный сайт"},{name:"Itch.io (PDF, $15)"},{name:"Купить PDF"}],quotes:[{text:"Одна из самых высоко оценённых критикой соло-дневниковых игр всех времён…"},{text:"Главное — слоты памяти; именно здесь Thousand Year Old Vampire превращается в по-настоящему пронзительный опыт."}]},en:{tagShort:"solo journaling",tagline:'"A thousand years of loneliness, loss, and blood."',description:`A solo roleplaying game in which you chronicle the centuries of a vampire's existence — from the moment mortality ends to inevitable destruction. No GM, no other players, only you, two dice, and the pages of a memory that keeps fading. This is not an adventure. It is a chronicle of forgetting.

Winner of Gold ENNIE Awards 2020 for Best Rules and Best Production Values, and IndieCade Tabletop Design Award. The physical edition — a digest hardcover with foil, ribbons, and hand-aged design — is itself an artifact.`,setting:"There is no fixed setting — only time. You choose the historical era of your vampire's birth: ancient Rome, Renaissance Florence, colonial India, Victorian London. Then the centuries turn, the people around you die, civilizations rise and collapse, and you are still here — remembering less and less.",vignette:"You begin with one memory of mortal life. You roll d10 and subtract d6: the result is −2. You flip back two pages and read the prompt: 'Someone close to you finds evidence of your nature. They are horrified. Record this Experience.' You write. Then a sixth memory needs space, but you only have room for five. Something must go. You choose a face you will never recall again.",prep:"0 min",mechanics:[{title:"Random progression",text:"Rolling d10 − d6 determines how many pages forward or backward you move through the prompt book. A negative result sends you into the past. There is no linear order — the story is non-linear, like memory itself."},{title:"Five memories",text:"You can never hold more than five Memories at once. Each Memory holds up to three Experiences. When a sixth demands space, you permanently erase one. That loss is mechanically real — not narrated, enacted."},{title:"The diary and forgetting",text:"Up to four Memories can be recorded in a diary. But the diary cannot be updated — it is sealed at the moment of writing. If it is ever lost, everything inside it vanishes with it."},{title:"Characters, Skills, Resources",text:"Your sheet tracks mortal and immortal characters, skills, and resources. Prompts order you to kill characters, lose resources, and accumulate marks of vampirism. Everything you write down will eventually disappear."}],gallery:[{cap:"Cover"},{cap:"Spread — character sheet"},{cap:"Prompt page"}],resources:[{name:"Official website"},{name:"Itch.io (PDF, $15)"},{name:"Buy PDF"}]}}),registerSystem("trail-of-cthulhu",{groups:{default:{key:"narrative",order:33},family:{key:"standalone",order:42},genre:{key:"horror",order:10}},name:"Trail of Cthulhu",publisher:"Pelgrane Press",dice:"GUMSHOE (d6, clue-driven)",players:"3–5",complexity:2,free:!0,foundryStatus:"Community",heroImage:"https://pelgranepress.com/wp-content/uploads/2020/04/Softcover-PELGT01-scaled.jpg",playstyleTags:["mystery","horror","narrative"],settingTags:["historical","weird"],gallery:[{src:"https://pelgranepress.com/wp-content/uploads/2020/04/Hardcover-PELGT16.jpg"},{src:"https://pelgranepress.com/wp-content/uploads/2020/04/Hardcover-PELGT34.jpg"},{src:"https://pelgranepress.com/wp-content/uploads/2020/04/Hardcover-PELGT37.jpg"}],resources:[{type:"link",url:"https://pelgranepress.com/trail-of-cthulhu/",fmt:"Web"},{type:"quickstart",url:"https://pelgranepress.com/trail-of-cthulhu-second-edition/",fmt:"Web"}],mechanics:[{icon:"search"},{icon:"dices"},{icon:"brain"},{icon:"skull"}],quotes:[{text:"GUMSHOE is a perfect fit for investigating the supernatural mysteries and horrors associated with the Cthulhu Mythos.",author:"MJ Harnish, Wired"}],ru:{tagShort:"GUMSHOE-хоррор: ключи всегда находятся",tagline:"«Проблема не в том, чтобы найти улику. Проблема — что делать с тем, что она значит».",description:"Trail of Cthulhu — детективный хоррор Кеннета Хайта на движке GUMSHOE. Его гениальная идея: базовые улики находятся автоматически, если у героя есть нужный навык. Расследование никогда не встаёт из-за проваленного броска — напряжение в интерпретации найденного и в цене, которую платит рассудок. Лавкрафт 1930-х без тупиков.",setting:"1930-е: мировая депрессия, тень тоталитаризма и лавкрафтовский Мифос за фасадом реальной истории. Сыщики, профессора и журналисты идут по следу культов и тварей извне. Два режима: Purist (безнадёжный космический ужас) и Pulp (героическое приключение с револьвером против Ктулху).",vignette:"Библиотека покойного профессора. У вас есть навык «Библиотечное дело» — значит, ключевую книгу вы находите автоматически, без броска. Вопрос не «найдёте ли», а «выдержит ли рассудок то, что в ней». Проверка Стабильности: тратите очки General-навыка. Формула на полях страницы шевелится, будто живая. Минус к Стабильности. Что вы запишете в блокнот — и стоит ли?",prep:"~30 мин",mechanics:[{title:"GUMSHOE: улики находятся",text:"Есть нужный Расследовательский навык — базовая улика ваша автоматически. Расследование не буксует из-за кубика. Драма — в том, что улики значат и куда ведут."},{title:"Расследовательские и Общие навыки",text:"Investigative-навыки дают улики без броска; можно тратить их очки для дополнительных деталей. General-навыки (стрельба, побег, Стабильность) бросаются d6 с тратой пула — ресурс, а не удача."},{title:"Стабильность и Рассудок",text:"Две шкалы психики: краткосрочная Стабильность и долгосрочный Рассудок. Столкновение с Мифосом подтачивает обе. Знание освобождает и разрушает — фирменный лавкрафтовский маятник."},{title:"Purist или Pulp",text:"Один движок, два тона: Purist — беспомощный космический ужас, где герои обречены; Pulp — героика, где против твари можно и с револьвером. Выбираете под настроение группы."}],gallery:[{cap:"Core Rulebook"},{cap:"Материалы линейки"},{cap:"Приключения"}],resources:[{name:"Официальная страница — Pelgrane Press"},{name:"Бесплатный Quickstart"}],quotes:[{text:"GUMSHOE идеально подходит для расследования сверхъестественных тайн и ужасов, связанных с Мифосом Ктулху."}]},en:{tagShort:"GUMSHOE horror: the clues are always found",tagline:`"The problem isn't finding the clue. It's what to do with what it means."`,description:"Trail of Cthulhu is Kenneth Hite's investigative horror on the GUMSHOE engine. Its brilliant idea: core clues are found automatically if a character has the right ability. The investigation never stalls on a failed roll — the tension is in interpreting what you find, and the price your sanity pays. 1930s Lovecraft without the dead ends.",setting:"The 1930s: global depression, the shadow of totalitarianism, and the Lovecraftian Mythos behind the facade of real history. Investigators, professors, and journalists trail cults and things from beyond. Two modes: Purist (hopeless cosmic horror) and Pulp (heroic adventure, revolver against Cthulhu).",vignette:"The dead professor's library. You have the Library Use ability — so you find the key book automatically, no roll. The question isn't whether you'll find it, but whether your mind survives what's inside. A Stability test: spend from a General-ability pool. A formula in the page's margin seems to writhe, as if alive. Stability drops. What will you write in your notebook — and should you?",prep:"~30 min",mechanics:[{title:"GUMSHOE: clues are found",text:"Have the right Investigative ability and the core clue is yours automatically. The investigation never bogs down on a die roll. The drama is in what the clues mean and where they lead."},{title:"Investigative & General abilities",text:"Investigative abilities give clues without a roll, and you can spend their points for extra detail. General abilities (shooting, fleeing, Stability) roll a d6 with a spendable pool — a resource, not luck."},{title:"Stability & Sanity",text:"Two tracks of the mind: short-term Stability and long-term Sanity. Contact with the Mythos erodes both. Knowledge frees and destroys — the signature Lovecraftian pendulum."},{title:"Purist or Pulp",text:"One engine, two tones: Purist — helpless cosmic horror where heroes are doomed; Pulp — heroics where a revolver against the beast is on the table. Choose to fit your group's mood."}],gallery:[{cap:"Core Rulebook"},{cap:"Line materials"},{cap:"Adventures"}],resources:[{name:"Official page — Pelgrane Press"},{name:"Free Quickstart"}],quotes:[{text:"GUMSHOE is a perfect fit for investigating the supernatural mysteries and horrors associated with the Cthulhu Mythos."}]}}),registerSystem("traveller",{groups:{default:{key:"tactical",order:6},family:{key:"standalone",order:20},genre:{key:"sci-fi",order:11},solo:{key:"solo-compatible",order:12}},name:"Traveller",publisher:"Mongoose Publishing",dice:"2d6 + mods",players:"3–5",complexity:3,foundryStatus:"Official",heroImage:"https://www.mongoosepublishing.com/cdn/shop/files/The_Core_Rulebook_2022_New_Cover_1800x.jpg?v=1733921202",playstyleTags:["explore","sandbox","tactical"],settingTags:["space"],gallery:[{src:"https://www.mongoosepublishing.com/cdn/shop/files/The_Core_Rulebook_2022_New_Cover_1800x.jpg?v=1733921202"},{src:"https://www.mongoosepublishing.com/cdn/shop/files/hg2022_1562x.jpg?v=1777472594"},{src:"https://www.mongoosepublishing.com/cdn/shop/products/CSCUpdate2023frontCoverJPEG_aa9b7abf-6aad-4e3e-a506-12811312c221_1269x.jpg?v=1671718881"},{src:"https://www.mongoosepublishing.com/cdn/shop/products/travthirdimp_2_914fc99f-1930-49cd-9b05-bf52448a0adf_1800x.jpg?v=1646393186"}],resources:[{type:"link",url:"https://www.mongoosepublishing.com/collections/traveller-rpgs",fmt:"Web"},{type:"sheet",url:"https://cdn.shopify.com/s/files/1/0609/6139/0839/files/travcharsheetedit.pdf?v=1642023932",fmt:"PDF"},{type:"quickstart",url:"https://www.mongoosepublishing.com/products/starterpack",fmt:"PDF"},{type:"link",url:"https://www.traveller-srd.com/",fmt:"Web"}],mechanics:[{icon:"compass"},{icon:"rocket"},{icon:"coins"},{icon:"dice-6"}],quotes:[{text:"I think even its harshest critics would have to admit that the worldbuilding is incredible, if a bit spread out.",author:"Aki, Cannibal Halfling Gaming"}],ru:{tagShort:"Хардовая сай-фай про вольных торговцев",tagline:"«Персонаж может умереть на этапе создания. И это фича».",description:"Traveller — дедушка научно-фантастических ролёвок (1977, Марк Миллер). Текущая редакция — Mongoose 2e: 2d6 + модификаторы, броски на навыки, лайфпас вместо классов. Вы создаёте не героя, а биографию: служба в Имперском флоте, провал на брокерской сделке, потерянная нога на колониальной планете. Игра про фрилансеров на потрёпанном корабле, ипотеку за джамп-двигатель и грузы, которые лучше не вскрывать.",setting:"Charted Space и Третья Империя. 11 000 населённых миров, гиперпространственные прыжки до 6 парсеков, феодальная аристократия с лазерами. Между секторами — фронтир, пираты, потерянные колонии. Вы — не спасители галактики, а команда вольного торговца с выплатой банку каждые 30 дней.",vignette:"Лайфпас. Вы выбрали Скаута. Бросок на поступление: 2d6, нужно 6+. Прошли. Первый срок — четыре года разведки. Бросок на выживание: 1+1 = 2. Провал. Открываете таблицу «Mishap» (d66): 11 — «Тяжёлое ранение, конец карьеры». В Mongoose 2e обычно выживаете, но шрамы остаются. Стол смеётся. Бросаете заново — на этот раз Drifter. Через сорок минут у вас — седой ветеран с тремя контрактами, кибернетической рукой, врагом-капитаном и долей в торговом корабле Type-A Free Trader. Игра ещё не началась, а биография уже есть.",prep:"~20–30 мин",mechanics:[{title:"Лайфпас вместо левелапа",text:"Карьера до старта: служба, события, провалы. Можно умереть на чарген. Зато на выходе — живой человек со шрамами, а не ходячая статистика."},{title:"Корабль = персонаж",text:"Free Trader, Scout, Far Trader. Ипотека на 40 лет, расход топлива, страховка. Корабль — пятый член команды и главный источник проблем."},{title:"Торговля как геймплей",text:"Купил пшеницу на аграрном мире — продал на промышленном. Брокерские броски, спекулятивные грузы, контрабанда. Целая мини-игра в экономику."},{title:"2d6 + всё",text:"Один бросок на всё: навык + характеристика + модификатор, цель — 8+. Простая шкала, понятные шансы. Двадцатигранник не нужен."}],gallery:[{cap:"Core Rulebook 2022"},{cap:"High Guard — корабли"},{cap:"Central Supply Catalogue — снаряжение"},{cap:"The Third Imperium"}],resources:[{name:"Официальный сайт"},{name:"Официальный лист персонажа"},{name:"Starter Pack (бесплатно)"},{name:"Traveller SRD"}],quotes:[{text:"Думаю, даже самые жёсткие критики признают: мироздание здесь невероятное — пусть и слегка разбросанное."}]},en:{tagShort:"Hard sci-fi about freelance traders",tagline:`"Your character can die during character creation. That's a feature."`,description:"Traveller is the granddaddy of sci-fi tabletop RPGs (1977, Marc Miller). Current edition is Mongoose 2e: 2d6 + modifiers, skill checks, lifepath instead of classes. You don't build a hero — you build a biography: a stint in the Imperial Navy, a botched brokerage deal, a leg lost on a colonial backwater. The game is about freelancers on a beaten-up ship, a mortgage on the jump drive, and cargo you'd rather not inspect.",setting:"Charted Space and the Third Imperium. 11,000 inhabited worlds, jump drives up to 6 parsecs, feudal aristocracy with lasers. Beyond the sectors lie frontiers, pirates, lost colonies. You're not galactic saviors — you're a free trader's crew with a bank payment due every 30 days.",vignette:"Lifepath. You picked Scout. Enlistment roll: 2d6, need 6+. You're in. First term — four years of survey work. Survival roll: 1+1 = 2. Failure. You consult the Mishap table (d66): 11 — 'Severely injured, career ends.' In Mongoose 2e you usually survive, but the scars stick. The table laughs. You roll again — this time, Drifter. Forty minutes later you've got a grey-haired veteran with three terms, a cybernetic arm, an enemy captain, and a share in a Type-A Free Trader. The game hasn't started, but the biography already has.",prep:"~20–30 min",mechanics:[{title:"Lifepath, not level-up",text:"Career before play: service, events, failures. You can die at chargen. But what walks out is a person with scars — not a walking stat block."},{title:"The ship is a character",text:"Free Trader, Scout, Far Trader. A 40-year mortgage, fuel costs, insurance. The ship is your fifth crewmember and your biggest problem."},{title:"Trade as gameplay",text:"Buy wheat on an agri-world, sell it on an industrial one. Broker rolls, speculative cargo, smuggling. A whole economic mini-game."},{title:"2d6 + everything",text:"One roll for everything: skill + stat + modifier, target 8+. Simple curve, intuitive odds. No d20 required."}],gallery:[{cap:"Core Rulebook 2022"},{cap:"High Guard — starships"},{cap:"Central Supply Catalogue — gear"},{cap:"The Third Imperium"}],resources:[{name:"Official website"},{name:"Official character sheet"},{name:"Starter Pack (free)"},{name:"Traveller SRD"}]}}),registerSystem("triangle",{groups:{default:{key:"narrative",order:3},family:{key:"standalone",order:2},genre:{key:"narrative-weird",order:5}},name:"Triangle Agency",publisher:"Haunted Table",dice:"Пул d4",players:"3–5",complexity:2,foundryStatus:"Community",heroImage:"https://img.itch.zone/aW1nLzE2NTI3MDUyLmpwZw==/original/FIDchU.jpg",playstyleTags:["mystery","horror","social"],gallery:[{src:"https://img.itch.zone/aW1nLzIzMTIyMTYzLmpwZw==/original/638fvX.jpg"},{src:"https://img.itch.zone/aW1nLzIzMTIyMTQzLnBuZw==/original/yIrTaf.png"},{src:"https://img.itch.zone/aW1nLzIzMTIxOTQ5LnBuZw==/original/%2F%2B9FZ8.png"},{src:"https://cdn.shopify.com/s/files/1/0581/0464/3719/files/lobby_sample.jpg"},{src:"https://cdn.shopify.com/s/files/1/0581/0464/3719/files/Back_Endpaper__Agents_on_Break.jpg"}],resources:[{type:"link",url:"https://hauntedtable.itch.io/triangle-agency",fmt:"Web"},{type:"sheet",url:"https://shop.hauntedtable.games/pages/resources",fmt:"PDF"}],mechanics:[{icon:"eye"},{icon:"scale"},{icon:"badge"},{icon:"dices"}],quotes:[{text:"The punchline-per-page ratio is astronomical.",author:"Rowan Zeoli, Polygon"}],ru:{tagShort:"RPG про агентов аномалий",tagline:"«SCP встречает X-Files. Вы — агенты, контролирующие аномальное».",description:"RPG о спецагентах, работающих в секретном агентстве, которое сдерживает аномальные явления. Каждая миссия — выезд на аномалию: изучить, классифицировать, решить что делать. Генератор аномалий создаёт уникальные угрозы. Бюрократия агентства — враг не менее опасный.",setting:"Современный мир, но за фасадом реальности — аномалии. Агентство «Треугольник» — секретная организация, которая их сдерживает. Три доктрины: Сдержать, Уничтожить или Использовать. Каждая миссия — моральный выбор, и Агентство запоминает ваши решения.",vignette:"Аномалия: дверь в подвале жилого дома. Она открывается в комнату, которой нет в планах здания. Внутри — стул и записка: «Сядьте.» Бросок Исследования — 3d4, две тройки. Успех: записка написана почерком вашего директора. Доктрина? Сдержать — замуровать дверь. Использовать — сесть на стул. Уничтожить — сжечь дом. Отчёт нужен к утру.",prep:"~25 мин",mechanics:[{title:"Генератор аномалий",text:"Процедурная система создаёт уникальные аномалии для каждой миссии. Бесконечная реиграбельность."},{title:"Три доктрины",text:"Сдержать, Уничтожить, Использовать. Каждое решение формирует репутацию группы в Агентстве."},{title:"Бюрократия",text:"Отчёты, допуски, внутренняя политика. Агентство — не союзник, а инструмент, который может повернуться против вас."},{title:"Лёгкая механика",text:"Пул d4, простые правила. Фокус — на расследовании и принятии решений, а не на тактике."}],gallery:[{cap:"Промо-арт агентства"},{cap:"Иллюстрация: агенты"},{cap:"Разворот книги"},{cap:"Лобби агентства"},{cap:"Агенты на перерыве"}],resources:[{name:"Официальный сайт"},{name:"Официальные листы"}],quotes:[{text:"Соотношение шуток на страницу — астрономическое."}]},en:{tagShort:"SCP-meets-X-Files agent RPG",tagline:'"SCP meets X-Files. You are agents containing the anomalous."',description:"An RPG about special agents working for a secret agency that contains anomalous phenomena. Every mission is a field response to an anomaly: study it, classify it, decide what to do. The anomaly generator creates unique threats. Agency bureaucracy is an equally dangerous enemy.",setting:"The modern world, but behind the facade of reality — anomalies. The Triangle Agency is a secret organization that contains them. Three doctrines: Contain, Destroy, or Exploit. Every mission is a moral choice, and the Agency remembers your decisions.",vignette:"Anomaly: a door in an apartment building's basement. It opens into a room that doesn't exist on the building plans. Inside — a chair and a note: 'Sit down.' Investigation roll — 3d4, two threes. Success: the note is in your director's handwriting. Doctrine? Contain — brick up the door. Exploit — sit in the chair. Destroy — burn the building. Report due by morning.",prep:"~25 min",mechanics:[{title:"Anomaly generator",text:"A procedural system creates unique anomalies for every mission. Infinite replayability."},{title:"Three doctrines",text:"Contain, Destroy, Exploit. Every decision shapes the team's reputation within the Agency."},{title:"Bureaucracy",text:"Reports, clearances, internal politics. The Agency isn't an ally — it's a tool that can turn against you."},{title:"Light mechanics",text:"d4 dice pool, simple rules. Focus is on investigation and decision-making, not tactics."}],gallery:[{cap:"Agency promo art"},{cap:"Illustration: agents"},{cap:"Book spread"},{cap:"Agency lobby"},{cap:"Agents on break"}],resources:[{name:"Official website"},{name:"Official sheets"}]}}),registerSystem("troika",{groups:{default:{key:"osr",order:14},family:{key:"standalone",order:22},genre:{key:"narrative-weird",order:10}},name:"Troika!",publisher:"Melsonian Arts Council",dice:"2d6 (roll-under) + d66",players:"2–5",complexity:1,free:!0,foundryStatus:"Official",heroImage:"https://img.itch.zone/aW1nLzMyMjg4MDkucG5n/original/hYv6Fw.png",playstyleTags:["narrative","explore","social"],settingTags:["weird"],gallery:[{src:"https://img.itch.zone/aW1hZ2UvMzkyODUxLzE5NDYwMDAuanBn/original/Wjwgpm.jpg"},{src:"https://img.itch.zone/aW1hZ2UvMzkyODUxLzE5NDU5OTEuanBn/original/bcfBWl.jpg"},{src:"https://img.itch.zone/aW1hZ2UvMzkyODUxLzE5NDU5OTMuanBn/original/8w8VYj.jpg"}],resources:[{type:"link",url:"https://melsonian-arts-council.itch.io/troika-numinous-edition",fmt:"Web"},{type:"quickstart",url:"https://melsonian-arts-council.itch.io/troika-numinous-edition/devlog/104412/srd",fmt:"Web"}],mechanics:[{icon:"shuffle"},{icon:"dices"},{icon:"sparkles"},{icon:"backpack"}],quotes:[{text:"Light but limitless role-playing among the best in the RPG field today.",author:"Michael Barnes, There Will Be Games"},{text:"A masterpiece. The perfect place to start for anyone looking for a game of real adventure.",author:"Christopher Eggett, Tabletop Gaming"}],ru:{tagShort:"Пси-фэнтези прыжки между сферами",tagline:"«Гуманистическая научная фэнтези о путешествиях между сферами по золотым баржам».",description:"Troika! — правила-лёгкая ролевая игра-погружение в сюрреалистичную мультивселенную, где кристаллические сферы связаны межпланетными баржами. Собственная система на 2d6, а не клон D&D. Знаменита 36 безумными предысториями персонажей и неповторимым визуальным стилем. Сердце «нью-школы» (NSR): минимум правил, максимум странного.",setting:"Бесконечная мультивселенная сфер, соединённых золотыми баржами, что скользят по невозможным небесам. Один мир — базарный город богов, другой — болото философов, третий — арена бессмертных гладиаторов. Тон — печальный, смешной и глубоко чуждый; научная фэнтези в духе «Умирающей Земли» Вэнса и «Книги Нового Солнца» Вулфа.",vignette:"Ваш Чемпион Хаоса сходит с баржи в город, где дождь идёт вверх. Стражник-многоножка требует пошлину. Вы врёте — бросок против навыка Обмана: Навык 7, кидаете 2d6, нужно 7 или меньше. Выпало 9 — провал. Многоножка щёлкает жвалами. Вы тянете жетон инициативы из мешка; выпал не ваш. Стража ходит первой.",prep:"~10 мин",mechanics:[{title:"36 предысторий (d66)",text:"Вместо классов — бросок d66 по таблице из 36 предысторий: от Монахоторговца до Зоантропа. Каждая даёт странный набор навыков и снаряжения. Персонаж за минуту."},{title:"Бросок «меньше-равно» на 2d6",text:"Проверка: киньте 2d6, сравните с суммой Навыка и профильного Продвинутого навыка. Меньше или равно — успех. Вся резолюция в одной механике."},{title:"Три характеристики",text:"Навык, Выносливость и Удача — вот и всё. Удача тратится и восстанавливается, влияя на броски и урон. Никаких листов на страницу."},{title:"Инициатива из мешка",text:"Порядок ходов не пошаговый: в мешок кладут жетоны за каждого участника плюс жетоны конца раунда. Тянешь вслепую — хаос боя на удаче."}],gallery:[{cap:"Разворот книги"},{cap:"Предыстории персонажей"},{cap:"Интерьерный арт"}],resources:[{name:"Официальный сайт — troika.fyi"},{name:"Бесплатный Quickstart и SRD (itch.io)"}],quotes:[{text:"Лёгкая, но безграничная ролевая игра — одна из лучших в поле RPG на сегодня."},{text:"Шедевр. Идеальная отправная точка для всех, кто ищет игру о настоящем приключении."}]},en:{tagShort:"Sphere-hopping science-fantasy on golden barges",tagline:'"A humanist science-fantasy of travel between crystal spheres."',description:"Troika! is a rules-light roleplaying game of surreal travel across a multiverse of crystal spheres linked by interplanetary barges. Its own 2d6 engine, not a D&D clone. Famous for its 36 bizarre character backgrounds and an unmistakable visual style. A cornerstone of the NSR (New School Revolution): minimal rules, maximal strangeness.",setting:"An endless multiverse of spheres joined by golden barges that sail impossible skies. One world is a bazaar-city of gods, another a swamp of philosophers, another an arena of undying gladiators. The tone is melancholy, funny, and deeply alien — science-fantasy in the tradition of Vance's Dying Earth and Wolfe's Book of the New Sun.",vignette:"Your Chaos Champion steps off the barge into a city where rain falls upward. A centipede guardsman demands a toll. You lie — test against Con: Skill 7, roll 2d6, need 7 or under. You roll a 9 — failure. The centipede clicks its mandibles. You draw an initiative token from the bag; it isn't yours. The guards act first.",prep:"~10 min",mechanics:[{title:"36 Backgrounds (d66)",text:"No classes — roll d66 on a table of 36 backgrounds, from Monkeymonger to Zoanthrop. Each grants a strange bundle of skills and possessions. A character in a minute."},{title:"Roll-under 2d6",text:"To test something, roll 2d6 against the sum of your Skill and the relevant Advanced Skill. Roll equal or under to succeed. The entire resolution system in one mechanic."},{title:"Three stats only",text:"Skill, Stamina, and Luck — that's it. Luck is spent and recovered, swinging rolls and damage. No character sheet longer than an index card."},{title:"Initiative from a bag",text:"Turn order isn't round-by-round: tokens for each combatant plus end-of-round tokens go into a bag. You draw blind — combat as beautiful, lethal chaos."}],gallery:[{cap:"Book spread"},{cap:"Character backgrounds"},{cap:"Interior art"}],resources:[{name:"Official site — troika.fyi"},{name:"Free Quickstart & SRD (itch.io)"}],quotes:[{text:"Light but limitless role-playing among the best in the RPG field today."},{text:"A masterpiece. The perfect place to start for anyone looking for a game of real adventure."}]}}),registerSystem("trophy",{groups:{default:{key:"narrative",order:24},family:{key:"pbta-fitd",order:3},genre:{key:"horror",order:6}},name:"Trophy",publisher:"Hedgemaze Press",dice:"d6 pools (light & dark dice)",players:"3–5",complexity:2,free:!0,foundryStatus:"Community",heroImage:"https://trophyrpg.com/downloads/Trophy-Map.png",playstyleTags:["narrative","horror","social"],settingTags:["fantasy","weird"],gallery:[{src:"https://trophyrpg.com/assets/images/cover-trophy-dark.jpg"},{src:"https://trophyrpg.com/assets/images/cover-trophy-gold.jpg"},{src:"https://trophyrpg.com/assets/images/cover-trophy-loom.jpg"}],resources:[{type:"link",url:"https://trophyrpg.com/",fmt:"Web"},{type:"quickstart",url:"https://trophyrpg.com/system/",fmt:"Web"}],mechanics:[{icon:"dices"},{icon:"skull"},{icon:"trees"},{icon:"users"}],quotes:[{text:"It is a game of moods and resonances and excels in capturing them.",author:"James L. Smith, Gothic Nature Journal"},{text:"I do love a sad story! Each time we've played, it's ended either violently, or creepily, or awash in melancholy.",author:"Paul Beakley, Indie Game Reading Club"}],ru:{tagShort:"FitD-хоррор об обречённых кладоискателях",tagline:"«Жадные искатели сокровищ входят в лес, из которого не возвращаются».",description:"Trophy — нарративная хоррор-игра о кладоискателях, обречённых сгинуть в проклятом лесу. Наследует Cthulhu Dark и Blades in the Dark: пулы кубиков, где тёмные кости тянут героя к гибели. Два режима: Trophy Dark — беспощадный ваншот-спуск в ужас, и Trophy Gold — кампания в духе OSR-подземелий, но с тем же фатализмом.",setting:"Гримдарк-сказка: жадность, долги и голод гонят охотников за сокровищами в древний лес, что живёт, дышит и ненавидит пришельцев. Не героика — трагедия. Игроки сами придумывают, как их персонажи катятся к погибели; вопрос не «выживут ли», а «насколько красиво падут».",vignette:"Ваш охотник тянется к золотому идолу. Ведущий предлагает риск. Вы собираете пул: светлые кости за навык плюс одна тёмная кость Руин. Бросок — высшая кость решает исход. Выпадает 5... но это тёмная кость. Успех: идол ваш. Цена: Руин растёт. Лес шепчет ваше имя, и вы чувствуете, как он тянет вас глубже.",prep:"~10 мин",mechanics:[{title:"Светлые и тёмные кости",text:"Проверка — пул d6: светлые кости за навыки и помощь, тёмные кости Руин добавляет игрок ради шанса. Высшая кость решает. Но если победила тёмная — успех приходит с ростом Руин."},{title:"Руин — трек гибели",text:"Руин копится и толкает персонажа к жуткому концу. Достигнув предела, герой поддаётся лесу — сходит с ума, перерождается чудовищем или гибнет. Обречённость встроена в правила."},{title:"Dark против Gold",text:"Trophy Dark — ваншот-спуск в ужас без победы. Trophy Gold — кампания: «вылазки» за золотом в опасные места, разбор сокровищ и долгов. Один тон, два формата игры."},{title:"Совместный хоррор",text:"Fiction-first, минимум правил. Игроки сами вводят осложнения и описывают, как их герои катятся к гибели. Ведущий плетёт настроение, а не считает хиты."}],gallery:[{cap:"Trophy Dark"},{cap:"Trophy Gold"},{cap:"Trophy Loom"}],resources:[{name:"Официальный сайт — trophyrpg.com"},{name:"Бесплатный SRD «Rooted in Trophy» (CC-BY)"}],quotes:[{text:"Это игра настроений и резонансов, и она превосходно их улавливает."},{text:"Я обожаю печальные истории! Каждый раз наша игра заканчивалась либо жестоко, либо жутко, либо в накрывающей меланхолии."}]},en:{tagShort:"FitD horror of doomed treasure-hunters",tagline:'"Greedy treasure-hunters enter a forest they will not leave."',description:"Trophy is a narrative horror game about treasure-hunters doomed to perish in a cursed forest. It draws on Cthulhu Dark and Blades in the Dark: dice pools where dark dice drag a character toward ruin. Two modes: Trophy Dark, a merciless one-shot descent into horror, and Trophy Gold, an OSR-flavored dungeon-crawl campaign with the same fatalism.",setting:"A grimdark fairy tale: greed, debt, and hunger drive treasure-hunters into an ancient forest that lives, breathes, and hates intruders. Not heroism — tragedy. Players invent how their own characters slide toward doom; the question isn't whether they survive, but how beautifully they fall.",vignette:"Your hunter reaches for the golden idol. The GM offers a risk. You gather a pool: light dice for skill, plus one dark Ruin die. You roll — the highest die decides. A 5 comes up... but it's the dark die. Success: the idol is yours. The cost: Ruin rises. The forest whispers your name, and you feel it pulling you deeper.",prep:"~10 min",mechanics:[{title:"Light & dark dice",text:"A check is a d6 pool: light dice for skill and help, plus dark Ruin dice the player adds for a better chance. The highest die decides. But if a dark die wins, success comes with rising Ruin."},{title:"Ruin — the doom track",text:"Ruin accumulates and pushes a character toward a grisly end. At its limit, the hero gives in to the forest — going mad, transforming into a monster, or dying. Doom is built into the rules."},{title:"Dark vs. Gold",text:"Trophy Dark is a one-shot descent into horror with no winning. Trophy Gold is a campaign: 'incursions' for gold into dangerous places, dividing loot and debts. One tone, two formats."},{title:"Collaborative horror",text:"Fiction-first, minimal rules. Players introduce their own complications and narrate how their characters slide toward ruin. The GM weaves mood, not hit-point math."}],gallery:[{cap:"Trophy Dark"},{cap:"Trophy Gold"},{cap:"Trophy Loom"}],resources:[{name:"Official site — trophyrpg.com"},{name:"Free 'Rooted in Trophy' SRD (CC-BY)"}],quotes:[{text:"It is a game of moods and resonances and excels in capturing them."},{text:"I do love a sad story! Each time we've played, it's ended either violently, or creepily, or awash in melancholy."}]}}),registerSystem("twilight",{groups:{default:{key:"fl",order:5},family:{key:"year-zero",order:5},genre:{key:"sci-fi",order:8}},name:"Twilight: 2000",publisher:"Free League / Year Zero Engine",dice:"Пул d6–d12",players:"3–5",complexity:4,foundryStatus:"Official",heroImage:"https://freeleaguepublishing.com/wp-content/uploads/2023/08/Twilight_2000_RPG_Combat_3000-1440x720.jpg",playstyleTags:["survival","tactical","sandbox","social"],settingTags:["modern","postapoc"],gallery:[{src:"https://freeleaguepublishing.com/wp-content/uploads/2023/08/Twilight_2000_RPG_Factions.jpg"},{src:"https://freeleaguepublishing.com/wp-content/uploads/2023/11/1.-Rules-Gear-intro.jpg"},{src:"https://freeleaguepublishing.com/wp-content/uploads/2023/11/travel-intro.jpg"},{src:"https://freeleaguepublishing.com/wp-content/uploads/2023/08/Twilight_2000_RPG_Scenarios.jpg"}],resources:[{type:"link",url:"https://freeleaguepublishing.com/games/twilight-2000/",fmt:"Web"},{type:"sheet",url:"https://legacy.drivethrurpg.com/product/478574/Twilight-2000-4e-Character-Sheets-printable-and-formfillable",fmt:"PDF"}],mechanics:[{icon:"crosshair"},{icon:"fuel"},{icon:"truck"},{icon:"compass"}],quotes:[{text:"Free League took something old and legitimately distilled many of the things we liked about it originally, while removing a lot of the cruft that made it a product of the 1980s.",author:"Aaron Marks, Cannibal Halfling Gaming"}],ru:{tagShort:"Пост-ядерный сэндбокс RPG",tagline:"«Третья мировая окончена. Вы проиграли. Теперь — выживайте».",description:"Милитари-сэндбокс о выживании после ядерной войны. Вы — остатки разбитого подразделения NATO в Польше (или Швеции). Командование молчит, топливо кончается, патронов мало, а зима близко. Сможете ли вы добраться домой — или хотя бы выжить до весны?",setting:"Альтернативный 2000 год. Третья мировая война произошла. Ядерные удары уничтожили крупные города. Европа — зона хаоса: мародёры, дезертиры, местные военачальники. Польская зима, разрушенная инфраструктура и остатки цивилизации.",vignette:"У вас 12 патронов для M16, полбака дизеля в БТР и двое раненых. Деревня впереди контролируется местным полевым командиром. Он предлагает: бак дизеля за работу — зачистить мародёров на мосту. Бросок Убеждения на d10+d8 — провал. Он поднимает цену: дизель И ваш медпакет. Январь. До весны — три месяца.",prep:"~30 мин",mechanics:[{title:"Реалистичный бой",text:"Баллистика, укрытия, подавление. Одна пуля может убить. Бой — отчаянный, короткий и страшный."},{title:"Экономика дефицита",text:"Топливо, патроны, медикаменты — на вес золота. Каждый выстрел — решение: стоит ли цель патрона?"},{title:"Техника",text:"Танки, БТР, грузовики — ваш дом на колёсах. Ремонт и модификация — отдельный слой геймплея."},{title:"Гексплорейшн",text:"Открытая карта Польши с точками интереса, фракциями и случайными событиями. Куда идти — решаете вы."}],gallery:[{cap:"Фракции"},{cap:"Правила и снаряжение"},{cap:"Путешествие"},{cap:"Сценарии"}],resources:[{name:"Официальный сайт"},{name:"Листы персонажей"}],quotes:[{text:"Free League взяла что-то старое и честно переплавила многое из того, что нам в этом нравилось изначально, попутно вычистив весь мусор, делавший её продуктом 1980-х."}]},en:{tagShort:"post-WW3 survival RPG",tagline:'"World War III is over. You lost. Now — survive."',description:"A military sandbox about surviving after nuclear war. You are the remnants of a shattered NATO unit in Poland (or Sweden). Command is silent, fuel is running out, ammo is scarce, and winter is coming. Can you make it home — or at least survive until spring?",setting:"An alternate year 2000. World War III happened. Nuclear strikes destroyed major cities. Europe is a zone of chaos: marauders, deserters, local warlords. Polish winter, ruined infrastructure, and the remnants of civilization.",vignette:"You have 12 rounds for the M16, half a tank of diesel in the APC, and two wounded. The village ahead is controlled by a local warlord. He offers: a tank of diesel for a job — clear the marauders on the bridge. Persuasion roll on d10+d8 — failure. He raises the price: diesel AND your medkit. January. Three months until spring.",prep:"~30 min",mechanics:[{title:"Realistic combat",text:"Ballistics, cover, suppression. A single bullet can kill. Combat is desperate, short, and terrifying."},{title:"Scarcity economy",text:"Fuel, ammo, medicine — worth their weight in gold. Every shot is a decision: is the target worth a round?"},{title:"Vehicles",text:"Tanks, APCs, trucks — your home on wheels. Repair and modification are a separate layer of gameplay."},{title:"Hexploration",text:"An open map of Poland with points of interest, factions, and random events. Where to go is your call."}],gallery:[{cap:"Factions"},{cap:"Rules and gear"},{cap:"Travel"},{cap:"Scenarios"}],resources:[{name:"Official website"},{name:"Character sheets"}]}}),registerSystem("uvg",{groups:{default:{key:"narrative",order:8},family:{key:"standalone",order:4},genre:{key:"narrative-weird",order:4}},name:"Ultraviolet Grasslands",publisher:"Luka Rejec / Exalted Funeral",dice:"Любые (OSR)",players:"2–5",complexity:2,foundryStatus:"Community (SDM)",heroImage:"https://sessionzero.games/images/systems/uvg-hero.jpeg",playstyleTags:["explore","worldbuild","survival"],settingTags:["fantasy","weird"],gallery:[{src:"https://cdn.shopify.com/s/files/1/0025/6006/5625/products/reanimated-damage-the-ultra-violet-grasslands-and-the-black-city-warning-book-1347321.jpg?v=1753228007"},{src:"https://sessionzero.games/images/systems/uvg-g1.jpg"},{src:"https://sessionzero.games/images/systems/uvg-g2.jpg"},{src:"https://www.exaltedfuneral.com/cdn/shop/files/uvg-2e-book-463900.jpg?v=1720802815"},{src:"https://www.exaltedfuneral.com/cdn/shop/files/uvg-2e-book-296196.jpg?v=1720802815"}],resources:[{type:"link",url:"https://wizardthieffighter.itch.io/uvg-2e",fmt:"Web"},{type:"quickstart",url:"https://wizardthieffighter.itch.io/uvg-free-player-guide",fmt:"PDF"},{type:"sheet",url:"https://dimfringes.itch.io/uvg-full-spectrum-character-sheets",fmt:"PDF"}],mechanics:[{icon:"palette"},{icon:"package"},{icon:"route"},{icon:"plug"}],quotes:[{text:"It's a gamebook, not a novel or a tasteful heap of prose. It is a finely crafted tool to create stories.",author:"Skerples, Coins and Scrolls"},{text:"Ultraviolet Grasslands is a phenomenal RPG. My players had enormous fun with it, and I had enormous fun running it.",author:"Tristan Zimmerman, Molten Sulfur Blog"}],ru:{tagShort:"Психоделический OSR",tagline:"«Психоделический Шёлковый Путь через умирающие земли».",description:"Не совсем система — скорее мегамодуль-сеттинг для любой OSR-игры. Линейный маршрут через психоделические пустоши — «поинткроул» (путешествие от точки к точке по маршруту). Каждая неделя пути — новая безумная локация. Работает с Cairn, Into the Odd, D&D 5e — адаптируется под любой движок.",setting:"Вы ведёте торговый караван от Фиолетового Города через ультрафиолетовые степи к Чёрному Городу на краю мира. По пути: кошачьи люди на парусниках, живые горы, руины цивилизаций, которые играли с реальностью. Стиль — Мёбиус + «Жёлтая субмарина» + Dying Earth.",vignette:"Неделя 7 пути. Караван: два верблюда, наёмник-кошколюд, повозка с фиолетовыми кристаллами. Вы входите в Поющую Пустошь — воздух вибрирует, кристаллы начинают резонировать. Бросок Удачи — провал. Один верблюд сходит с ума от звука и убегает. Половина товара потеряна. Впереди — Стеклянная Ярмарка, где торгуют воспоминаниями.",prep:"~15 мин",mechanics:[{title:"Арт как контент",text:"Лука Реец — художник. Каждая страница — произведение искусства. Стиль вдохновляет на игру сам по себе."},{title:"Караванная экономика",text:"Ресурсы, торговля, наёмники. Караван — ваш передвижной дом. Управление им — ключевой геймплей."},{title:"Линейный маршрут",text:"Карта — путь с точками интереса. Каждая неделя — новая локация. Простая структура, бесконечная глубина."},{title:"Системоагностик",text:"Работает с любой OSR-системой. Cairn, ItO, даже 5e. UVG — контент, а не правила."}],gallery:[{cap:"Kickstarter арт"},{cap:"Психоделический пейзаж"},{cap:"Караван"},{cap:"Разворот книги"},{cap:"Интерьерный арт"}],resources:[{name:"Официальный сайт"},{name:"Free Player Guide (70 стр.)"},{name:"Character Sheets"}],quotes:[{text:"Это игровая книга, а не роман и не элегантная куча прозы. Это тонко сработанный инструмент для создания историй."},{text:"Ultraviolet Grasslands — феноменальная RPG. Игроки получили море удовольствия, и я как мастер получил его не меньше."}]},en:{tagShort:"psychedelic OSR",tagline:'"A psychedelic Silk Road through dying lands."',description:"Not quite a system — more of a mega-module setting for any OSR game. A linear route through psychedelic wastelands — a 'pointcrawl' (traveling point to point along a route). Every week of travel brings a new wild location. Works with Cairn, Into the Odd, D&D 5e — adapts to any engine.",setting:"You lead a trade caravan from the Violet City through ultraviolet steppes to the Black City at the edge of the world. Along the way: cat-people on sailboats, living mountains, ruins of civilizations that toyed with reality. Style — Moebius + Yellow Submarine + Dying Earth.",vignette:"Week 7 of the journey. Caravan: two camels, a cat-folk mercenary, a wagon of violet crystals. You enter the Singing Waste — the air vibrates, the crystals start resonating. Luck roll — failure. One camel goes mad from the sound and bolts. Half the goods are lost. Ahead — the Glass Fair, where memories are traded.",prep:"~15 min",mechanics:[{title:"Art as content",text:"Luka Rejec is an artist. Every page is a work of art. The style inspires play all by itself."},{title:"Caravan economy",text:"Resources, trade, hirelings. The caravan is your mobile home. Managing it is core gameplay."},{title:"Linear route",text:"The map is a path with points of interest. Every week — a new location. Simple structure, infinite depth."},{title:"System-agnostic",text:"Works with any OSR system. Cairn, ItO, even 5e. UVG is content, not rules."}],gallery:[{cap:"Kickstarter art"},{cap:"Psychedelic landscape"},{cap:"Caravan"},{cap:"Book spread"},{cap:"Interior art"}],resources:[{name:"Official website"},{name:"Free Player Guide (70 pp.)"},{name:"Character Sheets"}]}}),registerSystem("vaesen",{groups:{default:{key:"fl",order:3},family:{key:"year-zero",order:3},genre:{key:"horror",order:3}},name:"Vaesen",publisher:"Free League / Year Zero Engine",dice:"Пул d6",players:"3–5",complexity:2,foundryStatus:"Official контент",heroImage:"https://freeleaguepublishing.com/wp-content/uploads/2023/08/Vaesen_hero3-1440x720.jpg",playstyleTags:["mystery","horror","social"],settingTags:["historical","urban-fantasy"],gallery:[{src:"https://freeleaguepublishing.com/wp-content/uploads/2023/11/sjora.jpg"},{src:"https://freeleaguepublishing.com/wp-content/uploads/2023/08/VAE_ENG_cover-1200x1200.jpg"}],resources:[{type:"link",url:"https://freeleaguepublishing.com/games/vaesen/",fmt:"Web"},{type:"sheet",url:"https://freeleaguepublishing.com/wp-content/uploads/2023/08/Vaesen-Character-Sheet.pdf",fmt:"PDF"}],mechanics:[{icon:"castle"},{icon:"book-x"},{icon:"users"},{icon:"heart-crack"}],quotes:[{text:"This beautifully produced and wonderfully written book enriches an already compelling game.",author:"Ed Power, Tabletop Gaming"}],ru:{tagShort:"Скандинавская готика XIX века",tagline:"«Мистический детектив в Скандинавии XIX века».",description:"Вы — члены Общества, способные видеть сверхъестественное в мире, где остальные давно перестали верить. Каждое приключение — расследование: деревня обращается за помощью, вы изучаете мифологию существа, находите его слабость и проводите ритуал. Структура «монстр недели» работает идеально.",setting:"Скандинавия XIX века. Индустриализация наступает, старые боги забыты. Но в лесах и озёрах живут вэттиры — существа из скандинавского фольклора: тролли, ниссе, мюлинги, дракены. Они злы, потому что люди их забыли. Между расследованиями вы восстанавливаете замок — штаб-квартиру Общества.",vignette:"Деревня Норрбю. Дети пропадают по ночам. Вы нашли след — мокрые следы босых ног, ведущие к озеру. Бросок Учёности: 4 кубика — один успех. Вы вспоминаете: нёкк, водяной дух, заманивает музыкой. Его слабость — сталь, брошенная в воду с его именем. Но как узнать имя существа, которое забыли сто лет назад?",prep:"~20 мин",mechanics:[{title:"Штаб-квартира",text:"Замок Общества. Между приключениями — улучшайте его. Библиотека, лаборатория, конюшня — каждое даёт бонусы."},{title:"Ритуалы изгнания",text:"Монстров нельзя просто убить мечом. Нужно узнать их тайну и провести правильный ритуал. Знание = сила."},{title:"Структура «Мистерия»",text:"Каждый сценарий — готовая мистерия: деревня, проблема, существо, улики, ритуал. Идеально для эпизодической игры."},{title:"Психологические условия",text:"Встречи с вэттирами оставляют психологические шрамы. Страх, одержимость, ночные кошмары."}],gallery:[{cap:"Шьора — водный дух"},{cap:"Обложка"}],resources:[{name:"Официальный сайт"},{name:"Официальный лист"}],quotes:[{text:"Эта прекрасно изданная и великолепно написанная книга обогащает и без того захватывающую игру."}]},en:{tagShort:"Nordic gothic mystery RPG",tagline:'"Supernatural mystery in 19th-century Scandinavia."',description:"You are members of the Society, able to see the supernatural in a world where everyone else has long stopped believing. Every adventure is an investigation: a village asks for help, you research the creature's mythology, find its weakness, and perform a ritual. The 'monster of the week' structure works perfectly.",setting:"19th-century Scandinavia. Industrialization advances, the old gods are forgotten. But in forests and lakes dwell vaesen — creatures from Scandinavian folklore: trolls, nisse, mylings, drakes. They are angry because humans have forgotten them. Between investigations, you restore a castle — the Society's headquarters.",vignette:"The village of Norrby. Children vanish at night. You found a trail — wet barefoot prints leading to the lake. Learning roll: 4 dice — one success. You recall: a neck, a water spirit, lures with music. Its weakness — steel thrown into the water with its name. But how do you learn the name of a creature forgotten a hundred years ago?",prep:"~20 min",mechanics:[{title:"Headquarters",text:"The Society's castle. Between adventures — upgrade it. Library, laboratory, stables — each provides bonuses."},{title:"Banishment rituals",text:"Monsters can't simply be killed with a sword. You must learn their secret and perform the right ritual. Knowledge is power."},{title:"Mystery structure",text:"Each scenario is a ready-made mystery: village, problem, creature, clues, ritual. Perfect for episodic play."},{title:"Psychological conditions",text:"Encounters with vaesen leave psychological scars. Fear, obsession, nightmares."}],gallery:[{cap:"Sjora — water spirit"},{cap:"Cover"}],resources:[{name:"Official website"},{name:"Official sheet"}]}}),registerSystem("vampire-the-masquerade",{groups:{default:{key:"narrative",order:26},family:{key:"standalone",order:30},genre:{key:"horror",order:3.5}},name:"Vampire: The Masquerade",publisher:"Renegade Game Studios",dice:"d10 pool",players:"3–5",complexity:3,free:!1,foundryStatus:"Community",heroImage:"https://cdn11.bigcommerce.com/s-kftzvkkgjv/images/stencil/500x659/products/292/1534/V5_CoreRulebook_FrontCover__22095.1657225192.jpg",playstyleTags:["narrative","combat","explore"],settingTags:["modern","urban-fantasy"],gallery:[{src:"https://static.wikia.nocookie.net/whitewolf/images/7/78/VampireMasqueradeV5Logo.png/revision/latest"},{src:"https://www.grimdarkmagazine.com/wp-content/uploads/2019/09/V5-1.jpeg"},{src:"https://cdn11.bigcommerce.com/s-kftzvkkgjv/images/stencil/500x659/products/292/1534/V5_CoreRulebook_FrontCover__22095.1657225192.jpg"}],resources:[{type:"link",url:"https://www.worldofdarkness.com/vampire-the-masquerade",fmt:"Web"},{type:"link",url:"https://store.worldofdarkness.com/products/vampire-the-masquerade-5th-edition-core-book.html",fmt:"Web"},{type:"quickstart",url:"https://www.drivethrurpg.com/en/product/266095/vampire-the-masquerade-5th-edition-the-monster-s",fmt:"PDF"}],mechanics:[{icon:"sparkles"},{icon:"dices"},{icon:"book-open"},{icon:"scroll"}],quotes:[{text:"The system is timeless and extremely easy to learn. It all boils down to 'roll dice, you succeed at 50% per die'. Vampire is a game that thrives on drama. Hunger deserves a special mention, since it is not something to brush aside.",author:"Antonios S, RPGnet"}],ru:{tagShort:"Готический хоррор на d10-пуле",tagline:"«Ты — чудовище. Голод — твой закон. Маскарад — твоя тюрьма».",description:"Vampire: The Masquerade — настольная RPG в жанре готического хоррора от Renegade Game Studios (5-е издание, V5, 2018). Система Storyteller: бросок пула d10, успехи на 6+. Два десятка = крит (4 успеха). Голод (Hunger) заменяет часть пула — жажда крови становится механикой. Играешь вампиром (Kindred), балансируя между Humanity и зверем внутри.",setting:"Современный мир — тёмное отражение нашей реальности. Камилла (консервативный вампирский истеблишмент) рушится, Анархи поднимаются, Вторая Инквизиция (секретные правительственные охотники) ищет вампиров. Каждый клан — отдельная политика, каждый город — арена.",vignette:"Третья Точка. Новобранец-вампир чувствует Голод — красный кубик в пуле. Бросок на сопротивление: 3+5+7+8+Hunger(10!) = 5 успехов. Крит! Но... крит с Hunger-кубиком = Hunger Rises. Человечество падает. Ты только что убил того, кого хотел спасти. Добро пожаловать в Ночь.",prep:"~20 мин",mechanics:[{title:"Storyteller System (d10 pool)",text:"Бросок Атрибут + Навык в d10. Успехи на 6+. Два десятка = крит (4 успеха). Простая, но элегантная математика."},{title:"Голод (Hunger)",text:"Красный кубик в пуле заменяет обычный. Hunger растёт, если не пить кровь. Высокий Hunger = неконтролируемые действия, провалы на критах, и в итоге — потеря Humanity."},{title:"Humanity",text:"Шкала от 0 до 10. Потеря Humanity = потеря контроля. На нуле — вы становитесь Зверем, NPC управляют вашим персонажем. Конец истории."},{title:"Кланы",text:"13 кланов с уникальными дисциплинами (способностями), слабостями и культурой. Brujah — ярость, Ventrue — амбиции, Malkavian — безумие..."}],gallery:[{cap:"Core Rulebook (V5, 2018)"},{cap:"Логотип V5"},{cap:"Арт из обзора Grimdark Magazine"}],resources:[{name:"Официальный сайт — World of Darkness"},{name:"Магазин — купить Core Rulebook"},{name:"The Monsters (бесплатный квикстарт PDF)"}],quotes:[{text:"Система вечна и невероятно проста для обучения. Всё сводится к 'бросай кубики, у тебя 50% шанс на кость'. Vampire процветает на драме. Голод заслуживает особого упоминания."}]},en:{tagShort:"Gothic horror d10-pool — you are the monster",tagline:'"You are the monster. Hunger is your law. The Masquerade is your prison."',description:"Vampire: The Masquerade is a gothic horror tabletop RPG from Renegade Game Studios (5th Edition / V5, 2018). Storyteller System: roll a pool of d10s, count successes on 6+. Two 10s = critical (4 successes). Hunger dice replace part of the pool — the thirst for blood becomes a core mechanic. You play a Kindred (vampire), balancing Humanity against the Beast within.",setting:"The modern world — a dark reflection of our reality. The Camarilla (conservative vampire establishment) crumbles, the Anarchs rise, and the Second Inquisition (secret government hunters) stalks the night. Every clan is its own politics, every city is an arena.",vignette:"Third Point. A neonate vampire feels Hunger — a red die in the pool. Resistance roll: 3+5+7+8+Hunger(10!) = 5 successes. Critical! But... a critical with the Hunger die = Hunger Rises. Humanity drops. You just killed the one you tried to save. Welcome to the Night.",prep:"~20 min",mechanics:[{title:"Storyteller System (d10 pool)",text:"Roll Attribute + Skill in d10s. Success on 6+. Two 10s = critical (4 successes). Simple but elegant math."},{title:"Hunger",text:"A red die replaces a normal one in your pool. Hunger grows if you don't feed. High Hunger = uncontrollable actions, crit failures, and eventually — Humanity loss."},{title:"Humanity",text:"A scale from 0 to 10. Lose Humanity = lose control. At zero — you become the Beast, NPCs run your character. End of story."},{title:"Clans",text:"13 clans with unique Disciplines (powers), weaknesses, and culture. Brujah — rage, Ventrue — ambition, Malkavian — madness..."}],gallery:[{cap:"Core Rulebook (V5, 2018)"},{cap:"V5 Logo"},{cap:"Art from Grimdark Magazine review"}],resources:[{name:"Official site — World of Darkness"},{name:"Store — buy Core Rulebook"},{name:"The Monsters (free quickstart PDF)"}],quotes:[{text:"The system is timeless and extremely easy to learn. It all boils down to 'roll dice, you succeed at 50% per die'. Vampire is a game that thrives on drama. Hunger deserves a special mention."}]}}),registerSystem("vaults-of-vaarn",{groups:{default:{key:"osr",order:25},family:{key:"osr-modern",order:5},genre:{key:"narrative-weird",order:11}},name:"Vaults of Vaarn",publisher:"Leo Hunt",dice:"d20, rules-light (Knave-based)",players:"3–6",complexity:2,edition:null,free:!0,foundryStatus:"None",heroImage:"https://iglootree.com/cdn/shop/files/VaultsofVaarnIssue4_1.jpg",playstyleTags:["explore","survival","sandbox"],settingTags:["fantasy","weird"],gallery:[{src:"https://iglootree.com/cdn/shop/files/VaultsofVaarnIssue4_2.jpg"},{src:"https://iglootree.com/cdn/shop/files/VaultsofVaarnIssue4_3.jpg"},{src:"https://iglootree.com/cdn/shop/files/VaultsofVaarnIssue4_4.jpg"}],resources:[{type:"link",url:"https://iglootree.com/products/gme384",fmt:"Web"}],mechanics:[{icon:"backpack"},{icon:"sun"},{icon:"dna"},{icon:"shuffle"}],quotes:[{text:"A real masterclass in how to pack a bunch of flavour and setting into some very very small packages.",author:"Chris McDowall, author of Into the Odd"},{text:"An electric shock to the creative parts of the brain... A sleek game as excellent as it is blue.",author:"Joel Hines, author of Desert Moon of Karth"}],ru:{tagShort:"Синяя пустыня на краю времени, science-fantasy OSR",tagline:"«Постлюди-изгои копаются в руинах будущего под лазурным песком».",description:"Vaults of Vaarn — правила-лёгкая science-fantasy OSR-игра Лео Ханта на движке Knave. Вы — постчеловеческие изгои, что исследуют погребённые под песком руины далёкого будущего: тепловые волны, мутировавшие твари, свихнувшиеся роботы. Меланхоличная странность в духе «Дюны», «Книги Нового Солнца» и Мёбиуса, с богатым набором генераторов контента.",setting:"Ваарн — бескрайняя лазурно-синяя пустыня на краю времени. Цивилизации пали, остались руины Предтеч, обломки ИИ и мутанты. Постлюди, киборги и странные народы бредут между оазисами, торгуя памятью и водой. Красивый, печальный и абсолютно чуждый мир — science-fantasy, где технология неотличима от магии.",vignette:"Отряд спускается в вскрытый песком бункер Предтеч. Взломщик проверяет древний замок: d20 + бонус, против сложности. Успех — люк со скрежетом отходит. Внутри — не сокровище, а спящий сервитор с треснувшим ядром. Один из героев тянется к нему; таблица мутаций Ваарна уже наготове. В синей пустыне любопытство меняет тебя — иногда буквально.",prep:"~10 мин",mechanics:[{title:"Лёгкое ядро на Knave",text:"Движок Knave: бесклассовость, d20 + бонус против сложности, инвентарь по слотам. Правил — минимум, порог входа — нулевой. Вся глубина в сеттинге и генераторах."},{title:"Синяя пустыня science-fantasy",text:"Готовый мир Ваарна: лазурные пески на краю времени, руины будущего, оазисы и павшие ИИ. Технология как магия, меланхолия как тон. Сеттинг — главная звезда игры."},{title:"Мутации и постлюди",text:"Персонажи — постчеловеческие изгои. Обширные таблицы мутаций и странных черт делают каждого героя причудливым, а контакт с реликтами будущего может изменить тело и разум."},{title:"Процедурные генераторы",text:"Сердце игры — таблицы: NPC, руины, фракции, находки, чудеса. Ваарн собирается на лету, выдавая ту самую печальную странность без долгой подготовки ведущего."}],gallery:[{cap:"Разворот зина"},{cap:"Арт Ваарна"},{cap:"Интерьер"}],resources:[{name:"Магазин — Iglootree"}]},en:{tagShort:"A blue desert at the end of time — science-fantasy OSR",tagline:'"Post-human misfits delve future ruins beneath the sky-blue sand."',description:"Vaults of Vaarn is Leo Hunt's rules-light science-fantasy OSR game on the Knave engine. You play post-human misfits delving the far-future ruins buried beneath the sand: heatwaves, mutated beasts, crazed robots. Melancholy weirdness in the vein of Dune, The Book of the New Sun, and Moebius, with a rich set of content-generation tools.",setting:"Vaarn — a vast sky-blue desert at the end of time. Civilizations have fallen, leaving Precursor ruins, shards of AI, and mutants. Post-humans, cyborgs, and strange peoples wander between oases, trading memory and water. A beautiful, sorrowful, utterly alien world — science-fantasy where technology is indistinguishable from magic.",vignette:"The party descends into a Precursor bunker cracked open by the sand. The delver tests an ancient lock: d20 + bonus against a difficulty. Success — the hatch grinds open. Inside isn't treasure but a sleeping servitor with a cracked core. One of the heroes reaches for it; Vaarn's mutation table is already waiting. In the blue desert, curiosity changes you — sometimes literally.",prep:"~10 min",mechanics:[{title:"Light Knave-based core",text:"The Knave engine: classless, d20 + bonus against a difficulty, slot-based inventory. Minimal rules, a zero-cost on-ramp. All the depth lives in the setting and the generators."},{title:"Blue-desert science-fantasy",text:"A ready-made world of Vaarn: sky-blue sands at the end of time, future ruins, oases, and fallen AIs. Technology as magic, melancholy as tone. The setting is the game's real star."},{title:"Mutations & post-humans",text:"Characters are post-human misfits. Extensive mutation and weird-trait tables make every hero strange, and contact with future relics can reshape body and mind."},{title:"Procedural generators",text:"The heart of the game is its tables: NPCs, ruins, factions, finds, wonders. Vaarn assembles on the fly, spitting out that signature sorrowful weirdness with little GM prep."}],gallery:[{cap:"Zine spread"},{cap:"Vaarn art"},{cap:"Interior"}],resources:[{name:"Store — Iglootree"}]}}),registerSystem("wanderhome",{groups:{default:{key:"narrative",order:40},family:{key:"pbta-fitd",order:30},genre:{key:"adventure",order:26}},name:"Wanderhome",publisher:"Possum Creek Games",dice:"Без кубиков (жетоны, на основе PbtA)",players:"2–5",complexity:1,foundryStatus:"None",heroImage:"https://possumcreekgames.com/cdn/shop/files/wanderhome_Sylvia_2_1500x.png?v=1625780744",playstyleTags:["narrative","social","explore"],settingTags:["fantasy"],gallery:[{src:"https://cdn.shopify.com/s/files/1/0569/2912/4552/files/Parade_of_small_and_forgotten_gods_600x600.jpg?v=1637781495"},{src:"https://cdn.shopify.com/s/files/1/0569/2912/4552/files/Candlefeast-9x18_low-res-JPG_600x600.jpg?v=1637781564"},{src:"https://cdn.shopify.com/s/files/1/0569/2912/4552/files/2021_Wanderhome_Oneshot-1536x1536_480x480.png?v=1637783341"}],resources:[{type:"link",url:"https://possumcreekgames.com/products/wanderhome",fmt:"Web"}],mechanics:[{icon:"leaf"},{icon:"coins"},{icon:"users"},{icon:"sun"}],quotes:[{text:"It positions the drama of the Redwall series alongside Animal Crossing's endless Sunday afternoons, and displays the competence to juggle both of those vibes in a single game.",author:"Chase Carter, Polygon"},{text:"Once conflict arises, it is most often settled with dialogue and not daggers.",author:"Chase Carter, Polygon"}],ru:{tagShort:"Уютная пастораль о зверолюдях-странниках",tagline:"«Игра о временах года, маленьких историях и покое после войны».",description:"Wanderhome — умиротворяющая ролевая игра Джея Дракона о зверолюдях, что странствуют по нежному миру Хэта. Без кубиков и почти без ведущего: играете жетонами и ходами, а конфликты решаются разговором, а не клинком. Это игра про отдых, дружбу, смену сезонов и тихое исцеление после большой войны. Cozy-жанр в чистейшем виде.",setting:"Хэт — тёплый пасторальный мир антропоморфных зверей: лягушки-поэты, ежи-паломники, кошки-бродяги. Год делится на пять сезонов, и группа путешествует от места к месту, оставляя за собой маленькие истории. В прошлом была война, её эхо ещё живёт, но игра — о том, как мир и герои восстанавливаются, находя красоту в простом.",vignette:"Ваша компания приходит в деревню в разгар осеннего праздника. Кубиков нет — вы просто описываете сцену. Ваш герой, старый барсук-сказитель, тратит жетон Уюта, чтобы утешить местного, потерявшего дом на войне. За доброту вы получаете жетон Природы. Ведущего нет — вы вместе решаете, каким будет это место и кто в нём живёт. История растёт из тишины и внимания друг к другу.",prep:"~5 мин",mechanics:[{title:"Без кубиков, на жетонах",text:"Никаких бросков. Ходы тратят и приносят жетоны, а исход сцены рождается из фикшена. Мягкая, ненапряжная резолюция — ставки здесь эмоциональные, а не боевые."},{title:"Ведущий опционален",text:"Традиционного ГМа нет: игроки вместе строят мир через карты мест, природы и сезонов. Ответственность за историю распределена — каждый привносит свой кусочек Хэта."},{title:"Плейбуки-зверолюди",text:"Вы играете конкретного зверя-архетипа (Оборванец, Поэт, Свет Очага и др.), у каждого — свои уютные ходы и своя маленькая драма. Персонаж задаёт тон, а не набор сил."},{title:"Уют без насилия",text:"Конфликты решаются разговором, а не кинжалом. Игра — о покое, заботе, временах года и восстановлении после войны. Redwall встречает бесконечные воскресенья Animal Crossing."}],gallery:[{cap:"Парад маленьких забытых богов"},{cap:"Праздник свечей"},{cap:"Материалы игры"}],resources:[{name:"Официальная страница — Possum Creek Games"}],quotes:[{text:"Игра ставит драму «Рэдволла» рядом с бесконечными воскресными вечерами Animal Crossing — и умело жонглирует обоими настроениями в одной книге."},{text:"Когда конфликт всё же возникает, чаще всего он решается диалогом, а не кинжалами."}]},en:{tagShort:"A cozy pastoral of animal-folk travelers",tagline:'"A game of the seasons, small stories, and peace after a war."',description:"Wanderhome is Jay Dragon's serene RPG about animal-folk wandering the gentle world of Hæth. Diceless and nearly GM-less: you play with tokens and moves, and conflicts are settled with conversation, not a blade. It's a game about rest, friendship, the turning of seasons, and quiet healing after a great war. The cozy genre in its purest form.",setting:"Hæth is a warm, pastoral world of anthropomorphic animals: poet frogs, pilgrim hedgehogs, wandering cats. The year has five seasons, and the group travels place to place, leaving small stories behind. There was a war in the past, and its echoes linger, but the game is about how the world and its people recover, finding beauty in the simple.",vignette:"Your company arrives at a village mid-autumn festival. There are no dice — you simply describe the scene. Your character, an old badger storyteller, spends a Comfort token to console a local who lost their home to the war. For the kindness, you gain a Nature token. There's no GM — together you decide what this place is and who lives here. The story grows from quiet and attention to one another.",prep:"~5 min",mechanics:[{title:"Diceless, token-based",text:"No rolls. Moves spend and earn tokens, and a scene's outcome grows from the fiction. Gentle, low-pressure resolution — the stakes here are emotional, not martial."},{title:"GM optional",text:"There's no traditional GM: players build the world together through place, nature, and season cards. Authorship is shared — everyone brings their own piece of Hæth."},{title:"Animal-folk playbooks",text:"You play a specific animal archetype (the Ragamuffin, the Poet, the Firelight, and more), each with its own cozy moves and small drama. Character sets the tone, not a power set."},{title:"Cozy, without violence",text:"Conflicts are settled with conversation, not a dagger. The game is about peace, care, the seasons, and recovery after a war. Redwall meets Animal Crossing's endless Sundays."}],gallery:[{cap:"Parade of small and forgotten gods"},{cap:"Candlefeast"},{cap:"Game materials"}],resources:[{name:"Official page — Possum Creek Games"}],quotes:[{text:"It positions the drama of the Redwall series alongside Animal Crossing's endless Sunday afternoons, and displays the competence to juggle both of those vibes in a single game."},{text:"Once conflict arises, it is most often settled with dialogue and not daggers."}]}}),registerSystem("werewolf-the-apocalypse",{groups:{default:{key:"narrative",order:41},family:{key:"standalone",order:49},genre:{key:"horror",order:14}},name:"Werewolf: The Apocalypse",publisher:"Onyx Path Publishing / White Wolf",dice:"d10 dice pool (Storyteller System)",players:"3–5",complexity:3,free:!1,edition:null,foundryStatus:"Community",heroImage:"https://image.nobleknight.com/w/jpg1500/wta20onyx.jpg",playstyleTags:["combat","narrative","horror"],settingTags:["modern","urban-fantasy"],gallery:[{src:"https://image.nobleknight.com/w/jpg1500/wendigorev.jpg"},{src:"https://image.nobleknight.com/w/jpg1500/w20apocalypticrecorddx.jpg"},{src:"https://image.nobleknight.com/i/jpg1500/iprop-w-de.jpg"}],resources:[{type:"link",url:"https://theonyxpath.com/category/worlds/werewolftheapocalypse/",fmt:"Web"},{type:"link",url:"https://www.drivethrurpg.com/en/product/149136/werewolf-the-apocalypse-20th-anniversary-edition",fmt:"PDF"}],mechanics:[{icon:"dices"},{icon:"flame"},{icon:"moon"},{icon:"skull"}],quotes:[{text:"Werewolf is a fantastic game and I'd argue that is probably the best written game after Vampire: The Masquerade, even more so than Mage.",author:"C.T. Phipps, Grimdark Magazine"}],ru:{tagShort:"Ярость оборотней против гибели мира",tagline:"«Гея умирает. Гару — её последние воины, и они проигрывают».",description:"Werewolf: The Apocalypse — легендарная RPG Мира Тьмы о Гару, оборотнях-воинах, ведущих обречённую войну за умирающую Землю. Вы — не человек и не волк, а нечто третье, рождённое яростью и духом. На движке Storyteller (пулы d10) игра сплетает экологический хоррор, племенную мистику и трагедию борьбы, которую, возможно, уже не выиграть.",setting:"Современный мир на грани апокалипсиса. Гару служат Гее и сражаются с Вирмом — вселенской силой порчи, что расползается через корпорации, загрязнение и отчаяние. Стая — ваша семья и боевое подразделение; племя задаёт культуру и веру. Между мирами лежит Умбра, духовное отражение реальности, куда Гару уходят на охоту и паломничество.",vignette:"Фабрика Пентекса дышит ядом в реку. Ваша стая крадётся в тени, и тут — прорыв: вы призываете Ярость и переходите в Кринос, форму боевого чудовища. Мастер требует пул d10 на Ловкость + Первобытность против сложности. Пять кубов, три успеха — Делирий охватывает охранников-людей, они бегут в ужасе. Но каждая вспышка Ярости приближает вас к безумию Тени.",prep:"~45 мин",mechanics:[{title:"Storyteller System (d10)",text:"Броски — пулы d10 по «Атрибут + Способность»; каждый кубик выше сложности — успех. Тот же движок, что в Vampire и Mage: акцент на драме и повествовании, а не на тактической сетке."},{title:"Пять форм",text:"Гару переключаются между формами: Хомид (человек), Кринос (боевое чудовище), Луперус (волк) и две промежуточные. Форма меняет параметры и возможности — Кринос вселяет в людей первобытный ужас (Делирий)."},{title:"Ярость, Гнозис и Сила воли",text:"Три ресурса-движителя: Ярость толкает в бой и превращения, Гнозис питает духовную магию (Дары), Сила воли удерживает от срыва. Слишком много Ярости — и герой теряет контроль."},{title:"Племена и Умбра",text:"Тринадцать племён задают культуру, Дары и мировоззрение. Духовный мир — Умбра — реален: Гару странствуют по нему, договариваются с духами и сражаются с порождениями Вирма."}],gallery:[{cap:"Обложка 20th Anniversary Edition"},{cap:"Tribebook: Вендиго"},{cap:"Apocalyptic Record (deluxe)"}],resources:[{name:"Официальная страница — Onyx Path"},{name:"W20 Anniversary Edition (DriveThruRPG)"}],quotes:[{text:"Werewolf — фантастическая игра, и я бы сказал, что она, пожалуй, лучше всего написана после Vampire: The Masquerade — даже больше, чем Mage."}]},en:{tagShort:"Werewolf warriors raging against the end of the world",tagline:'"Gaia is dying. The Garou are her last warriors — and they are losing."',description:"Werewolf: The Apocalypse is the landmark World of Darkness RPG about the Garou, shapeshifting warriors waging a doomed war for a dying Earth. You are neither human nor wolf but a third thing, born of rage and spirit. On the Storyteller System (d10 pools), it braids ecological horror, tribal mysticism, and the tragedy of a fight that may already be lost.",setting:"The modern world on the edge of apocalypse. The Garou serve Gaia and battle the Wyrm — a cosmic force of corruption that spreads through corporations, pollution, and despair. Your pack is your family and combat unit; your tribe sets your culture and creed. Between worlds lies the Umbra, the spirit reflection of reality where the Garou hunt and make pilgrimage.",vignette:"A Pentex factory breathes poison into the river. Your pack slinks through the shadows — then the breach comes: you call up your Rage and shift into Crinos, the war-form. The Storyteller calls for a d10 pool of Dexterity + Primal-Urge against a difficulty. Five dice, three successes — the Delirium takes the human guards and they flee in terror. But every burst of Rage pulls you closer to the madness of the Wyrm.",prep:"~45 min",mechanics:[{title:"Storyteller System (d10)",text:"Rolls are d10 pools of Attribute + Ability; each die over the difficulty is a success. The same engine as Vampire and Mage: the emphasis is drama and narrative, not a tactical grid."},{title:"Five forms",text:"The Garou shift between forms: Homid (human), Crinos (war-beast), Lupus (wolf), and two in-between. Form changes your stats and options — Crinos strikes primal terror (the Delirium) into humans."},{title:"Rage, Gnosis & Willpower",text:"Three driving resources: Rage pushes you into combat and transformation, Gnosis fuels spirit magic (Gifts), Willpower keeps you from breaking. Too much Rage and your character loses control."},{title:"Tribes & the Umbra",text:"Thirteen tribes set culture, Gifts, and worldview. The spirit world — the Umbra — is real: the Garou travel it, bargain with spirits, and fight the Wyrm's spawn."}],gallery:[{cap:"20th Anniversary Edition cover"},{cap:"Tribebook: Wendigo"},{cap:"Apocalyptic Record (deluxe)"}],resources:[{name:"Official page — Onyx Path"},{name:"W20 Anniversary Edition (DriveThruRPG)"}],quotes:[{text:"Werewolf is a fantastic game and I'd argue that is probably the best written game after Vampire: The Masquerade, even more so than Mage."}]}}),registerSystem("wfrp",{groups:{default:{key:"tactical",order:9},family:{key:"standalone",order:28},genre:{key:"dark-fantasy",order:2.5}},name:"Warhammer Fantasy Roleplay",publisher:"Cubicle 7",dice:"d100",players:"3–5",complexity:3,free:!0,foundryStatus:"Official",heroImage:"https://d1vzi28wh99zvq.cloudfront.net/images/54/248284.jpg",playstyleTags:["combat","explore","narrative"],settingTags:["fantasy"],gallery:[{src:"https://d1vzi28wh99zvq.cloudfront.net/images/54/261941.jpg"},{src:"https://manaburnt.wordpress.com/wp-content/uploads/2018/09/warhammer-4th-ed.jpg"},{src:"https://manaburnt.wordpress.com/wp-content/uploads/2018/09/untitled.png"}],resources:[{type:"link",url:"https://wfrp.wiki/",fmt:"Web"},{type:"link",url:"https://cubicle7games.com/en_GB/warhammer-fantasy-roleplay-rulebook-pdf",fmt:"Web"},{type:"quickstart",url:"https://foundryvtt.com/packages/wfrp4e",fmt:"Web"}],mechanics:[{icon:"swords"},{icon:"dices"},{icon:"book-open"},{icon:"scroll"}],quotes:[{text:"The Between Adventures chapter is one of the better approaches I've seen to handling downtime. Nicely done.",author:"Andy Slack, Halfway Station"},{text:"The full-color artwork throughout the book is both consistent and outstanding. I particularly appreciate the moody landscapes that capture the feel of the Reikland.",author:"The Hardboiled GMshoe"}],ru:{tagShort:"Гримдарт-фэнтези на d100",tagline:"«Мрачный, опасный мир — карьеры, криты и безумие магии».",description:"Warhammer Fantasy Roleplay — настольная RPG в жанре гримдарк-фэнтези на системе d100 (процентные кубики), созданная Games Workshop и изданная Cubicle 7 (4-е издание, 2018). 64 карьеры с пошаговым продвижением, попадания по локациям, критические ранения, система преимуществ (Advantage) и безумная магия с таблицами исступления. Мир Старого Света — готическое средневековье с чернокнижниками, скавенами и культами.",setting:"Старый Мир — Империя, земля, где коррумпированные дворяне, фанатичные охотники на ведьм и простые крестьяне выживают между войнами, чумой и вторжениями скавенов. Каждый город — отдельная история, каждый трактир — начало приключения (или конца).",vignette:"Маг-коллегии готовит заклинание — d100, бросок Ingredients, успех! Но Wait — ещё бросок на исступление... 96! Дрожащие руки, зелёные искры. Соседи в ужасе. Охотник на ведьм уже стучит в дверь. Аwarf-шахтёр просто хочет допить своё пиво и вернуться в шахту. Добро пожаловать в Старый Мир.",prep:"~15 мин",mechanics:[{title:"Процентные кубики (d100)",text:"Бросок d100 против навыка: чем меньше результат, тем лучше. Успех определяется степенью (Success Level): разница между броском и навыком. Криты — двойной успех, фалы — двойной провал."},{title:"Карьерная система",text:"64 карьеры от слуги до ведьмака. Каждая с 4 рангами продвижения: от ученика до мастера. Продвижение стоит XP и открывает новые навыки, таланты и социальный статус."},{title:"Попадания по локациям",text:"При попадании бросок по таблице определяет часть тела: голова, рука, нога... У каждой свои модификаторы. Критические ранения — от забитого пальца до мгновенной смерти."},{title:"Преимущество (Advantage)",text:"Каждое попадание в бою даёт 1 Advantage, который cộngуется. На максимуме — одноразовый бонусный бросок. Но лопнувший Advantage (промах) — штраф. Бой становится спиралью азарта и риска."}],gallery:[{cap:"Обложка (Cubicle 7)"},{cap:"Starter Set — обложка"},{cap:"Сравнение 1-го и 4-го изданий"}],resources:[{name:"WFRP Wiki (бесплатный SRD)"},{name:"Cubicle 7 — PDF правила"},{name:"Foundry VTT — официальная система"}],quotes:[{text:"Глава о межсессиях — один из лучших подходов к обработке даунтайма, которые я видел. Отлично сделано."},{text:"Цветные иллюстрации по всей книге выглядят цельно и великолепно. Особенно впечатляют мрачные пейзажи, передающие атмосферу Рейкланда."}]},en:{tagShort:"Grimdark d100 fantasy with careers",tagline:'"A grim world of perilous adventure — careers, crits, and magic miscasts."',description:"Warhammer Fantasy Roleplay is a grimdark fantasy tabletop RPG built on the d100 percentile system, created by Games Workshop and published by Cubicle 7 (4th Edition, 2018). 64 careers with step-by-step advancement, hit locations, critical injuries, the Advantage system, and wild magic with miscast tables. The Old World is gothic medievalism with witches, Skaven, and cults lurking in every shadow.",setting:"The Old World — the Empire, a land where corrupt nobles, fanatical Witch Hunters, and simple peasants survive between wars, plague, and Skaven incursions. Every city is its own story, every tavern the start of an adventure (or its end).",vignette:"A College wizard prepares a spell — d100, Ingredients roll, success! But wait — a miscast check... 96! Trembling hands, green sparks. Neighbors in horror. The Witch Hunter is already pounding on the door. And the Dwarf just wants to finish his beer and get back to the mine. Welcome to the Old World.",prep:"~15 min",mechanics:[{title:"Percentile Dice (d100)",text:"Roll d100 against your skill: the lower the result, the better. Success is determined by Success Level — the difference between roll and skill. Doubles = critical, snake-eyes = fumble."},{title:"Career System",text:"64 careers from peasant to Witch Hunter. Each with 4 advancement tiers: from novice to master. Advancement costs XP and unlocks new skills, talents, and social standing."},{title:"Hit Locations",text:"On a hit, a roll determines the body part: head, arm, leg... Each has its own modifiers. Critical injuries range from a bruised finger to instant death."},{title:"Advantage",text:"Every hit in combat grants 1 Advantage, which stacks. At max — a one-time bonus roll. But a blown Advantage (miss) applies a penalty. Combat becomes a spiral of greed and risk."}],gallery:[{cap:"Core Rulebook (Cubicle 7)"},{cap:"Starter Set — cover"},{cap:"1st vs 4th edition cover comparison"}],resources:[{name:"WFRP Wiki (free SRD)"},{name:"Cubicle 7 — PDF rulebook"},{name:"Foundry VTT — official system"}],quotes:[{text:"I love the Between Adventures chapter, the acknowledgement that we all have our own take on the setting, and the Small but Vicious Dog still being there."},{text:"The full-color artwork throughout the book is both consistent and outstanding. I particularly appreciate the moody landscapes that capture the feel of the Reikland."}]}}),registerSystem("white-box-fmag",{groups:{default:{key:"osr",order:20},family:{key:"osr-classic",order:12},genre:{key:"adventure",order:19}},name:"White Box: Fantastic Medieval Adventure Game",publisher:"Charlie Mason / Seattle Hill Games",dice:"d20 (OD&D, single saving throw)",players:"3–6",complexity:1,edition:"OD&D",free:!0,foundryStatus:"None",heroImage:"https://image.nobleknight.com/w/jpg1500/whiteboxfmag.jpg",playstyleTags:["combat","explore","sandbox"],settingTags:["fantasy"],gallery:[],resources:[{type:"link",url:"https://whiteboxgame.blogspot.com/",fmt:"Web"}],mechanics:[{icon:"shield"},{icon:"swords"},{icon:"dices"},{icon:"gift"}],quotes:[{text:"There is nothing horribly new in FMAG, but at the same time there is nothing that will turn off your average S&W / OSR gamer.",author:"Erik Tenkar, Tenkar's Tavern"},{text:"All this is free in PDF and POD copies are sold at cost on Lulu or Amazon, making it one of the more affordable OSR games to play.",author:"Doug, Smoldering Wizard"}],ru:{tagShort:"Самый дешёвый полный OSR: клон OD&D",tagline:"«Вся оригинальная D&D на сотне страниц — бесплатно».",description:"White Box: Fantastic Medieval Adventure Game — предельно лёгкий клон оригинальной D&D 1974 года от Чарли Мэйсона. Переработка Swords & Wizardry WhiteBox с добавленным вором, турнирами и правилами путешествий. Бесплатный PDF, печать по себестоимости — недаром его зовут «самой дешёвой полной OSR-игрой». Идеальная стартовая точка в старую школу.",setting:"Система-агностик классического фэнтези: подземелья, деревни, драконы. Минимализм правил делает White Box чистым каркасом под любой мир. Дух — самая ранняя D&D: воображение важнее таблиц, а ведущий решает всё, чего нет в тонкой книжке.",vignette:"Маг-новичок в затхлом подземелье тратит единственное заклинание — «Свет» вспыхивает над скелетами. Боец бросается вперёд: d20 против AC. Скелет отвечает; маг проваливает единый спасбросок и получает удар. Правил — на сотню страниц, но за столом рождается вся классика приключений.",prep:"~15 мин",mechanics:[{title:"Единый спасбросок",text:"Как в S&W WhiteBox — один универсальный спасбросок вместо пяти категорий. Проще некуда: минимум таблиц, максимум скорости за столом."},{title:"Четыре класса",text:"Воин, Клерик, Маг плюс добавленный Вор. Ничего лишнего — тот самый костяк оригинальной D&D, к которому легко прикрутить что угодно своё."},{title:"Восходящий или нисходящий AC",text:"В комплекте оба варианта класса брони. Совместимость и с олдскульными модулями, и с привычками современных d20-игроков."},{title:"Самая дешёвая полная OSR",text:"Полные правила — бесплатный PDF; печать по себестоимости на Lulu/Amazon. Вся игра умещается в ~100 страниц. Нулевой порог входа в старую школу."}],gallery:[],resources:[{name:"Официальный блог — бесплатный PDF"}],quotes:[{text:"В FMAG нет ничего радикально нового, но при этом нет и ничего, что оттолкнуло бы среднего игрока S&W / OSR."},{text:"Всё это бесплатно в PDF, а печатные копии продаются по себестоимости на Lulu или Amazon — одна из самых доступных OSR-игр."}]},en:{tagShort:"The cheapest full OSR game — an OD&D clone",tagline:'"All of original D&D in a hundred pages — for free."',description:"White Box: Fantastic Medieval Adventure Game is Charlie Mason's ultra-light clone of 1974 original D&D. A reworking of Swords & Wizardry WhiteBox with an added thief, jousting, and travel rules. Free PDF, print-on-demand at cost — small wonder it's called 'one of the most affordable OSR games to play.' A perfect on-ramp into old-school play.",setting:"Setting-agnostic classic fantasy: dungeons, villages, dragons. The rules' minimalism makes White Box a clean frame for any world. The spirit is the earliest D&D — imagination over tables, and the GM deciding everything the slim book leaves out.",vignette:"A first-level magic-user in a dank dungeon spends their single spell — 'Light' flares over the skeletons. The fighter charges: d20 against AC. A skeleton strikes back; the mage fails their single saving throw and takes the hit. A hundred pages of rules, but the whole classic of adventure is born at the table.",prep:"~15 min",mechanics:[{title:"Single saving throw",text:"Like S&W WhiteBox — one unified saving throw instead of five categories. As simple as it gets: minimal tables, maximal speed at the table."},{title:"Four classes",text:"Fighter, Cleric, Magic-User, plus an added Thief. Nothing extraneous — the very chassis of original D&D, easy to bolt your own ideas onto."},{title:"Ascending or descending AC",text:"Both armor-class options are included. Compatible with old-school modules and with modern d20 players' instincts alike."},{title:"The cheapest full OSR",text:"The complete rules are a free PDF; print is sold at cost on Lulu/Amazon. The whole game fits in ~100 pages. A zero-cost on-ramp into old-school play."}],gallery:[],resources:[{name:"Official blog — free PDF"}],quotes:[{text:"There is nothing horribly new in FMAG, but at the same time there is nothing that will turn off your average S&W / OSR gamer."},{text:"All this is free in PDF and POD copies are sold at cost on Lulu or Amazon, making it one of the more affordable OSR games to play."}]}}),registerSystem("wildsea",{groups:{default:{key:"narrative",order:6},family:{key:"pbta-fitd",order:2},genre:{key:"narrative-weird",order:3}},name:"The Wildsea",publisher:"Mythworks / Felix Isaacs",dice:"Пул d6",players:"3–5",complexity:3,foundryStatus:"Community",heroImage:"https://img.itch.zone/aW1nLzgwNTI1NzYuanBn/original/jf%2BYt%2B.jpg",playstyleTags:["explore","narrative","worldbuild"],settingTags:["fantasy","weird"],gallery:[{src:"https://img.itch.zone/aW1hZ2UvMTMyNjI2My84MDUxMjgyLnBuZw==/original/tY0wGS.png"},{src:"https://img.itch.zone/aW1hZ2UvMTMyNjI2My84MDUxMjgzLnBuZw==/original/Zti8Xd.png"},{src:"https://img.itch.zone/aW1hZ2UvMTMyNjI2My84MDUxMjg0LnBuZw==/original/jzpDEX.png"},{src:"https://img.itch.zone/aW1hZ2UvMTMyNjI2My84MDUxMjg1LnBuZw==/original/FulxaS.png"},{src:"https://img.itch.zone/aW1hZ2UvMTMyNjI2My84MDUyMjYwLnBuZw==/original/4WEEWR.png"}],resources:[{type:"link",url:"https://felixisaacs.itch.io/thewildsea",fmt:"Web"},{type:"rules",url:"https://felixisaacs.itch.io/the-wildsea-free-basic-rules",fmt:"PDF"},{type:"quickstart",url:"https://felixisaacs.itch.io/the-wildsea-one-armed-scissor",fmt:"PDF"},{type:"tool",url:"https://wildsea.charsmith.com/",fmt:"Web"}],mechanics:[{icon:"ship"},{icon:"pen-tool"},{icon:"leaf"},{icon:"sprout"}],quotes:[{text:"Except the ships are essentially giant chainsaws and the seas are rapidly regenerating forests.",author:"Rob Wieland, EN World"},{text:"The gorgeous book and art catches your eye, but what makes Wildsea unique in its worldbuilding vision is that there's follow-through.",author:"Aaron Marks, Cannibal Halfling Gaming"}],ru:{tagShort:"Корабли по кронам RPG",tagline:"«Мир утонул в деревьях. Вы плывёте по кронам на бензопиле-корабле».",description:"Самый необычный сеттинг в индустрии. Цивилизация погибла под Зелёным Приливом — деревья выросли на километры, покрыв всё. «Океан» — это кроны деревьев. Корабли режут ветви пилами. Вы — команда одного такого корабля, исследующая дикоморье. Система на нарративных метках вместо числовых бонусов.",setting:"Дикоморье — бесконечные кроны, полные чудес. Города на ветвях, базары в дуплах, руины старого мира под корнями. Расы: люди-грибы, люди-пауки, живые кактусы, построенные из обломков роботы. Визуально — Миядзаки встречает Мёбиуса.",vignette:"Ваш корабль-пила застрял в сплетении лиан. Штурман — женщина-паук с меткой «Шёлковые руки» — пытается распутать такелаж. Бросок: 3 кубика, лучший результат — 4, частичный успех. Корабль свободен, но вы привлекли внимание гнезда ос размером с дом. Механик-кактус добавляет метку «Треснувший борт» на карточку корабля. Ремонт — только в ближайшем порту-дупле.",prep:"~20 мин",mechanics:[{title:"Корабль-пила",text:"Ваш корабль режет кроны пилами. Его модификации, команда и маршрут — центр игры."},{title:"Нарративные метки",text:"Вместо числовых бонусов — описательные теги. «Горящий меч», «Шрам от корня» — каждый влияет на механику."},{title:"Безумные расы",text:"Люди-грибы, люди-пауки, живые кактусы. Ни одного эльфа. Ни одного дварфа. Наконец-то."},{title:"Живой мир",text:"Лес растёт, мутирует, реагирует. Маршрут, пройденный месяц назад, может быть перекрыт новыми ветвями."}],gallery:[{cap:"Мир Дикоморья"},{cap:"Персонажи и корабли"},{cap:"Существа дикого моря"},{cap:"Правила и иллюстрации"},{cap:"Экипаж и снаряжение"}],resources:[{name:"Официальный сайт"},{name:"Free Basic Rules"},{name:"Приключение One-Armed Scissor"},{name:"Цифровой лист (Charsmith)"}],quotes:[{text:"Только корабли здесь по сути гигантские бензопилы, а моря — стремительно восстанавливающиеся леса."},{text:"Великолепная книга и арт цепляют взгляд, но Wildsea уникален тем, что за этим миро-видением стоит реальная проработка."}]},en:{tagShort:"weird treetop sailing RPG",tagline:'"The world drowned in trees. You sail the canopy on a chainsaw-ship."',description:"The most unusual setting in the industry. Civilization perished under the Green Tide — trees grew for miles, covering everything. The 'ocean' is the treetop canopy. Ships cut through branches with saws. You are the crew of one such ship, exploring the Wildsea. The system uses narrative tags instead of numerical bonuses.",setting:"The Wildsea — endless canopies full of wonders. Cities on branches, bazaars in hollows, ruins of the old world beneath the roots. Peoples: fungus-folk, spider-folk, living cacti, robots built from salvage. Visually — Miyazaki meets Moebius.",vignette:"Your saw-ship is stuck in a tangle of vines. The navigator — a spider-woman with the tag 'Silk Hands' — tries to untangle the rigging. Roll: 3 dice, best result — 4, partial success. The ship is free, but you've drawn the attention of a house-sized wasp nest. The cactus-mechanic adds the tag 'Cracked Hull' to the ship card. Repairs — only at the nearest hollow-port.",prep:"~20 min",mechanics:[{title:"Saw-ship",text:"Your ship cuts through the canopy with saws. Its modifications, crew, and route are the game's focus."},{title:"Narrative tags",text:"Instead of numerical bonuses — descriptive tags. 'Burning Sword', 'Root Scar' — each affects mechanics."},{title:"Wild peoples",text:"Fungus-folk, spider-folk, living cacti. Not a single elf. Not a single dwarf. Finally."},{title:"Living world",text:"The forest grows, mutates, reacts. A route traveled a month ago may be blocked by new branches."}],gallery:[{cap:"The Wildsea world"},{cap:"Characters and ships"},{cap:"Wildsea creatures"},{cap:"Rules and illustrations"},{cap:"Crew and gear"}],resources:[{name:"Official website"},{name:"Free Basic Rules"},{name:"Adventure: One-Armed Scissor"},{name:"Digital sheet (Charsmith)"}]}}),registerSystem("worlds-without-number",{groups:{default:{key:"osr",order:16},family:{key:"osr-classic",order:10},genre:{key:"adventure",order:16},solo:{key:"solo-compatible",order:17}},name:"Worlds Without Number",publisher:"Sine Nomine Publishing / Kevin Crawford",dice:"d20 (combat) + 2d6 (skills)",players:"3–6",complexity:3,edition:"B/X",free:!0,foundryStatus:"Community",heroImage:"https://image.nobleknight.com/2/jpg1500/2370011105765worlds.jpg",playstyleTags:["explore","combat","sandbox"],settingTags:["fantasy"],gallery:[{src:"https://thegaminggang.com/wp-content/uploads/2021/03/Worlds-Without-Number.jpg"},{src:"https://image.nobleknight.com/2/jpg1500/23222440222h.jpg"}],resources:[{type:"quickstart",url:"https://www.drivethrurpg.com/en/product/348809/worlds-without-number-free-edition",fmt:"PDF"},{type:"link",url:"https://www.drivethrurpg.com/en/publisher/3482/Sine-Nomine-Publishing",fmt:"Web"}],mechanics:[{icon:"map"},{icon:"sparkles"},{icon:"dices"},{icon:"flag"}],quotes:[{text:"Kevin Crawford's Worlds Without Number builds on the excellent foundation established by its science fiction predecessor, Stars Without Number, to deliver a compelling and unique fantasy game with special interest for GMs.",author:"Sami Yuhas, The Gaming Gang"}],ru:{tagShort:"Олдскульная фэнтези-песочница от автора SWN",tagline:"«Фэнтезийный близнец Stars Without Number — и лучший GM-тулкит для sandbox-игры».",description:"Worlds Without Number — олдскульная фэнтези-RPG Кевина Кроуфорда, фэнтезийная спутница Stars Without Number. B/X-наследие с восходящим AC, но главная сила — генераторы наций, фракций, карт и подземелий, превращающие подготовку в удовольствие. Отдельная система магии «Искусства» и героические пути делают персонажей мощнее классического олдскула.",setting:"Латтер-Эрт (Latter Earth) — постапокалиптическое фэнтези на руинах бесчисленных погибших цивилизаций. Магия здесь — оружие, некогда расколовшее мир; её боятся и запрещают. Регион Гир полон павших империй, забытых чудес и фракций, грызущихся за власть. Готовая песочница для долгой кампании.",vignette:"Отряд входит в занесённый песком храм эпохи до Катастрофы. Взломщик проверяет древний механизм: 2d6 + Ловкость + навык против порога 10. Выпало 11 — успех, плита отходит. Между сессиями ход фракции: соседний культ бросает на «Расширить влияние» и захватывает деревню на тракте. Мир меняется сам, без рельсов ведущего.",prep:"~20 мин",mechanics:[{title:"GM-тулкит песочницы",text:"Генераторы наций, фракций, карт, подземелий и таблиц зацепок. Целый мир и живые силы в нём собираются за вечер — минимум ручной работы, максимум игры."},{title:"Система «Искусства» (магия)",text:"Низкая, Высокая и магия Адептов — разные традиции. Магия опасна и раскалывает мир; она отделена от боевой мощи, так что маг не обязан быть хрупким."},{title:"Гибрид d20 + 2d6",text:"Бой — привычный d20 против AC. Навыки — 2d6 + атрибут + навык против порога. Две простые механики в духе олдскульной D&D."},{title:"Фокусы и герои",text:"«Фокусы» и предыстории настраивают персонажа, а героические пути дают эпические трюки. Совместимо со Stars Without Number — можно смешивать фэнтези и сай-фай."}],gallery:[{cap:"Обложка"},{cap:"Издание Print-on-Demand"}],resources:[{name:"Бесплатная Free Edition (DriveThruRPG)"},{name:"Sine Nomine Publishing"}],quotes:[{text:"Worlds Without Number Кевина Кроуфорда развивает превосходный фундамент своего научно-фантастического предшественника, Stars Without Number, и выдаёт цельную и самобытную фэнтези-игру, особенно ценную для ведущих."}]},en:{tagShort:"Old-school fantasy sandbox from the SWN designer",tagline:'"The fantasy twin of Stars Without Number — and the best GM sandbox toolkit going."',description:"Worlds Without Number is Kevin Crawford's old-school fantasy RPG, the fantasy companion to Stars Without Number. B/X heritage with ascending AC, but its real strength is the generators — nations, factions, maps, and dungeons — that turn prep into a pleasure. A distinct 'Arts' magic system and heroic paths make characters mightier than classic old-school.",setting:"The Latter Earth — a post-apocalyptic fantasy built on the ruins of countless dead civilizations. Magic here is the weapon that once shattered the world; it is feared and outlawed. The Gyre region teems with fallen empires, forgotten wonders, and factions clawing for power. A ready-made sandbox for a long campaign.",vignette:"The party enters a sand-choked temple from before the Cataclysm. The delver tests an ancient mechanism: 2d6 + Dexterity + skill against difficulty 10. She rolls 11 — success, and the slab grinds aside. Between sessions, a faction turn: a neighboring cult rolls to Expand Influence and seizes a village on the road. The world moves on its own, no GM rails.",prep:"~20 min",mechanics:[{title:"Sandbox GM toolkit",text:"Generators for nations, factions, maps, dungeons, and hook tables. A whole world and the living powers within it come together in an evening — minimal hand-crafting, maximal play."},{title:"The Arts (magic)",text:"Low, High, and Adept traditions are distinct paths. Magic is dangerous and world-shattering, and it's decoupled from combat power, so a mage need not be fragile."},{title:"d20 + 2d6 hybrid",text:"Combat is familiar d20 vs AC. Skills are 2d6 + attribute + skill against a difficulty. Two simple mechanics in the old-school D&D idiom."},{title:"Foci & heroes",text:"'Foci' and backgrounds customize a character, while heroic paths grant epic stunts. Fully compatible with Stars Without Number — mix fantasy and sci-fi freely."}],gallery:[{cap:"Cover"},{cap:"Print-on-Demand edition"}],resources:[{name:"Free Edition (DriveThruRPG)"},{name:"Sine Nomine Publishing"}],quotes:[{text:"Kevin Crawford's Worlds Without Number builds on the excellent foundation established by its science fiction predecessor, Stars Without Number, to deliver a compelling and unique fantasy game with special interest for GMs."}]}}),registerSystem("wrath-and-glory",{groups:{default:{key:"tactical",order:33},family:{key:"standalone",order:36},genre:{key:"sci-fi",order:8.7}},name:"Warhammer 40,000: Wrath & Glory",publisher:"Cubicle 7 Games",dice:"d6 pool",players:"3–6",complexity:3,free:!0,foundryStatus:"Official",heroImage:"https://image.nobleknight.com/c/jpg1500/cb72600.jpg",playstyleTags:["combat","tactical","narrative"],settingTags:["space","weird"],gallery:[{src:"https://image.nobleknight.com/c/jpg1500/cb72618.jpg"},{src:"https://image.nobleknight.com/c/jpg1500/cb72627.jpg"},{src:"https://image.nobleknight.com/c/jpg1500/cb72626.jpg"}],resources:[{type:"quickstart",url:"https://www.drivethrurpg.com/en/product/370883/warhammer-40000-wrath-glory-a-bitter-promise",fmt:"PDF"},{type:"link",url:"https://www.cubicle7games.com/our-games/warhammer-40000-roleplay/wrath-glory/",fmt:"Web"},{type:"link",url:"https://www.cubicle7games.com/our-games/warhammer-40000-roleplay/wrath-glory/wrath-glory-core-rulebook/",fmt:"Web"}],mechanics:[{icon:"dices"},{icon:"zap"},{icon:"target"},{icon:"flame"}],quotes:[{text:"While it has its quirks and complications, the simple fact that Wrath & Glory works at all is strangely impressive.",author:"Richard Jansen-Parkes, EN World"},{text:"If you're a 40k player, I definitely recommend it, and if you aren't, embrace the dark far future.",author:"Mark, Dice Monkey"}],ru:{tagShort:"d6 pool — grimdark 40K в формате RPG",tagline:"«Во Гrimdark далёкого будущего нет войны — только вечная битва».",description:"Warhammer 40,000: Wrath & Glory — настольная RPG (2019 Ulisses Spiele, 2022 Cubicle 7 Games) по вселенной Warhammer 40K. Игроки берут на себя роли Имперских Агентов, Космодесантников, Культистов или Орков. Механика d6 pool: бросаете кубиков столько, сколько у вас рейтинг в атрибуте и навыке, считаете successful die (6+). Wrath dice (красные) — критические и трэш-события.",setting:"Год 41-го тысячелетия. Император Человечества — живой труп на Золотом Троне. Галактика разрывается войнами: Хаос, Орки, Тыраноиды, Эльфы. Простые люди — пешки в игре богов. Игра охватывает все аспекты 40K: от кадетов до космодесантников.",vignette:"Мастер: «Ты в коридоре космического десантного корабля. Стены покрыты кровью. Ты слышишь крики из каюты 12.» Игрок: «Иду туда с болтером наготове.» Мастер: «Брось d6 pool: 4 кубика.» Игрок: 5, 3, 1, 6. Одна шестёрка — успех! Но Wrath die (красный) показал 1 — трэш-событие: «Из стены вылезает жук-паразит и кусает тебя за ногу.»",prep:"~20 мин",mechanics:[{title:"d6 Pool (Успех = 6+)",text:"Бросаете кубиков = ATTRIBUTE + SKILL. Каждая 6+ — один успех. Wrath dice (красные): 6 — крит, 1 — трэш."},{title:"Тир персонажа",text:"Tier 1 (кадеты) → Tier 4 (космодесантники). Мощь персонажа масштабируется с тиром."},{title:"Иерархия фракций",text:"Империум, Хаос, Орки, Тыраноиды, Эльфы. Каждая фракция — свой набор персонажей и механик."},{title:"Wrath & Glory Dice",text:"Красные Wrath dice: 6 — Wrathful (сильный крит), 1 — Malefic (трэш-событие). Создают драму."}],gallery:[{cap:"Core Rulebook (Cubicle 7)"},{cap:"Warhammer 40K: Wrath & Glory — Amazon"},{cap:"Warhammer 40K: Wrath & Glory — обложка"}],resources:[{name:"Бесплатный Quickstart — A Bitter Promise (PDF)"},{name:"Официальная страница (Cubicle 7)"},{name:"Core Rulebook — Cubicle 7"}],quotes:[{text:"Несмотря на все свои причуды и сложности, сам факт, что Wrath & Glory вообще работает, странным образом впечатляет."},{text:"Если вы играете в 40k — однозначно рекомендую; а если нет — примите тёмное далёкое будущее."}]},en:{tagShort:"d6 pool — grimdark 40K in RPG format",tagline:'"In the grim darkness of the far future there is only war."',description:"Warhammer 40,000: Wrath & Glory is a tabletop RPG (2019 Ulisses Spiele, 2022 Cubicle 7 Games) set in the Warhammer 40K universe. Players take on the roles of Imperial Agents, Space Marines, Cultists, or Orks. d6 pool mechanic: roll dice equal to your Attribute + Skill rating, count successes (6+). Wrath dice (red) — crits and trash events.",setting:"The year is the 41st Millennium. The Emperor of Mankind is a living corpse on the Golden Throne. The galaxy is torn apart by war: Chaos, Orks, Tyranids, Elves. Ordinary people are pawns in the game of gods. The game covers every aspect of 40K: from cadets to Space Marines.",vignette:"GM: 'You're in the corridor of a Space Marine ship. Walls are covered in blood. You hear screams from Cabin 12.' Player: 'I go in with bolter ready.' GM: 'Roll d6 pool: 4 dice.' Player: 5, 3, 1, 6. One six — success! But the Wrath die (red) shows 1 — trash event: 'A parasitic bug emerges from the wall and bites your leg.'",prep:"~20 min",mechanics:[{title:"d6 Pool (Success = 6+)",text:"Roll dice = ATTRIBUTE + SKILL. Each 6+ is one success. Wrath dice (red): 6 — critical, 1 — trash."},{title:"Character Tier",text:"Tier 1 (cadets) → Tier 4 (Space Marines). Character power scales with tier."},{title:"Faction Hierarchy",text:"Imperium, Chaos, Orks, Tyranids, Elves. Each faction — its own character set and mechanics."},{title:"Wrath & Glory Dice",text:"Red Wrath dice: 6 — Wrathful (strong crit), 1 — Malefic (trash event). Creates drama."}],gallery:[{cap:"Core Rulebook (Cubicle 7)"},{cap:"Warhammer 40K: Wrath & Glory — Amazon"},{cap:"Warhammer 40K: Wrath & Glory — cover"}],resources:[{name:"Free Quickstart — A Bitter Promise (PDF)"},{name:"Official page (Cubicle 7)"},{name:"Core Rulebook — Cubicle 7"}],quotes:[{text:"While it has its quirks and complications, the simple fact that Wrath & Glory works at all is strangely impressive."},{text:"If you're a 40k player, I definitely recommend it, and if you aren't, embrace the dark far future."}]}});
